  const keywordData = useMemo(() => ({
    one: getKeywords(content, 1, keywordLimit),
    two: getKeywords(content, 2, keywordLimit),
    three: getKeywords(content, 3, keywordLimit),
    four: getKeywords(content, 4, keywordLimit),
  }), [content, keywordLimit]);

  const execCommand = (command: string, value: string = '') => {
    document.execCommand(command, false, value);
    if (editorRef.current) setContent(editorRef.current.innerHTML);
  };

  const convertCase = (type: 'upper' | 'lower' | 'capitalize' | 'sentence') => {
    const selection = window.getSelection();
    if (!selection || selection.rangeCount === 0 || selection.toString().length === 0) {
      // Apply to whole doc if no selection
      const text = editorRef.current?.innerText || '';
      let newText = text;
      if (type === 'upper') newText = text.toUpperCase();
      if (type === 'lower') newText = text.toLowerCase();
      if (type === 'capitalize') newText = text.replace(/\b\w/g, l => l.toUpperCase());
      if (type === 'sentence') newText = text.charAt(0).toUpperCase() + text.slice(1).toLowerCase();

      if (editorRef.current) {
        editorRef.current.innerText = newText;
        setContent(editorRef.current.innerHTML);
      }
      return;
    }

    const text = selection.toString();
    let newText = text;
    if (type === 'upper') newText = text.toUpperCase();
    if (type === 'lower') newText = text.toLowerCase();
    if (type === 'capitalize') newText = text.replace(/\b\w/g, l => l.toUpperCase());
    if (type === 'sentence') newText = text.charAt(0).toUpperCase() + text.slice(1).toLowerCase();

