    <div className={`min-h-screen flex flex-col md:flex-row bg-zinc-950 text-zinc-100 selection:bg-blue-500/30`}>
      {/* Left Sidebar / Main Content Area */}
      <div className="flex-1 flex flex-col relative overflow-hidden">
        {/* Top Navbar */}
        <header className="h-16 border-b border-zinc-800 flex items-center justify-between px-6 glass-panel z-10">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center font-bold text-white shadow-lg shadow-blue-500/20">
              S
            </div>
            <h1 className="font-bold text-lg tracking-tight hidden sm:block">SEO FOCUS <span className="text-zinc-500 font-medium">EDITOR</span></h1>
          </div>

          <div className="flex items-center gap-2">
