          <ToolbarButton icon={<Heading2 size={18} />} onClick={() => execCommand('formatBlock', 'H2')} title="H2" />
          <ToolbarButton icon={<Heading3 size={18} />} onClick={() => execCommand('formatBlock', 'H3')} title="H3" />
          <div className="w-[1px] h-6 bg-zinc-800 self-center mx-1" />
