// --- Helper Components ---

const ToolbarButton = ({ icon, onClick, title }: { icon: React.ReactNode, onClick: () => void, title: string }) => (
  <button 
    onMouseDown={(e) => { e.preventDefault(); onClick(); }} // Use onMouseDown to prevent losing focus
    className="p-2 hover:bg-zinc-800 text-zinc-400 hover:text-white rounded-lg transition-all"
    title={title}
  >
    {icon}
  </button>
);

const TabButton = ({ active, onClick, label, icon }: { active: boolean, onClick: () => void, label: string, icon: React.ReactNode }) => (
  <button 
    onClick={onClick}
    className={`flex-1 flex items-center justify-center gap-2 text-sm font-bold transition-all relative ${active ? 'text-blue-500' : 'text-zinc-500 hover:text-zinc-300'}`}
  >
    {icon}
    {label}
    {active && <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-blue-500" />}
  </button>
);

const StatCard = ({ label, value }: { label: string, value: string | number }) => (
  <div className="p-4 bg-zinc-900/40 rounded-2xl border border-zinc-800/50 flex flex-col gap-1">
    <span className="text-xs font-medium text-zinc-500 uppercase tracking-tight">{label}</span>
    <span className="text-xl font-bold text-zinc-100">{value}</span>
  </div>
);

const KeywordSection = ({ title, data }: { title: string, data: KeywordDensity[] }) => (
  <div>
    <h4 className="text-xs font-bold text-zinc-600 mb-3 flex items-center gap-2">
      <div className="w-1 h-3 bg-blue-600 rounded-full" />
      {title}
    </h4>
    {data.length === 0 ? (
      <div className="text-xs text-zinc-600 italic px-3">No phrases found.</div>
    ) : (
      <div className="overflow-hidden rounded-xl border border-zinc-800/50">
        <table className="w-full text-left text-xs">
          <thead className="bg-zinc-900/80 text-zinc-500 uppercase text-[10px] font-bold">
            <tr>
              <th className="px-3 py-2">Keyword</th>
              <th className="px-3 py-2 text-right">Count</th>
              <th className="px-3 py-2 text-right">Density</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-800/30">
            {data.map((item, idx) => {
              let densityColor = 'text-green-500';
              if (item.percentage >= 2 && item.percentage <= 3) densityColor = 'text-yellow-500';
              if (item.percentage > 3) densityColor = 'text-red-500';

              return (
                <tr key={idx} className="hover:bg-zinc-900/50 transition-colors group">
                  <td className="px-3 py-2 font-medium text-zinc-300 max-w-[120px] truncate group-hover:text-white">{item.phrase}</td>
                  <td className="px-3 py-2 text-right text-zinc-400">{item.count}</td>
                  <td className={`px-3 py-2 text-right font-bold ${densityColor}`}>{item.percentage}%</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    )}
  </div>
);

const ActionButton = ({ onClick, label, variant = 'primary' }: { onClick: () => void, label: string, variant?: 'primary' | 'secondary' | 'danger' }) => {
  const styles = {
    primary: 'bg-zinc-800 hover:bg-zinc-700 text-zinc-100 border-zinc-700',
    secondary: 'bg-zinc-900 hover:bg-zinc-800 text-zinc-400 hover:text-zinc-200 border-zinc-800',
    danger: 'bg-red-500/10 hover:bg-red-500/20 text-red-500 border-red-500/20',
  };

  return (
    <button 
      onClick={onClick}
      className={`w-full py-2 px-4 rounded-xl text-sm font-medium border transition-all ${styles[variant]}`}
    >
      {label}
    </button>
  );
};

