import React, { useState, useEffect, useRef, useMemo, useDeferredValue } from 'react';
import ReactDOM from 'react-dom/client';
import { 
  Bold, Italic, Underline, Heading, 
  List, ListOrdered, Quote, Code, Link as LinkIcon, 
  Trash2, Download, Copy, FileText, BarChart3, 
  Type, Settings, Sun, Moon, Maximize2, Minimize2,
  ChevronRight, Search, Info, RotateCcw, ArrowRightLeft,
  X, ExternalLink, Edit2, ChevronDown
} from 'lucide-react';

// --- Types ---
type Tab = 'stats' | 'keywords' | 'tools';
type SEOPhraseTab = 1 | 2 | 3 | 4;
type KeywordDensity = {
  phrase: string;
  count: number;
  percentage: number;
};

// --- Utilities ---
const STOP_WORDS = new Set([
  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'but', 'by', 'for', 'if', 'in', 'into', 'is', 'it', 
  'no', 'not', 'of', 'on', 'or', 'such', 'that', 'the', 'their', 'then', 'there', 'these', 
  'they', 'this', 'to', 'was', 'will', 'with', 'from', 'up', 'down', 'out', 'over', 'under', 
  'again', 'further', 'once', 'here', 'there', 'when', 'where', 'why', 'how', 'all', 'any', 
  'both', 'each', 'few', 'more', 'most', 'other', 'some', 'such', 'nor', 'too', 'very', 's', 't', 
  'can', 'will', 'just', 'don', 'should', 'now', 'has', 'had', 'been', 'being', 'having'
]);

const getStats = (text: string) => {
  const cleanText = text.replace(/<[^>]*>/g, ' ').trim();
  const words = cleanText ? cleanText.split(/\s+/) : [];
  const sentences = cleanText ? cleanText.split(/[.!?]+/).filter(Boolean) : [];
  const paragraphs = text.split(/<\/p>|<\/div>|<br\s*\/?>/).filter(p => p.replace(/<[^>]*>/g, '').trim().length > 0);

  const wordCount = words.length;

  return {
    words: wordCount,
    characters: cleanText.length,
    charactersNoSpaces: cleanText.replace(/\s/g, '').length,
    sentences: sentences.length,
    paragraphs: paragraphs.length,
    readingTime: Math.ceil(wordCount / 200),
    speakingTime: Math.ceil(wordCount / 130),
  };
};

const getKeywords = (text: string, n: number = 1) => {
  const cleanText = text.replace(/<[^>]*>/g, ' ').toLowerCase();
  const tokens = cleanText.replace(/[^\w\s]/g, '').split(/\s+/).filter(t => t.length > 1);
  const totalTokens = tokens.length;

  if (totalTokens === 0) return [];

  const phrases: Record<string, number> = {};

  for (let i = 0; i <= tokens.length - n; i++) {
    const phrase = tokens.slice(i, i + n).join(' ');
    if (n === 1 && STOP_WORDS.has(phrase)) continue;
    if (n > 1 && tokens.slice(i, i + n).every(w => STOP_WORDS.has(w))) continue;

    phrases[phrase] = (phrases[phrase] || 0) + 1;
  }

  return Object.entries(phrases)
    .map(([phrase, count]) => ({
      phrase,
      count,
      percentage: Number(((count * n) / totalTokens * 100).toFixed(2))
    }))
    .sort((a, b) => b.count - a.count);
};

const htmlToMarkdown = (html: string) => {
  let md = html
    .replace(/<h1>(.*?)<\/h1>/gi, '# $1\n\n')
    .replace(/<h2>(.*?)<\/h2>/gi, '## $1\n\n')
    .replace(/<h3>(.*?)<\/h3>/gi, '### $1\n\n')
    .replace(/<h4>(.*?)<\/h4>/gi, '#### $1\n\n')
    .replace(/<h5>(.*?)<\/h5>/gi, '##### $1\n\n')
    .replace(/<h6>(.*?)<\/h6>/gi, '###### $1\n\n')
    .replace(/<b>(.*?)<\/b>/gi, '**$1**')
    .replace(/<strong>(.*?)<\/strong>/gi, '**$1**')
    .replace(/<i>(.*?)<\/i>/gi, '*$1*')
    .replace(/<em>(.*?)<\/em>/gi, '*$1*')
    .replace(/<li>(.*?)<\/li>/gi, '- $1\n')
    .replace(/<ul>(.*?)<\/ul>/gi, '$1\n')
    .replace(/<ol>(.*?)<\/ol>/gi, '$1\n')
    .replace(/<p>(.*?)<\/p>/gi, '$1\n\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<blockquote[^>]*>(.*?)<\/blockquote>/gi, '> $1\n\n')
    .replace(/<[^>]*>/g, '');
  return md.trim();
};

// --- Components ---

const App = () => {
  const [content, setContent] = useState(() => localStorage.getItem('seo-editor-content') || '<h1>Futuristic SEO Editor</h1><p>Start crafting high-ranking content with real-time analysis.</p>');
  const [isDarkMode, setIsDarkMode] = useState(() => localStorage.getItem('seo-editor-theme') !== 'light');
  const [activeTab, setActiveTab] = useState<Tab>('stats');
  const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
  const [grammarEnabled, setGrammarEnabled] = useState(() => localStorage.getItem('seo-editor-grammar') !== 'false');
  const [isExpanded, setIsExpanded] = useState(false);
  const [activeLink, setActiveLink] = useState<{ element: HTMLAnchorElement, url: string } | null>(null);
  const editorRef = useRef<HTMLDivElement>(null);

  // Debounced content for heavy analysis
  const [debouncedContent, setDebouncedContent] = useState(content);
  const deferredContent = useDeferredValue(debouncedContent);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedContent(content);
      localStorage.setItem('seo-editor-content', content);
    }, 500);
    return () => clearTimeout(handler);
  }, [content]);

  useEffect(() => {
    localStorage.setItem('seo-editor-theme', isDarkMode ? 'dark' : 'light');
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  useEffect(() => {
    localStorage.setItem('seo-editor-grammar', String(grammarEnabled));
  }, [grammarEnabled]);

  const stats = useMemo(() => getStats(deferredContent), [deferredContent]);

  const currentKeywords = useMemo(() => {
    return getKeywords(deferredContent, seoTab);
  }, [deferredContent, seoTab]);

  const execCommand = (command: string, value: string = '') => {
    document.execCommand(command, false, value);
    if (editorRef.current) setContent(editorRef.current.innerHTML);
  };

  const handleEditorClick = (e: React.MouseEvent) => {
    const target = e.target as HTMLElement;
    const anchor = target.closest('a');
    if (anchor) {
      setActiveLink({ element: anchor as HTMLAnchorElement, url: (anchor as HTMLAnchorElement).href });
    } else {
      setActiveLink(null);
    }
  };

  const editLink = () => {
    if (!activeLink) return;
    const newUrl = prompt("Update link URL:", activeLink.url);
    if (newUrl !== null) {
      activeLink.element.href = newUrl;
      if (editorRef.current) setContent(editorRef.current.innerHTML);
      setActiveLink({ ...activeLink, url: newUrl });
    }
  };

  const removeLink = () => {
    if (!activeLink) return;
    const parent = activeLink.element.parentNode;
    if (parent) {
      while (activeLink.element.firstChild) {
        parent.insertBefore(activeLink.element.firstChild, activeLink.element);
      }
      parent.removeChild(activeLink.element);
      if (editorRef.current) setContent(editorRef.current.innerHTML);
      setActiveLink(null);
    }
  };

  const convertCase = (type: 'upper' | 'lower' | 'capitalize' | 'sentence' | 'toggle') => {
    const selection = window.getSelection();
    const textToConvert = selection && selection.toString().length > 0 ? selection.toString() : editorRef.current?.innerText || '';

    let newText = textToConvert;
    switch (type) {
      case 'upper': newText = textToConvert.toUpperCase(); break;
      case 'lower': newText = textToConvert.toLowerCase(); break;
      case 'capitalize': newText = textToConvert.replace(/\b\w/g, l => l.toUpperCase()); break;
      case 'sentence': 
        newText = textToConvert.toLowerCase().replace(/(^\s*\w|[\.\!\?]\s*\w)/g, c => c.toUpperCase());
        break;
      case 'toggle':
        newText = textToConvert.split('').map(c => c === c.toUpperCase() ? c.toLowerCase() : c.toUpperCase()).join('');
        break;
    }

    if (selection && selection.toString().length > 0) {
      document.execCommand('insertText', false, newText);
    } else if (editorRef.current) {
      editorRef.current.innerText = newText;
    }
    if (editorRef.current) setContent(editorRef.current.innerHTML);
  };

  const exportDoc = (format: 'txt' | 'html' | 'md') => {
    let output = '';
    let fileName = `seo-content.${format}`;
    if (format === 'txt') output = editorRef.current?.innerText || '';
    else if (format === 'html') output = `<!DOCTYPE html><html><head><meta charset="utf-8"></head><body>${content}</body></html>`;
    else output = htmlToMarkdown(content);

    const element = document.createElement("a");
    const file = new Blob([output], {type: 'text/plain'});
    element.href = URL.createObjectURL(file);
    element.download = fileName;
    document.body.appendChild(element);
    element.click();
    document.body.removeChild(element);
  };

  const copyToClipboard = (type: 'plain' | 'html' | 'markdown') => {
    let text = '';
    if (type === 'plain') text = editorRef.current?.innerText || '';
    else if (type === 'html') text = content;
    else text = htmlToMarkdown(content);

    navigator.clipboard.writeText(text);
  };

  const clearDoc = () => {
    if (window.confirm("Delete everything? This cannot be undone.")) {
      setContent('');
      if (editorRef.current) editorRef.current.innerHTML = '';
    }
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-white dark:bg-zinc-950 text-zinc-900 dark:text-zinc-100 selection:bg-blue-500/30 transition-colors duration-300">

      {/* Primary Workspace */}
      <div className="flex-1 flex flex-col relative overflow-hidden">

        {/* Nav Bar */}
        <header className="h-16 border-b border-zinc-200 dark:border-zinc-800 flex items-center justify-between px-6 glass-panel z-30">
          <div className="flex items-center gap-3 group">
            <div className="w-8 h-8 bg-blue-600 rounded-xl flex items-center justify-center font-black text-white shadow-lg shadow-blue-500/40 group-hover:scale-110 transition-transform">
              S
            </div>
            <h1 className="font-bold text-lg tracking-tight hidden sm:block">SEO FOCUS <span className="text-zinc-400 dark:text-zinc-500 font-medium">EDITOR</span></h1>
          </div>

          <div className="flex items-center gap-2">
            <button 
              onClick={() => setIsDarkMode(!isDarkMode)}
              className="p-2 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-xl transition-colors text-zinc-500 dark:text-zinc-400 hover:text-blue-500"
              title="Toggle Theme"
            >
              {isDarkMode ? <Sun size={20} /> : <Moon size={20} />}
            </button>
            <div className="h-4 w-[1px] bg-zinc-200 dark:bg-zinc-800 mx-1" />
            <div className="relative group">
              <button className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-500 text-white rounded-xl text-sm font-bold shadow-lg shadow-blue-600/20 transition-all">
                <Download size={16} />
                <span className="hidden sm:inline">Export</span>
              </button>
              <div className="absolute right-0 top-full mt-2 w-48 bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-xl shadow-2xl opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all z-50 p-2">
                <button onClick={() => exportDoc('html')} className="w-full text-left px-3 py-2 text-sm hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-lg">Web Page (.HTML)</button>
                <button onClick={() => exportDoc('txt')} className="w-full text-left px-3 py-2 text-sm hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-lg">Plain Text (.TXT)</button>
                <button onClick={() => exportDoc('md')} className="w-full text-left px-3 py-2 text-sm hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-lg">Markdown (.MD)</button>
              </div>
            </div>
          </div>
        </header>

        {/* Toolbar */}
        <div className="border-b border-zinc-200 dark:border-zinc-800 bg-zinc-50/50 dark:bg-zinc-900/50 backdrop-blur-md p-2 flex flex-wrap gap-1 sticky top-0 z-20 overflow-x-auto no-scrollbar items-center">
          <ToolbarGroup>
            <div className="relative flex items-center px-2 group">
              <select 
                onChange={(e) => {
                  const val = e.target.value;
                  if (val === 'p') execCommand('formatBlock', 'p');
                  else execCommand('formatBlock', val);
                }}
                className="bg-transparent appearance-none text-xs font-bold outline-none cursor-pointer pr-6 py-2 text-zinc-600 dark:text-zinc-400 hover:text-blue-500"
              >
                <option value="p">Normal Text</option>
                <option value="H1">Heading 1</option>
                <option value="H2">Heading 2</option>
                <option value="H3">Heading 3</option>
                <option value="H4">Heading 4</option>
                <option value="H5">Heading 5</option>
                <option value="H6">Heading 6</option>
              </select>
              <ChevronDown size={12} className="absolute right-2 pointer-events-none text-zinc-400" />
            </div>
          </ToolbarGroup>
          <ToolbarGroup>
            <ToolbarButton icon={<Bold size={18} />} onClick={() => execCommand('bold')} title="Bold" />
            <ToolbarButton icon={<Italic size={18} />} onClick={() => execCommand('italic')} title="Italic" />
            <ToolbarButton icon={<Underline size={18} />} onClick={() => execCommand('underline')} title="Underline" />
          </ToolbarGroup>
          <ToolbarGroup>
            <ToolbarButton icon={<List size={18} />} onClick={() => execCommand('insertUnorderedList')} title="Bullet List" />
            <ToolbarButton icon={<ListOrdered size={18} />} onClick={() => execCommand('insertOrderedList')} title="Numbered List" />
            <ToolbarButton icon={<Quote size={18} />} onClick={() => execCommand('formatBlock', 'blockquote')} title="Blockquote" />
            <ToolbarButton icon={<Code size={18} />} onClick={() => execCommand('formatBlock', 'pre')} title="Code" />
          </ToolbarGroup>
          <ToolbarGroup>
            <ToolbarButton icon={<LinkIcon size={18} />} onClick={() => {
              const url = prompt("Link URL:");
              if (url) execCommand('createLink', url);
            }} title="Insert Link" />
            <ToolbarButton icon={<Trash2 size={18} />} onClick={() => execCommand('removeFormat')} title="Clear Format" />
          </ToolbarGroup>
        </div>

        {/* Editor Area */}
        <main className="flex-1 overflow-y-auto p-6 md:p-12 lg:p-16 flex justify-center custom-scrollbar">
          <div className="w-full max-w-4xl bg-white dark:bg-transparent rounded-3xl p-8 md:p-12 shadow-sm dark:shadow-none relative">
            {/* Link Popover */}
            {activeLink && (
              <div 
                className="absolute bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 shadow-2xl rounded-xl p-2 flex items-center gap-2 z-50 animate-in zoom-in-95"
                style={{ 
                  top: activeLink.element.offsetTop + activeLink.element.offsetHeight + 10,
                  left: Math.min(activeLink.element.offsetLeft, window.innerWidth - 300)
                }}
              >
                <span className="text-xs text-blue-500 font-medium px-2 truncate max-w-[150px]">{activeLink.url}</span>
                <div className="w-[1px] h-4 bg-zinc-200 dark:bg-zinc-800" />
                <button onClick={editLink} className="p-1.5 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-lg text-zinc-500" title="Edit Link"><Edit2 size={14} /></button>
                <button onClick={() => window.open(activeLink.url, '_blank')} className="p-1.5 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-lg text-zinc-500" title="Open Link"><ExternalLink size={14} /></button>
                <button onClick={removeLink} className="p-1.5 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-lg text-red-500" title="Remove Link"><X size={14} /></button>
              </div>
            )}

            <div
              ref={editorRef}
              contentEditable
              spellCheck={grammarEnabled}
              onClick={handleEditorClick}
              onInput={(e) => setContent(e.currentTarget.innerHTML)}
              dangerouslySetInnerHTML={{ __html: content }}
              className="editor-content min-h-[70vh] focus:outline-none text-xl text-zinc-800 dark:text-zinc-300 leading-relaxed font-normal"
            />
          </div>
        </main>

        {/* Mobile Navigation */}
        <div className="md:hidden flex border-t border-zinc-200 dark:border-zinc-800 glass-panel shadow-up">
          <MobileNavBtn active={activeTab === 'stats'} onClick={() => setActiveTab('stats')} icon={<BarChart3 size={20} />} label="Stats" />
          <MobileNavBtn active={activeTab === 'keywords'} onClick={() => setActiveTab('keywords')} icon={<Search size={20} />} label="SEO" />
          <MobileNavBtn active={activeTab === 'tools'} onClick={() => setActiveTab('tools')} icon={<Settings size={20} />} label="Tools" />
        </div>
      </div>

      {/* Sidebar Analysis */}
      <aside className={`w-full md:w-80 lg:w-[400px] border-l border-zinc-200 dark:border-zinc-800 flex flex-col bg-zinc-50 dark:bg-zinc-950/50 backdrop-blur-2xl ${activeTab ? '' : 'hidden md:flex'}`}>
        {/* Desktop Tabs */}
        <div className="hidden md:flex border-b border-zinc-200 dark:border-zinc-800 h-16 shrink-0">
          <TabButton active={activeTab === 'stats'} onClick={() => setActiveTab('stats')} label="Stats" icon={<BarChart3 size={16} />} />
          <TabButton active={activeTab === 'keywords'} onClick={() => setActiveTab('keywords')} label="SEO" icon={<Search size={16} />} />
          <TabButton active={activeTab === 'tools'} onClick={() => setActiveTab('tools')} label="Tools" icon={<Settings size={16} />} />
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-6 space-y-8 pb-32 md:pb-8">
          {activeTab === 'stats' && (
            <div className="space-y-6 animate-in fade-in slide-in-from-right-4">
              <SectionHeader title="Content Metrics" />
              <div className="grid grid-cols-2 gap-3">
                <StatCard label="Words" value={stats.words} />
                <StatCard label="Sentences" value={stats.sentences} />
                <StatCard label="Chars (Spaces)" value={stats.characters} />
                <StatCard label="Chars (No Spc)" value={stats.charactersNoSpaces} />
                <StatCard label="Paragraphs" value={stats.paragraphs} />
                <StatCard label="Reading" value={`${stats.readingTime}m`} />
                <StatCard label="Speaking" value={`${stats.speakingTime}m`} />
              </div>
            </div>
          )}

          {activeTab === 'keywords' && (
            <div className="space-y-6 animate-in fade-in slide-in-from-right-4">
              <SectionHeader title="SEO Analyzer" />

              {/* Phrase Tabs */}
              <div className="flex bg-zinc-200 dark:bg-zinc-900 p-1 rounded-xl gap-1">
                {[1, 2, 3, 4].map(num => (
                  <button 
                    key={num}
                    onClick={() => { setSeoTab(num as SEOPhraseTab); setIsExpanded(false); }}
                    className={`flex-1 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${seoTab === num ? 'bg-white dark:bg-zinc-800 text-blue-500 shadow-sm' : 'text-zinc-500 hover:text-zinc-700 dark:hover:text-zinc-300'}`}
                  >
                    {num} Phrase
                  </button>
                ))}
              </div>

              <KeywordSection 
                title={`${seoTab}-Word Phrases`} 
                data={isExpanded ? currentKeywords : currentKeywords.slice(0, 15)} 
              />

              {currentKeywords.length > 15 && (
                <button 
                  onClick={() => setIsExpanded(!isExpanded)}
                  className="w-full py-2 text-[10px] font-black uppercase tracking-widest text-blue-500 hover:text-blue-600 transition-colors flex items-center justify-center gap-2"
                >
                  {isExpanded ? 'Show Less' : `Expand to view all (${currentKeywords.length})`}
                  <ChevronDown size={14} className={isExpanded ? 'rotate-180 transition-transform' : 'transition-transform'} />
                </button>
              )}
            </div>
          )}

          {activeTab === 'tools' && (
            <div className="space-y-8 animate-in fade-in slide-in-from-right-4">
              <div className="space-y-4">
                <SectionHeader title="Case Utilities" />
                <div className="grid grid-cols-1 gap-2">
                  <ActionButton onClick={() => convertCase('upper')} label="UPPERCASE" icon={<ArrowRightLeft size={14}/>} />
                  <ActionButton onClick={() => convertCase('lower')} label="lowercase" icon={<ArrowRightLeft size={14}/>}/>
                  <ActionButton onClick={() => convertCase('capitalize')} label="Capitalize Words" icon={<ArrowRightLeft size={14}/>}/>
                  <ActionButton onClick={() => convertCase('sentence')} label="Sentence case" icon={<ArrowRightLeft size={14}/>}/>
                  <ActionButton onClick={() => convertCase('toggle')} label="tOGGLE cASE" icon={<RotateCcw size={14}/>}/>
                </div>
              </div>

              <div className="space-y-4">
                <SectionHeader title="Editor Settings" />
                <div className="flex items-center justify-between p-4 bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-2xl shadow-sm">
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-blue-500/10 rounded-lg"><Info size={16} className="text-blue-500" /></div>
                    <div className="flex flex-col">
                       <span className="text-sm font-bold">Spellcheck</span>
                       <span className="text-[10px] text-zinc-500">Browser native check</span>
                    </div>
                  </div>
                  <Toggle active={grammarEnabled} onToggle={() => setGrammarEnabled(!grammarEnabled)} />
                </div>
              </div>

              <div className="space-y-4">
                <SectionHeader title="Clipboard & Wipe" />
                <div className="grid grid-cols-2 gap-2">
                  <ActionButton onClick={() => copyToClipboard('plain')} label="Copy Plain" variant="secondary" />
                  <ActionButton onClick={() => copyToClipboard('markdown')} label="Copy Markdown" variant="secondary" />
                </div>
                <ActionButton onClick={clearDoc} label="Clear Entire Canvas" variant="danger" icon={<Trash2 size={14}/>} />
              </div>
            </div>
          )}
        </div>
      </aside>
    </div>
  );
};

