  <button 
    onMouseDown={(e) => { e.preventDefault(); onClick(); }}
    className="w-10 h-10 flex items-center justify-center hover:bg-zinc-100 dark:hover:bg-zinc-700 text-zinc-500 dark:text-zinc-400 hover:text-blue-500 dark:hover:text-white rounded-lg transition-all"
    title={title}
  >
    {icon}
  </button>
);

