import React, { useState, useEffect, useRef, useMemo, useDeferredValue } from 'react';
import ReactDOM from 'react-dom/client';
import { 
  Bold, Italic, Underline, Heading, 
  List, ListOrdered, Quote, Code, Link as LinkIcon, 
  Trash2, Download, Copy, FileText, BarChart3, 
  Type, Settings, Sun, Moon, Maximize2, Minimize2,
  ChevronRight, Search, Info, RotateCcw, ArrowRightLeft,
  X, ExternalLink, Edit2, ChevronDown, Sparkles,
  Type as TypeIcon, CaseSensitive
} from 'lucide-react';

// --- Types ---
type Tab = 'stats' | 'keywords' | 'tools';
type SEOPhraseTab = 1 | 2 | 3 | 4;
type KeywordDensity = {
  phrase: string;
  count: number;
  percentage: number;
};

// --- Utilities ---
const STOP_WORDS = new Set([
  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'but', 'by', 'for', 'if', 'in', 'into', 'is', 'it', 
  'no', 'not', 'of', 'on', 'or', 'such', 'that', 'the', 'their', 'then', 'there', 'these', 
  'they', 'this', 'to', 'was', 'will', 'with', 'from', 'up', 'down', 'out', 'over', 'under', 
  'again', 'further', 'once', 'here', 'there', 'when', 'where', 'why', 'how', 'all', 'any', 
  'both', 'each', 'few', 'more', 'most', 'other', 'some', 'such', 'nor', 'too', 'very', 's', 't', 
  'can', 'will', 'just', 'don', 'should', 'now', 'has', 'had', 'been', 'being', 'having'
]);

const COMPLEX_WORDS: Record<string, string> = {
  'utilize': 'use', 'implement': 'do', 'commence': 'start', 'terminate': 'end',
  'subsequently': 'later', 'additional': 'more', 'endeavor': 'try', 'ascertain': 'find out',
  'facilitate': 'help', 'advantageous': 'helpful', 'remuneration': 'pay', 'expeditious': 'fast',
  'magnitude': 'size', 'notwithstanding': 'despite',
};

const getHemingwayInsights = (text: string) => {
  const cleanText = text.replace(/<[^>]*>/g, ' ').trim();
  if (!cleanText) return null;

  const sentences = cleanText.split(/[.!?]+/).filter(s => s.trim().length > 0);
  const words = cleanText.split(/\s+/);

  let hardSentences = 0;
  let veryHardSentences = 0;
  let adverbs = 0;
  let passiveVoice = 0;
  let complexWordsFound = 0;

  sentences.forEach(s => {
    const wordCount = s.trim().split(/\s+/).length;
    if (wordCount > 25) veryHardSentences++;
    else if (wordCount > 18) hardSentences++;
  });

  words.forEach(w => {
    const cleanWord = w.toLowerCase().replace(/[^\w]/g, '');
    if (cleanWord.endsWith('ly') && !['only', 'family', 'apply', 'early', 'really', 'silly', 'holy', 'fly', 'rely'].includes(cleanWord)) {
      adverbs++;
    }
    if (COMPLEX_WORDS[cleanWord]) {
      complexWordsFound++;
    }
  });

  const passiveRegex = /\b(am|is|are|was|were|be|been|being)\b\s+(\w+ed)\b/gi;
  const matches = cleanText.match(passiveRegex);
  passiveVoice = matches ? matches.length : 0;

  return {
    totalSentences: sentences.length,
    hardSentences,
    veryHardSentences,
    adverbs,
    passiveVoice,
    complexWordsFound
  };
};

const getStats = (text: string) => {
  const cleanText = text.replace(/<[^>]*>/g, ' ').trim();
  const words = cleanText ? cleanText.split(/\s+/) : [];
  const sentences = cleanText ? cleanText.split(/[.!?]+/).filter(Boolean) : [];
  const paragraphs = text.split(/<\/p>|<\/div>|<br\s*\/?>/).filter(p => p.replace(/<[^>]*>/g, '').trim().length > 0);

  const wordCount = words.length;

  return {
    words: wordCount,
    characters: cleanText.length,
    charactersNoSpaces: cleanText.replace(/\s/g, '').length,
    sentences: sentences.length,
    paragraphs: paragraphs.length,
    readingTime: Math.ceil(wordCount / 200),
    speakingTime: Math.ceil(wordCount / 130),
  };
};

const getKeywords = (text: string, n: number = 1) => {
  const cleanText = text.replace(/<[^>]*>/g, ' ').toLowerCase();
  const tokens = cleanText.replace(/[^\w\s]/g, '').split(/\s+/).filter(t => t.length > 1);
  const totalTokens = tokens.length;

  if (totalTokens === 0) return [];

  const phrases: Record<string, number> = {};

  for (let i = 0; i <= tokens.length - n; i++) {
    const phrase = tokens.slice(i, i + n).join(' ');
    if (n === 1 && STOP_WORDS.has(phrase)) continue;
    if (n > 1 && tokens.slice(i, i + n).every(w => STOP_WORDS.has(w))) continue;

    phrases[phrase] = (phrases[phrase] || 0) + 1;
  }

  return Object.entries(phrases)
    .map(([phrase, count]) => ({
      phrase,
      count,
      percentage: Number(((count * n) / totalTokens * 100).toFixed(2))
    }))
    .sort((a, b) => b.count - a.count);
};

const htmlToMarkdown = (html: string) => {
  let md = html
    .replace(/<h1>(.*?)<\/h1>/gi, '# $1\n\n')
    .replace(/<h2>(.*?)<\/h2>/gi, '## $1\n\n')
    .replace(/<h3>(.*?)<\/h3>/gi, '### $1\n\n')
    .replace(/<h4>(.*?)<\/h4>/gi, '#### $1\n\n')
    .replace(/<b>(.*?)<\/b>/gi, '**$1**')
    .replace(/<strong>(.*?)<\/strong>/gi, '**$1**')
    .replace(/<i>(.*?)<\/i>/gi, '*$1*')
    .replace(/<li>(.*?)<\/li>/gi, '- $1\n')
    .replace(/<p>(.*?)<\/p>/gi, '$1\n\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<blockquote[^>]*>(.*?)<\/blockquote>/gi, '> $1\n\n')
    .replace(/<[^>]*>/g, '');
  return md.trim();
};

