const App = () => {
  const [content, setContent] = useState(() => localStorage.getItem('seo-editor-content') || '<h1>Futuristic SEO Editor</h1><p>Start crafting high-ranking content with real-time analysis.</p>');
  const [isDarkMode, setIsDarkMode] = useState(() => localStorage.getItem('seo-editor-theme') !== 'light');
  const [activeTab, setActiveTab] = useState<Tab>('stats');
  const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
  const [grammarEnabled, setGrammarEnabled] = useState(() => localStorage.getItem('seo-editor-grammar') !== 'false');
  const [isExpanded, setIsExpanded] = useState(false);
  const [activeLink, setActiveLink] = useState<{ element: HTMLAnchorElement, url: string } | null>(null);
  const [fontFamily, setFontFamily] = useState('Inter');
  const [fontSize, setFontSize] = useState('20px');

  const editorRef = useRef<HTMLDivElement>(null);
  const [debouncedContent, setDebouncedContent] = useState(content);
  const deferredContent = useDeferredValue(debouncedContent);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedContent(content);
      localStorage.setItem('seo-editor-content', content);
    }, 500);
    return () => clearTimeout(handler);
  }, [content]);

  useEffect(() => {
    localStorage.setItem('seo-editor-theme', isDarkMode ? 'dark' : 'light');
    if (isDarkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [isDarkMode]);

  const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
  const insights = useMemo(() => getHemingwayInsights(deferredContent), [deferredContent]);
  const currentKeywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);

  const execCommand = (command: string, value: string = '') => {
    if (command === 'createLink') {
      const selection = window.getSelection();
      if (!selection || selection.toString().length === 0) {
        alert("Please select some text first to link it.");
        return;
      }
      const url = prompt("Enter link URL:");
      if (url) document.execCommand(command, false, url);
    } else {
      document.execCommand(command, false, value);
    }
    if (editorRef.current) setContent(editorRef.current.innerHTML);
  };

  const handleEditorClick = (e: React.MouseEvent) => {
    const target = e.target as HTMLElement;
    const anchor = target.closest('a');
    if (anchor) {
      e.preventDefault(); // Stop immediate navigation
      setActiveLink({ element: anchor as HTMLAnchorElement, url: (anchor as HTMLAnchorElement).href });
    } else {
      setActiveLink(null);
    }
  };

  const editLink = () => {
    if (!activeLink) return;
    const newUrl = prompt("Update link URL:", activeLink.url);
    if (newUrl !== null) {
      activeLink.element.href = newUrl;
      if (editorRef.current) setContent(editorRef.current.innerHTML);
      setActiveLink({ ...activeLink, url: newUrl });
    }
  };

  const removeLink = () => {
    if (!activeLink) return;
    const parent = activeLink.element.parentNode;
    if (parent) {
      while (activeLink.element.firstChild) {
        parent.insertBefore(activeLink.element.firstChild, activeLink.element);
      }
      parent.removeChild(activeLink.element);
      if (editorRef.current) setContent(editorRef.current.innerHTML);
      setActiveLink(null);
    }
  };

  const convertCase = (type: 'upper' | 'lower' | 'capitalize' | 'sentence' | 'toggle') => {
    const selection = window.getSelection();
    const textToConvert = selection && selection.toString().length > 0 ? selection.toString() : editorRef.current?.innerText || '';

    let newText = textToConvert;
    switch (type) {
      case 'upper': newText = textToConvert.toUpperCase(); break;
      case 'lower': newText = textToConvert.toLowerCase(); break;
      case 'capitalize': newText = textToConvert.replace(/\b\w/g, l => l.toUpperCase()); break;
      case 'sentence': newText = textToConvert.toLowerCase().replace(/(^\s*\w|[\.\!\?]\s*\w)/g, c => c.toUpperCase()); break;
      case 'toggle': newText = textToConvert.split('').map(c => c === c.toUpperCase() ? c.toLowerCase() : c.toUpperCase()).join(''); break;
    }

    if (selection && selection.toString().length > 0) document.execCommand('insertText', false, newText);
    else if (editorRef.current) editorRef.current.innerText = newText;
    if (editorRef.current) setContent(editorRef.current.innerHTML);
  };

  const exportDoc = (format: 'txt' | 'html' | 'md') => {
    let output = '';
    if (format === 'txt') output = editorRef.current?.innerText || '';
    else if (format === 'html') output = `<!DOCTYPE html><html><head><meta charset="utf-8"></head><body>${content}</body></html>`;
    else output = htmlToMarkdown(content);

    const element = document.createElement("a");
    const file = new Blob([output], {type: 'text/plain'});
    element.href = URL.createObjectURL(file);
    element.download = `seo-content.${format}`;
    document.body.appendChild(element);
    element.click();
    document.body.removeChild(element);
  };

  const copyToClipboard = (type: 'plain' | 'html' | 'markdown') => {
    let text = type === 'plain' ? editorRef.current?.innerText || '' : type === 'html' ? content : htmlToMarkdown(content);
    navigator.clipboard.writeText(text);
  };

