    const selection = window.getSelection();
    const textToConvert = selection && selection.toString().length > 0 ? selection.toString() : editorRef.current?.innerText || '';
    let newText = textToConvert;
    if (type === 'upper') newText = textToConvert.toUpperCase();
    else if (type === 'lower') newText = textToConvert.toLowerCase();
    else if (type === 'capitalize') newText = textToConvert.replace(/\b\w/g, l => l.toUpperCase());
    else if (type === 'sentence') newText = textToConvert.toLowerCase().replace(/(^\s*\w|[\.\!\?]\s*\w)/g, c => c.toUpperCase());
    else if (type === 'toggle') newText = textToConvert.split('').map(c => c === c.toUpperCase() ? c.toLowerCase() : c.toUpperCase()).join('');

    if (selection && selection.toString().length > 0) document.execCommand('insertText', false, newText);
    else if (editorRef.current) editorRef.current.innerText = newText;
    if (editorRef.current) setContent(editorRef.current.innerHTML);
  };

