export interface KeywordDensity {
  phrase: string;
  count: number;
  percentage: number;
}

export interface TextStats {
  words: number;
  pubWords: number;
  sentences: number;
  readingTime: number;
  speakingTime: number;
  characters: number;
}

export interface ReadabilityInsights {
  totalSentences: number;
  hardSentences: number;
  veryHardSentences: number;
  adverbs: number;
  passiveVoice: number;
}

import { TextStats } from '../types/editor.types';

export const getStats = (html: string): TextStats => {
  const cleanText = html.replace(/<[^>]*>/g, ' ').trim();
  const words = cleanText ? cleanText.split(/\s+/) : [];
  const sentences = cleanText ? cleanText.split(/[.!?]+/).filter(Boolean) : [];

  const wordCount = words.length;
  // Publisher Word Count: 6 characters (including spaces) = 1 word
  const pubWords = Math.ceil(cleanText.length / 6);

  return {
    words: wordCount,
    pubWords: pubWords,
    sentences: sentences.length,
    characters: cleanText.length,
    readingTime: Math.ceil(wordCount / 200),
    speakingTime: Math.ceil(wordCount / 130),
  };
};

import { KeywordDensity } from '../types/editor.types';
import { STOP_WORDS } from './stopwords';

export const getKeywords = (html: string, n: number = 1): KeywordDensity[] => {
  const cleanText = html.replace(/<[^>]*>/g, ' ').toLowerCase();
  const tokens = cleanText.replace(/[^\w\s]/g, '').split(/\s+/).filter(t => t.length > 1);
  const totalTokens = tokens.length;

  if (totalTokens === 0) return [];

  const phrases: Record<string, number> = {};

  for (let i = 0; i <= tokens.length - n; i++) {
    const phrase = tokens.slice(i, i + n).join(' ');
    if (n === 1 && STOP_WORDS.has(phrase)) continue;
    if (n > 1 && tokens.slice(i, i + n).every(w => STOP_WORDS.has(w))) continue;

    phrases[phrase] = (phrases[phrase] || 0) + 1;
  }

  return Object.entries(phrases)
    .map(([phrase, count]) => ({
      phrase,
      count,
      percentage: Number(((count * n) / totalTokens * 100).toFixed(2))
    }))
    .sort((a, b) => b.count - a.count);
};

import { ReadabilityInsights } from '../types/editor.types';

export const getReadabilityInsights = (html: string): ReadabilityInsights | null => {
  const cleanText = html.replace(/<[^>]*>/g, ' ').trim();
  if (!cleanText) return null;

  const sentences = cleanText.split(/[.!?]+/).filter(s => s.trim().length > 0);
  const words = cleanText.split(/\s+/);

  let hardSentences = 0;
  let veryHardSentences = 0;
  let adverbs = 0;
  let passiveVoice = 0;

  sentences.forEach(s => {
    const wordCount = s.trim().split(/\s+/).length;
    if (wordCount > 25) veryHardSentences++;
    else if (wordCount > 18) hardSentences++;
  });

  words.forEach(w => {
    const cleanWord = w.toLowerCase().replace(/[^\w]/g, '');
    if (cleanWord.endsWith('ly') && !['only', 'family', 'apply', 'early', 'really', 'silly', 'holy', 'fly', 'rely'].includes(cleanWord)) {
      adverbs++;
    }
  });

  const passiveRegex = /\b(am|is|are|was|were|be|been|being)\b\s+(\w+ed)\b/gi;
  const matches = cleanText.match(passiveRegex);
  passiveVoice = matches ? matches.length : 0;

  return {
    totalSentences: sentences.length,
    hardSentences,
    veryHardSentences,
    adverbs,
    passiveVoice
  };
};

export const convertText = (text: string, type: string): string => {
  switch (type) {
    case 'upper': return text.toUpperCase();
    case 'lower': return text.toLowerCase();
    case 'capitalize': return text.replace(/\b\w/g, l => l.toUpperCase());
    case 'sentence': return text.toLowerCase().replace(/(^\s*\w|[\.\!\?]\s*\w)/g, c => c.toUpperCase());
    case 'toggle': return text.split('').map(c => c === c.toUpperCase() ? c.toLowerCase() : c.toUpperCase()).join('');
    default: return text;
  }
};

export const htmlToMarkdown = (html: string): string => {
  return html
    .replace(/<h1>(.*?)<\/h1>/gi, '# $1\n\n')
    .replace(/<h2>(.*?)<\/h2>/gi, '## $1\n\n')
    .replace(/<h3>(.*?)<\/h3>/gi, '### $1\n\n')
    .replace(/<b>(.*?)<\/b>/gi, '**$1**')
    .replace(/<strong>(.*?)<\/strong>/gi, '**$1**')
    .replace(/<i>(.*?)<\/i>/gi, '*$1*')
    .replace(/<p>(.*?)<\/p>/gi, '$1\n\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]*>/g, '')
    .trim();
};

