const TabButton = ({ active, onClick, label, icon }: any) => (
  <button onClick={onClick} className={`flex-1 flex flex-col items-center justify-center gap-1 text-[10px] font-black uppercase tracking-tighter relative py-4 ${active ? 'text-blue-500' : 'text-zinc-500'}`}>
