import { TextStats, HeadingNode } from '../types/editor.types';

export const getStats = (html: string): TextStats => {
  const cleanText = html.replace(/<[^>]*>/g, ' ').trim();
  const words = cleanText ? cleanText.split(/\s+/) : [];
  const sentences = cleanText ? cleanText.split(/[.!?]+/).filter(Boolean) : [];

  const wordCount = words.length;
  const pubWords = Math.ceil(cleanText.length / 6);
  const paragraphsCount = cleanText ? html.split(/<\/p>|<div>/i).filter(p => p.replace(/<[^>]*>/g, '').trim().length > 0).length : 0;

  // Entity detection (Simple heuristic: capitalized words not at start of sentence)
  const entities = extractEntities(cleanText);

  // Heading tree extraction
  const headingTree = extractHeadingTree(html);

  return {
    words: wordCount,
    pubWords: pubWords,
    sentences: sentences.length,
    characters: cleanText.length,
    readingTime: Math.ceil(wordCount / 200),
    speakingTime: Math.ceil(wordCount / 130),
    paragraphs: paragraphsCount || (cleanText ? 1 : 0),
    entities,
    headingTree
  };
};

const extractEntities = (text: string): string[] => {
  // Regex for capitalized words. Avoid first words of sentences roughly.
  // This is a browser-side approximation.
  const words = text.split(/\s+/);
  const detected = new Set<string>();
  const commonExclusions = new Set(['The', 'A', 'An', 'This', 'That', 'These', 'Those', 'It', 'My', 'Your', 'His', 'Her', 'Our', 'They', 'And', 'But', 'Or', 'If']);

  for (let i = 1; i < words.length; i++) {
    const word = words[i].replace(/[^\w]/g, '');
    if (word.length > 2 && /^[A-Z]/.test(word) && !commonExclusions.has(word)) {
      detected.add(word);
    }
  }
  return Array.from(detected).slice(0, 15);
};

const extractHeadingTree = (html: string): HeadingNode[] => {
  const parser = new DOMParser();
  const doc = parser.parseFromString(html, 'text/html');
  const headings = doc.querySelectorAll('h1, h2, h3, h4, h5, h6');
  return Array.from(headings).map(h => ({
    tag: h.tagName.toLowerCase(),
    text: h.textContent?.trim() || 'Empty Heading',
    level: parseInt(h.tagName.substring(1))
  }));
};

import { SEOHealth, KeywordDensity, SEOChecklistItem, KeywordTarget } from '../types/editor.types';

export const analyzeSEOHealth = (
  html: string, 
  keywords: KeywordDensity[], 
  targets: KeywordTarget,
  metaDescription: string
): SEOHealth => {
  const warnings: string[] = [];
  const checklist: SEOChecklistItem[] = [];
  let score = 100;

  const cleanText = html.replace(/<[^>]*>/g, ' ').trim();
  const first100Words = cleanText.split(/\s+/).slice(0, 100).join(' ').toLowerCase();
  const primaryK = targets.primary.toLowerCase();

  // 1. Primary Keyword Checks
  if (primaryK) {
    // In H1
    const h1Match = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
    const hasInH1 = h1Match ? h1Match[1].toLowerCase().includes(primaryK) : false;
    checklist.push({ label: `Primary keyword in H1`, passed: hasInH1, impact: 'critical' });
    if (!hasInH1) score -= 15;

    // In First 100 words
    const hasInIntro = first100Words.includes(primaryK);
    checklist.push({ label: `Primary keyword in intro (first 100 words)`, passed: hasInIntro, impact: 'moderate' });
    if (!hasInIntro) score -= 10;

    // In Meta Description
    const hasInMeta = metaDescription.toLowerCase().includes(primaryK);
    checklist.push({ label: `Primary keyword in meta description`, passed: hasInMeta, impact: 'moderate' });
    if (!hasInMeta) score -= 10;

    // In at least one H2
    const h2Matches = html.match(/<h2[^>]*>([\s\S]*?)<\/h2>/gi) || [];
    const hasInH2 = h2Matches.some(h => h.toLowerCase().includes(primaryK));
    checklist.push({ label: `Primary keyword in at least one H2`, passed: hasInH2, impact: 'moderate' });
    if (!hasInH2) score -= 5;
  }

  // 2. Structural Checks
  const h1Count = (html.match(/<h1/gi) || []).length;
  if (h1Count === 0) { warnings.push("Missing H1 title tag."); score -= 20; }
  if (h1Count > 1) { warnings.push("Multiple H1 tags detected."); score -= 15; }

  const h2Count = (html.match(/<h2/gi) || []).length;
  const h3Count = (html.match(/<h3/gi) || []).length;
  if (h2Count === 0 && h3Count === 0) { warnings.push("Lack of sub-heading structure (H2/H3)."); score -= 10; }

  // 3. Keyword Stuffing
  const overUsed = keywords.filter(k => k.percentage > 3);
  if (overUsed.length > 0) {
    warnings.push(`Keyword stuffing detected: "${overUsed[0].phrase}".`);
    score -= 15;
  }

  // 4. Content Length
  const wordCount = cleanText.split(/\s+/).length;
  if (wordCount < 300) { warnings.push("Content is thin (<300 words)."); score -= 15; }

  score = Math.max(0, score);

  let status: SEOHealth['status'] = 'excellent';
  if (score < 50) status = 'poor';
  else if (score < 70) status = 'fair';
  else if (score < 90) status = 'good';

  return { score, warnings, status, checklist };
};

import React, { useState, useEffect, useRef, useMemo, useDeferredValue } from 'react';
import ReactDOM from 'react-dom/client';
import { 
  Sun, Moon, Download, Edit2, ExternalLink, X, Sparkles 
} from 'lucide-react';

import { getStats } from './core/text-analysis';
import { getKeywords } from './core/keyword-density';
import { getReadabilityScore } from './core/readability';
import { analyzeSEOHealth } from './core/seo-health';
import { detectIntent } from './core/intent-detector';
import { convertText } from './core/case-converter';
import { rewriteContent } from './ai/ai-engine';
import { htmlToMarkdown } from './utils/text-cleaner';

import { Toolbar } from './components/editor/Toolbar';
import { Sidebar } from './components/layout/Sidebar';
import { Tab, SEOPhraseTab, KeywordTarget } from './types/editor.types';

const App = () => {
  const [content, setContent] = useState(() => localStorage.getItem('seo-editor-content') || '<h1>SEO Focus Pro</h1><p>Start crafting optimized, AI-enhanced content here. Select text to rewrite or use the tabs on the right to analyze your performance in real-time.</p>');
  const [isDarkMode, setIsDarkMode] = useState(() => localStorage.getItem('seo-editor-theme') !== 'light');
  const [activeTab, setActiveTab] = useState<Tab>('keywords'); // Start on keywords to show new features
  const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
  const [isExpanded, setIsExpanded] = useState(false);
  const [activeLink, setActiveLink] = useState<{ element: HTMLAnchorElement, url: string } | null>(null);
  const [fontFamily, setFontFamily] = useState('Inter');
  const [fontSize, setFontSize] = useState('18px');
  const [isAIProcessing, setIsAIProcessing] = useState(false);

  // Keyword Targeting State
  const [targets, setTargets] = useState<KeywordTarget>(() => {
    const saved = localStorage.getItem('seo-targets');
    return saved ? JSON.parse(saved) : { primary: '', secondary: ['', '', ''] };
  });
  const [metaDescription, setMetaDescription] = useState(() => localStorage.getItem('seo-meta') || '');

  const editorRef = useRef<HTMLDivElement>(null);
  const [debouncedContent, setDebouncedContent] = useState(content);
  const deferredContent = useDeferredValue(debouncedContent);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedContent(content);
      localStorage.setItem('seo-editor-content', content);
      localStorage.setItem('seo-targets', JSON.stringify(targets));
      localStorage.setItem('seo-meta', metaDescription);
    }, 500);
    return () => clearTimeout(handler);
  }, [content, targets, metaDescription]);

  useEffect(() => {
    if (isDarkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
    localStorage.setItem('seo-editor-theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
  const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
  const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
  const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, targets, metaDescription), [deferredContent, keywords, targets, metaDescription]);
  const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);

  const execCommand = (command: string, value: string = '') => {
    if (editorRef.current) {
      editorRef.current.focus();
    }

    if (command === 'createLink') {
      const selection = window.getSelection();
      if (!selection || selection.rangeCount === 0) return;

      let containerNode = selection.anchorNode;
      let existingLink: HTMLAnchorElement | null = null;

      while (containerNode && containerNode !== editorRef.current) {
        if (containerNode.nodeName === 'A') {
          existingLink = containerNode as HTMLAnchorElement;
          break;
        }
        containerNode = containerNode.parentNode;
      }

      if (existingLink) {
        const currentUrl = existingLink.getAttribute('href') || '';
        const action = prompt(`Existing Link Found: ${currentUrl}\n\nEnter new URL to edit, or leave blank to remove the link:`, currentUrl);

        if (action === null) return; 

        if (action === '') {
          const text = existingLink.textContent || '';
          const textNode = document.createTextNode(text);
          existingLink.parentNode?.replaceChild(textNode, existingLink);
        } else {
          existingLink.setAttribute('href', action);
        }
      } else {
        if (selection.toString().length === 0) {
          alert("Please select some text to create a link.");
          return;
        }
        const url = prompt("Enter link URL:", "https://");
        if (url) {
          document.execCommand('createLink', false, url);
        }
      }
    } else {
      document.execCommand(command, false, value);
    }

    if (editorRef.current) {
      setContent(editorRef.current.innerHTML);
    }
  };

  const handlePaste = (e: React.ClipboardEvent | React.MouseEvent) => {
    if ('clipboardData' in e) {
      e.preventDefault();
      const text = e.clipboardData.getData('text/plain');
      document.execCommand('insertText', false, text);
    } 
    if (editorRef.current) setContent(editorRef.current.innerHTML);
  };

  const updateActiveLinkStatus = () => {
    const selection = window.getSelection();
    if (selection && selection.rangeCount > 0) {
      let node = selection.getRangeAt(0).startContainer;
      let parent: HTMLElement | null = node.nodeType === 3 ? node.parentElement : node as HTMLElement;

      while (parent && parent !== editorRef.current) {
        if (parent.tagName === 'A') {
          setActiveLink({ element: parent as HTMLAnchorElement, url: (parent as HTMLAnchorElement).href });
          return;
        }
        parent = parent.parentElement;
      }
    }
    setActiveLink(null);
  };

  const onRewrite = async (mode: any) => {
    const selection = window.getSelection();
    const textToProcess = (selection && selection.toString().length > 0) 
      ? selection.toString() 
      : editorRef.current?.innerText || '';

    if (!textToProcess) {
      alert("Please select or type some content to rewrite.");
      return;
    }

    setIsAIProcessing(true);
    try {
      const result = await rewriteContent(textToProcess, mode);
      if (selection && selection.toString().length > 0) {
        document.execCommand('insertText', false, result);
      } else if (editorRef.current) {
        editorRef.current.innerText = result;
      }
      if (editorRef.current) setContent(editorRef.current.innerHTML);
    } catch (err) {
      console.error(err);
      alert("AI rewrite failed. Check your connection.");
    } finally {
      setIsAIProcessing(false);
    }
  };

  const onConvertCase = (type: string) => {
    const selection = window.getSelection();
    const textToConvert = selection && selection.toString().length > 0 ? selection.toString() : editorRef.current?.innerText || '';
    const newText = convertText(textToConvert, type);
    if (selection && selection.toString().length > 0) document.execCommand('insertText', false, newText);
    else if (editorRef.current) editorRef.current.innerText = newText;
    if (editorRef.current) setContent(editorRef.current.innerHTML);
  };

  const onCopy = async (type: 'plain' | 'markdown') => {
    const textToCopy = type === 'plain' ? (editorRef.current?.innerText || '') : htmlToMarkdown(content);
    try {
      await navigator.clipboard.writeText(textToCopy);
    } catch (err) {
      alert("Copy failed.");
    }
  };

  const onClear = () => {
    if (confirm("Reset current document?")) {
      setContent("");
      if (editorRef.current) editorRef.current.innerHTML = "";
    }
  };

  const fontFamilies: Record<string, string> = {
    'Inter': "'Inter', sans-serif",
    'Georgia': "Georgia, serif",
    'monospace': "monospace"
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-white dark:bg-zinc-950 text-zinc-900 dark:text-zinc-100 transition-colors duration-300">

      <div className="flex-1 flex flex-col relative overflow-hidden">
        <header className="h-16 border-b border-zinc-200 dark:border-zinc-800 flex items-center justify-between px-6 glass-panel z-30 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-600 rounded-xl flex items-center justify-center font-black text-white shadow-lg relative">
              S
              {isAIProcessing && <div className="absolute -top-1 -right-1 w-3 h-3 bg-white rounded-full flex items-center justify-center text-[8px] text-blue-600 animate-pulse shadow-sm"><Sparkles size={8}/></div>}
            </div>
            <h1 className="font-bold text-lg tracking-tight hidden sm:block uppercase">SEO Focus <span className="text-zinc-400">Pro</span></h1>
          </div>
          <div className="flex items-center gap-2">
            <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-xl text-zinc-500 transition-colors">
              {isDarkMode ? <Sun size={20} /> : <Moon size={20} />}
            </button>
            <button onClick={() => {
              const element = document.createElement("a");
              const file = new Blob([content], {type: 'text/html'});
              element.href = URL.createObjectURL(file);
              element.download = "seo-content.html";
              element.click();
            }} className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-500 text-white rounded-xl text-sm font-bold shadow-lg transition-all hover:scale-105 active:scale-95">
              <Download size={16} />
              <span className="hidden sm:inline">Export</span>
            </button>
          </div>
        </header>

        <Toolbar 
          onCommand={execCommand} 
          onPaste={handlePaste} 
          fontFamily={fontFamily} 
          fontSize={fontSize} 
          setFontFamily={setFontFamily} 
          setFontSize={setFontSize} 
        />

        <main className="flex-1 overflow-y-auto p-6 md:p-12 lg:p-16 flex justify-center custom-scrollbar bg-zinc-50 dark:bg-zinc-950">
          <div className="w-full max-w-4xl relative">
            {activeLink && (
              <div 
                className="fixed bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 shadow-2xl rounded-xl p-2 flex items-center gap-2 z-[99] animate-in zoom-in-95"
                style={{ 
                  top: activeLink.element.getBoundingClientRect().bottom + window.scrollY + 8,
                  left: activeLink.element.getBoundingClientRect().left
                }}
              >
                <div className="text-xs text-blue-500 font-bold px-3 truncate max-w-[200px]">{activeLink.url}</div>
                <div className="w-[1px] h-4 bg-zinc-200 dark:bg-zinc-800" />
                <button onClick={() => {
                  const newUrl = prompt("Update link URL:", activeLink.url);
                  if (newUrl !== null) {
                    activeLink.element.href = newUrl;
                    if (editorRef.current) setContent(editorRef.current.innerHTML);
                    setActiveLink({ ...activeLink, url: newUrl });
                  }
                }} className="p-2 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-lg text-zinc-500 transition-colors" title="Edit Link"><Edit2 size={14} /></button>
                <button onClick={() => window.open(activeLink.url, '_blank')} className="p-2 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-lg text-zinc-500 transition-colors" title="Open Link"><ExternalLink size={14} /></button>
                <button onClick={() => {
                  const parent = activeLink.element.parentNode;
                  if (parent) {
                    while (activeLink.element.firstChild) parent.insertBefore(activeLink.element.firstChild, activeLink.element);
                    parent.removeChild(activeLink.element);
                    if (editorRef.current) setContent(editorRef.current.innerHTML);
                    setActiveLink(null);
                  }
                }} className="p-2 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-lg text-red-500 transition-colors" title="Remove Link"><X size={14} /></button>
              </div>
            )}
            <div
              ref={editorRef}
              contentEditable
              onInput={(e) => setContent(e.currentTarget.innerHTML)}
              onPaste={handlePaste as any}
              onKeyUp={updateActiveLinkStatus}
              onMouseUp={updateActiveLinkStatus}
              onClick={(e) => {
                const target = e.target as HTMLElement;
                const anchor = target.closest('a');
                if (anchor) {
                  e.preventDefault();
                  e.stopPropagation();
                  setActiveLink({ element: anchor as HTMLAnchorElement, url: (anchor as HTMLAnchorElement).href });
                } else {
                  setActiveLink(null);
                }
              }}
              dangerouslySetInnerHTML={{ __html: content }}
              style={{ fontFamily: fontFamilies[fontFamily], fontSize: fontSize }}
              className="editor-content min-h-[75vh] focus:outline-none text-zinc-800 dark:text-zinc-300 leading-relaxed font-normal"
            />
          </div>
        </main>
      </div>

      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        stats={stats} 
        readability={readability}
        health={health}
        intent={intent}
        keywords={keywords} 
        seoTab={seoTab} 
        setSeoTab={setSeoTab} 
        isExpanded={isExpanded} 
        setIsExpanded={setIsExpanded} 
        onRewrite={onRewrite}
        onConvertCase={onConvertCase} 
        onCopy={onCopy} 
        onClear={onClear} 
        isAIProcessing={isAIProcessing}
        targets={targets}
        setTargets={setTargets}
        metaDescription={metaDescription}
        setMetaDescription={setMetaDescription}
      />
    </div>
  );
};

