              <div className="space-y-3">
                <div className="relative">
                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-blue-500"><Target size={14}/></span>
                  <input 
                    type="text" 
                    placeholder="Primary Keyword..." 
                    value={targets.primary}
                    onChange={(e) => setTargets({ ...targets, primary: e.target.value })}
                    className="w-full bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-xl py-2.5 pl-10 pr-4 text-sm focus:border-blue-500 outline-none transition-all font-bold"
                  />
                </div>
                <div className="space-y-2">
                   {targets.secondary.map((val, idx) => (
                     <input 
                      key={idx}
                      type="text" 
                      placeholder={`Secondary Keyword ${idx + 1}...`} 
                      value={val}
                      onChange={(e) => {
                        const newSec = [...targets.secondary];
                        newSec[idx] = e.target.value;
                        setTargets({ ...targets, secondary: newSec });
                      }}
                      className="w-full bg-zinc-100 dark:bg-zinc-800/50 border border-transparent rounded-xl py-2 px-4 text-xs focus:border-blue-500/50 outline-none transition-all"
                    />
