            <div>
              <SectionHeader title="SERP Snippet" />
              <div className="space-y-2">
                <label className="text-[9px] font-bold text-zinc-400 uppercase ml-1">Meta Description</label>
                <textarea 
                  rows={3}
                  value={metaDescription}
                  onChange={(e) => setMetaDescription(e.target.value)}
                  placeholder="Paste your meta description here for SEO analysis..."
                  className="w-full bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-xl p-3 text-xs outline-none focus:border-blue-500 transition-all resize-none leading-relaxed"
                />
                <div className={`text-[9px] text-right font-bold ${metaDescription.length > 160 ? 'text-red-500' : 'text-zinc-400'}`}>
                  {metaDescription.length} / 160 characters
                </div>
              </div>
            </div>

            {targets.primary && (
              <div className="space-y-3 pt-4 border-t border-zinc-200 dark:border-zinc-800">
                <SectionHeader title="Targeting Checklist" />
                <div className="space-y-2">
                  {health.checklist.map((item, i) => (
                    <div key={i} className="flex items-center justify-between p-3 bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-xl">
