            <div className="pt-4 border-t border-zinc-200 dark:border-zinc-800">
              <SectionHeader title="Frequency Analysis" />
              <div className="flex bg-zinc-200 dark:bg-zinc-800 p-1 rounded-xl gap-1 shrink-0 mb-4">
                {[1, 2, 3, 4].map(num => (
                  <button key={num} onClick={() => { setSeoTab(num as SEOPhraseTab); setIsExpanded(false); }} className={`flex-1 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${seoTab === num ? 'bg-white dark:bg-zinc-700 text-blue-500 shadow-sm' : 'text-zinc-500'}`}>{num} Phrase</button>
                ))}
              </div>
              <div className={`rounded-2xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 shadow-sm transition-all duration-300 ${isExpanded ? 'max-h-[60vh] overflow-y-auto custom-scrollbar' : 'overflow-hidden'}`}>
                <table className="w-full text-left text-xs">
                  <thead className="bg-zinc-50 dark:bg-zinc-800/50 text-[9px] font-black text-zinc-400 border-b dark:border-zinc-800 sticky top-0 z-10">
                    <tr><th className="px-4 py-3">PHRASE</th><th className="px-4 py-3 text-right">#</th><th className="px-4 py-3 text-right">%</th></tr>
                  </thead>
                  <tbody className="divide-y divide-zinc-100 dark:divide-zinc-800">
                    {(isExpanded ? keywords : keywords.slice(0, 15)).map((item, idx) => (
                      <tr key={idx} className="hover:bg-zinc-50 dark:hover:bg-zinc-800/20 transition-colors">
                        <td className="px-4 py-3 font-medium truncate max-w-[140px] text-zinc-600 dark:text-zinc-400">{item.phrase}</td>
                        <td className="px-4 py-3 text-right text-zinc-400 font-mono">{item.count}</td>
