                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              {keywords.length > 15 && (
                <button onClick={() => setIsExpanded(!isExpanded)} className="w-full py-3 text-[10px] font-black uppercase text-blue-500 flex items-center justify-center gap-2 shrink-0 hover:bg-blue-500/5 rounded-xl transition-colors mt-2">
                  {isExpanded ? 'Show Less' : `View all ${keywords.length} phrases`}
                  <ChevronDown className={`transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} size={14} />
                </button>
              )}
            </div>
          </div>
        )}

        {activeTab === 'seo-health' && (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-2">
            <SectionHeader title="SEO Health Score" />
            <div className="p-6 bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-3xl text-center shadow-sm">
              <div className="text-6xl font-black tracking-tighter mb-1" style={{ color: health.score > 80 ? '#10b981' : health.score > 60 ? '#f59e0b' : '#ef4444' }}>{health.score}</div>
              <div className="text-[10px] font-bold text-zinc-400 uppercase tracking-widest">Optimization Level</div>
            </div>

            <div className="space-y-3">
              <h4 className="text-[9px] font-bold text-zinc-400 uppercase ml-2 mb-2">Structure & Content Warnings</h4>
              {health.warnings.length > 0 ? health.warnings.map((w, i) => (
                <div key={i} className="p-4 bg-amber-500/5 border border-amber-500/20 rounded-2xl flex items-start gap-3 animate-in slide-in-from-bottom-1">
                  <AlertCircle size={14} className="text-amber-500 shrink-0 mt-0.5" />
                  <span className="text-[11px] font-medium text-amber-700 dark:text-amber-300 leading-snug">{w}</span>
                </div>
              )) : (
                <div className="p-4 bg-emerald-500/5 border border-emerald-500/20 rounded-2xl flex items-start gap-3">
                  <CheckCircle2 size={14} className="text-emerald-500 shrink-0 mt-0.5" />
                  <span className="text-[11px] font-medium text-emerald-700 dark:text-emerald-300">Your content is perfectly structured!</span>
                </div>
              )}
            </div>

            <div className="space-y-3 pt-6 border-t border-zinc-200 dark:border-zinc-800">
              <SectionHeader title="Intent Analysis" />
              <div className="p-5 bg-zinc-100 dark:bg-zinc-900 rounded-2xl border border-zinc-200 dark:border-zinc-800 flex items-center justify-between">
