      let node = selection.getRangeAt(0).startContainer;
      let parent: HTMLElement | null = node.nodeType === 3 ? node.parentElement : node as HTMLElement;

      while (parent && parent !== editorRef.current) {
        if (parent.tagName === 'A') {
          setActiveLink({ element: parent as HTMLAnchorElement, url: (parent as HTMLAnchorElement).href });
          return;
