                  alert("Schema copied to clipboard!");
                }}
                className="flex-1 py-3 bg-blue-600 text-white rounded-2xl font-bold uppercase text-xs tracking-widest shadow-lg shadow-blue-500/20"
              >
                Copy to Clipboard
              </button>
              <button onClick={() => setShowSchema(false)} className="px-6 py-3 border border-zinc-200 dark:border-zinc-800 rounded-2xl font-bold uppercase text-xs tracking-widest">
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="flex-1 flex flex-col relative overflow-hidden h-full">
        <header className="h-16 border-b border-zinc-200 dark:border-zinc-800 flex items-center justify-between px-6 glass-panel z-30 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-600 rounded-xl flex items-center justify-center font-black text-white shadow-lg relative">S</div>
