              {isDarkMode ? <Sun size={20} /> : <Moon size={20} />}
            </button>
            <button onClick={() => {
              const element = document.createElement("a");
              const file = new Blob([content], {type: 'text/html'});
              element.href = URL.createObjectURL(file);
              element.download = "seo-content.html";
              element.click();
            }} className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-500 text-white rounded-xl text-sm font-bold shadow-lg transition-all hover:scale-105 active:scale-95">
              <Download size={16} />
              <span className="hidden sm:inline">Export</span>
            </button>
          </div>
        </header>

        <Toolbar onCommand={execCommand} onPaste={handlePaste as any} fontFamily={fontFamily} fontSize={fontSize} setFontFamily={setFontFamily} setFontSize={setFontSize} />

        <main className="flex-1 overflow-y-auto p-6 md:p-12 lg:p-16 flex flex-col items-center custom-scrollbar bg-zinc-50 dark:bg-zinc-950 relative">
          <div className="w-full max-w-4xl relative pb-32">
            <div
              ref={editorRef}
              contentEditable
              onInput={(e) => setContent(e.currentTarget.innerHTML)}
              onPaste={handlePaste}
              onKeyUp={updateActiveLinkStatus}
              onMouseUp={updateActiveLinkStatus}
              dangerouslySetInnerHTML={{ __html: content }}
              style={{ fontFamily: fontFamilies[fontFamily], fontSize: fontSize }}
              className="editor-content w-full min-h-[50vh] focus:outline-none text-zinc-800 dark:text-zinc-300 leading-relaxed font-normal"
            />
          </div>
        </main>
      </div>

      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        stats={stats} 
        readability={readability}
        health={health}
        intent={intent}
        keywords={keywords} 
        seoTab={seoTab} 
        setSeoTab={setSeoTab} 
        isExpanded={isExpanded} 
        setIsExpanded={setIsExpanded} 
        onRewrite={onRewrite}
        onConvertCase={onConvertCase} 
        onCopy={onCopy} 
        onClear={onClear} 
        isAIProcessing={isAIProcessing}
        targets={targets}
        setTargets={setTargets}
        metaTitle={metaTitle}
        setMetaTitle={setMetaTitle}
        metaDescription={metaDescription}
        setMetaDescription={setMetaDescription}
        faqs={faqs}
        setFaqs={setFaqs}
        onGenerateMetadata={handleGenerateMetadata}
        onDetectAI={handleAIDetection}
        onGenerateFAQs={handleGenerateFAQs}
        onExportSchema={() => setShowSchema(true)}
      />
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root')!);
