}

const TabButton = ({ active, onClick, label, icon }: any) => (
  <button onClick={onClick} className={`flex-1 flex flex-col items-center justify-center gap-1 text-[10px] font-black uppercase tracking-tighter relative py-4 transition-all ${active ? 'text-blue-500' : 'text-zinc-500'}`}>
    {icon}
    <span className="hidden lg:inline">{label}</span>
    {active && <div className="absolute bottom-0 left-2 right-2 h-1 bg-blue-500 rounded-t-full animate-in fade-in zoom-in-50" />}
  </button>
);

const StatCard = ({ label, value }: any) => (
  <div className="p-4 bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-2xl shadow-sm">
    <div className="text-[10px] font-bold text-zinc-400 uppercase mb-1 tracking-tight">{label}</div>
    <div className="text-xl font-black tracking-tight">{value}</div>
  </div>
);

const SectionHeader = ({ title }: { title: string }) => (
  <h3 className="text-[10px] font-black text-zinc-400 uppercase tracking-[0.2em] mb-4">{title}</h3>
);

const ActionButton = ({ onClick, label, variant = 'primary', icon, className, disabled }: any) => {
  const styles: any = {
    primary: 'bg-white dark:bg-zinc-900 text-zinc-800 dark:text-zinc-200 border-zinc-200 dark:border-zinc-800 hover:border-blue-500 shadow-sm',
    secondary: 'bg-zinc-100 dark:bg-zinc-800 text-zinc-600 dark:text-zinc-400 border-transparent hover:bg-zinc-200 dark:hover:bg-zinc-700',
    danger: 'bg-red-500/10 text-red-500 border-red-500/20 hover:bg-red-500/20',
    ai: 'bg-blue-600 text-white border-transparent hover:bg-blue-500 shadow-lg shadow-blue-500/20'
  };
  return (
    <button 
      onClick={onClick} 
      disabled={disabled}
      className={`w-full py-3 px-4 rounded-2xl text-[11px] font-bold border transition-all flex items-center justify-center gap-2 uppercase tracking-wider disabled:opacity-50 ${styles[variant]} ${className}`}
    >
      {icon}{label}
    </button>
  );
};

