              <ActionButton onClick={() => onRewrite('humanize')} label="Humanize AI Text" icon={<ScanEye size={14}/>} disabled={isAIProcessing} variant="secondary" />
              <ActionButton onClick={() => onRewrite('remove_fluff')} label="Remove Fluff" icon={<Trash2 size={14}/>} disabled={isAIProcessing} variant="secondary" />
