              <div className="grid grid-cols-2 gap-2">
                <ActionButton onClick={() => onConvertCase('upper')} label="UPPERCASE" variant="secondary" />
                <ActionButton onClick={() => onConvertCase('lower')} label="lowercase" variant="secondary" />
                <ActionButton onClick={() => onConvertCase('capitalize')} label="Capitalize Each" variant="secondary" />
                <ActionButton onClick={() => onConvertCase('sentence')} label="Sentence case" variant="secondary" />
              </div>
            </div>
            <div>
              <SectionHeader title="Data Operations" />
              <div className="grid grid-cols-1 gap-2">
                <ActionButton onClick={() => onCopy('plain')} label="Copy Plain Text" icon={<Copy size={12}/>} variant="primary" />
                <ActionButton onClick={() => {
                   const html = document.querySelector('.editor-content')?.innerHTML || '';
                   navigator.clipboard.writeText(html).then(() => alert("HTML copied to clipboard"));
                }} label="Copy HTML Code" icon={<Code size={12}/>} variant="primary" />
                <ActionButton onClick={() => onCopy('markdown')} label="Copy Markdown" icon={<Copy size={12}/>} variant="primary" />
                <div className="pt-4">
                  <ActionButton onClick={onClear} label="Reset Document" variant="danger" icon={<Trash2 size={14}/>} />
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </aside>
  );
};

import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export type RewriteMode = 
  | 'clarity' 
  | 'concise' 
  | 'expand_examples' 
  | 'add_stats' 
  | 'authoritative' 
  | 'humanize' 
  | 'remove_fluff' 
  | 'conversational' 
  | 'formal' 
  | 'active_voice'
  | 'expand'
  | 'shorten';

export const rewriteContent = async (text: string, mode: RewriteMode, customPrompt?: string): Promise<string> => {
  const ai = getAI();
  const modePrompts: Record<RewriteMode, string> = {
    clarity: "Rewrite the following text for maximum clarity, ensuring it's easy to follow while maintaining the original message.",
    concise: "Make the following text as concise as possible. Remove redundant words and shorten sentences without losing meaning.",
    expand_examples: "Expand the following content by adding relevant, illustrative examples that help clarify the points made.",
    add_stats: "Incorporate realistic (placeholder format like [X%]) statistics and data points into the text to boost its credibility.",
    authoritative: "Rewrite the text in an authoritative, expert tone. Use decisive language and establish high topical authority.",
    humanize: "Adjust the tone of the text to sound more human and less like a machine. Vary sentence length and use more natural expressions.",
    remove_fluff: "Identify and remove all 'filler' content, flowery adjectives, and unnecessary fluff from the following text.",
    conversational: "Rewrite the text in a friendly, conversational tone, as if talking directly to a peer.",
    formal: "Convert the following text into a professional, formal business tone suitable for corporate environments.",
    active_voice: "Convert all passive voice sentences in the following text into active voice for more direct and impactful writing.",
    expand: "Elaborate on the following text to provide more depth, detail, and context while maintaining the original tone.",
    shorten: "Drastically shorten the following text while preserving the core message and primary information."
  };

  const instruction = customPrompt || modePrompts[mode];

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `${instruction}\n\nText to process:\n"${text}"\n\nReturn ONLY the processed text with NO meta-talk.`,
    config: { temperature: 0.7 }
  });

  return response.text || text;
};

export const generateMetadata = async (content: string, type: 'title' | 'description'): Promise<string> => {
  const ai = getAI();
  const prompt = type === 'title' 
    ? "Generate a compelling, SEO-optimized Meta Title (max 60 characters) for the following content. Return ONLY the title."
    : "Generate a compelling, SEO-optimized Meta Description (max 160 characters) for the following content. Return ONLY the description.";

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `${prompt}\n\nContent:\n${content.substring(0, 3000)}`,
    config: { temperature: 0.8 }
  });

  return response.text?.trim() || "";
};

export const generateFAQs = async (content: string): Promise<any[]> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Generate 5 relevant Frequently Asked Questions and detailed answers based on the following content. Provide the output in a clean JSON array of objects with 'question' and 'answer' keys. Content: ${content.substring(0, 4000)}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            question: { type: Type.STRING },
            answer: { type: Type.STRING }
          },
          required: ["question", "answer"]
        }
      }
    }
  });

  try {
    return JSON.parse(response.text || "[]");
  } catch (e) {
    console.error("Failed to parse FAQ JSON", e);
    return [];
  }
};

export const detectAIContent = async (text: string): Promise<{ score: number, analysis: string }> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Analyze the following text for AI-generated patterns (perplexity, burstiness, linguistic consistency). 
    Provide:
    1. A probability score (0-100) where 100 is definitely AI.
    2. A short 1-sentence explanation of why.

    Return in format: SCORE: [number] | REASON: [text]

    Text: "${text.substring(0, 2000)}"`,
    config: { temperature: 0.1 }
  });

  const raw = response.text || "SCORE: 0 | REASON: Analysis failed";
  const scoreMatch = raw.match(/SCORE:\s*(\d+)/i);
  const reasonMatch = raw.match(/REASON:\s*(.*)/i);

  return {
    score: scoreMatch ? parseInt(scoreMatch[1]) : 0,
    analysis: reasonMatch ? reasonMatch[1].trim() : "Unable to analyze content."
  };
};

import React, { useState, useEffect, useRef, useMemo, useDeferredValue } from 'react';
import ReactDOM from 'react-dom/client';
import { 
  Sun, Moon, Download, Edit2, ExternalLink, X, Sparkles, Plus, Minus
} from 'lucide-react';

import { getStats } from './core/text-analysis';
import { getKeywords } from './core/keyword-density';
import { getReadabilityScore } from './core/readability';
import { analyzeSEOHealth } from './core/seo-health';
import { detectIntent } from './core/intent-detector';
import { convertText } from './core/case-converter';
import { rewriteContent, generateMetadata, detectAIContent, RewriteMode, generateFAQs } from './ai/ai-engine';
import { htmlToMarkdown } from './utils/text-cleaner';

import { Toolbar } from './components/editor/Toolbar';
import { Sidebar } from './components/layout/Sidebar';
import { Tab, SEOPhraseTab, KeywordTarget, FAQ } from './types/editor.types';

const App = () => {
  const [content, setContent] = useState(() => localStorage.getItem('seo-editor-content') || '<h1>SEO Focus Pro</h1><p>Start crafting optimized, AI-enhanced content here. Select text to rewrite or use the tabs on the right to analyze your performance in real-time.</p>');
  const [isDarkMode, setIsDarkMode] = useState(() => localStorage.getItem('seo-editor-theme') !== 'light');
  const [activeTab, setActiveTab] = useState<Tab>('insights'); 
  const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
  const [isExpanded, setIsExpanded] = useState(false);
  const [activeLink, setActiveLink] = useState<{ element: HTMLAnchorElement, url: string } | null>(null);
  const [fontFamily, setFontFamily] = useState('Inter');
  const [fontSize, setFontSize] = useState('18px');
  const [isAIProcessing, setIsAIProcessing] = useState(false);

  // Floating selection menu state
  const [selectionMenu, setSelectionMenu] = useState<{ x: number, y: number, text: string } | null>(null);

  // Metadata State
  const [metaTitle, setMetaTitle] = useState(() => localStorage.getItem('seo-meta-title') || '');
  const [metaDescription, setMetaDescription] = useState(() => localStorage.getItem('seo-meta') || '');
  const [targets, setTargets] = useState<KeywordTarget>(() => {
    const saved = localStorage.getItem('seo-targets');
    return saved ? JSON.parse(saved) : { primary: '', secondary: ['', '', ''] };
  });
  const [faqs, setFaqs] = useState<FAQ[]>(() => {
    const saved = localStorage.getItem('seo-faqs');
    return saved ? JSON.parse(saved) : [];
  });
  const [showSchema, setShowSchema] = useState(false);

  const editorRef = useRef<HTMLDivElement>(null);
  const [debouncedContent, setDebouncedContent] = useState(content);
  const deferredContent = useDeferredValue(debouncedContent);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedContent(content);
      localStorage.setItem('seo-editor-content', content);
      localStorage.setItem('seo-targets', JSON.stringify(targets));
      localStorage.setItem('seo-meta', metaDescription);
      localStorage.setItem('seo-meta-title', metaTitle);
      localStorage.setItem('seo-faqs', JSON.stringify(faqs));
    }, 500);
    return () => clearTimeout(handler);
  }, [content, targets, metaDescription, metaTitle, faqs]);

  useEffect(() => {
    if (isDarkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
    localStorage.setItem('seo-editor-theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
  const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
  const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
  const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, targets, metaDescription), [deferredContent, keywords, targets, metaDescription]);
  const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);

  const execCommand = (command: string, value: string = '') => {
    if (editorRef.current) {
      editorRef.current.focus();
    }
    document.execCommand(command, false, value);
    if (editorRef.current) {
      setContent(editorRef.current.innerHTML);
    }
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    e.preventDefault();
    const htmlData = e.clipboardData.getData('text/html');
    const plainText = e.clipboardData.getData('text/plain');

    if (htmlData) {
      document.execCommand('insertHTML', false, htmlData);
    } else if (plainText) {
      document.execCommand('insertText', false, plainText);
    }

    if (editorRef.current) {
      setContent(editorRef.current.innerHTML);
    }
  };

  const handleSelectionChange = () => {
    const selection = window.getSelection();
    if (selection && selection.rangeCount > 0 && selection.toString().trim().length > 0) {
      const range = selection.getRangeAt(0);
      const rect = range.getBoundingClientRect();

      // Check if selection is inside editor
      if (editorRef.current?.contains(range.commonAncestorContainer)) {
        setSelectionMenu({
          x: rect.left + rect.width / 2,
          y: rect.top + window.scrollY,
          text: selection.toString()
        });
      } else {
        setSelectionMenu(null);
      }
    } else {
      setSelectionMenu(null);
    }
  };

  const updateActiveLinkStatus = () => {
    const selection = window.getSelection();
    if (selection && selection.rangeCount > 0) {
      let node = selection.getRangeAt(0).startContainer;
      let parent: HTMLElement | null = node.nodeType === 3 ? node.parentElement : node as HTMLElement;

      while (parent && parent !== editorRef.current) {
        if (parent.tagName === 'A') {
          setActiveLink({ element: parent as HTMLAnchorElement, url: (parent as HTMLAnchorElement).href });
          return;
        }
        parent = parent.parentElement;
      }
    }
    setActiveLink(null);
  };

  const onRewrite = async (mode: RewriteMode) => {
    const selection = window.getSelection();
    const textToProcess = (selection && selection.toString().length > 0) 
      ? selection.toString() 
      : editorRef.current?.innerText || '';

    if (!textToProcess) return;

    setIsAIProcessing(true);
    setSelectionMenu(null); // Close menu during processing
    try {
      const result = await rewriteContent(textToProcess, mode);
      if (selection && selection.toString().length > 0) {
        document.execCommand('insertText', false, result);
      } else if (editorRef.current) {
        editorRef.current.innerText = result;
      }
      if (editorRef.current) setContent(editorRef.current.innerHTML);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const onConvertCase = (type: string) => {
    if (editorRef.current) {
      const selection = window.getSelection();
      const selectedText = selection?.toString();

      if (selectedText && selectedText.length > 0) {
        document.execCommand('insertText', false, convertText(selectedText, type));
      } else {
        editorRef.current.innerText = convertText(editorRef.current.innerText, type);
      }
      setContent(editorRef.current.innerHTML);
    }
  };

  const onCopy = async (type: 'plain' | 'markdown') => {
    const text = editorRef.current?.innerText || '';
    const toCopy = type === 'markdown' ? htmlToMarkdown(content) : text;
    try {
      await navigator.clipboard.writeText(toCopy);
    } catch (err) {
      console.error('Failed to copy text:', err);
    }
  };

  const onClear = () => {
    if (window.confirm('Are you sure you want to clear the entire document?')) {
      setContent('');
      if (editorRef.current) {
        editorRef.current.innerHTML = '';
      }
    }
  };

  const handleGenerateMetadata = async (type: 'title' | 'description') => {
    setIsAIProcessing(true);
    try {
      const result = await generateMetadata(editorRef.current?.innerText || content, type);
      if (type === 'title') setMetaTitle(result);
      else setMetaDescription(result);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleAIDetection = async () => {
    setIsAIProcessing(true);
    try {
      const result = await detectAIContent(editorRef.current?.innerText || "");
      alert(`AI Detection Score: ${result.score}%\n\nAnalysis: ${result.analysis}`);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleGenerateFAQs = async () => {
    setIsAIProcessing(true);
    try {
      const result = await generateFAQs(editorRef.current?.innerText || content);
      setFaqs(result);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const faqSchema = useMemo(() => {
    return JSON.stringify({
      "@context": "https://schema.org",
      "@type": "FAQPage",
      "mainEntity": faqs.map(f => ({
        "@type": "Question",
        "name": f.question,
        "acceptedAnswer": {
          "@type": "Answer",
          "text": f.answer
        }
      }))
    }, null, 2);
  }, [faqs]);

  const fontFamilies: Record<string, string> = {
    'Inter': "'Inter', sans-serif",
    'Georgia': "Georgia, serif",
    'monospace': "monospace"
  };

  return (
    <div className="h-screen w-screen flex flex-col md:flex-row bg-white dark:bg-zinc-950 text-zinc-900 dark:text-zinc-100 transition-colors duration-300 overflow-hidden">

      {/* Floating Selection AI Menu */}
      {selectionMenu && (
        <div 
          className="fixed z-[90] -translate-x-1/2 -translate-y-full mb-4 flex gap-1 p-1 bg-zinc-900/90 dark:bg-white/90 backdrop-blur-xl border border-white/10 dark:border-black/10 rounded-2xl shadow-2xl animate-in zoom-in-95 fade-in duration-200"
          style={{ top: selectionMenu.y, left: selectionMenu.x }}
        >
          <button 
            onClick={() => onRewrite('expand')}
            className="flex items-center gap-2 px-4 py-2 hover:bg-white/10 dark:hover:bg-black/5 rounded-xl text-white dark:text-black text-[11px] font-black uppercase tracking-wider transition-colors"
          >
            <Plus size={14} className="text-blue-500" />
            Expand
          </button>
          <div className="w-[1px] h-4 bg-white/20 dark:bg-black/10 self-center" />
          <button 
            onClick={() => onRewrite('shorten')}
            className="flex items-center gap-2 px-4 py-2 hover:bg-white/10 dark:hover:bg-black/5 rounded-xl text-white dark:text-black text-[11px] font-black uppercase tracking-wider transition-colors"
          >
            <Minus size={14} className="text-red-500" />
            Shorten
          </button>
          <div className="w-[1px] h-4 bg-white/20 dark:bg-black/10 self-center" />
          <button 
            onClick={() => onRewrite('clarity')}
            className="flex items-center gap-2 px-4 py-2 hover:bg-white/10 dark:hover:bg-black/5 rounded-xl text-white dark:text-black text-[11px] font-black uppercase tracking-wider transition-colors"
          >
            <Sparkles size={14} className="text-yellow-500" />
            Clarity
          </button>
        </div>
      )}

      {/* Schema Export Popup */}
      {showSchema && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
          <div className="bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-3xl w-full max-w-2xl shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95">
            <div className="p-6 border-b border-zinc-200 dark:border-zinc-800 flex items-center justify-between">
              <h3 className="font-black text-sm uppercase tracking-wider">FAQ Schema (JSON-LD)</h3>
              <button onClick={() => setShowSchema(false)} className="p-2 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-xl transition-colors"><X size={20}/></button>
            </div>
            <div className="p-6 overflow-hidden">
              <pre className="bg-zinc-50 dark:bg-black/40 p-4 rounded-2xl text-[11px] font-mono overflow-auto max-h-[60vh] border border-zinc-200 dark:border-zinc-800 text-zinc-600 dark:text-zinc-400">
                {faqSchema}
              </pre>
            </div>
            <div className="p-6 bg-zinc-50 dark:bg-zinc-900/50 border-t border-zinc-200 dark:border-zinc-800 flex gap-3">
              <button 
                onClick={() => {
                  navigator.clipboard.writeText(faqSchema);
                  alert("Schema copied to clipboard!");
                }}
                className="flex-1 py-3 bg-blue-600 text-white rounded-2xl font-bold uppercase text-xs tracking-widest shadow-lg shadow-blue-500/20"
              >
                Copy to Clipboard
              </button>
              <button onClick={() => setShowSchema(false)} className="px-6 py-3 border border-zinc-200 dark:border-zinc-800 rounded-2xl font-bold uppercase text-xs tracking-widest">
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="flex-1 flex flex-col relative overflow-hidden h-full">
        <header className="h-16 border-b border-zinc-200 dark:border-zinc-800 flex items-center justify-between px-6 glass-panel z-30 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-600 rounded-xl flex items-center justify-center font-black text-white shadow-lg relative">S</div>
            <h1 className="font-bold text-lg tracking-tight hidden sm:block uppercase">SEO Focus <span className="text-zinc-400">Pro</span></h1>
          </div>
          <div className="flex items-center gap-2">
            <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-xl text-zinc-500 transition-colors">
              {isDarkMode ? <Sun size={20} /> : <Moon size={20} />}
            </button>
            <button onClick={() => {
              const element = document.createElement("a");
              const file = new Blob([content], {type: 'text/html'});
              element.href = URL.createObjectURL(file);
              element.download = "seo-content.html";
              element.click();
            }} className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-500 text-white rounded-xl text-sm font-bold shadow-lg transition-all hover:scale-105 active:scale-95">
              <Download size={16} />
              <span className="hidden sm:inline">Export</span>
            </button>
          </div>
        </header>

        <Toolbar onCommand={execCommand} onPaste={handlePaste as any} fontFamily={fontFamily} fontSize={fontSize} setFontFamily={setFontFamily} setFontSize={setFontSize} />

        <main className="flex-1 overflow-y-auto p-6 md:p-12 lg:p-16 flex flex-col items-center custom-scrollbar bg-zinc-50 dark:bg-zinc-950 relative">
          <div className="w-full max-w-4xl relative pb-32">
            <div
              ref={editorRef}
              contentEditable
              onInput={(e) => setContent(e.currentTarget.innerHTML)}
              onPaste={handlePaste}
              onMouseUp={handleSelectionChange}
              onKeyUp={() => {
                handleSelectionChange();
                updateActiveLinkStatus();
              }}
              onMouseDown={() => setSelectionMenu(null)}
              dangerouslySetInnerHTML={{ __html: content }}
              style={{ fontFamily: fontFamilies[fontFamily], fontSize: fontSize }}
              className="editor-content w-full min-h-[50vh] focus:outline-none text-zinc-800 dark:text-zinc-300 leading-relaxed font-normal"
            />
          </div>
        </main>
      </div>

      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        stats={stats} 
        readability={readability}
        health={health}
        intent={intent}
        keywords={keywords} 
        seoTab={seoTab} 
        setSeoTab={setSeoTab} 
        isExpanded={isExpanded} 
        setIsExpanded={setIsExpanded} 
        onRewrite={onRewrite}
        onConvertCase={onConvertCase} 
        onCopy={onCopy} 
        onClear={onClear} 
        isAIProcessing={isAIProcessing}
        targets={targets}
        setTargets={setTargets}
        metaTitle={metaTitle}
        setMetaTitle={setMetaTitle}
        metaDescription={metaDescription}
        setMetaDescription={setMetaDescription}
        faqs={faqs}
        setFaqs={setFaqs}
        onGenerateMetadata={handleGenerateMetadata}
        onDetectAI={handleAIDetection}
        onGenerateFAQs={handleGenerateFAQs}
        onExportSchema={() => setShowSchema(true)}
      />
    </div>
  );
};

