    return () => clearTimeout(handler);
  }, [content, targets, metaDescription, metaTitle, faqs]);

  useEffect(() => {
    if (isDarkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
    localStorage.setItem('seo-editor-theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
  const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
  const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
  const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, targets, metaDescription), [deferredContent, keywords, targets, metaDescription]);
  const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);

  const execCommand = (command: string, value: string = '') => {
    if (editorRef.current) {
      editorRef.current.focus();
    }
    document.execCommand(command, false, value);
    if (editorRef.current) {
      setContent(editorRef.current.innerHTML);
    }
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    e.preventDefault();
    const htmlData = e.clipboardData.getData('text/html');
    const plainText = e.clipboardData.getData('text/plain');

    if (htmlData) {
      document.execCommand('insertHTML', false, htmlData);
    } else if (plainText) {
      document.execCommand('insertText', false, plainText);
    }

    if (editorRef.current) {
      setContent(editorRef.current.innerHTML);
    }
  };

  const updateActiveLinkStatus = () => {
    const selection = window.getSelection();
    if (selection && selection.rangeCount > 0) {
      let node = selection.getRangeAt(0).startContainer;
      let parent: HTMLElement | null = node.nodeType === 3 ? node.parentElement : node as HTMLElement;

      while (parent && parent !== editorRef.current) {
        if (parent.tagName === 'A') {
          const rect = (parent as HTMLAnchorElement).getBoundingClientRect();
          setActiveLink({ 
            element: parent as HTMLAnchorElement, 
            url: (parent as HTMLAnchorElement).href,
            rect
          });
          return;
        }
        parent = parent.parentElement;
      }
    }
    setActiveLink(null);
  };

  const onRewrite = async (mode: RewriteMode) => {
    const selection = window.getSelection();
    const textToProcess = (selection && selection.toString().trim().length > 0) 
      ? selection.toString() 
      : "";

    if (!textToProcess) {
      alert("Please select text in the editor to use AI rewrite options.");
      return;
    }

    // Save selection to restore later
    if (selection && selection.rangeCount > 0) {
      setSavedSelection(selection.getRangeAt(0).cloneRange());
    }

    setIsAIProcessing(true);
    try {
      const results = await rewriteContent(textToProcess, mode);
      setAiOptions(results);
    } catch (err) {
      console.error(err);
      alert("AI Processing failed. Please check your connection.");
    } finally {
      setIsAIProcessing(false);
    }
  };

  const applyAIOption = (text: string) => {
    if (!savedSelection) return;

    const selection = window.getSelection();
    if (selection) {
      selection.removeAllRanges();
      selection.addRange(savedSelection);
      document.execCommand('insertText', false, text);
      if (editorRef.current) setContent(editorRef.current.innerHTML);
    }
    setAiOptions(null);
    setSavedSelection(null);
