import React, { useState, useEffect, useRef, useMemo, useDeferredValue } from 'react';
import ReactDOM from 'react-dom/client';
import { 
  Sun, Moon, Download, Edit2, ExternalLink, X, Sparkles, Plus, Minus, Check, Copy, Clock, Trash2
} from 'lucide-react';

import { getStats } from './core/text-analysis';
import { getKeywords } from './core/keyword-density';
import { getReadabilityScore } from './core/readability';
import { analyzeSEOHealth } from './core/seo-health';
import { detectIntent } from './core/intent-detector';
import { convertText } from './core/case-converter';
import { rewriteContent, generateMetadata, detectAIContent, RewriteMode, generateFAQs } from './ai/ai-engine';
import { htmlToMarkdown } from './utils/text-cleaner';

import { Toolbar } from './components/editor/Toolbar';
import { Sidebar } from './components/layout/Sidebar';
import { Tab, SEOPhraseTab, KeywordTarget, FAQ } from './types/editor.types';

interface Version {
  id: string;
  timestamp: number;
  content: string;
  wordCount: number;
}

const App = () => {
  const [content, setContent] = useState(() => localStorage.getItem('seo-editor-content') || '<h1>SEO Focus Pro</h1><p>Start crafting optimized, AI-enhanced content here. Select text to rewrite or use the tabs on the right to analyze your performance in real-time.</p>');
  const [isDarkMode, setIsDarkMode] = useState(() => localStorage.getItem('seo-editor-theme') !== 'light');
  const [activeTab, setActiveTab] = useState<Tab>('insights'); 
  const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
  const [isExpanded, setIsExpanded] = useState(false);
  const [activeLink, setActiveLink] = useState<{ element: HTMLAnchorElement, url: string, rect: DOMRect } | null>(null);
  const [fontFamily, setFontFamily] = useState('Inter');
  const [fontSize, setFontSize] = useState('18px');
  const [isAIProcessing, setIsAIProcessing] = useState(false);

  // Version History State
  const [versions, setVersions] = useState<Version[]>(() => {
    const saved = localStorage.getItem('seo-versions');
    return saved ? JSON.parse(saved) : [];
  });
  const [showHistory, setShowHistory] = useState(false);

  // AI Options Modal state
  const [aiOptions, setAiOptions] = useState<string[] | null>(null);
  const [savedSelection, setSavedSelection] = useState<Range | null>(null);

  // Metadata State
  const [metaTitle, setMetaTitle] = useState(() => localStorage.getItem('seo-meta-title') || '');
  const [metaDescription, setMetaDescription] = useState(() => localStorage.getItem('seo-meta') || '');
  const [targets, setTargets] = useState<KeywordTarget>(() => {
    const saved = localStorage.getItem('seo-targets');
    return saved ? JSON.parse(saved) : { primary: '', secondary: ['', '', ''] };
  });
  const [faqs, setFaqs] = useState<FAQ[]>(() => {
    const saved = localStorage.getItem('seo-faqs');
    return saved ? JSON.parse(saved) : [];
  });
  const [showSchema, setShowSchema] = useState(false);
  const [showEmbedModal, setShowEmbedModal] = useState(false);

  const editorRef = useRef<HTMLDivElement>(null);
  const [debouncedContent, setDebouncedContent] = useState(content);
  const deferredContent = useDeferredValue(debouncedContent);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedContent(content);
      localStorage.setItem('seo-editor-content', content);
      localStorage.setItem('seo-targets', JSON.stringify(targets));
      localStorage.setItem('seo-meta', metaDescription);
      localStorage.setItem('seo-meta-title', metaTitle);
      localStorage.setItem('seo-faqs', JSON.stringify(faqs));
      localStorage.setItem('seo-versions', JSON.stringify(versions));
    }, 500);
    return () => clearTimeout(handler);
  }, [content, targets, metaDescription, metaTitle, faqs, versions]);

  useEffect(() => {
    if (isDarkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
    localStorage.setItem('seo-editor-theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
  const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
  const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
  const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, targets, metaDescription), [deferredContent, keywords, targets, metaDescription]);
  const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);

  const execCommand = (command: string, value: string = '') => {
    if (editorRef.current) {
      editorRef.current.focus();
    }
    document.execCommand(command, false, value);
    if (editorRef.current) {
      setContent(editorRef.current.innerHTML);
    }
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    e.preventDefault();
    const htmlData = e.clipboardData.getData('text/html');
    const plainText = e.clipboardData.getData('text/plain');

    if (htmlData) {
      document.execCommand('insertHTML', false, htmlData);
    } else if (plainText) {
      document.execCommand('insertText', false, plainText);
    }

    if (editorRef.current) {
      setContent(editorRef.current.innerHTML);
    }
  };

  const updateActiveLinkStatus = () => {
    const selection = window.getSelection();
    if (selection && selection.rangeCount > 0) {
      let node = selection.getRangeAt(0).startContainer;
      let parent: HTMLElement | null = node.nodeType === 3 ? node.parentElement : node as HTMLElement;

      while (parent && parent !== editorRef.current) {
        if (parent.tagName === 'A') {
          const rect = (parent as HTMLAnchorElement).getBoundingClientRect();
          setActiveLink({ 
            element: parent as HTMLAnchorElement, 
            url: (parent as HTMLAnchorElement).href,
            rect
          });
          return;
        }
        parent = parent.parentElement;
      }
    }
    setActiveLink(null);
  };

  const onRewrite = async (mode: RewriteMode) => {
    const selection = window.getSelection();
    const textToProcess = (selection && selection.toString().trim().length > 0) 
      ? selection.toString() 
      : "";

    if (!textToProcess) {
      alert("Please select text in the editor to use AI rewrite options.");
      return;
    }

    if (selection && selection.rangeCount > 0) {
      setSavedSelection(selection.getRangeAt(0).cloneRange());
    }

    setIsAIProcessing(true);
    try {
      const results = await rewriteContent(textToProcess, mode);
      setAiOptions(results);
    } catch (err) {
      console.error(err);
      alert("AI Processing failed. Please check your connection.");
    } finally {
      setIsAIProcessing(false);
    }
  };

  const applyAIOption = (text: string) => {
    if (!savedSelection) return;

    const selection = window.getSelection();
    if (selection) {
      selection.removeAllRanges();
      selection.addRange(savedSelection);
      document.execCommand('insertText', false, text);
      if (editorRef.current) setContent(editorRef.current.innerHTML);
    }
    setAiOptions(null);
    setSavedSelection(null);
  };

  const onNewDocument = () => {
    if (window.confirm('Create a new document? Current progress will be lost unless saved to history.')) {
      setContent('<h1>New Document</h1><p>Start writing...</p>');
      if (editorRef.current) editorRef.current.innerHTML = '<h1>New Document</h1><p>Start writing...</p>';
    }
  };

  const saveToHistory = () => {
    const newVersion: Version = {
      id: Math.random().toString(36).substring(7),
      timestamp: Date.now(),
      content: content,
      wordCount: stats.words
    };
    setVersions([newVersion, ...versions].slice(0, 20)); // Keep last 20
  };

  const loadVersion = (v: Version) => {
    if (window.confirm('Load this version? Current editor content will be replaced.')) {
      setContent(v.content);
      if (editorRef.current) editorRef.current.innerHTML = v.content;
      setShowHistory(false);
    }
  };

  const deleteVersion = (id: string) => {
    setVersions(versions.filter(v => v.id !== id));
  };

  const insertTable = () => {
    const rows = prompt("Number of rows?", "3");
    const cols = prompt("Number of columns?", "3");
    if (!rows || !cols) return;
    let html = '<table style="width:100%; border-collapse: collapse; margin-bottom: 1.5rem;" border="1">';
    for (let i = 0; i < parseInt(rows); i++) {
      html += '<tr>';
      for (let j = 0; j < parseInt(cols); j++) {
        html += '<td style="padding: 8px;">Cell</td>';
      }
      html += '</tr>';
    }
    html += '</table><p><br></p>';
    execCommand('insertHTML', html);
  };

  const insertImage = () => {
    const url = prompt("Image URL:");
    if (url) {
      execCommand('insertHTML', `<img src="${url}" style="max-width:100%; height:auto; border-radius:1rem; margin-bottom:1.5rem;" /><p><br></p>`);
    }
  };

  const handleEmbed = (type: 'youtube' | 'vimeo' | 'custom') => {
    const input = prompt(type === 'custom' ? "Paste embed code:" : `Enter ${type} URL or ID:`);
    if (!input) return;

    let html = '';
    if (type === 'youtube') {
      const id = input.includes('v=') ? input.split('v=')[1].split('&')[0] : input;
      html = `<iframe width="100%" height="400" src="https://www.youtube.com/embed/${id}" frameborder="0" allowfullscreen style="border-radius:1rem; margin-bottom:1.5rem;"></iframe>`;
    } else if (type === 'vimeo') {
      const id = input.split('/').pop();
      html = `<iframe src="https://player.vimeo.com/video/${id}" width="100%" height="400" frameborder="0" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen style="border-radius:1rem; margin-bottom:1.5rem;"></iframe>`;
    } else {
      html = `<div class="custom-embed" style="margin-bottom:1.5rem;">${input}</div>`;
    }
    execCommand('insertHTML', html + '<p><br></p>');
    setShowEmbedModal(false);
  };

  const insertCodeBlock = () => {
    execCommand('insertHTML', `<pre style="background:rgba(0,0,0,0.05); padding:1.5rem; border-radius:1rem; margin-bottom:1.5rem; font-family:monospace;"><code>// Your code here</code></pre><p><br></p>`);
  };

  const onConvertCase = (type: string) => {
    if (editorRef.current) {
      const selection = window.getSelection();
      const selectedText = selection?.toString();
      if (selectedText && selectedText.length > 0) {
        document.execCommand('insertText', false, convertText(selectedText, type));
      } else {
        editorRef.current.innerText = convertText(editorRef.current.innerText, type);
      }
      setContent(editorRef.current.innerHTML);
    }
  };

  const onCopy = async (type: 'plain' | 'markdown') => {
    const text = editorRef.current?.innerText || '';
    const toCopy = type === 'markdown' ? htmlToMarkdown(content) : text;
    try {
      await navigator.clipboard.writeText(toCopy);
    } catch (err) {
      console.error('Failed to copy text:', err);
    }
  };

  const onClear = () => {
    if (window.confirm('Are you sure you want to clear the entire document?')) {
      setContent('');
      if (editorRef.current) {
        editorRef.current.innerHTML = '';
      }
    }
  };

  const handleGenerateMetadata = async (type: 'title' | 'description') => {
    setIsAIProcessing(true);
    try {
      const result = await generateMetadata(editorRef.current?.innerText || content, type);
      if (type === 'title') setMetaTitle(result);
      else setMetaDescription(result);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleAIDetection = async () => {
    setIsAIProcessing(true);
    try {
      const result = await detectAIContent(editorRef.current?.innerText || "");
      alert(`AI Detection Score: ${result.score}%\n\nAnalysis: ${result.analysis}`);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleGenerateFAQs = async () => {
    setIsAIProcessing(true);
    try {
      const result = await generateFAQs(editorRef.current?.innerText || content);
      setFaqs(result);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const faqSchema = useMemo(() => {
    return JSON.stringify({
      "@context": "https://schema.org",
      "@type": "FAQPage",
      "mainEntity": faqs.map(f => ({
        "@type": "Question",
        "name": f.question,
        "acceptedAnswer": {
          "@type": "Answer",
          "text": f.answer
        }
      }))
    }, null, 2);
  }, [faqs]);

  const fontFamilies: Record<string, string> = {
    'Inter': "'Inter', sans-serif",
    'Georgia': "Georgia, serif",
    'monospace': "monospace"
  };

  return (
    <div className="h-screen w-screen flex flex-col md:flex-row bg-white dark:bg-zinc-950 text-zinc-900 dark:text-zinc-100 transition-colors duration-300 overflow-hidden">

      {/* Link Tooltip */}
      {activeLink && (
        <div 
          className="fixed z-[80] bg-zinc-900 text-white dark:bg-white dark:text-zinc-900 px-3 py-1.5 rounded-lg text-[11px] font-bold flex items-center gap-2 shadow-xl border border-white/10 animate-in fade-in zoom-in-95"
          style={{ 
            top: activeLink.rect.top - 40 + window.scrollY, 
            left: activeLink.rect.left + activeLink.rect.width / 2,
            transform: 'translateX(-50%)'
          }}
        >
          <ExternalLink size={12} className="text-blue-400" />
          <span className="max-w-[200px] truncate">{activeLink.url}</span>
          <button onClick={() => window.open(activeLink.url, '_blank')} className="hover:text-blue-400 transition-colors uppercase">Visit</button>
          <div className="w-[1px] h-3 bg-white/20 dark:bg-zinc-200" />
          <button 
            onClick={() => {
              const newUrl = prompt("Enter new URL:", activeLink.url);
              if (newUrl !== null) {
                activeLink.element.href = newUrl;
                setContent(editorRef.current?.innerHTML || '');
              }
            }}
            className="hover:text-blue-400 transition-colors uppercase"
          >
            Edit
          </button>
        </div>
      )}

      {/* Version History Modal */}
      {showHistory && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-black/60 backdrop-blur-md p-4 animate-in fade-in duration-300">
          <div className="bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-[32px] w-full max-w-2xl shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95">
            <div className="p-8 border-b border-zinc-200 dark:border-zinc-800 flex items-center justify-between">
              <div className="flex items-center gap-4">
                <Clock size={24} className="text-blue-500" />
                <h3 className="font-black text-xl uppercase tracking-tighter">History</h3>
              </div>
              <div className="flex gap-2">
                <button onClick={saveToHistory} className="px-4 py-2 bg-blue-600 text-white text-[10px] font-bold uppercase rounded-xl shadow-lg">Snapshot Current</button>
                <button onClick={() => setShowHistory(false)} className="p-3 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-2xl"><X size={24}/></button>
              </div>
            </div>
            <div className="p-4 flex-1 overflow-y-auto max-h-[60vh] custom-scrollbar space-y-3">
              {versions.length > 0 ? versions.map((v) => (
                <div key={v.id} className="p-4 bg-zinc-50 dark:bg-zinc-950 border border-zinc-200 dark:border-zinc-800 rounded-2xl flex items-center justify-between hover:border-blue-500/50 transition-all group">
                  <div>
                    <div className="text-[11px] font-black text-zinc-900 dark:text-zinc-100 uppercase">{new Date(v.timestamp).toLocaleString()}</div>
                    <div className="text-[10px] text-zinc-400 font-bold uppercase mt-1">{v.wordCount} Words</div>
                  </div>
                  <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button onClick={() => loadVersion(v)} className="p-2 bg-blue-500/10 text-blue-500 rounded-lg hover:bg-blue-500 hover:text-white transition-all"><Edit2 size={16} /></button>
                    <button onClick={() => deleteVersion(v.id)} className="p-2 bg-red-500/10 text-red-500 rounded-lg hover:bg-red-500 hover:text-white transition-all"><Trash2 size={16} /></button>
                  </div>
                </div>
              )) : (
                <div className="text-center py-12 text-zinc-400 italic text-sm">No versions saved yet. Click "Snapshot Current" to save the current state.</div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Embed Modal */}
      {showEmbedModal && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-black/60 backdrop-blur-md p-4 animate-in fade-in duration-300">
          <div className="bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-[32px] w-full max-w-sm shadow-2xl overflow-hidden animate-in zoom-in-95">
            <div className="p-6 border-b border-zinc-200 dark:border-zinc-800 flex items-center justify-between">
              <h3 className="font-black text-lg uppercase tracking-tighter">Embed Media</h3>
              <button onClick={() => setShowEmbedModal(false)}><X size={20}/></button>
            </div>
            <div className="p-6 space-y-3">
              <button onClick={() => handleEmbed('youtube')} className="w-full py-3 bg-red-600 text-white rounded-xl font-bold uppercase text-xs tracking-widest flex items-center justify-center gap-2 shadow-lg"><Youtube size={16}/> YouTube</button>
              <button onClick={() => handleEmbed('vimeo')} className="w-full py-3 bg-blue-400 text-white rounded-xl font-bold uppercase text-xs tracking-widest flex items-center justify-center gap-2 shadow-lg">Vimeo</button>
              <button onClick={() => handleEmbed('custom')} className="w-full py-3 bg-zinc-800 text-white rounded-xl font-bold uppercase text-xs tracking-widest flex items-center justify-center gap-2 shadow-lg"><Code size={16}/> Custom Embed</button>
            </div>
          </div>
        </div>
      )}

      {/* AI Options Modal */}
      {aiOptions && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/60 backdrop-blur-md p-4 animate-in fade-in duration-300">
          <div className="bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-[32px] w-full max-w-4xl shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95">
            <div className="p-8 border-b border-zinc-200 dark:border-zinc-800 flex items-center justify-between bg-zinc-50/50 dark:bg-zinc-800/30">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-blue-500/20">
                  <Sparkles size={24} />
                </div>
                <div>
                  <h3 className="font-black text-xl uppercase tracking-tighter">AI Suggestions</h3>
                  <p className="text-[10px] font-bold text-zinc-400 uppercase tracking-widest mt-1">Select the best version to replace your text</p>
                </div>
              </div>
              <button onClick={() => setAiOptions(null)} className="p-3 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-2xl transition-all"><X size={24}/></button>
            </div>
            <div className="p-8 grid md:grid-cols-2 gap-6 overflow-y-auto max-h-[70vh] custom-scrollbar">
              {aiOptions.map((option, i) => (
                <div key={i} className="group relative bg-zinc-50 dark:bg-zinc-950 border border-zinc-200 dark:border-zinc-800 rounded-3xl p-6 flex flex-col h-full hover:border-blue-500 transition-all duration-300">
                  <div className="absolute top-4 right-4 bg-blue-600/10 text-blue-600 text-[9px] font-black px-2 py-1 rounded-full uppercase tracking-widest">Version {i + 1}</div>
                  <div className="flex-1 text-sm leading-relaxed text-zinc-600 dark:text-zinc-400 italic mb-6">"{option}"</div>
                  <button onClick={() => applyAIOption(option)} className="w-full py-4 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-white border border-zinc-200 dark:border-zinc-800 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-blue-600 hover:text-white hover:border-blue-600 transition-all shadow-lg">Apply Selection</button>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* FAQ Schema Modal */}
      {showSchema && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
          <div className="bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-3xl w-full max-w-2xl shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95">
            <div className="p-6 border-b border-zinc-200 dark:border-zinc-800 flex items-center justify-between">
              <h3 className="font-black text-sm uppercase tracking-wider">FAQ Schema (JSON-LD)</h3>
              <button onClick={() => setShowSchema(false)} className="p-2 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-xl transition-colors"><X size={20}/></button>
            </div>
            <div className="p-6 overflow-hidden">
              <pre className="bg-zinc-50 dark:bg-black/40 p-4 rounded-2xl text-[11px] font-mono overflow-auto max-h-[60vh] border border-zinc-200 dark:border-zinc-800 text-zinc-600 dark:text-zinc-400">
                {faqSchema}
              </pre>
            </div>
            <div className="p-6 bg-zinc-50 dark:bg-zinc-900/50 border-t border-zinc-200 dark:border-zinc-800 flex gap-3">
              <button onClick={() => { navigator.clipboard.writeText(faqSchema); alert("Schema copied!"); }} className="flex-1 py-3 bg-blue-600 text-white rounded-2xl font-bold uppercase text-xs tracking-widest">Copy Schema</button>
              <button onClick={() => setShowSchema(false)} className="px-6 py-3 border border-zinc-200 dark:border-zinc-800 rounded-2xl font-bold uppercase text-xs tracking-widest">Close</button>
            </div>
          </div>
        </div>
      )}

      <div className="flex-1 flex flex-col relative overflow-hidden h-full">
        <header className="h-16 border-b border-zinc-200 dark:border-zinc-800 flex items-center justify-between px-6 glass-panel z-30 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-600 rounded-xl flex items-center justify-center font-black text-white shadow-lg relative">S</div>
            <h1 className="font-bold text-lg tracking-tight hidden sm:block uppercase">SEO Focus <span className="text-zinc-400">Pro</span></h1>
          </div>
          <div className="flex items-center gap-2">
            <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-xl text-zinc-500 transition-colors">
              {isDarkMode ? <Sun size={20} /> : <Moon size={20} />}
            </button>
            <button onClick={() => {
              const element = document.createElement("a");
              const file = new Blob([content], {type: 'text/html'});
              element.href = URL.createObjectURL(file);
              element.download = "seo-content.html";
              element.click();
            }} className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-500 text-white rounded-xl text-sm font-bold shadow-lg transition-all">
              <Download size={16} />
              <span className="hidden sm:inline">Export</span>
            </button>
          </div>
        </header>

        <Toolbar 
          onCommand={execCommand} 
          onPaste={handlePaste as any} 
          fontFamily={fontFamily} 
          fontSize={fontSize} 
          setFontFamily={setFontFamily} 
          setFontSize={setFontSize} 
          onNewDocument={onNewDocument}
          onShowHistory={() => setShowHistory(true)}
          onInsertTable={insertTable}
          onInsertImage={insertImage}
          onInsertEmbed={() => setShowEmbedModal(true)}
          onInsertCodeBlock={insertCodeBlock}
        />

        <main className="flex-1 overflow-y-auto p-6 md:p-12 lg:p-16 flex flex-col items-center custom-scrollbar bg-zinc-50 dark:bg-zinc-950 relative">
          <div className="w-full max-w-4xl relative pb-32">
            <div
              ref={editorRef}
              contentEditable
              onInput={(e) => setContent(e.currentTarget.innerHTML)}
              onPaste={handlePaste}
              onMouseUp={updateActiveLinkStatus}
              onKeyUp={updateActiveLinkStatus}
              onMouseDown={() => {
                setAiOptions(null);
                setActiveLink(null);
              }}
              dangerouslySetInnerHTML={{ __html: content }}
              style={{ fontFamily: fontFamilies[fontFamily], fontSize: fontSize }}
              className="editor-content w-full min-h-[50vh] focus:outline-none text-zinc-800 dark:text-zinc-300 leading-relaxed font-normal"
            />
          </div>
        </main>
      </div>

      <Sidebar 
        activeTab={activeTab} setActiveTab={setActiveTab} 
        stats={stats} readability={readability} health={health} intent={intent} keywords={keywords} 
        seoTab={seoTab} setSeoTab={setSeoTab} isExpanded={isExpanded} setIsExpanded={setIsExpanded} 
        onRewrite={onRewrite} onConvertCase={onConvertCase} onCopy={onCopy} onClear={onClear} 
        isAIProcessing={isAIProcessing} targets={targets} setTargets={setTargets}
        metaTitle={metaTitle} setMetaTitle={setMetaTitle} metaDescription={metaDescription} setMetaDescription={setMetaDescription}
        faqs={faqs} setFaqs={setFaqs} onGenerateMetadata={handleGenerateMetadata} onDetectAI={handleAIDetection} 
        onGenerateFAQs={handleGenerateFAQs} onExportSchema={() => setShowSchema(true)}
      />
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useEffect, useRef, useMemo, useDeferredValue } from 'react';
import ReactDOM from 'react-dom/client';
import { 
  Sun, Moon, Download, Edit2, ExternalLink, X, Sparkles, Plus, Minus, Check, Copy, Clock, Trash2, Youtube, Code
} from 'lucide-react';

import { getStats } from './core/text-analysis';
import { getKeywords } from './core/keyword-density';
import { getReadabilityScore } from './core/readability';
import { analyzeSEOHealth } from './core/seo-health';
import { detectIntent } from './core/intent-detector';
import { convertText } from './core/case-converter';
import { rewriteContent, generateMetadata, detectAIContent, RewriteMode, generateFAQs } from './ai/ai-engine';
import { htmlToMarkdown } from './utils/text-cleaner';

import { Toolbar } from './components/editor/Toolbar';
import { Sidebar } from './components/layout/Sidebar';
import { Tab, SEOPhraseTab, KeywordTarget, FAQ } from './types/editor.types';

interface Version {
  id: string;
  timestamp: number;
  content: string;
  wordCount: number;
}

const App = () => {
  const [content, setContent] = useState(() => localStorage.getItem('seo-editor-content') || '<h1>SEO Focus Pro</h1><p>Start crafting optimized, AI-enhanced content here. Select text to rewrite or use the tabs on the right to analyze your performance in real-time.</p>');
  const [isDarkMode, setIsDarkMode] = useState(() => localStorage.getItem('seo-editor-theme') !== 'light');
  const [activeTab, setActiveTab] = useState<Tab>('insights'); 
  const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
  const [isExpanded, setIsExpanded] = useState(false);
  const [activeLink, setActiveLink] = useState<{ element: HTMLAnchorElement, url: string, rect: DOMRect } | null>(null);
  const [fontFamily, setFontFamily] = useState('Inter');
  const [fontSize, setFontSize] = useState('18px');
  const [isAIProcessing, setIsAIProcessing] = useState(false);

  // Version History State
  const [versions, setVersions] = useState<Version[]>(() => {
    const saved = localStorage.getItem('seo-versions');
    return saved ? JSON.parse(saved) : [];
  });
  const [showHistory, setShowHistory] = useState(false);

  // AI Options Modal state
  const [aiOptions, setAiOptions] = useState<string[] | null>(null);
  const [savedSelection, setSavedSelection] = useState<Range | null>(null);

  // Metadata State
  const [metaTitle, setMetaTitle] = useState(() => localStorage.getItem('seo-meta-title') || '');
  const [metaDescription, setMetaDescription] = useState(() => localStorage.getItem('seo-meta') || '');
  const [targets, setTargets] = useState<KeywordTarget>(() => {
    const saved = localStorage.getItem('seo-targets');
    return saved ? JSON.parse(saved) : { primary: '', secondary: ['', '', ''] };
  });
  const [faqs, setFaqs] = useState<FAQ[]>(() => {
    const saved = localStorage.getItem('seo-faqs');
    return saved ? JSON.parse(saved) : [];
  });
  const [showSchema, setShowSchema] = useState(false);
  const [showEmbedModal, setShowEmbedModal] = useState(false);

  const editorRef = useRef<HTMLDivElement>(null);
  const [debouncedContent, setDebouncedContent] = useState(content);
  const deferredContent = useDeferredValue(debouncedContent);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedContent(content);
      localStorage.setItem('seo-editor-content', content);
      localStorage.setItem('seo-targets', JSON.stringify(targets));
      localStorage.setItem('seo-meta', metaDescription);
      localStorage.setItem('seo-meta-title', metaTitle);
      localStorage.setItem('seo-faqs', JSON.stringify(faqs));
      localStorage.setItem('seo-versions', JSON.stringify(versions));
    }, 500);
    return () => clearTimeout(handler);
  }, [content, targets, metaDescription, metaTitle, faqs, versions]);

  useEffect(() => {
    if (isDarkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
    localStorage.setItem('seo-editor-theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
  const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
  const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
  const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, targets, metaDescription), [deferredContent, keywords, targets, metaDescription]);
  const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);

  const execCommand = (command: string, value: string = '') => {
    if (editorRef.current) {
      editorRef.current.focus();
    }
    document.execCommand(command, false, value);
    if (editorRef.current) {
      setContent(editorRef.current.innerHTML);
    }
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    e.preventDefault();
    const htmlData = e.clipboardData.getData('text/html');
    const plainText = e.clipboardData.getData('text/plain');

    if (htmlData) {
      document.execCommand('insertHTML', false, htmlData);
    } else if (plainText) {
      document.execCommand('insertText', false, plainText);
    }

    if (editorRef.current) {
      setContent(editorRef.current.innerHTML);
    }
  };

  const updateActiveLinkStatus = () => {
    const selection = window.getSelection();
    if (selection && selection.rangeCount > 0) {
      let node = selection.getRangeAt(0).startContainer;
      let parent: HTMLElement | null = node.nodeType === 3 ? node.parentElement : node as HTMLElement;

      while (parent && parent !== editorRef.current) {
        if (parent.tagName === 'A') {
          const rect = (parent as HTMLAnchorElement).getBoundingClientRect();
          setActiveLink({ 
            element: parent as HTMLAnchorElement, 
            url: (parent as HTMLAnchorElement).href,
            rect
          });
          return;
        }
        parent = parent.parentElement;
      }
    }
    setActiveLink(null);
  };

  const onRewrite = async (mode: RewriteMode) => {
    const selection = window.getSelection();
    const textToProcess = (selection && selection.toString().trim().length > 0) 
      ? selection.toString() 
      : "";

    if (!textToProcess) {
      alert("Please select text in the editor to use AI rewrite options.");
      return;
    }

    if (selection && selection.rangeCount > 0) {
      setSavedSelection(selection.getRangeAt(0).cloneRange());
    }

    setIsAIProcessing(true);
    try {
      const results = await rewriteContent(textToProcess, mode);
      setAiOptions(results);
    } catch (err) {
      console.error(err);
      alert("AI Processing failed. Please check your connection.");
    } finally {
      setIsAIProcessing(false);
    }
  };

  const applyAIOption = (text: string) => {
    if (!savedSelection) return;

    const selection = window.getSelection();
    if (selection) {
      selection.removeAllRanges();
      selection.addRange(savedSelection);
      document.execCommand('insertText', false, text);
      if (editorRef.current) setContent(editorRef.current.innerHTML);
    }
    setAiOptions(null);
    setSavedSelection(null);
  };

  const onNewDocument = () => {
    if (window.confirm('Create a new document? Current progress will be lost unless saved to history.')) {
      setContent('<h1>New Document</h1><p>Start writing...</p>');
      if (editorRef.current) editorRef.current.innerHTML = '<h1>New Document</h1><p>Start writing...</p>';
    }
  };

  const saveToHistory = () => {
    const newVersion: Version = {
      id: Math.random().toString(36).substring(7),
      timestamp: Date.now(),
      content: content,
      wordCount: stats.words
    };
    setVersions([newVersion, ...versions].slice(0, 20)); // Keep last 20
  };

  const loadVersion = (v: Version) => {
    if (window.confirm('Load this version? Current editor content will be replaced.')) {
      setContent(v.content);
      if (editorRef.current) editorRef.current.innerHTML = v.content;
      setShowHistory(false);
    }
  };

  const deleteVersion = (id: string) => {
    setVersions(versions.filter(v => v.id !== id));
  };

  const insertTable = () => {
    const rows = prompt("Number of rows?", "3");
    const cols = prompt("Number of columns?", "3");
    if (!rows || !cols) return;
    let html = '<table style="width:100%; border-collapse: collapse; margin-bottom: 1.5rem;" border="1">';
    for (let i = 0; i < parseInt(rows); i++) {
      html += '<tr>';
      for (let j = 0; j < parseInt(cols); j++) {
        html += '<td style="padding: 8px;">Cell</td>';
      }
      html += '</tr>';
    }
    html += '</table><p><br></p>';
    execCommand('insertHTML', html);
  };

  const insertImage = () => {
    const url = prompt("Image URL:");
    if (url) {
      execCommand('insertHTML', `<img src="${url}" style="max-width:100%; height:auto; border-radius:1rem; margin-bottom:1.5rem;" /><p><br></p>`);
    }
  };

  const handleEmbed = (type: 'youtube' | 'vimeo' | 'custom') => {
    const input = prompt(type === 'custom' ? "Paste embed code:" : `Enter ${type} URL or ID:`);
    if (!input) return;

    let html = '';
    if (type === 'youtube') {
      const id = input.includes('v=') ? input.split('v=')[1].split('&')[0] : input;
      html = `<iframe width="100%" height="400" src="https://www.youtube.com/embed/${id}" frameborder="0" allowfullscreen style="border-radius:1rem; margin-bottom:1.5rem;"></iframe>`;
    } else if (type === 'vimeo') {
      const id = input.split('/').pop();
      html = `<iframe src="https://player.vimeo.com/video/${id}" width="100%" height="400" frameborder="0" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen style="border-radius:1rem; margin-bottom:1.5rem;"></iframe>`;
    } else {
      html = `<div class="custom-embed" style="margin-bottom:1.5rem;">${input}</div>`;
    }
    execCommand('insertHTML', html + '<p><br></p>');
    setShowEmbedModal(false);
  };

  const insertCodeBlock = () => {
    execCommand('insertHTML', `<pre style="background:rgba(0,0,0,0.05); padding:1.5rem; border-radius:1rem; margin-bottom:1.5rem; font-family:monospace;"><code>// Your code here</code></pre><p><br></p>`);
  };

  const onConvertCase = (type: string) => {
    if (editorRef.current) {
      const selection = window.getSelection();
      const selectedText = selection?.toString();
      if (selectedText && selectedText.length > 0) {
        document.execCommand('insertText', false, convertText(selectedText, type));
      } else {
        editorRef.current.innerText = convertText(editorRef.current.innerText, type);
      }
      setContent(editorRef.current.innerHTML);
    }
  };

  const onCopy = async (type: 'plain' | 'markdown') => {
    const text = editorRef.current?.innerText || '';
    const toCopy = type === 'markdown' ? htmlToMarkdown(content) : text;
    try {
      await navigator.clipboard.writeText(toCopy);
    } catch (err) {
      console.error('Failed to copy text:', err);
    }
  };

  const onClear = () => {
    if (window.confirm('Are you sure you want to clear the entire document?')) {
      setContent('');
      if (editorRef.current) {
        editorRef.current.innerHTML = '';
      }
    }
  };

  const handleGenerateMetadata = async (type: 'title' | 'description') => {
    setIsAIProcessing(true);
    try {
      const result = await generateMetadata(editorRef.current?.innerText || content, type);
      if (type === 'title') setMetaTitle(result);
      else setMetaDescription(result);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleAIDetection = async () => {
    setIsAIProcessing(true);
    try {
      const result = await detectAIContent(editorRef.current?.innerText || "");
      alert(`AI Detection Score: ${result.score}%\n\nAnalysis: ${result.analysis}`);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleGenerateFAQs = async () => {
    setIsAIProcessing(true);
    try {
      const result = await generateFAQs(editorRef.current?.innerText || content);
      setFaqs(result);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const faqSchema = useMemo(() => {
    return JSON.stringify({
      "@context": "https://schema.org",
      "@type": "FAQPage",
      "mainEntity": faqs.map(f => ({
        "@type": "Question",
        "name": f.question,
        "acceptedAnswer": {
          "@type": "Answer",
          "text": f.answer
        }
      }))
    }, null, 2);
  }, [faqs]);

  const fontFamilies: Record<string, string> = {
    'Inter': "'Inter', sans-serif",
    'Georgia': "Georgia, serif",
    'monospace': "monospace"
  };

  return (
    <div className="h-screen w-screen flex flex-col md:flex-row bg-white dark:bg-zinc-950 text-zinc-900 dark:text-zinc-100 transition-colors duration-300 overflow-hidden">

      {/* Link Tooltip */}
      {activeLink && (
        <div 
          className="fixed z-[80] bg-zinc-900 text-white dark:bg-white dark:text-zinc-900 px-3 py-1.5 rounded-lg text-[11px] font-bold flex items-center gap-2 shadow-xl border border-white/10 animate-in fade-in zoom-in-95"
          style={{ 
            top: activeLink.rect.top - 40 + window.scrollY, 
            left: activeLink.rect.left + activeLink.rect.width / 2,
            transform: 'translateX(-50%)'
          }}
        >
          <ExternalLink size={12} className="text-blue-400" />
          <span className="max-w-[200px] truncate">{activeLink.url}</span>
          <button onClick={() => window.open(activeLink.url, '_blank')} className="hover:text-blue-400 transition-colors uppercase">Visit</button>
          <div className="w-[1px] h-3 bg-white/20 dark:bg-zinc-200" />
          <button 
            onClick={() => {
              const newUrl = prompt("Enter new URL:", activeLink.url);
              if (newUrl !== null) {
                activeLink.element.href = newUrl;
                setContent(editorRef.current?.innerHTML || '');
              }
            }}
            className="hover:text-blue-400 transition-colors uppercase"
          >
            Edit
          </button>
        </div>
      )}

      {/* Version History Modal */}
      {showHistory && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-black/60 backdrop-blur-md p-4 animate-in fade-in duration-300">
          <div className="bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-[32px] w-full max-w-2xl shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95">
            <div className="p-8 border-b border-zinc-200 dark:border-zinc-800 flex items-center justify-between">
              <div className="flex items-center gap-4">
                <Clock size={24} className="text-blue-500" />
                <h3 className="font-black text-xl uppercase tracking-tighter">History</h3>
              </div>
              <div className="flex gap-2">
                <button onClick={saveToHistory} className="px-4 py-2 bg-blue-600 text-white text-[10px] font-bold uppercase rounded-xl shadow-lg">Snapshot Current</button>
                <button onClick={() => setShowHistory(false)} className="p-3 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-2xl"><X size={24}/></button>
              </div>
            </div>
            <div className="p-4 flex-1 overflow-y-auto max-h-[60vh] custom-scrollbar space-y-3">
              {versions.length > 0 ? versions.map((v) => (
                <div key={v.id} className="p-4 bg-zinc-50 dark:bg-zinc-950 border border-zinc-200 dark:border-zinc-800 rounded-2xl flex items-center justify-between hover:border-blue-500/50 transition-all group">
                  <div>
                    <div className="text-[11px] font-black text-zinc-900 dark:text-zinc-100 uppercase">{new Date(v.timestamp).toLocaleString()}</div>
                    <div className="text-[10px] text-zinc-400 font-bold uppercase mt-1">{v.wordCount} Words</div>
                  </div>
                  <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button onClick={() => loadVersion(v)} className="p-2 bg-blue-500/10 text-blue-500 rounded-lg hover:bg-blue-500 hover:text-white transition-all"><Edit2 size={16} /></button>
                    <button onClick={() => deleteVersion(v.id)} className="p-2 bg-red-500/10 text-red-500 rounded-lg hover:bg-red-500 hover:text-white transition-all"><Trash2 size={16} /></button>
                  </div>
                </div>
              )) : (
                <div className="text-center py-12 text-zinc-400 italic text-sm">No versions saved yet. Click "Snapshot Current" to save the current state.</div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Embed Modal */}
      {showEmbedModal && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-black/60 backdrop-blur-md p-4 animate-in fade-in duration-300">
          <div className="bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-[32px] w-full max-w-sm shadow-2xl overflow-hidden animate-in zoom-in-95">
            <div className="p-6 border-b border-zinc-200 dark:border-zinc-800 flex items-center justify-between">
              <h3 className="font-black text-lg uppercase tracking-tighter">Embed Media</h3>
              <button onClick={() => setShowEmbedModal(false)}><X size={20}/></button>
            </div>
            <div className="p-6 space-y-3">
              {/* Fix: Youtube and Code are now imported from lucide-react at the top of the file */}
              <button onClick={() => handleEmbed('youtube')} className="w-full py-3 bg-red-600 text-white rounded-xl font-bold uppercase text-xs tracking-widest flex items-center justify-center gap-2 shadow-lg"><Youtube size={16}/> YouTube</button>
              <button onClick={() => handleEmbed('vimeo')} className="w-full py-3 bg-blue-400 text-white rounded-xl font-bold uppercase text-xs tracking-widest flex items-center justify-center gap-2 shadow-lg">Vimeo</button>
              <button onClick={() => handleEmbed('custom')} className="w-full py-3 bg-zinc-800 text-white rounded-xl font-bold uppercase text-xs tracking-widest flex items-center justify-center gap-2 shadow-lg"><Code size={16}/> Custom Embed</button>
            </div>
          </div>
        </div>
      )}

      {/* AI Options Modal */}
      {aiOptions && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/60 backdrop-blur-md p-4 animate-in fade-in duration-300">
          <div className="bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-[32px] w-full max-w-4xl shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95">
            <div className="p-8 border-b border-zinc-200 dark:border-zinc-800 flex items-center justify-between bg-zinc-50/50 dark:bg-zinc-800/30">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-blue-500/20">
                  <Sparkles size={24} />
                </div>
                <div>
                  <h3 className="font-black text-xl uppercase tracking-tighter">AI Suggestions</h3>
                  <p className="text-[10px] font-bold text-zinc-400 uppercase tracking-widest mt-1">Select the best version to replace your text</p>
                </div>
              </div>
              <button onClick={() => setAiOptions(null)} className="p-3 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-2xl transition-all"><X size={24}/></button>
            </div>
            <div className="p-8 grid md:grid-cols-2 gap-6 overflow-y-auto max-h-[70vh] custom-scrollbar">
              {aiOptions.map((option, i) => (
                <div key={i} className="group relative bg-zinc-50 dark:bg-zinc-950 border border-zinc-200 dark:border-zinc-800 rounded-3xl p-6 flex flex-col h-full hover:border-blue-500 transition-all duration-300">
                  <div className="absolute top-4 right-4 bg-blue-600/10 text-blue-600 text-[9px] font-black px-2 py-1 rounded-full uppercase tracking-widest">Version {i + 1}</div>
                  <div className="flex-1 text-sm leading-relaxed text-zinc-600 dark:text-zinc-400 italic mb-6">"{option}"</div>
                  <button onClick={() => applyAIOption(option)} className="w-full py-4 bg-white dark:bg-zinc-900 text-zinc-900 dark:text-white border border-zinc-200 dark:border-zinc-800 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-blue-600 hover:text-white hover:border-blue-600 transition-all shadow-lg">Apply Selection</button>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* FAQ Schema Modal */}
      {showSchema && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
          <div className="bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-3xl w-full max-w-2xl shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95">
            <div className="p-6 border-b border-zinc-200 dark:border-zinc-800 flex items-center justify-between">
              <h3 className="font-black text-sm uppercase tracking-wider">FAQ Schema (JSON-LD)</h3>
              <button onClick={() => setShowSchema(false)} className="p-2 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-xl transition-colors"><X size={20}/></button>
            </div>
            <div className="p-6 overflow-hidden">
              <pre className="bg-zinc-50 dark:bg-black/40 p-4 rounded-2xl text-[11px] font-mono overflow-auto max-h-[60vh] border border-zinc-200 dark:border-zinc-800 text-zinc-600 dark:text-zinc-400">
                {faqSchema}
              </pre>
            </div>
            <div className="p-6 bg-zinc-50 dark:bg-zinc-900/50 border-t border-zinc-200 dark:border-zinc-800 flex gap-3">
              <button onClick={() => { navigator.clipboard.writeText(faqSchema); alert("Schema copied!"); }} className="flex-1 py-3 bg-blue-600 text-white rounded-2xl font-bold uppercase text-xs tracking-widest">Copy Schema</button>
              <button onClick={() => setShowSchema(false)} className="px-6 py-3 border border-zinc-200 dark:border-zinc-800 rounded-2xl font-bold uppercase text-xs tracking-widest">Close</button>
            </div>
          </div>
        </div>
      )}

      <div className="flex-1 flex flex-col relative overflow-hidden h-full">
        <header className="h-16 border-b border-zinc-200 dark:border-zinc-800 flex items-center justify-between px-6 glass-panel z-30 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-600 rounded-xl flex items-center justify-center font-black text-white shadow-lg relative">S</div>
            <h1 className="font-bold text-lg tracking-tight hidden sm:block uppercase">SEO Focus <span className="text-zinc-400">Pro</span></h1>
          </div>
          <div className="flex items-center gap-2">
            <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-xl text-zinc-500 transition-colors">
              {isDarkMode ? <Sun size={20} /> : <Moon size={20} />}
            </button>
            <button onClick={() => {
              const element = document.createElement("a");
              const file = new Blob([content], {type: 'text/html'});
              element.href = URL.createObjectURL(file);
              element.download = "seo-content.html";
              element.click();
            }} className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-500 text-white rounded-xl text-sm font-bold shadow-lg transition-all">
              <Download size={16} />
              <span className="hidden sm:inline">Export</span>
            </button>
          </div>
        </header>

        <Toolbar 
          onCommand={execCommand} 
          onPaste={handlePaste as any} 
          fontFamily={fontFamily} 
          fontSize={fontSize} 
          setFontFamily={setFontFamily} 
          setFontSize={setFontSize} 
          onNewDocument={onNewDocument}
          onShowHistory={() => setShowHistory(true)}
          onInsertTable={insertTable}
          onInsertImage={insertImage}
          onInsertEmbed={() => setShowEmbedModal(true)}
          onInsertCodeBlock={insertCodeBlock}
        />

        <main className="flex-1 overflow-y-auto p-6 md:p-12 lg:p-16 flex flex-col items-center custom-scrollbar bg-zinc-50 dark:bg-zinc-950 relative">
          <div className="w-full max-w-4xl relative pb-32">
            <div
              ref={editorRef}
              contentEditable
              onInput={(e) => setContent(e.currentTarget.innerHTML)}
              onPaste={handlePaste}
              onMouseUp={updateActiveLinkStatus}
              onKeyUp={updateActiveLinkStatus}
              onMouseDown={() => {
                setAiOptions(null);
                setActiveLink(null);
              }}
              dangerouslySetInnerHTML={{ __html: content }}
              style={{ fontFamily: fontFamilies[fontFamily], fontSize: fontSize }}
              className="editor-content w-full min-h-[50vh] focus:outline-none text-zinc-800 dark:text-zinc-300 leading-relaxed font-normal"
            />
          </div>
        </main>
      </div>

      <Sidebar 
        activeTab={activeTab} setActiveTab={setActiveTab} 
        stats={stats} readability={readability} health={health} intent={intent} keywords={keywords} 
        seoTab={seoTab} setSeoTab={setSeoTab} isExpanded={isExpanded} setIsExpanded={setIsExpanded} 
        onRewrite={onRewrite} onConvertCase={onConvertCase} onCopy={onCopy} onClear={onClear} 
        isAIProcessing={isAIProcessing} targets={targets} setTargets={setTargets}
        metaTitle={metaTitle} setMetaTitle={setMetaTitle} metaDescription={metaDescription} setMetaDescription={setMetaDescription}
        faqs={faqs} setFaqs={setFaqs} onGenerateMetadata={handleGenerateMetadata} onDetectAI={handleAIDetection} 
        onGenerateFAQs={handleGenerateFAQs} onExportSchema={() => setShowSchema(true)}
      />
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useEffect, useRef, useMemo, useDeferredValue } from 'react';
import ReactDOM from 'react-dom/client';
import { 
  X, Sparkles, Clock, Trash2, Mail, MessageSquare, Send
} from 'lucide-react';

import { getStats } from './core/text-analysis';
import { getKeywords } from './core/keyword-density';
import { getReadabilityScore } from './core/readability';
import { analyzeSEOHealth } from './core/seo-health';
import { detectIntent } from './core/intent-detector';
import { convertText } from './core/case-converter';
import { rewriteContent, generateMetadata, detectAIContent, RewriteMode, generateFAQs } from './ai/ai-engine';
import { htmlToMarkdown } from './utils/text-cleaner';

import { Toolbar } from './components/editor/Toolbar';
import { Sidebar } from './components/layout/Sidebar';
import { Tab, SEOPhraseTab, KeywordTarget, FAQ } from './types/editor.types';

interface Version {
  id: string;
  timestamp: number;
  content: string;
  wordCount: number;
}

const App = () => {
  const [content, setContent] = useState(() => localStorage.getItem('seo-editor-content') || '<h1>SEO Focus Pro</h1><p>Start crafting optimized, AI-enhanced content here. Select text to rewrite or use the tabs on the right to analyze your performance in real-time.</p>');
  const [activeTab, setActiveTab] = useState<Tab>('insights'); 
  const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
  const [isExpanded, setIsExpanded] = useState(false);
  const [activeLink, setActiveLink] = useState<{ element: HTMLAnchorElement, url: string, rect: DOMRect } | null>(null);
  const [isAIProcessing, setIsAIProcessing] = useState(false);

  // Version History State
  const [versions, setVersions] = useState<Version[]>(() => {
    const saved = localStorage.getItem('seo-versions');
    return saved ? JSON.parse(saved) : [];
  });
  const [showHistory, setShowHistory] = useState(false);

  // Report Issue State
  const [showReportModal, setShowReportModal] = useState(false);
  const [reportEmail, setReportEmail] = useState('');
  const [reportIssue, setReportIssue] = useState('');

  // AI Options Modal state
  const [aiOptions, setAiOptions] = useState<string[] | null>(null);
  const [savedSelection, setSavedSelection] = useState<Range | null>(null);

  // Metadata State
  const [metaTitle, setMetaTitle] = useState(() => localStorage.getItem('seo-meta-title') || '');
  const [metaDescription, setMetaDescription] = useState(() => localStorage.getItem('seo-meta') || '');
  const [targets, setTargets] = useState<KeywordTarget>(() => {
    const saved = localStorage.getItem('seo-targets');
    return saved ? JSON.parse(saved) : { primary: '', secondary: ['', '', ''] };
  });
  const [faqs, setFaqs] = useState<FAQ[]>(() => {
    const saved = localStorage.getItem('seo-faqs');
    return saved ? JSON.parse(saved) : [];
  });
  const [showSchema, setShowSchema] = useState(false);

  const editorRef = useRef<HTMLDivElement>(null);
  const [debouncedContent, setDebouncedContent] = useState(content);
  const deferredContent = useDeferredValue(debouncedContent);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedContent(content);
      localStorage.setItem('seo-editor-content', content);
      localStorage.setItem('seo-targets', JSON.stringify(targets));
      localStorage.setItem('seo-meta', metaDescription);
      localStorage.setItem('seo-meta-title', metaTitle);
      localStorage.setItem('seo-faqs', JSON.stringify(faqs));
      localStorage.setItem('seo-versions', JSON.stringify(versions));
    }, 500);
    return () => clearTimeout(handler);
  }, [content, targets, metaDescription, metaTitle, faqs, versions]);

  const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
  const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
  const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
  const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, targets, metaDescription), [deferredContent, keywords, targets, metaDescription]);
  const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);

  const handleUpdate = () => {
    if (editorRef.current) {
      setContent(editorRef.current.innerHTML);
    }
  };

  const updateActiveLinkStatus = () => {
    const selection = window.getSelection();
    if (selection && selection.rangeCount > 0) {
      let node = selection.getRangeAt(0).startContainer;
      let parent: HTMLElement | null = node.nodeType === 3 ? node.parentElement : node as HTMLElement;

      while (parent && parent !== editorRef.current) {
        if (parent.tagName === 'A') {
          const rect = (parent as HTMLAnchorElement).getBoundingClientRect();
          setActiveLink({ 
            element: parent as HTMLAnchorElement, 
            url: (parent as HTMLAnchorElement).href,
            rect
          });
          return;
        }
        parent = parent.parentElement;
      }
    }
    setActiveLink(null);
  };

  const onRewrite = async (mode: RewriteMode) => {
    const selection = window.getSelection();
    const textToProcess = (selection && selection.toString().trim().length > 0) 
      ? selection.toString() 
      : "";

    if (!textToProcess) {
      alert("Please select text in the editor to use AI rewrite options.");
      return;
    }

    if (selection && selection.rangeCount > 0) {
      setSavedSelection(selection.getRangeAt(0).cloneRange());
    }

    setIsAIProcessing(true);
    try {
      const results = await rewriteContent(textToProcess, mode);
      setAiOptions(results);
    } catch (err) {
      console.error(err);
      alert("AI Processing failed. Please check your connection.");
    } finally {
      setIsAIProcessing(false);
    }
  };

  const applyAIOption = (text: string) => {
    if (!savedSelection) return;

    const selection = window.getSelection();
    if (selection) {
      selection.removeAllRanges();
      selection.addRange(savedSelection);
      document.execCommand('insertText', false, text);
      handleUpdate();
    }
    setAiOptions(null);
    setSavedSelection(null);
  };

  const handleReportSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!reportEmail || !reportIssue) return;

    // Simulate sending report
    console.log(`Sending report from ${reportEmail} to rathod.shivang@gmail.com: ${reportIssue}`);
    alert("Issue reported successfully to the administrator.");
    setShowReportModal(false);
    setReportEmail('');
    setReportIssue('');
  };

  const onCopy = async (type: 'plain' | 'markdown') => {
    const text = editorRef.current?.innerText || '';
    const toCopy = type === 'markdown' ? htmlToMarkdown(content) : text;
    try {
      await navigator.clipboard.writeText(toCopy);
    } catch (err) {
      console.error('Failed to copy text:', err);
    }
  };

  const onClear = () => {
    if (window.confirm('Are you sure you want to clear the entire document?')) {
      setContent('');
      if (editorRef.current) {
        editorRef.current.innerHTML = '';
      }
    }
  };

  const handleGenerateMetadata = async (type: 'title' | 'description') => {
    setIsAIProcessing(true);
    try {
      const result = await generateMetadata(editorRef.current?.innerText || content, type);
      if (type === 'title') setMetaTitle(result);
      else setMetaDescription(result);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleAIDetection = async () => {
    setIsAIProcessing(true);
    try {
      const result = await detectAIContent(editorRef.current?.innerText || "");
      alert(`AI Detection Score: ${result.score}%\n\nAnalysis: ${result.analysis}`);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleGenerateFAQs = async () => {
    setIsAIProcessing(true);
    try {
      const result = await generateFAQs(editorRef.current?.innerText || content);
      setFaqs(result);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  return (
    <div className="h-screen w-screen flex flex-col md:flex-row bg-zinc-950 text-zinc-100 transition-colors duration-300 overflow-hidden">

      {/* Report Issue Modal */}
      {showReportModal && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center bg-black/80 backdrop-blur-md p-4 animate-in fade-in">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[32px] w-full max-w-md shadow-2xl overflow-hidden animate-in zoom-in-95">
            <div className="p-8 border-b border-zinc-800 flex items-center justify-between">
              <h3 className="font-black text-xl uppercase tracking-tighter flex items-center gap-2">
                <Mail className="text-blue-500" size={24} /> Report Issue
              </h3>
              <button onClick={() => setShowReportModal(false)} className="p-2 hover:bg-zinc-800 rounded-full transition-colors"><X size={24}/></button>
            </div>
            <form onSubmit={handleReportSubmit} className="p-8 space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-zinc-400 tracking-widest">Your Email</label>
                <div className="relative">
