import React, { useRef, useState } from 'react';
import { 
  Bold, Italic, Underline, Link as LinkIcon, 
  List, ListOrdered, ChevronDown, Type, Undo, Redo,
  FilePlus, History, Table as TableIcon, Image as ImageIcon,
  Youtube, Code as CodeIcon, Plus, Save, X, Globe, Upload
} from 'lucide-react';

interface ToolbarProps {
  editorRef: React.RefObject<HTMLDivElement | null>;
  onUpdate: () => void;
  onNewDocument: () => void;
  onShowHistory: () => void;
  onSaveVersion: () => void;
}

const ToolbarGroup = ({ children }: { children?: React.ReactNode }) => (
  <div className="flex bg-zinc-800/50 p-1 rounded-xl border border-zinc-700/50 shadow-sm mx-1 items-center">{children}</div>
);

const ToolbarButton = ({ icon, onClick, title, active = false }: any) => (
  <button 
    onMouseDown={(e) => { e.preventDefault(); onClick(e); }} 
    className={`w-10 h-10 flex items-center justify-center hover:bg-zinc-700 rounded-lg transition-all ${active ? 'text-blue-500 bg-blue-500/10' : 'text-zinc-500'}`} 
    title={title}
  >
    {icon}
  </button>
);

export const Toolbar = ({ 
  editorRef,
  onUpdate,
  onNewDocument,
  onShowHistory,
  onSaveVersion
}: ToolbarProps) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [showEmbedModal, setShowEmbedModal] = useState(false);
  const [showImageModal, setShowImageModal] = useState(false);

  const execCommand = (command: string, value: string = '') => {
    if (editorRef.current) {
      editorRef.current.focus();
      document.execCommand(command, false, value);
      onUpdate();
    }
  };

  const insertTable = () => {
    const rows = prompt("Number of rows?", "3");
    const cols = prompt("Number of columns?", "3");
    if (!rows || !cols) return;
    let html = '<table style="width:100%; border-collapse: collapse; margin-bottom: 1.5rem; border: 1px solid #3f3f46;" border="1">';
    for (let i = 0; i < parseInt(rows); i++) {
      html += '<tr>';
      for (let j = 0; j < parseInt(cols); j++) {
        html += '<td style="padding: 12px; border: 1px solid #3f3f46; color: #d4d4d8;">Cell</td>';
      }
      html += '</tr>';
    }
    html += '</table><p><br></p>';
    execCommand('insertHTML', html);
  };

  const insertImageFromUrl = () => {
    const url = prompt("Image URL:");
    if (url) {
      execCommand('insertHTML', `<img src="${url}" style="max-width:100%; height:auto; border-radius:1rem; margin-bottom:1.5rem; display:block;" /><p><br></p>`);
      setShowImageModal(false);
    }
  };

  const handleLocalImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        const base64 = event.target?.result as string;
        execCommand('insertHTML', `<img src="${base64}" style="max-width:100%; height:auto; border-radius:1rem; margin-bottom:1.5rem; display:block;" /><p><br></p>`);
      };
      reader.readAsDataURL(file);
      setShowImageModal(false);
    }
  };

  const handleEmbed = (type: 'youtube' | 'vimeo' | 'custom') => {
    const input = prompt(type === 'custom' ? "Paste embed code:" : `Enter ${type} URL or ID:`);
    if (!input) return;

    let html = '';
    if (type === 'youtube') {
      const id = input.includes('v=') ? input.split('v=')[1].split('&')[0] : input;
      html = `<div style="position:relative; padding-bottom:56.25%; height:0; overflow:hidden; border-radius:1rem; margin-bottom:1.5rem;"><iframe width="100%" height="100%" src="https://www.youtube.com/embed/${id}" frameborder="0" allowfullscreen style="position:absolute; top:0; left:0;"></iframe></div>`;
    } else if (type === 'vimeo') {
      const id = input.split('/').pop();
      html = `<div style="position:relative; padding-bottom:56.25%; height:0; overflow:hidden; border-radius:1rem; margin-bottom:1.5rem;"><iframe src="https://player.vimeo.com/video/${id}" width="100%" height="100%" frameborder="0" allow="autoplay; fullscreen" allowfullscreen style="position:absolute; top:0; left:0;"></iframe></div>`;
    } else {
      html = `<div class="custom-embed" style="margin-bottom:1.5rem;">${input}</div>`;
    }
    execCommand('insertHTML', html + '<p><br></p>');
    setShowEmbedModal(false);
  };

  return (
    <>
      <div className="border-b border-zinc-800 bg-zinc-900/50 backdrop-blur-md p-2 flex flex-wrap gap-1 sticky top-0 z-20 overflow-x-auto no-scrollbar items-center shrink-0">
        <ToolbarGroup>
          <ToolbarButton icon={<FilePlus size={18} />} onClick={onNewDocument} title="New Document" />
          <ToolbarButton icon={<Save size={18} />} onClick={onSaveVersion} title="Save Snapshot" />
          <ToolbarButton icon={<History size={18} />} onClick={onShowHistory} title="Version History" />
        </ToolbarGroup>

        <ToolbarGroup>
          <ToolbarButton icon={<Undo size={18} />} onClick={() => execCommand('undo')} title="Undo" />
          <ToolbarButton icon={<Redo size={18} />} onClick={() => execCommand('redo')} title="Redo" />
        </ToolbarGroup>

        <ToolbarGroup>
          <div className="relative flex items-center px-2">
            <Type size={14} className="text-zinc-400 mr-2" />
            <select 
              onChange={(e) => execCommand('formatBlock', e.target.value)} 
              className="bg-transparent appearance-none text-[11px] font-black uppercase outline-none cursor-pointer pr-6 py-2 tracking-wider text-zinc-300"
              defaultValue="p"
            >
              <option value="p">Paragraph</option>
              <option value="h1">Heading 1</option>
              <option value="h2">Heading 2</option>
              <option value="h3">Heading 3</option>
              <option value="h4">Heading 4</option>
              <option value="h5">Heading 5</option>
              <option value="h6">Heading 6</option>
              <option value="blockquote">Quote Block</option>
            </select>
            <ChevronDown size={12} className="absolute right-2 pointer-events-none text-zinc-400" />
          </div>
        </ToolbarGroup>

        <ToolbarGroup>
          <ToolbarButton icon={<Bold size={18} />} onClick={() => execCommand('bold')} title="Bold" />
          <ToolbarButton icon={<Italic size={18} />} onClick={() => execCommand('italic')} title="Italic" />
          <ToolbarButton icon={<Underline size={18} />} onClick={() => execCommand('underline')} title="Underline" />
        </ToolbarGroup>

        <ToolbarGroup>
          <ToolbarButton icon={<TableIcon size={18} />} onClick={insertTable} title="Insert Table" />
          <ToolbarButton icon={<ImageIcon size={18} />} onClick={() => setShowImageModal(true)} title="Insert Image" />
          <ToolbarButton icon={<Youtube size={18} />} onClick={() => setShowEmbedModal(true)} title="Embed Media" />
          <ToolbarButton icon={<CodeIcon size={18} />} onClick={() => execCommand('insertHTML', `<pre style="background:#18181b; color:#d4d4d8; padding:1.5rem; border-radius:1rem; border:1px solid #27272a; margin-bottom: 1.5rem; font-family: monospace;"><code>// Code block</code></pre><p><br></p>`)} title="Insert Code Block" />
        </ToolbarGroup>

        <ToolbarGroup>
          <ToolbarButton icon={<List size={18} />} onClick={() => execCommand('insertUnorderedList')} title="Bullet List" />
          <ToolbarButton icon={<ListOrdered size={18} />} onClick={() => execCommand('insertOrderedList')} title="Numbered List" />
          <ToolbarButton icon={<LinkIcon size={18} />} onClick={() => {
            const url = prompt("Enter URL:");
            if (url) execCommand('createLink', url);
          }} title="Insert Link" />
        </ToolbarGroup>
      </div>

      {/* Embed Choice Modal */}
      {showEmbedModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/80 backdrop-blur-md p-4">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[32px] w-full max-w-sm shadow-2xl overflow-hidden animate-in zoom-in-95">
            <div className="p-6 border-b border-zinc-800 flex items-center justify-between">
              <h3 className="font-black text-lg uppercase tracking-tighter">Embed Media</h3>
              <button onClick={() => setShowEmbedModal(false)}><X size={20}/></button>
            </div>
            <div className="p-6 space-y-3">
              <button onClick={() => handleEmbed('youtube')} className="w-full py-4 bg-red-600/10 text-red-500 rounded-2xl font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-3 border border-red-500/20 hover:bg-red-600/20"><Youtube size={16}/> YouTube</button>
              <button onClick={() => handleEmbed('vimeo')} className="w-full py-4 bg-blue-500/10 text-blue-500 rounded-2xl font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-3 border border-blue-500/20 hover:bg-blue-500/20">Vimeo</button>
              <button onClick={() => handleEmbed('custom')} className="w-full py-4 bg-zinc-800 text-zinc-300 rounded-2xl font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-3 border border-zinc-700 hover:bg-zinc-700"><CodeIcon size={16}/> Embed Code</button>
            </div>
          </div>
        </div>
      )}

      {/* Image Choice Modal */}
      {showImageModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/80 backdrop-blur-md p-4">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[32px] w-full max-w-sm shadow-2xl overflow-hidden animate-in zoom-in-95">
            <div className="p-6 border-b border-zinc-800 flex items-center justify-between">
              <h3 className="font-black text-lg uppercase tracking-tighter">Insert Image</h3>
              <button onClick={() => setShowImageModal(false)}><X size={20}/></button>
            </div>
            <div className="p-6 space-y-3">
              <button onClick={insertImageFromUrl} className="w-full py-4 bg-blue-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-3 shadow-lg"><Globe size={16}/> Image URL</button>
              <button onClick={() => fileInputRef.current?.click()} className="w-full py-4 bg-zinc-800 text-zinc-300 rounded-2xl font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-3 border border-zinc-700 hover:bg-zinc-700"><Upload size={16}/> Upload Local</button>
              <input 
                type="file" 
                ref={fileInputRef} 
                className="hidden" 
                accept="image/*" 
                onChange={handleLocalImageUpload}
              />
            </div>
          </div>
        </div>
      )}
    </>
  );
};

import React, { useState, useEffect, useRef, useMemo, useDeferredValue } from 'react';
import ReactDOM from 'react-dom/client';
import { Editor } from '@tinymce/tinymce-react';
import { 
  X, Sparkles, Clock, Trash2, Mail, MessageSquare, Send
} from 'lucide-react';

import { getStats } from './core/text-analysis';
import { getKeywords } from './core/keyword-density';
import { getReadabilityScore } from './core/readability';
import { analyzeSEOHealth } from './core/seo-health';
import { detectIntent } from './core/intent-detector';
import { convertText } from './core/case-converter';
import { rewriteContent, generateMetadata, detectAIContent, RewriteMode, generateFAQs } from './ai/ai-engine';
import { htmlToMarkdown } from './utils/text-cleaner';

import { Toolbar } from './components/editor/Toolbar';
import { Sidebar } from './components/layout/Sidebar';
import { Tab, SEOPhraseTab, KeywordTarget, FAQ } from './types/editor.types';

interface Version {
  id: string;
  timestamp: number;
  content: string;
  wordCount: number;
}

const App = () => {
  const [content, setContent] = useState(() => localStorage.getItem('seo-editor-content') || '<h1>SEO Focus Pro</h1><p>Start crafting optimized, AI-enhanced content here. Select text to rewrite or use the tabs on the right to analyze your performance in real-time.</p>');
  const [activeTab, setActiveTab] = useState<Tab>('insights'); 
  const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
  const [isExpanded, setIsExpanded] = useState(false);
  const [activeLink, setActiveLink] = useState<{ element: HTMLElement, url: string, rect: DOMRect } | null>(null);
  const [isAIProcessing, setIsAIProcessing] = useState(false);

  // TinyMCE instance ref
  const tinymceRef = useRef<any>(null);

  // Version History State
  const [versions, setVersions] = useState<Version[]>(() => {
    const saved = localStorage.getItem('seo-versions');
    return saved ? JSON.parse(saved) : [];
  });
  const [showHistory, setShowHistory] = useState(false);

  // Report Issue State
  const [showReportModal, setShowReportModal] = useState(false);
  const [reportEmail, setReportEmail] = useState('');
  const [reportIssue, setReportIssue] = useState('');

  // AI Options Modal state
  const [aiOptions, setAiOptions] = useState<string[] | null>(null);

  // Metadata State
  const [metaTitle, setMetaTitle] = useState(() => localStorage.getItem('seo-meta-title') || '');
  const [metaDescription, setMetaDescription] = useState(() => localStorage.getItem('seo-meta') || '');
  const [targets, setTargets] = useState<KeywordTarget>(() => {
    const saved = localStorage.getItem('seo-targets');
    return saved ? JSON.parse(saved) : { primary: '', secondary: ['', '', ''] };
  });
  const [faqs, setFaqs] = useState<FAQ[]>(() => {
    const saved = localStorage.getItem('seo-faqs');
    return saved ? JSON.parse(saved) : [];
  });
  const [showSchema, setShowSchema] = useState(false);

  const [debouncedContent, setDebouncedContent] = useState(content);
  const deferredContent = useDeferredValue(debouncedContent);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedContent(content);
      localStorage.setItem('seo-editor-content', content);
      localStorage.setItem('seo-targets', JSON.stringify(targets));
      localStorage.setItem('seo-meta', metaDescription);
      localStorage.setItem('seo-meta-title', metaTitle);
      localStorage.setItem('seo-faqs', JSON.stringify(faqs));
      localStorage.setItem('seo-versions', JSON.stringify(versions));
    }, 500);
    return () => clearTimeout(handler);
  }, [content, targets, metaDescription, metaTitle, faqs, versions]);

  const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
  const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
  const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
  const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, targets, metaDescription), [deferredContent, keywords, targets, metaDescription]);
  const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);

  const onRewrite = async (mode: RewriteMode) => {
    const editor = tinymceRef.current;
    if (!editor) return;

    const textToProcess = editor.selection.getContent({ format: 'text' }).trim();

    if (!textToProcess) {
      alert("Please select text in the editor to use AI rewrite options.");
      return;
    }

    setIsAIProcessing(true);
    try {
      const results = await rewriteContent(textToProcess, mode);
      setAiOptions(results);
    } catch (err) {
      console.error(err);
      alert("AI Processing failed. Please check your connection.");
    } finally {
      setIsAIProcessing(false);
    }
  };

  const applyAIOption = (text: string) => {
    const editor = tinymceRef.current;
    if (editor) {
      editor.selection.setContent(text);
      setContent(editor.getContent());
    }
    setAiOptions(null);
  };

  const handleReportSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!reportEmail || !reportIssue) return;
    console.log(`Sending report from ${reportEmail} to rathod.shivang@gmail.com: ${reportIssue}`);
    alert("Issue reported successfully to the administrator.");
    setShowReportModal(false);
    setReportEmail('');
    setReportIssue('');
  };

  const onCopy = async (type: 'plain' | 'markdown') => {
    const text = tinymceRef.current?.getContent({ format: 'text' }) || '';
    const toCopy = type === 'markdown' ? htmlToMarkdown(content) : text;
    try {
      await navigator.clipboard.writeText(toCopy);
    } catch (err) {
      console.error('Failed to copy text:', err);
    }
  };

  const onClear = () => {
    if (window.confirm('Are you sure you want to clear the entire document?')) {
      if (tinymceRef.current) {
        tinymceRef.current.setContent('');
        setContent('');
      }
    }
  };

  const handleGenerateMetadata = async (type: 'title' | 'description') => {
    setIsAIProcessing(true);
    try {
      const result = await generateMetadata(tinymceRef.current?.getContent({ format: 'text' }) || content, type);
      if (type === 'title') setMetaTitle(result);
      else setMetaDescription(result);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleAIDetection = async () => {
    setIsAIProcessing(true);
    try {
      const result = await detectAIContent(tinymceRef.current?.getContent({ format: 'text' }) || "");
      alert(`AI Detection Score: ${result.score}%\n\nAnalysis: ${result.analysis}`);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleGenerateFAQs = async () => {
    setIsAIProcessing(true);
    try {
      const result = await generateFAQs(tinymceRef.current?.getContent({ format: 'text' }) || content);
      setFaqs(result);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  return (
    <div className="h-screen w-screen flex flex-col md:flex-row bg-zinc-950 text-zinc-100 transition-colors duration-300 overflow-hidden">

      {/* Report Issue Modal */}
      {showReportModal && (
