import React, { useRef, useState } from 'react';
import { 
  Bold, Italic, Underline, Link as LinkIcon, 
  List, ListOrdered, ChevronDown, Type, Undo, Redo,
  FilePlus, History, Table as TableIcon, Image as ImageIcon,
  Youtube, Code as CodeIcon, Save, X, Globe, Upload
} from 'lucide-react';

interface ToolbarProps {
  editorInstance: any;
  onUpdate: () => void;
  onNewDocument: () => void;
  onShowHistory: () => void;
  onSaveVersion: () => void;
}

const ToolbarGroup = ({ children }: { children?: React.ReactNode }) => (
  <div className="flex bg-zinc-800/50 p-1 rounded-xl border border-zinc-700/50 shadow-sm mx-1 items-center">{children}</div>
);

const ToolbarButton = ({ icon, onClick, title, active = false }: any) => (
  <button 
    onMouseDown={(e) => { e.preventDefault(); onClick(e); }} 
    className={`w-10 h-10 flex items-center justify-center hover:bg-zinc-700 rounded-lg transition-all ${active ? 'text-blue-500 bg-blue-500/10' : 'text-zinc-500'}`} 
    title={title}
  >
    {icon}
  </button>
);

export const Toolbar = ({ 
  editorInstance,
  onUpdate,
  onNewDocument,
  onShowHistory,
  onSaveVersion
}: ToolbarProps) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [showEmbedModal, setShowEmbedModal] = useState(false);
  const [showImageModal, setShowImageModal] = useState(false);

  const execCommand = (command: string, value: string = '') => {
    if (editorInstance) {
      editorInstance.focus();
      editorInstance.execCommand(command, false, value);
      onUpdate();
    }
  };

  const insertTable = () => {
    const rows = prompt("Number of rows?", "3");
    const cols = prompt("Number of columns?", "3");
    if (!rows || !cols) return;

    if (editorInstance) {
      editorInstance.plugins.table.insertTable(parseInt(cols), parseInt(rows));
      onUpdate();
    }
  };

  const insertImageFromUrl = () => {
    const url = prompt("Image URL:");
    if (url && editorInstance) {
      editorInstance.insertContent(`<img src="${url}" style="max-width:100%; height:auto; border-radius:1rem; margin-bottom:1.5rem; display:block;" />`);
      onUpdate();
      setShowImageModal(false);
    }
  };

  const handleLocalImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && editorInstance) {
      const reader = new FileReader();
      reader.onload = (event) => {
        const base64 = event.target?.result as string;
        editorInstance.insertContent(`<img src="${base64}" style="max-width:100%; height:auto; border-radius:1rem; margin-bottom:1.5rem; display:block;" />`);
        onUpdate();
      };
      reader.readAsDataURL(file);
      setShowImageModal(false);
    }
  };

  const handleEmbed = (type: 'youtube' | 'vimeo' | 'custom') => {
    const input = prompt(type === 'custom' ? "Paste embed code:" : `Enter ${type} URL or ID:`);
    if (!input || !editorInstance) return;

    let html = '';
    if (type === 'youtube') {
      const id = input.includes('v=') ? input.split('v=')[1].split('&')[0] : input;
      html = `<div style="position:relative; padding-bottom:56.25%; height:0; overflow:hidden; border-radius:1rem; margin-bottom:1.5rem;"><iframe width="100%" height="100%" src="https://www.youtube.com/embed/${id}" frameborder="0" allowfullscreen style="position:absolute; top:0; left:0;"></iframe></div>`;
    } else if (type === 'vimeo') {
      const id = input.split('/').pop();
      html = `<div style="position:relative; padding-bottom:56.25%; height:0; overflow:hidden; border-radius:1rem; margin-bottom:1.5rem;"><iframe src="https://player.vimeo.com/video/${id}" width="100%" height="100%" frameborder="0" allow="autoplay; fullscreen" allowfullscreen style="position:absolute; top:0; left:0;"></iframe></div>`;
    } else {
      html = `<div class="custom-embed" style="margin-bottom:1.5rem;">${input}</div>`;
    }

    editorInstance.insertContent(html);
    onUpdate();
    setShowEmbedModal(false);
  };

  return (
    <>
      <div className="border-b border-zinc-800 bg-zinc-900/50 backdrop-blur-md p-2 flex flex-wrap gap-1 sticky top-0 z-20 overflow-x-auto no-scrollbar items-center shrink-0">
        <ToolbarGroup>
          <ToolbarButton icon={<FilePlus size={18} />} onClick={onNewDocument} title="New Document" />
          <ToolbarButton icon={<Save size={18} />} onClick={onSaveVersion} title="Save Snapshot" />
          <ToolbarButton icon={<History size={18} />} onClick={onShowHistory} title="Version History" />
        </ToolbarGroup>

        <ToolbarGroup>
          <ToolbarButton icon={<Undo size={18} />} onClick={() => execCommand('undo')} title="Undo" />
          <ToolbarButton icon={<Redo size={18} />} onClick={() => execCommand('redo')} title="Redo" />
        </ToolbarGroup>

        <ToolbarGroup>
          <div className="relative flex items-center px-2">
            <Type size={14} className="text-zinc-400 mr-2" />
            <select 
              onChange={(e) => execCommand('FormatBlock', e.target.value)} 
              className="bg-transparent appearance-none text-[11px] font-black uppercase outline-none cursor-pointer pr-6 py-2 tracking-wider text-zinc-300"
              defaultValue="p"
            >
              <option value="p">Paragraph</option>
              <option value="h1">Heading 1</option>
              <option value="h2">Heading 2</option>
              <option value="h3">Heading 3</option>
              <option value="h4">Heading 4</option>
              <option value="h5">Heading 5</option>
              <option value="h6">Heading 6</option>
              <option value="blockquote">Quote Block</option>
            </select>
            <ChevronDown size={12} className="absolute right-2 pointer-events-none text-zinc-400" />
          </div>
        </ToolbarGroup>

        <ToolbarGroup>
          <ToolbarButton icon={<Bold size={18} />} onClick={() => execCommand('bold')} title="Bold" />
          <ToolbarButton icon={<Italic size={18} />} onClick={() => execCommand('italic')} title="Italic" />
          <ToolbarButton icon={<Underline size={18} />} onClick={() => execCommand('underline')} title="Underline" />
        </ToolbarGroup>

        <ToolbarGroup>
          <ToolbarButton icon={<TableIcon size={18} />} onClick={insertTable} title="Insert Table" />
          <ToolbarButton icon={<ImageIcon size={18} />} onClick={() => setShowImageModal(true)} title="Insert Image" />
          <ToolbarButton icon={<Youtube size={18} />} onClick={() => setShowEmbedModal(true)} title="Embed Media" />
          <ToolbarButton icon={<CodeIcon size={18} />} onClick={() => {
            if (editorInstance) {
              editorInstance.insertContent(`<pre><code>// Code block</code></pre><p>&nbsp;</p>`);
              onUpdate();
            }
          }} title="Insert Code Block" />
        </ToolbarGroup>

        <ToolbarGroup>
          <ToolbarButton icon={<List size={18} />} onClick={() => execCommand('InsertUnorderedList')} title="Bullet List" />
          <ToolbarButton icon={<ListOrdered size={18} />} onClick={() => execCommand('InsertOrderedList')} title="Numbered List" />
          <ToolbarButton icon={<LinkIcon size={18} />} onClick={() => {
            const url = prompt("Enter URL:");
            if (url) execCommand('CreateLink', url);
          }} title="Insert Link" />
        </ToolbarGroup>
      </div>

      {/* Embed Choice Modal */}
      {showEmbedModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/80 backdrop-blur-md p-4">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[32px] w-full max-w-sm shadow-2xl overflow-hidden animate-in zoom-in-95">
            <div className="p-6 border-b border-zinc-800 flex items-center justify-between">
              <h3 className="font-black text-lg uppercase tracking-tighter text-white">Embed Media</h3>
              <button onClick={() => setShowEmbedModal(false)} className="text-zinc-400 hover:text-white"><X size={20}/></button>
            </div>
            <div className="p-6 space-y-3">
              <button onClick={() => handleEmbed('youtube')} className="w-full py-4 bg-red-600/10 text-red-500 rounded-2xl font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-3 border border-red-500/20 hover:bg-red-600/20 transition-all"><Youtube size={16}/> YouTube</button>
              <button onClick={() => handleEmbed('vimeo')} className="w-full py-4 bg-blue-500/10 text-blue-500 rounded-2xl font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-3 border border-blue-500/20 hover:bg-blue-500/20 transition-all">Vimeo</button>
              <button onClick={() => handleEmbed('custom')} className="w-full py-4 bg-zinc-800 text-zinc-300 rounded-2xl font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-3 border border-zinc-700 hover:bg-zinc-700 transition-all"><CodeIcon size={16}/> Embed Code</button>
            </div>
          </div>
        </div>
      )}

      {/* Image Choice Modal */}
      {showImageModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/80 backdrop-blur-md p-4">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[32px] w-full max-w-sm shadow-2xl overflow-hidden animate-in zoom-in-95">
            <div className="p-6 border-b border-zinc-800 flex items-center justify-between">
              <h3 className="font-black text-lg uppercase tracking-tighter text-white">Insert Image</h3>
              <button onClick={() => setShowImageModal(false)} className="text-zinc-400 hover:text-white"><X size={20}/></button>
            </div>
            <div className="p-6 space-y-3">
              <button onClick={insertImageFromUrl} className="w-full py-4 bg-blue-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-3 shadow-lg hover:bg-blue-500 transition-all"><Globe size={16}/> Image URL</button>
              <button onClick={() => fileInputRef.current?.click()} className="w-full py-4 bg-zinc-800 text-zinc-300 rounded-2xl font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-3 border border-zinc-700 hover:bg-zinc-700 transition-all"><Upload size={16}/> Upload Local</button>
              <input 
                type="file" 
                ref={fileInputRef} 
                className="hidden" 
                accept="image/*" 
                onChange={handleLocalImageUpload}
              />
            </div>
          </div>
        </div>
      )}
    </>
  );
};

