            const selectedText = editor.selection.getContent({ format: 'text' });
            if (selectedText) {
              editor.selection.setContent(convertText(selectedText, type));
              setContent(editor.getContent());
            }
          }
        }} 
        onCopy={onCopy} onClear={onClear} 
        isAIProcessing={isAIProcessing} targets={targets} setTargets={setTargets}
        metaTitle={metaTitle} setMetaTitle={setMetaTitle} metaDescription={metaDescription} setMetaDescription={setMetaDescription}
        faqs={faqs} setFaqs={setFaqs} onGenerateMetadata={handleGenerateMetadata} onDetectAI={handleAIDetection} 
        onGenerateFAQs={handleGenerateFAQs} onExportSchema={() => setShowSchema(true)}
      />
    </div>
  );
};

