                <Mail className="text-blue-500" size={24} /> Report Issue
              </h3>
              <button onClick={() => setShowReportModal(false)} className="p-2 hover:bg-zinc-800 rounded-full transition-colors"><X size={24}/></button>
            </div>
            <form onSubmit={handleReportSubmit} className="p-8 space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-zinc-400 tracking-widest">Your Email</label>
                <div className="relative">
                  <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-500" size={16} />
                  <input 
                    type="email" 
                    required
                    value={reportEmail}
                    onChange={(e) => setReportEmail(e.target.value)}
                    placeholder="name@example.com"
                    className="w-full bg-zinc-800 border border-zinc-700 rounded-2xl py-3 pl-12 pr-4 text-sm focus:border-blue-500 outline-none transition-all"
                  />
