                  <MessageSquare className="absolute left-4 top-4 text-zinc-500" size={16} />
                  <textarea 
                    required
                    rows={4}
                    value={reportIssue}
                    onChange={(e) => setReportIssue(e.target.value)}
                    placeholder="Describe the bug..."
                    className="w-full bg-zinc-800 border border-zinc-700 rounded-2xl py-3 pl-12 pr-4 text-sm focus:border-blue-500 outline-none transition-all resize-none"
                  />
                </div>
              </div>
              <button type="submit" className="w-full py-4 bg-blue-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-blue-500 transition-all flex items-center justify-center gap-2 shadow-lg shadow-blue-500/20"><Send size={16} /> Submit</button>
            </form>
          </div>
        </div>
      )}

      {/* AI Suggestions Modal */}
      {aiOptions && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/60 backdrop-blur-md p-4 animate-in fade-in">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[32px] w-full max-w-4xl shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95">
            <div className="p-8 border-b border-zinc-800 flex items-center justify-between bg-zinc-800/30">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-lg"><Sparkles size={24} /></div>
                <h3 className="font-black text-xl uppercase tracking-tighter">AI Suggestions</h3>
              </div>
              <button onClick={() => setAiOptions(null)} className="p-3 hover:bg-zinc-800 rounded-2xl"><X size={24}/></button>
            </div>
            <div className="p-8 grid md:grid-cols-2 gap-6 overflow-y-auto max-h-[70vh] custom-scrollbar">
              {aiOptions.map((option, i) => (
                <div key={i} className="bg-zinc-950 border border-zinc-800 rounded-3xl p-6 flex flex-col h-full hover:border-blue-500 transition-all duration-300">
                  <div className="flex-1 text-sm leading-relaxed text-zinc-400 italic mb-6">"{option}"</div>
                  <button onClick={() => applyAIOption(option)} className="w-full py-4 bg-zinc-900 text-white border border-zinc-800 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-blue-600 transition-all">Apply Selection</button>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      <div className="flex-1 flex flex-col relative overflow-hidden h-full">
        <header className="h-16 border-b border-zinc-800 flex items-center justify-between px-6 glass-panel z-30 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-600 rounded-xl flex items-center justify-center font-black text-white shadow-lg">S</div>
            <h1 className="font-bold text-lg tracking-tight uppercase">SEO Focus <span className="text-zinc-400">Pro</span></h1>
          </div>
          <button onClick={() => setShowReportModal(true)} className="px-4 py-2 bg-zinc-800 hover:bg-zinc-700 text-zinc-300 rounded-xl text-xs font-bold transition-all flex items-center gap-2"><Mail size={14} /><span>Report Issue</span></button>
        </header>

        <Toolbar 
          editorInstance={tinymceRef.current}
          onUpdate={() => startTransition(() => setContent(tinymceRef.current?.getContent() || ''))}
          onNewDocument={() => {
            if (window.confirm('Clear all and start new?')) {
              tinymceRef.current?.setContent('');
              startTransition(() => setContent(''));
            }
          }}
          onShowHistory={() => setShowHistory(true)}
          onSaveVersion={() => {
            const newVersion = { id: Math.random().toString(36), timestamp: Date.now(), content, wordCount: stats.words };
            setVersions([newVersion, ...versions].slice(0, 20));
            alert("Snapshot saved!");
          }}
        />

        <main className="flex-1 overflow-y-auto p-4 md:p-8 lg:p-12 flex flex-col items-center custom-scrollbar bg-zinc-950 relative">
          <div className="w-full max-w-4xl h-full relative">
            <Suspense fallback={<div className="flex items-center justify-center h-full text-zinc-500 uppercase font-black text-xs tracking-widest animate-pulse">Initializing AI Engine...</div>}>
              <Editor
                tinymceScriptSrc="https://cdn.tiny.cloud/1/no-api-key/tinymce/6/tinymce.min.js"
                onInit={(evt, editor) => {
                  tinymceRef.current = editor;
                }}
                value={content}
                onEditorChange={(newContent) => {
                  startTransition(() => {
                    setContent(newContent);
                  });
                }}
                init={editorInit}
              />
            </Suspense>
          </div>
        </main>
      </div>

      <Sidebar 
        activeTab={activeTab} setActiveTab={setActiveTab} 
        stats={stats} readability={readability} health={health} intent={intent} keywords={keywords} 
        seoTab={seoTab} setSeoTab={setSeoTab} isExpanded={isExpanded} setIsExpanded={setIsExpanded} 
        onRewrite={onRewrite} onConvertCase={(type) => {
          const editor = tinymceRef.current;
          if (editor) {
            const selectedText = editor.selection.getContent({ format: 'text' });
            if (selectedText) {
              editor.selection.setContent(convertText(selectedText, type));
              startTransition(() => {
                setContent(editor.getContent());
              });
            }
          }
        }} 
        onCopy={onCopy} onClear={onClear} 
        isAIProcessing={isAIProcessing} targets={targets} setTargets={setTargets}
        metaTitle={metaTitle} setMetaTitle={setMetaTitle} metaDescription={metaDescription} setMetaDescription={setMetaDescription}
        faqs={faqs} setFaqs={setFaqs} onGenerateMetadata={async (type) => {
          setIsAIProcessing(true);
          try {
            const result = await generateMetadata(tinymceRef.current?.getContent({ format: 'text' }) || content, type);
            if (type === 'title') setMetaTitle(result); else setMetaDescription(result);
          } finally { setIsAIProcessing(false); }
        }} 
        onDetectAI={async () => {
          setIsAIProcessing(true);
          try {
            const result = await detectAIContent(tinymceRef.current?.getContent({ format: 'text' }) || "");
            alert(`AI Detection Score: ${result.score}%\n\nAnalysis: ${result.analysis}`);
          } finally { setIsAIProcessing(false); }
        }} 
        onGenerateFAQs={async () => {
          setIsAIProcessing(true);
          try {
            const result = await generateFAQs(tinymceRef.current?.getContent({ format: 'text' }) || content);
            setFaqs(result);
          } finally { setIsAIProcessing(false); }
        }} 
        onExportSchema={() => setShowSchema(true)}
      />
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useEffect, useMemo, useDeferredValue, Suspense, startTransition } from 'react';
import ReactDOM from 'react-dom/client';
import { Editor } from '@tinymce/tinymce-react';
import { 
  X, Sparkles, Clock, Trash2, Mail, MessageSquare, Send
} from 'lucide-react';

import { getStats } from './core/text-analysis';
import { getKeywords } from './core/keyword-density';
import { getReadabilityScore } from './core/readability';
import { analyzeSEOHealth } from './core/seo-health';
import { detectIntent } from './core/intent-detector';
import { convertText } from './core/case-converter';
import { rewriteContent, generateMetadata, detectAIContent, RewriteMode, generateFAQs } from './ai/ai-engine';
import { htmlToMarkdown } from './utils/text-cleaner';

import { Toolbar } from './components/editor/Toolbar';
import { Sidebar } from './components/layout/Sidebar';
import { Tab, SEOPhraseTab, KeywordTarget, FAQ } from './types/editor.types';

interface Version {
  id: string;
  timestamp: number;
  content: string;
  wordCount: number;
}

const App = () => {
  const [content, setContent] = useState(() => localStorage.getItem('seo-editor-content') || '<h1>SEO Focus Pro</h1><p>Start crafting optimized, AI-enhanced content here. Select text to rewrite or use the tabs on the right to analyze your performance in real-time.</p>');
  const [activeTab, setActiveTab] = useState<Tab>('insights'); 
  const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isAIProcessing, setIsAIProcessing] = useState(false);

  // Use state instead of ref for the instance so Toolbar re-renders when editor is ready
  const [editor, setEditor] = useState<any>(null);

  const [versions, setVersions] = useState<Version[]>(() => {
    const saved = localStorage.getItem('seo-versions');
    return saved ? JSON.parse(saved) : [];
  });
  const [showHistory, setShowHistory] = useState(false);

  const [showReportModal, setShowReportModal] = useState(false);
  const [reportEmail, setReportEmail] = useState('');
  const [reportIssue, setReportIssue] = useState('');

  const [aiOptions, setAiOptions] = useState<string[] | null>(null);

  const [metaTitle, setMetaTitle] = useState(() => localStorage.getItem('seo-meta-title') || '');
  const [metaDescription, setMetaDescription] = useState(() => localStorage.getItem('seo-meta') || '');
  const [targets, setTargets] = useState<KeywordTarget>(() => {
    const saved = localStorage.getItem('seo-targets');
    return saved ? JSON.parse(saved) : { primary: '', secondary: ['', '', ''] };
  });
  const [faqs, setFaqs] = useState<FAQ[]>(() => {
    const saved = localStorage.getItem('seo-faqs');
    return saved ? JSON.parse(saved) : [];
  });
  const [showSchema, setShowSchema] = useState(false);

  const [debouncedContent, setDebouncedContent] = useState(content);
  const deferredContent = useDeferredValue(debouncedContent);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedContent(content);
      localStorage.setItem('seo-editor-content', content);
      localStorage.setItem('seo-targets', JSON.stringify(targets));
      localStorage.setItem('seo-meta', metaDescription);
      localStorage.setItem('seo-meta-title', metaTitle);
      localStorage.setItem('seo-faqs', JSON.stringify(faqs));
      localStorage.setItem('seo-versions', JSON.stringify(versions));
    }, 500);
    return () => clearTimeout(handler);
  }, [content, targets, metaDescription, metaTitle, faqs, versions]);

  const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
  const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
  const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
  const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, targets, metaDescription), [deferredContent, keywords, targets, metaDescription]);
  const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);

  const onRewrite = async (mode: RewriteMode) => {
    if (!editor) return;
    const textToProcess = editor.selection.getContent({ format: 'text' }).trim();

    if (!textToProcess) {
      alert("Please select text in the editor to use AI rewrite options.");
      return;
    }

    startTransition(() => setIsAIProcessing(true));
    try {
      const results = await rewriteContent(textToProcess, mode);
      startTransition(() => setAiOptions(results));
    } catch (err) {
      console.error(err);
      alert("AI Processing failed.");
    } finally {
      startTransition(() => setIsAIProcessing(false));
    }
  };

  const applyAIOption = (text: string) => {
    if (editor) {
      editor.selection.setContent(text);
      startTransition(() => {
        setContent(editor.getContent());
        setAiOptions(null);
      });
    }
  };

  const handleReportSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!reportEmail || !reportIssue) return;
    console.log(`Admin Report for rathod.shivang@gmail.com:`, { from: reportEmail, issue: reportIssue });
    alert("Issue reported successfully.");
    startTransition(() => {
      setShowReportModal(false);
      setReportEmail('');
      setReportIssue('');
    });
  };

  const onCopy = async (type: 'plain' | 'markdown') => {
    const text = editor?.getContent({ format: 'text' }) || '';
    const toCopy = type === 'markdown' ? htmlToMarkdown(content) : text;
    try {
      await navigator.clipboard.writeText(toCopy);
    } catch (err) {
      console.error('Failed to copy text:', err);
    }
  };

  const onClear = () => {
    if (window.confirm('Clear document?')) {
      if (editor) {
        editor.setContent('');
        startTransition(() => setContent(''));
      }
    }
  };

  const editorInit = useMemo(() => ({
    height: '100%',
    menubar: false,
    plugins: [
      'advlist', 'autolink', 'lists', 'link', 'image', 'charmap', 'preview',
      'anchor', 'searchreplace', 'visualblocks', 'code', 'fullscreen',
      'insertdatetime', 'media', 'table', 'code', 'help', 'wordcount'
    ],
    toolbar: false,
    content_style: `
      @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;700&display=swap');
      body { 
        font-family: 'Inter', sans-serif; 
        font-size: 18px; 
        color: #d4d4d8; 
        background: transparent; 
        line-height: 1.8;
        padding: 20px;
      }
      h1, h2, h3, h4, h5, h6 { color: #ffffff; margin-bottom: 0.5em; font-weight: 800; letter-spacing: -0.02em; }
      h1 { font-size: 2.5rem; }
      h2 { font-size: 2rem; }
      p { margin-bottom: 1.5rem; }
      table { border-collapse: collapse; width: 100%; margin-bottom: 1.5rem; border: 1px solid #3f3f46; }
      td, th { border: 1px solid #3f3f46; padding: 12px; }
      blockquote { border-left: 4px solid #3b82f6; padding-left: 1.5rem; font-style: italic; color: #a1a1aa; margin-bottom: 1.5rem; }
      pre { background: #18181b; padding: 1rem; border-radius: 0.75rem; border: 1px solid #27272a; margin-bottom: 1.5rem; font-family: monospace; overflow-x: auto; }
      a { color: #3b82f6; text-decoration: underline; }
      img { max-width: 100%; border-radius: 1rem; height: auto; }
    `,
    skin: 'oxide-dark',
    content_css: 'dark',
    branding: false,
    promotion: false
  }), []);

  return (
    <div className="h-screen w-screen flex flex-col md:flex-row bg-zinc-950 text-zinc-100 transition-colors duration-300 overflow-hidden">
      {/* Report Modal */}
      {showReportModal && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center bg-black/80 backdrop-blur-md p-4">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[32px] w-full max-w-md shadow-2xl overflow-hidden">
            <div className="p-8 border-b border-zinc-800 flex items-center justify-between">
              <h3 className="font-black text-xl uppercase tracking-tighter flex items-center gap-2 text-zinc-100"><Mail className="text-blue-500" size={24} /> Report Issue</h3>
              <button onClick={() => startTransition(() => setShowReportModal(false))} className="p-2 hover:bg-zinc-800 rounded-full"><X size={24}/></button>
            </div>
            <form onSubmit={handleReportSubmit} className="p-8 space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-zinc-400">Email</label>
                <input 
                  type="email" required value={reportEmail} onChange={(e) => setReportEmail(e.target.value)}
                  className="w-full bg-zinc-800 border border-zinc-700 rounded-2xl py-3 px-4 text-sm focus:border-blue-500 outline-none"
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-zinc-400">Issue</label>
                <textarea 
                  required rows={4} value={reportIssue} onChange={(e) => setReportIssue(e.target.value)}
                  className="w-full bg-zinc-800 border border-zinc-700 rounded-2xl py-3 px-4 text-sm focus:border-blue-500 outline-none resize-none"
                />
              </div>
              <button type="submit" className="w-full py-4 bg-blue-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-blue-500 transition-all flex items-center justify-center gap-2 shadow-lg shadow-blue-500/20"><Send size={16} /> Submit Report</button>
            </form>
          </div>
        </div>
      )}

      {/* AI Suggestions Modal */}
      {aiOptions && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/60 backdrop-blur-md p-4">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[32px] w-full max-w-4xl shadow-2xl flex flex-col overflow-hidden">
            <div className="p-8 border-b border-zinc-800 flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-lg"><Sparkles size={24} /></div>
                <h3 className="font-black text-xl uppercase tracking-tighter">AI Suggestions</h3>
              </div>
              <button onClick={() => startTransition(() => setAiOptions(null))} className="p-3 hover:bg-zinc-800 rounded-2xl"><X size={24}/></button>
            </div>
            <div className="p-8 grid md:grid-cols-2 gap-6 overflow-y-auto max-h-[70vh] custom-scrollbar">
              {aiOptions.map((option, i) => (
                <div key={i} className="bg-zinc-950 border border-zinc-800 rounded-3xl p-6 flex flex-col h-full hover:border-blue-500 transition-all">
                  <div className="flex-1 text-sm leading-relaxed text-zinc-400 italic mb-6">"{option}"</div>
                  <button onClick={() => applyAIOption(option)} className="w-full py-4 bg-zinc-900 text-white border border-zinc-800 rounded-2xl font-black uppercase text-xs hover:bg-blue-600 transition-all">Apply Selection</button>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      <div className="flex-1 flex flex-col relative overflow-hidden h-full">
        <header className="h-16 border-b border-zinc-800 flex items-center justify-between px-6 glass-panel z-30 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-600 rounded-xl flex items-center justify-center font-black text-white shadow-lg">S</div>
            <h1 className="font-bold text-lg tracking-tight uppercase">SEO Focus <span className="text-zinc-400">Pro</span></h1>
          </div>
          <button onClick={() => startTransition(() => setShowReportModal(true))} className="px-4 py-2 bg-zinc-800 hover:bg-zinc-700 text-zinc-300 rounded-xl text-xs font-bold transition-all flex items-center gap-2"><Mail size={14} /><span>Report Issue</span></button>
        </header>

        <Toolbar 
          editorInstance={editor}
          onUpdate={() => startTransition(() => setContent(editor?.getContent() || ''))}
          onNewDocument={onClear}
          onShowHistory={() => startTransition(() => setShowHistory(true))}
          onSaveVersion={() => {
            const newVersion = { id: Math.random().toString(36), timestamp: Date.now(), content, wordCount: stats.words };
            startTransition(() => {
              setVersions([newVersion, ...versions].slice(0, 20));
              alert("Snapshot saved!");
            });
          }}
        />

        <main className="flex-1 overflow-y-auto p-4 md:p-8 lg:p-12 flex flex-col items-center custom-scrollbar bg-zinc-950 relative">
          <div className="w-full max-w-4xl h-full relative">
            <Suspense fallback={<div className="flex items-center justify-center h-full text-zinc-500 uppercase font-black text-xs tracking-widest animate-pulse">Initializing Engine...</div>}>
              <Editor
                onInit={(evt, ed) => startTransition(() => setEditor(ed))}
                initialValue={content}
                onEditorChange={(newContent) => {
                  startTransition(() => {
                    setContent(newContent);
                  });
                }}
                init={editorInit}
              />
            </Suspense>
          </div>
        </main>
      </div>

      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={(tab) => startTransition(() => setActiveTab(tab))} 
        stats={stats} readability={readability} health={health} intent={intent} keywords={keywords} 
        seoTab={seoTab} 
        setSeoTab={(num) => startTransition(() => setSeoTab(num))} 
        isExpanded={isExpanded} 
        setIsExpanded={(val) => startTransition(() => setIsExpanded(val))} 
        onRewrite={onRewrite} 
        onConvertCase={(type) => {
          if (editor) {
            const selectedText = editor.selection.getContent({ format: 'text' });
            if (selectedText) {
              editor.selection.setContent(convertText(selectedText, type));
              startTransition(() => setContent(editor.getContent()));
            }
          }
        }} 
        onCopy={onCopy} onClear={onClear} 
        isAIProcessing={isAIProcessing} 
        targets={targets} 
        setTargets={(t) => startTransition(() => setTargets(t))}
        metaTitle={metaTitle} 
        setMetaTitle={(s) => startTransition(() => setMetaTitle(s))} 
        metaDescription={metaDescription} 
        setMetaDescription={(s) => startTransition(() => setMetaDescription(s))}
        faqs={faqs} 
        setFaqs={(f) => startTransition(() => setFaqs(f))} 
        onGenerateMetadata={async (type) => {
          startTransition(() => setIsAIProcessing(true));
          try {
            const result = await generateMetadata(editor?.getContent({ format: 'text' }) || content, type);
            startTransition(() => {
              if (type === 'title') setMetaTitle(result); else setMetaDescription(result);
            });
          } finally { startTransition(() => setIsAIProcessing(false)); }
        }} 
        onDetectAI={async () => {
          startTransition(() => setIsAIProcessing(true));
          try {
            const result = await detectAIContent(editor?.getContent({ format: 'text' }) || "");
            alert(`AI Detection Score: ${result.score}%\n\nAnalysis: ${result.analysis}`);
          } finally { startTransition(() => setIsAIProcessing(false)); }
        }} 
        onGenerateFAQs={async () => {
          startTransition(() => setIsAIProcessing(true));
          try {
            const result = await generateFAQs(editor?.getContent({ format: 'text' }) || content);
            startTransition(() => setFaqs(result));
          } finally { startTransition(() => setIsAIProcessing(false)); }
        }} 
        onExportSchema={() => startTransition(() => setShowSchema(true))}
      />
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useEffect, useMemo, useDeferredValue, startTransition } from 'react';
import ReactDOM from 'react-dom/client';
import { Editor } from '@tinymce/tinymce-react';
import { Mail, Send, X } from 'lucide-react';

import { getStats } from './core/text-analysis';
import { getKeywords } from './core/keyword-density';
import { getReadabilityScore } from './core/readability';
import { analyzeSEOHealth } from './core/seo-health';
import { detectIntent } from './core/intent-detector';
import { convertText } from './core/case-converter';
import { rewriteContent, generateMetadata, detectAIContent, RewriteMode, generateFAQs } from './ai/ai-engine';
import { htmlToMarkdown } from './utils/text-cleaner';

import { Toolbar } from './components/editor/Toolbar';
import { Sidebar } from './components/layout/Sidebar';
import { Tab, SEOPhraseTab, KeywordTarget, FAQ } from './types/editor.types';

const App = () => {
  // 1. Content State - The single source of truth for the editor
  const [content, setContent] = useState(() => 
    localStorage.getItem('seo-editor-content') || '<h1>SEO Focus Pro</h1><p>Start crafting optimized, AI-enhanced content here.</p>'
  );

  // 2. UI State
  const [activeTab, setActiveTab] = useState<Tab>('insights'); 
  const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [editorInstance, setEditorInstance] = useState<any>(null);
  const [showReportModal, setShowReportModal] = useState(false);
  const [reportEmail, setReportEmail] = useState('');
  const [reportIssue, setReportIssue] = useState('');
