/**
 * Stable Native Editor Component
 * Replaces TinyMCE to avoid React 19 Suspense errors (#525)
 * Uses browser-native execCommand to support Toolbar actions.
 */
const NativeEditor = ({ value, onEditorChange, onInit }: any) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const isInternalChange = useRef(false);

  // Sync state from parent (e.g. AI rewrite or New Document)
  useEffect(() => {
    if (editorRef.current && value !== editorRef.current.innerHTML) {
      if (!isInternalChange.current) {
        editorRef.current.innerHTML = value;
      }
    }
    isInternalChange.current = false;
  }, [value]);

  // Expose TinyMCE-like API to support existing Toolbar logic
  useEffect(() => {
    if (editorRef.current && onInit) {
      const instance = {
        focus: () => editorRef.current?.focus(),
        getContent: (args?: any) => {
          if (args?.format === 'text') return editorRef.current?.innerText || '';
          return editorRef.current?.innerHTML || '';
        },
        setContent: (html: string) => {
          if (editorRef.current) {
            editorRef.current.innerHTML = html;
            onEditorChange(html);
          }
        },
        execCommand: (cmd: string, ui: boolean, val: any) => {
          document.execCommand(cmd, ui, val);
          if (editorRef.current) onEditorChange(editorRef.current.innerHTML);
        },
        insertContent: (html: string) => {
          editorRef.current?.focus();
          document.execCommand('insertHTML', false, html);
          if (editorRef.current) onEditorChange(editorRef.current.innerHTML);
        },
        selection: {
          getContent: (args?: any) => {
            const sel = window.getSelection();
            if (!sel || sel.rangeCount === 0) return '';
            if (args?.format === 'text') return sel.toString();
            const container = document.createElement("div");
            for (let i = 0, len = sel.rangeCount; i < len; ++i) {
              container.appendChild(sel.getRangeAt(i).cloneContents());
            }
            return container.innerHTML;
          },
          setContent: (html: string) => {
            document.execCommand('insertHTML', false, html);
            if (editorRef.current) onEditorChange(editorRef.current.innerHTML);
          }
        },
        plugins: {
          table: {
            insertTable: (cols: number, rows: number) => {
              let tbl = '<table style="width:100%; border: 1px solid #3f3f46; border-collapse: collapse; margin-bottom: 1.5rem;">';
              for (let r = 0; r < rows; r++) {
                tbl += '<tr>';
                for (let c = 0; c < cols; c++) {
                  tbl += '<td style="border: 1px solid #3f3f46; padding: 12px;">&nbsp;</td>';
                }
                tbl += '</tr>';
              }
              tbl += '</table><p>&nbsp;</p>';
              document.execCommand('insertHTML', false, tbl);
              if (editorRef.current) onEditorChange(editorRef.current.innerHTML);
            }
          }
        }
      };
      onInit(null, instance);
    }
  }, []);

  return (
    <div 
      ref={editorRef}
      contentEditable
      onInput={(e) => {
        isInternalChange.current = true;
        onEditorChange(e.currentTarget.innerHTML);
      }}
      className="editor-content w-full h-full outline-none p-8 overflow-y-auto custom-scrollbar"
      style={{ 
        minHeight: '100%', 
        color: '#d4d4d8',
        fontSize: '16px',
        lineHeight: '1.6'
      }}
    />
  );
};

