interface TipTapEditorProps {
  initialContent: string;
  onUpdate: (html: string) => void;
  onInit: (editor: any) => void;
  onAIAssist: (mode: any) => void;
}

export const TipTapEditor = ({ initialContent, onUpdate, onInit, onAIAssist }: TipTapEditorProps) => {
  const [showPasteModal, setShowPasteModal] = useState(false);
  const [pendingPaste, setPendingPaste] = useState<{ text: string, html: string } | null>(null);

  const editor = useEditor({
    extensions: [
      StarterKit.configure({
        heading: { levels: [1, 2, 3, 4, 5, 6] },
        codeBlock: false, // will use custom if needed, or stick to starter-kit basic
      }),
      Underline,
      Link.configure({ openOnClick: false }),
      Table.configure({ resizable: true }),
      TableRow,
      TableHeader,
      TableCell,
      Image.configure({ allowBase64: true }),
      Youtube,
      Highlight.configure({ multicolor: true }),
      Placeholder.configure({ placeholder: 'Start writing your SEO masterpiece...' }),
      TextStyle,
      Color,
      Subscript,
      Superscript,
    ],
    content: initialContent,
    onUpdate: ({ editor }) => {
      onUpdate(editor.getHTML());
    },
    editorProps: {
      handlePaste: (view, event) => {
        const text = event.clipboardData?.getData('text/plain') || '';
        const html = event.clipboardData?.getData('text/html') || '';

        // If it's complex HTML, show smart paste dialog
        if (html && (html.includes('<') || text.length > 200)) {
          setPendingPaste({ text, html });
          setShowPasteModal(true);
          return true; // We handle it manually
        }
        return false; // Let default handle simple text
      },
      attributes: {
        class: 'focus:outline-none custom-scrollbar'
      },
      // Sentence & Paragraph Heatmap Logic via Decorations
      decorations: (state) => {
        const { doc } = state;
        const decorations: any[] = [];

        doc.descendants((node, pos) => {
          if (node.isTextblock && node.type.name === 'paragraph') {
            const text = node.textContent;
            const wordsInPara = text.split(/\s+/).filter(Boolean).length;

            // Paragraph warning
            if (wordsInPara > 150) {
              // Note: Decorations for block level need careful mapping. 
              // TipTap/PM doesn't natively allow CSS class on node via simple decoration 
              // without node views or similar. 
              // We'll skip complex decorations for performance and stick to heatmap for sentences.
            }

            // Simple Heatmap (Highlighting within text)
            // Splitting sentences roughly
            const sentenceMatches = text.split(/([.!?]+)/);
            let offset = 0;
            for (let i = 0; i < sentenceMatches.length; i += 2) {
              const sentence = sentenceMatches[i];
              const punc = sentenceMatches[i+1] || '';
              const fullSentence = sentence + punc;
              const words = sentence.trim().split(/\s+/).filter(Boolean).length;

              // We won't decorate EVERYTHING to avoid lag, only long ones
              if (words > 25) {
                // very hard
              } else if (words > 18) {
                // hard
              }
              offset += fullSentence.length;
            }
          }
        });
        return null; // For now return null to ensure stability, heatmap will be refined
      }
    }
  });

  useEffect(() => {
    if (editor) onInit(editor);
  }, [editor, onInit]);

  const applyPaste = (mode: 'clean' | 'plain' | 'original') => {
    if (!pendingPaste || !editor) return;

    editor.chain().focus();
    if (mode === 'plain') {
      editor.insertContent(pendingPaste.text);
    } else if (mode === 'clean') {
      // Basic cleaning heuristic
      const cleaned = pendingPaste.html
        .replace(/style="[^"]*"/gi, '')
        .replace(/class="[^"]*"/gi, '')
        .replace(/<span[^>]*>(.*?)<\/span>/gi, '$1');
      editor.insertContent(cleaned);
    } else {
      editor.insertContent(pendingPaste.html);
    }

    setPendingPaste(null);
    setShowPasteModal(false);
  };

  if (!editor) return null;

  return (
    <>
      <div className="relative h-full w-full group">
        <EditorContent editor={editor} className="h-full w-full" />

        {/* Floating AI Assist Trigger on hover/selection */}
        <BubbleMenu editor={editor} tippyOptions={{ duration: 100 }}>
          <div className="flex bg-zinc-900 border border-zinc-700 rounded-xl overflow-hidden shadow-2xl p-1 animate-in zoom-in-95">
            <button 
              onClick={() => onAIAssist('clarity')} 
              className="p-2 hover:bg-zinc-800 text-blue-500 rounded-lg"
              title="Improve with AI"
            ><Wand2 size={16} /></button>
            <div className="w-[1px] h-4 bg-zinc-700 mx-1 self-center" />
            <button 
              onClick={() => editor.chain().focus().toggleBold().run()}
              className={`p-2 rounded-lg ${editor.isActive('bold') ? 'bg-blue-600/10 text-blue-500' : 'text-zinc-400 hover:bg-zinc-800'}`}
            >B</button>
            <button 
              onClick={() => editor.chain().focus().toggleItalic().run()}
              className={`p-2 rounded-lg ${editor.isActive('italic') ? 'bg-blue-600/10 text-blue-500' : 'text-zinc-400 hover:bg-zinc-800'}`}
            >I</button>
          </div>
        </BubbleMenu>
      </div>

      {/* Smart Paste Modal */}
      {showPasteModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/80 backdrop-blur-md p-4">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[32px] w-full max-w-sm shadow-2xl overflow-hidden p-8 space-y-6">
            <div className="text-center">
              <div className="w-16 h-16 bg-blue-600/10 text-blue-500 rounded-3xl flex items-center justify-center mx-auto mb-4">
                <Clipboard size={32} />
              </div>
              <h3 className="font-black text-xl uppercase tracking-tighter">Smart Paste</h3>
              <p className="text-xs text-zinc-500 mt-2">How would you like to handle this content?</p>
            </div>
            <div className="space-y-3">
              <button onClick={() => applyPaste('clean')} className="w-full py-4 bg-zinc-800 text-zinc-100 rounded-2xl font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-3 border border-zinc-700 hover:bg-zinc-700 transition-all">Clean HTML</button>
              <button onClick={() => applyPaste('plain')} className="w-full py-4 bg-zinc-800 text-zinc-100 rounded-2xl font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-3 border border-zinc-700 hover:bg-zinc-700 transition-all">Plain Text</button>
              <button onClick={() => applyPaste('original')} className="w-full py-4 bg-blue-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-3 shadow-lg hover:bg-blue-500 transition-all">Keep Formatting</button>
            </div>
            <button onClick={() => setShowPasteModal(false)} className="w-full py-2 text-zinc-500 text-[9px] uppercase font-bold tracking-widest">Cancel</button>
          </div>
        </div>
      )}
    </>
  );
};

