        {/* GROUP 6: View */}
        <ToolbarGroup label="VIEW">
          <ToolbarButton 
            icon={<Edit3 size={16} />} 
            onClick={onToggleHtml} 
            active={showHtml}
            title="HTML Source" 
          />
          <ToolbarButton 
            icon={<Terminal size={16} />} 
            onClick={() => alert("Shortcut cheatsheet coming soon.")} 
