import React, { useEffect, useState, useRef, useCallback } from 'react';
import { Clipboard, Wand2, Sparkles, X } from 'lucide-react';

interface ProfessionalEditorProps {
  initialContent: string;
  onUpdate: (html: string) => void;
  onInit: (instance: any) => void;
  onAIAssist: (mode: any) => void;
}

export const ProfessionalEditor = ({ initialContent, onUpdate, onInit, onAIAssist }: ProfessionalEditorProps) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const [showPasteModal, setShowPasteModal] = useState(false);
  const [pendingPaste, setPendingPaste] = useState<{ text: string, html: string } | null>(null);
  const [showFloatingAssist, setShowFloatingAssist] = useState(false);
  const isInternalUpdate = useRef(false);
  const savedRange = useRef<Range | null>(null);

  const analyzeParagraphs = useCallback(() => {
    if (!editorRef.current) return;
    const paras = editorRef.current.querySelectorAll('p');
    paras.forEach(p => {
      const words = p.innerText.trim().split(/\s+/).filter(Boolean).length;
      if (words > 150) {
        p.classList.add('para-warning');
      } else {
        p.classList.remove('para-warning');
      }
    });
  }, []);

  // Initialize and expose API
  useEffect(() => {
    if (editorRef.current) {
      editorRef.current.innerHTML = initialContent;

      const instance = {
        getContent: () => editorRef.current?.innerHTML || '',
        setContent: (html: string) => {
          if (editorRef.current) {
            editorRef.current.innerHTML = html;
            onUpdate(html);
            analyzeParagraphs();
          }
        },
        execCommand: (cmd: string, ui: boolean, val: any) => {
          editorRef.current?.focus();
          document.execCommand(cmd, ui, val);
          if (editorRef.current) onUpdate(editorRef.current.innerHTML);
          analyzeParagraphs();
        },
        insertContent: (html: string) => {
          editorRef.current?.focus();
          const sel = window.getSelection();
          if (sel && sel.rangeCount > 0) {
            const range = sel.getRangeAt(0);
            range.deleteContents();
            const el = document.createElement("div");
            el.innerHTML = html;
            const frag = document.createDocumentFragment();
            let node;
            while (node = el.firstChild) frag.appendChild(node);
            range.insertNode(frag);
          } else {
            document.execCommand('insertHTML', false, html);
          }
          if (editorRef.current) onUpdate(editorRef.current.innerHTML);
          analyzeParagraphs();
        },
        getSelection: () => {
          const sel = window.getSelection();
          return sel?.toString() || '';
        },
        scrollToText: (text: string) => {
          if (!editorRef.current) return;
          const walker = document.createTreeWalker(editorRef.current, NodeFilter.SHOW_TEXT);
          let node;
          while (node = walker.nextNode()) {
            if (node.textContent?.includes(text)) {
              (node.parentElement as HTMLElement)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
              break;
            }
          }
        }
      };
      onInit(instance);
      analyzeParagraphs();
    }
  }, [onInit, onUpdate, analyzeParagraphs]);

  // Sync external changes
  useEffect(() => {
    if (editorRef.current && initialContent !== editorRef.current.innerHTML) {
      if (!isInternalUpdate.current) {
        editorRef.current.innerHTML = initialContent;
        analyzeParagraphs();
      }
    }
    isInternalUpdate.current = false;
  }, [initialContent, analyzeParagraphs]);

  const handleInput = (e: React.FormEvent<HTMLDivElement>) => {
    isInternalUpdate.current = true;
    const html = e.currentTarget.innerHTML;
    onUpdate(html);
    analyzeParagraphs();
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    const text = e.clipboardData.getData('text/plain');
    const html = e.clipboardData.getData('text/html');

    // For simple text, let it pass through
    if (!html || (html.trim() === "" && text.length < 300)) {
      return;
    }

    e.preventDefault();

    // Save selection range before modal opens
    const sel = window.getSelection();
    if (sel && sel.rangeCount > 0) {
      savedRange.current = sel.getRangeAt(0).cloneRange();
    }

    setPendingPaste({ text, html });
    setShowPasteModal(true);
  };

  const handleMouseUp = () => {
    const selection = window.getSelection();
    setShowFloatingAssist(!!selection && selection.toString().trim().length > 0);
  };

  const applyPaste = (mode: 'clean' | 'plain' | 'original') => {
    if (!pendingPaste || !editorRef.current) return;

    editorRef.current.focus();

    // Restore range
    const sel = window.getSelection();
    if (sel && savedRange.current) {
      sel.removeAllRanges();
      sel.addRange(savedRange.current);
    }

    let toInsert = '';
    if (mode === 'plain') {
      toInsert = pendingPaste.text.replace(/\n/g, '<br>');
    } else if (mode === 'clean') {
      toInsert = pendingPaste.html
        .replace(/style="[^"]*"/gi, '')
        .replace(/class="[^"]*"/gi, '')
        .replace(/<span[^>]*>(.*?)<\/span>/gi, '$1')
        .replace(/<o:p>.*?<\/o:p>/gi, '') // Clean Word residues
        .trim();
    } else {
      toInsert = pendingPaste.html;
    }

    // Use modern Range manipulation for insertion instead of execCommand
    if (sel && sel.rangeCount > 0) {
      const range = sel.getRangeAt(0);
      range.deleteContents();

      const el = document.createElement("div");
      el.innerHTML = toInsert;
      const frag = document.createDocumentFragment();
      let node;
      while (node = el.firstChild) frag.appendChild(node);

      const lastNode = frag.lastChild;
      range.insertNode(frag);

      if (lastNode) {
        range.setStartAfter(lastNode);
        range.collapse(true);
        sel.removeAllRanges();
        sel.addRange(range);
      }
    }

    onUpdate(editorRef.current.innerHTML);
    setPendingPaste(null);
    setShowPasteModal(false);
    savedRange.current = null;
    analyzeParagraphs();
  };

  return (
    <div className="relative h-full w-full group overflow-hidden flex flex-col">
      <div 
        ref={editorRef}
        contentEditable
        onInput={handleInput}
        onPaste={handlePaste}
        onMouseUp={handleMouseUp}
        onKeyUp={handleMouseUp}
        className="editor-content flex-1 w-full h-full custom-scrollbar overflow-y-auto outline-none"
        spellCheck="true"
      />

      {/* Floating Assist Trigger */}
      {showFloatingAssist && (
        <div className="absolute bottom-6 right-6 animate-in fade-in slide-in-from-bottom-2 duration-300 z-10">
          <button 
            onClick={() => {
              onAIAssist('clarity');
              setShowFloatingAssist(false);
            }}
            className="bg-blue-600 hover:bg-blue-500 text-white px-4 py-2.5 rounded-2xl shadow-2xl flex items-center gap-2 text-[11px] font-black uppercase tracking-widest border border-blue-400/20"
          >
            <Sparkles size={14} className="animate-pulse" /> AI Assist Selection
          </button>
        </div>
      )}

      {/* Smart Paste Modal */}
      {showPasteModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/80 backdrop-blur-md p-4">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[32px] w-full max-w-sm shadow-2xl overflow-hidden p-8 space-y-6">
            <div className="text-center">
              <div className="w-16 h-16 bg-blue-600/10 text-blue-500 rounded-3xl flex items-center justify-center mx-auto mb-4">
                <Clipboard size={32} />
              </div>
              <h3 className="font-black text-xl uppercase tracking-tighter text-white">Smart Paste</h3>
              <p className="text-xs text-zinc-500 mt-2">Complex content detected. How should we process it?</p>
            </div>
            <div className="space-y-3">
              <button 
                onClick={() => applyPaste('clean')} 
                className="w-full py-4 bg-zinc-800 text-zinc-100 rounded-2xl font-black uppercase text-[10px] tracking-widest border border-zinc-700 hover:bg-zinc-700 hover:border-blue-500/50 transition-all"
              >
                Clean Formatting
              </button>
              <button 
                onClick={() => applyPaste('plain')} 
                className="w-full py-4 bg-zinc-800 text-zinc-100 rounded-2xl font-black uppercase text-[10px] tracking-widest border border-zinc-700 hover:bg-zinc-700 hover:border-blue-500/50 transition-all"
              >
                Plain Text
              </button>
              <button 
                onClick={() => applyPaste('original')} 
                className="w-full py-4 bg-blue-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-lg hover:bg-blue-500 transition-all border border-blue-400/30"
              >
                Keep Original
              </button>
            </div>
            <button 
              onClick={() => {
                setShowPasteModal(false);
                setPendingPaste(null);
                savedRange.current = null;
              }} 
              className="w-full py-2 text-zinc-500 text-[9px] uppercase font-bold tracking-widest hover:text-white transition-colors"
            >
              Cancel Paste
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo, useDeferredValue, startTransition, useRef } from 'react';
import ReactDOM from 'react-dom/client';
import { Mail, Send, X, AlertTriangle, CheckCircle2, Layout, Maximize2, Columns } from 'lucide-react';

import { getStats } from './core/text-analysis';
import { getKeywords } from './core/keyword-density';
import { getReadabilityScore } from './core/readability';
import { analyzeSEOHealth } from './core/seo-health';
import { detectIntent } from './core/intent-detector';
import { convertText } from './core/case-converter';
import { rewriteContent, generateMetadata, detectAIContent, RewriteMode, generateFAQs } from './ai/ai-engine';
import { htmlToMarkdown } from './utils/text-cleaner';

import { Toolbar } from './components/editor/Toolbar';
import { Sidebar } from './components/layout/Sidebar';
import { Editor } from './components/editor/Editor';
import { Tab, SEOPhraseTab, KeywordTarget, FAQ } from './types/editor.types';

const App = () => {
  // 1. Content State
  const [content, setContent] = useState(() => 
    localStorage.getItem('seo-editor-content') || '<h1>SEO Focus Pro</h1><p>Start crafting optimized, AI-enhanced content here.</p>'
  );

  // 2. View States
  const [activeTab, setActiveTab] = useState<Tab>('insights'); 
  const [viewMode, setViewMode] = useState<'normal' | 'focus' | 'distraction' | 'split'>('normal');
  const [showHtml, setShowHtml] = useState(false);
  const [wordTarget, setWordTarget] = useState(1000);
  const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [editorInstance, setEditorInstance] = useState<any>(null);
  const [showReportModal, setShowReportModal] = useState(false);
  const [reportEmail, setReportEmail] = useState('');
  const [reportIssue, setReportIssue] = useState('');
  const [metaTitle, setMetaTitle] = useState(() => localStorage.getItem('seo-meta-title') || '');
  const [metaDescription, setMetaDescription] = useState(() => localStorage.getItem('seo-meta') || '');
  const [targets, setTargets] = useState<KeywordTarget>(() => {
    const saved = localStorage.getItem('seo-targets');
    return saved ? JSON.parse(saved) : { primary: '', secondary: ['', '', ''] };
  });
  const [faqs, setFaqs] = useState<FAQ[]>(() => {
    const saved = localStorage.getItem('seo-faqs');
    return saved ? JSON.parse(saved) : [];
  });

  const deferredContent = useDeferredValue(content);

  // Persistence
  useEffect(() => {
    localStorage.setItem('seo-editor-content', content);
    localStorage.setItem('seo-targets', JSON.stringify(targets));
    localStorage.setItem('seo-meta', metaDescription);
    localStorage.setItem('seo-meta-title', metaTitle);
    localStorage.setItem('seo-faqs', JSON.stringify(faqs));
  }, [content, targets, metaDescription, metaTitle, faqs]);

  // Analysis
  const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
  const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
  const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
  const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, targets, metaDescription), [deferredContent, keywords, targets, metaDescription]);
  const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);

  const handleEditorChange = (newContent: string) => {
    startTransition(() => {
      setContent(newContent);
    });
  };

  const onRewrite = async (mode: RewriteMode) => {
    if (!editorInstance) return;
    const selectedText = editorInstance.getSelection();

    if (!selectedText) {
      alert("Please select text to rewrite.");
      return;
    }

    setIsAIProcessing(true);
    try {
      const results = await rewriteContent(selectedText, mode);
      if (results && results.length > 0) {
        editorInstance.insertContent(results[0]);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleReportSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    console.log(`Issue: ${reportIssue} from ${reportEmail}`);
    alert("Reported.");
    setShowReportModal(false);
  };

  const toggleView = (mode: typeof viewMode) => {
    setViewMode(viewMode === mode ? 'normal' : mode);
  };

  return (
    <div className={`h-screen w-screen flex flex-col md:flex-row bg-zinc-950 text-zinc-100 overflow-hidden ${viewMode === 'focus' ? 'focus-mode' : ''} ${viewMode === 'distraction' ? 'distraction-free' : ''}`}>
      {showReportModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
          <div className="bg-zinc-900 border border-zinc-800 rounded-3xl w-full max-w-md p-8">
            <h3 className="text-xl font-bold mb-6 flex items-center gap-2 uppercase tracking-tighter text-blue-500">
              <Mail /> Report Issue
            </h3>
            <form onSubmit={handleReportSubmit} className="space-y-4">
              <input 
                type="email" required placeholder="Your email" value={reportEmail} 
                onChange={e => setReportEmail(e.target.value)}
                className="w-full bg-zinc-800 border border-zinc-700 rounded-xl p-3 outline-none" 
              />
              <textarea 
                required placeholder="What's wrong?" value={reportIssue} 
                onChange={e => setReportIssue(e.target.value)}
                className="w-full bg-zinc-800 border border-zinc-700 rounded-xl p-3 h-32 outline-none resize-none" 
              />
              <button type="submit" className="w-full bg-blue-600 py-3 rounded-xl font-bold flex items-center justify-center gap-2">
                <Send size={18} /> Send Report
              </button>
              <button type="button" onClick={() => setShowReportModal(false)} className="w-full py-2 text-zinc-500 text-sm">Cancel</button>
            </form>
          </div>
        </div>
      )}

      <div className="flex-1 flex flex-col relative overflow-hidden">
        <header className="h-16 border-b border-zinc-800 flex items-center justify-between px-6 bg-zinc-950/50 backdrop-blur-xl z-30">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center font-black">S</div>
            <h1 className="font-bold tracking-tight uppercase">SEO Focus</h1>
          </div>
          <div className="flex items-center gap-2">
            <button 
              onClick={() => toggleView('focus')} 
              className={`p-2 rounded-lg transition-colors ${viewMode === 'focus' ? 'bg-blue-600 text-white' : 'hover:bg-zinc-800 text-zinc-400'}`}
              title="Focus Mode"
            ><Layout size={18} /></button>
            <button 
              onClick={() => toggleView('distraction')} 
              className={`p-2 rounded-lg transition-colors ${viewMode === 'distraction' ? 'bg-blue-600 text-white' : 'hover:bg-zinc-800 text-zinc-400'}`}
              title="Distraction-Free"
            ><Maximize2 size={18} /></button>
             <button 
              onClick={() => toggleView('split')} 
              className={`p-2 rounded-lg transition-colors ${viewMode === 'split' ? 'bg-blue-600 text-white' : 'hover:bg-zinc-800 text-zinc-400'}`}
              title="Split View"
            ><Columns size={18} /></button>
            <div className="w-[1px] h-4 bg-zinc-800 mx-2" />
            <button onClick={() => setShowReportModal(true)} className="text-xs font-bold text-zinc-400 hover:text-white uppercase tracking-widest px-4 py-2 bg-zinc-900 border border-zinc-800 rounded-lg transition-all">Report</button>
          </div>
        </header>

        <div className="toolbar-wrapper sticky top-0 z-20">
          <Toolbar 
            editorInstance={editorInstance} 
            onUpdate={() => handleEditorChange(editorInstance?.getContent() || '')}
            onNewDocument={() => { if(confirm('Clear all?')) editorInstance?.setContent(''); }}
            onShowHistory={() => {}} 
            onSaveVersion={() => alert('Snapshot saved.')}
            viewMode={viewMode}
            onToggleHtml={() => setShowHtml(!showHtml)}
            showHtml={showHtml}
          />
        </div>

        <main className={`flex-1 p-4 md:p-8 bg-zinc-950 flex gap-4 overflow-hidden relative transition-all duration-500`}>
          <div className={`editor-container h-full border border-zinc-800 rounded-2xl overflow-hidden bg-zinc-900/20 shadow-2xl transition-all duration-500 ${viewMode === 'split' ? 'w-1/2' : 'w-full max-w-4xl mx-auto'}`}>
            {showHtml ? (
              <textarea 
                className="w-full h-full bg-zinc-950 text-emerald-500 font-mono p-8 text-sm outline-none resize-none"
                value={content}
                onChange={(e) => handleEditorChange(e.target.value)}
              />
            ) : (
              <Editor 
                initialContent={content}
                onUpdate={handleEditorChange}
                onInit={setEditorInstance}
                onAIAssist={onRewrite}
              />
            )}
          </div>

          {viewMode === 'split' && (
            <div className="w-1/2 h-full border border-zinc-800 rounded-2xl overflow-y-auto bg-zinc-900/40 p-10 custom-scrollbar prose prose-invert max-w-none">
              <div className="opacity-50 text-[10px] font-black uppercase tracking-widest mb-4 border-b border-zinc-800 pb-2">Markdown Preview</div>
              <pre className="whitespace-pre-wrap text-sm text-zinc-400 leading-relaxed font-mono">
                {htmlToMarkdown(content)}
              </pre>
            </div>
          )}

          {/* Word Goal Progress Overlay (Floater) */}
          {viewMode !== 'distraction' && (
            <div className="absolute bottom-12 left-1/2 -translate-x-1/2 bg-zinc-900/80 backdrop-blur-xl border border-zinc-700 rounded-full px-6 py-2 shadow-2xl flex items-center gap-4 z-40">
              <div className="text-[10px] font-black text-zinc-400 uppercase tracking-tighter">{stats.words} / {wordTarget} words</div>
              <div className="w-48 h-1.5 bg-zinc-800 rounded-full overflow-hidden">
                <div 
                  className={`h-full transition-all duration-1000 ${stats.words >= wordTarget ? 'bg-emerald-500' : 'bg-blue-600'}`} 
                  style={{ width: `${Math.min(100, (stats.words / wordTarget) * 100)}%` }} 
                />
              </div>
              <input 
                type="number" 
                value={wordTarget} 
                onChange={e => setWordTarget(parseInt(e.target.value) || 0)} 
                className="bg-transparent w-16 text-[10px] font-black text-blue-500 outline-none border-b border-blue-500/20"
                title="Set Word Goal"
              />
            </div>
          )}
        </main>
      </div>

      <Sidebar 
        activeTab={activeTab} setActiveTab={setActiveTab} 
        stats={stats} readability={readability} health={health} intent={intent} keywords={keywords} 
        seoTab={seoTab} setSeoTab={setSeoTab} isExpanded={isExpanded} setIsExpanded={setIsExpanded} 
        onRewrite={onRewrite} 
        onConvertCase={(type) => {
          if (editorInstance) {
            const selected = editorInstance.getSelection();
            if (selected) {
              editorInstance.insertContent(convertText(selected, type));
            }
          }
        }} 
        onCopy={(type) => {
          const toCopy = type === 'markdown' ? htmlToMarkdown(content) : content.replace(/<[^>]*>/g, '');
          navigator.clipboard.writeText(toCopy);
          alert("Copied.");
        }} 
        onClear={() => { if(confirm('Clear all?')) editorInstance?.setContent(''); }} 
        isAIProcessing={isAIProcessing} targets={targets} setTargets={setTargets}
        metaTitle={metaTitle} setMetaTitle={setMetaTitle} 
        metaDescription={metaDescription} setMetaDescription={setMetaDescription}
        faqs={faqs} setFaqs={setFaqs}
        onGenerateMetadata={async (type) => {
          setIsAIProcessing(true);
          try {
            const res = await generateMetadata(content, type);
            if (type === 'title') setMetaTitle(res); else setMetaDescription(res);
          } finally { setIsAIProcessing(false); }
        }}
        onDetectAI={async () => {
          setIsAIProcessing(true);
          try {
            const res = await detectAIContent(content);
            alert(`AI Score: ${res.score}% - ${res.analysis}`);
          } finally { setIsAIProcessing(false); }
        }}
        onGenerateFAQs={async () => {
          setIsAIProcessing(true);
          try {
            const res = await generateFAQs(content);
            setFaqs(res);
          } finally { setIsAIProcessing(false); }
        }}
        onExportSchema={() => alert("JSON-LD Exported to console.")}
        onNavigateOutline={(text) => {
           if (editorInstance) {
             editorInstance.scrollToText(text);
           }
        }}
      />
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useEffect, useState, useRef, useCallback } from 'react';
import { Clipboard, Wand2, Sparkles, X } from 'lucide-react';

interface EditorProps {
  initialContent: string;
  onUpdate: (html: string) => void;
  onInit: (instance: any) => void;
  onAIAssist: (mode: any) => void;
}

export const Editor = ({ initialContent, onUpdate, onInit, onAIAssist }: EditorProps) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const [showPasteModal, setShowPasteModal] = useState(false);
  const [pendingPaste, setPendingPaste] = useState<{ text: string, html: string } | null>(null);
  const [showFloatingAssist, setShowFloatingAssist] = useState(false);
  const isInternalUpdate = useRef(false);
  const savedRange = useRef<Range | null>(null);

  const analyzeParagraphs = useCallback(() => {
    if (!editorRef.current) return;
    const paras = editorRef.current.querySelectorAll('p');
    paras.forEach(p => {
      const words = p.innerText.trim().split(/\s+/).filter(Boolean).length;
      if (words > 150) {
        p.classList.add('para-warning');
      } else {
        p.classList.remove('para-warning');
      }
    });
  }, []);

  // Sync content updates to parent
  const emitUpdate = useCallback(() => {
    if (editorRef.current) {
      onUpdate(editorRef.current.innerHTML);
      analyzeParagraphs();
    }
  }, [onUpdate, analyzeParagraphs]);

  // Expose Editor API to Parent
  useEffect(() => {
    if (editorRef.current) {
      editorRef.current.innerHTML = initialContent;

      const instance = {
        getContent: () => editorRef.current?.innerHTML || '',
        setContent: (html: string) => {
          if (editorRef.current) {
            editorRef.current.innerHTML = html;
            emitUpdate();
          }
        },
        execCommand: (cmd: string, ui: boolean, val: any) => {
          editorRef.current?.focus();
          document.execCommand(cmd, ui, val);
          emitUpdate();
        },
        insertContent: (html: string) => {
          editorRef.current?.focus();
          const sel = window.getSelection();
          if (sel && sel.rangeCount > 0) {
            const range = sel.getRangeAt(0);
            range.deleteContents();
            const el = document.createElement("div");
            el.innerHTML = html;
            const frag = document.createDocumentFragment();
            let node;
            while (node = el.firstChild) frag.appendChild(node);
            range.insertNode(frag);
          } else {
            // Fallback for no selection
            editorRef.current!.innerHTML += html;
          }
          emitUpdate();
        },
        getSelection: () => {
          const sel = window.getSelection();
          return sel?.toString() || '';
        },
        scrollToText: (text: string) => {
          if (!editorRef.current) return;
          const walker = document.createTreeWalker(editorRef.current, NodeFilter.SHOW_TEXT);
          let node;
          while (node = walker.nextNode()) {
            if (node.textContent?.toLowerCase().includes(text.toLowerCase())) {
              (node.parentElement as HTMLElement)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
              break;
            }
          }
        }
      };
      onInit(instance);
      analyzeParagraphs();
    }
  }, [onInit, emitUpdate, analyzeParagraphs]);

  // Update editor if initialContent changes externally (avoiding loops)
  useEffect(() => {
    if (editorRef.current && initialContent !== editorRef.current.innerHTML) {
      if (!isInternalUpdate.current) {
        editorRef.current.innerHTML = initialContent;
        analyzeParagraphs();
      }
    }
    isInternalUpdate.current = false;
  }, [initialContent, analyzeParagraphs]);

  const handleInput = () => {
    isInternalUpdate.current = true;
    emitUpdate();
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    const text = e.clipboardData.getData('text/plain');
    const html = e.clipboardData.getData('text/html');

    // Threshold for smart paste: either rich HTML or very long plain text
    if (!html || (html.trim() === "" && text.length < 500)) {
      return;
    }

    e.preventDefault();

    const sel = window.getSelection();
    if (sel && sel.rangeCount > 0) {
      savedRange.current = sel.getRangeAt(0).cloneRange();
    }

    setPendingPaste({ text, html });
    setShowPasteModal(true);
  };

  const handleSelectionChange = () => {
    const selection = window.getSelection();
    const text = selection?.toString().trim() || '';
    setShowFloatingAssist(text.length > 0);
  };

  const applyPaste = (mode: 'clean' | 'plain' | 'original') => {
    if (!pendingPaste || !editorRef.current) return;

    editorRef.current.focus();
    const sel = window.getSelection();
    if (sel && savedRange.current) {
      sel.removeAllRanges();
      sel.addRange(savedRange.current);
    }

    let toInsert = '';
    if (mode === 'plain') {
      toInsert = pendingPaste.text.replace(/\n/g, '<br>');
    } else if (mode === 'clean') {
      toInsert = pendingPaste.html
        .replace(/style="[^"]*"/gi, '')
        .replace(/class="[^"]*"/gi, '')
        .replace(/id="[^"]*"/gi, '')
        .replace(/<span[^>]*>(.*?)<\/span>/gi, '$1')
        .replace(/<o:p>.*?<\/o:p>/gi, '') 
        .replace(/<!--[\s\S]*?-->/g, '') // Remove HTML comments
        .trim();
    } else {
      toInsert = pendingPaste.html;
    }

    if (sel && sel.rangeCount > 0) {
      const range = sel.getRangeAt(0);
      range.deleteContents();

      const el = document.createElement("div");
      el.innerHTML = toInsert;
      const frag = document.createDocumentFragment();
      let node;
      while (node = el.firstChild) frag.appendChild(node);

      const lastNode = frag.lastChild;
      range.insertNode(frag);

      if (lastNode) {
        range.setStartAfter(lastNode);
        range.collapse(true);
        sel.removeAllRanges();
        sel.addRange(range);
      }
    }

    emitUpdate();
    setPendingPaste(null);
    setShowPasteModal(false);
    savedRange.current = null;
  };

  return (
    <div className="relative h-full w-full group overflow-hidden flex flex-col">
      <div 
        ref={editorRef}
        contentEditable
        onInput={handleInput}
        onPaste={handlePaste}
        onMouseUp={handleSelectionChange}
        onKeyUp={handleSelectionChange}
        className="editor-content flex-1 w-full h-full custom-scrollbar overflow-y-auto outline-none"
        spellCheck="true"
        aria-label="Content Editor"
      />

      {showFloatingAssist && (
        <div className="absolute bottom-6 right-6 animate-in fade-in slide-in-from-bottom-2 duration-300 z-10">
          <button 
            onClick={() => {
              onAIAssist('clarity');
              setShowFloatingAssist(false);
            }}
            className="bg-blue-600 hover:bg-blue-500 text-white px-4 py-2.5 rounded-2xl shadow-2xl flex items-center gap-2 text-[11px] font-black uppercase tracking-widest border border-blue-400/20 active:scale-95 transition-all"
          >
            <Sparkles size={14} className="animate-pulse" /> AI Assist Selection
          </button>
        </div>
      )}

      {showPasteModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/80 backdrop-blur-md p-4">
          <div className="bg-zinc-900 border border-zinc-800 rounded-[32px] w-full max-w-sm shadow-2xl overflow-hidden p-8 space-y-6">
            <div className="text-center">
              <div className="w-16 h-16 bg-blue-600/10 text-blue-500 rounded-3xl flex items-center justify-center mx-auto mb-4">
                <Clipboard size={32} />
              </div>
              <h3 className="font-black text-xl uppercase tracking-tighter text-white">Smart Paste</h3>
              <p className="text-xs text-zinc-500 mt-2 leading-relaxed">External content detected. Choose your preferred processing method.</p>
            </div>
            <div className="space-y-3">
              <button 
                onClick={() => applyPaste('clean')} 
                className="w-full py-4 bg-zinc-800 text-zinc-100 rounded-2xl font-black uppercase text-[10px] tracking-widest border border-zinc-700 hover:bg-zinc-700 hover:border-blue-500/50 transition-all"
              >
                Clean Formatting
              </button>
              <button 
                onClick={() => applyPaste('plain')} 
                className="w-full py-4 bg-zinc-800 text-zinc-100 rounded-2xl font-black uppercase text-[10px] tracking-widest border border-zinc-700 hover:bg-zinc-700 hover:border-blue-500/50 transition-all"
              >
                Plain Text
              </button>
              <button 
                onClick={() => applyPaste('original')} 
                className="w-full py-4 bg-blue-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-lg hover:bg-blue-500 transition-all border border-blue-400/30"
              >
                Keep Original
              </button>
            </div>
            <button 
              onClick={() => {
                setShowPasteModal(false);
                setPendingPaste(null);
                savedRange.current = null;
              }} 
              className="w-full py-2 text-zinc-500 text-[9px] uppercase font-bold tracking-widest hover:text-white transition-colors"
            >
              Cancel
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useRef, useCallback } from 'react';
import { Clipboard, Wand2, Sparkles, X } from 'lucide-react';

interface EditorProps {
  initialContent: string;
  onUpdate: (html: string) => void;
  onInit: (instance: any) => void;
  onAIAssist: (mode: any) => void;
}

export const Editor = ({ initialContent, onUpdate, onInit, onAIAssist }: EditorProps) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const [showPasteModal, setShowPasteModal] = useState(false);
  const [pendingPaste, setPendingPaste] = useState<{ text: string, html: string } | null>(null);
  const [showFloatingAssist, setShowFloatingAssist] = useState(false);
  const isInternalUpdate = useRef(false);
  const savedRange = useRef<Range | null>(null);

  const analyzeParagraphs = useCallback(() => {
    if (!editorRef.current) return;
    const paras = editorRef.current.querySelectorAll('p');
    paras.forEach(p => {
      const words = p.innerText.trim().split(/\s+/).filter(Boolean).length;
      if (words > 150) {
        p.classList.add('para-warning');
      } else {
        p.classList.remove('para-warning');
      }
    });
  }, []);

  const emitUpdate = useCallback(() => {
    if (editorRef.current) {
      onUpdate(editorRef.current.innerHTML);
      analyzeParagraphs();
    }
  }, [onUpdate, analyzeParagraphs]);

  // Expose Editor API to Parent
  useEffect(() => {
    if (editorRef.current) {
      editorRef.current.innerHTML = initialContent;

      const instance = {
        getContent: () => editorRef.current?.innerHTML || '',
        setContent: (html: string) => {
          if (editorRef.current) {
            editorRef.current.innerHTML = html;
            emitUpdate();
          }
        },
        execCommand: (cmd: string, ui: boolean, val: any) => {
          editorRef.current?.focus();
          document.execCommand(cmd, ui, val);
          emitUpdate();
        },
        insertContent: (html: string) => {
          editorRef.current?.focus();
          const sel = window.getSelection();
          if (sel && sel.rangeCount > 0) {
            const range = sel.getRangeAt(0);
            range.deleteContents();
            const el = document.createElement("div");
            el.innerHTML = html;
            const frag = document.createDocumentFragment();
            let node;
            while (node = el.firstChild) frag.appendChild(node);
            range.insertNode(frag);
            // Move cursor after the inserted content
            range.collapse(false);
            sel.removeAllRanges();
            sel.addRange(range);
          } else {
            editorRef.current!.innerHTML += html;
          }
          emitUpdate();
        },
        getSelection: () => {
          const sel = window.getSelection();
          return sel?.toString() || '';
        },
        scrollToText: (text: string) => {
          if (!editorRef.current) return;
          const walker = document.createTreeWalker(editorRef.current, NodeFilter.SHOW_TEXT);
          let node;
          while (node = walker.nextNode()) {
            if (node.textContent?.toLowerCase().includes(text.toLowerCase())) {
              (node.parentElement as HTMLElement)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
              break;
            }
          }
        }
      };
      onInit(instance);
      analyzeParagraphs();
    }
  }, [onInit, emitUpdate, analyzeParagraphs]);

  // Sync content updates
  useEffect(() => {
    if (editorRef.current && initialContent !== editorRef.current.innerHTML) {
      if (!isInternalUpdate.current) {
        editorRef.current.innerHTML = initialContent;
        analyzeParagraphs();
      }
    }
    isInternalUpdate.current = false;
  }, [initialContent, analyzeParagraphs]);

  const handleInput = () => {
    isInternalUpdate.current = true;
    emitUpdate();
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    const text = e.clipboardData.getData('text/plain');
    const html = e.clipboardData.getData('text/html');

    // Only trigger Smart Paste for complex/rich content or significant length
    const isRich = html && html.includes('<') && !html.startsWith('<!--');
    const isVeryLong = text.length > 800;

    if (!isRich && !isVeryLong) {
      return; // Default paste behavior for simple text
    }

    e.preventDefault();

    // Save selection range before modal opens
    const sel = window.getSelection();
    if (sel && sel.rangeCount > 0) {
      savedRange.current = sel.getRangeAt(0).cloneRange();
    }

    setPendingPaste({ text, html });
    setShowPasteModal(true);
  };

  const handleSelectionChange = () => {
    const selection = window.getSelection();
    const text = selection?.toString().trim() || '';
    setShowFloatingAssist(text.length > 5); // Minimum 5 chars to show assist
  };

  const applyPaste = (mode: 'clean' | 'plain' | 'original') => {
    if (!pendingPaste || !editorRef.current) return;

    // Re-focus the editor first
    editorRef.current.focus();

    // Restore selection
    const sel = window.getSelection();
    if (sel && savedRange.current) {
      sel.removeAllRanges();
      sel.addRange(savedRange.current);
    } else {
      // If we lost the range, move to end
      const range = document.createRange();
      range.selectNodeContents(editorRef.current);
      range.collapse(false);
      sel?.removeAllRanges();
      sel?.addRange(range);
    }

    let toInsert = '';
    if (mode === 'plain') {
      toInsert = pendingPaste.text.replace(/\n/g, '<br>');
    } else if (mode === 'clean') {
      const tempDiv = document.createElement('div');
      tempDiv.innerHTML = pendingPaste.html;

      // Remove all styles, classes, ids, and comments
      const allElements = tempDiv.querySelectorAll('*');
      allElements.forEach(el => {
        el.removeAttribute('style');
        el.removeAttribute('class');
        el.removeAttribute('id');
        // Filter out undesirable tags like scripts, frames, etc.
        if (['SCRIPT', 'STYLE', 'IFRAME', 'OBJECT', 'EMBED'].includes(el.tagName)) {
          el.remove();
        }
      });

      toInsert = tempDiv.innerHTML.replace(/<!--[\s\S]*?-->/g, '').trim();
    } else {
      toInsert = pendingPaste.html;
    }

    // Perform insertion
    const range = sel?.getRangeAt(0);
    if (range) {
      range.deleteContents();
      const el = document.createElement("div");
      el.innerHTML = toInsert;
      const frag = document.createDocumentFragment();
      let node;
      while (node = el.firstChild) frag.appendChild(node);

      const lastNode = frag.lastChild;
      range.insertNode(frag);

      if (lastNode) {
        range.setStartAfter(lastNode);
        range.collapse(true);
        sel?.removeAllRanges();
        sel?.addRange(range);
      }
    }

    emitUpdate();
    setPendingPaste(null);
    setShowPasteModal(false);
    savedRange.current = null;
  };

  return (
    <div className="relative h-full w-full group overflow-hidden flex flex-col">
      <div 
        ref={editorRef}
        contentEditable
        onInput={handleInput}
        onPaste={handlePaste}
        onMouseUp={handleSelectionChange}
        onKeyUp={handleSelectionChange}
        className="editor-content flex-1 w-full h-full custom-scrollbar overflow-y-auto outline-none"
        spellCheck="true"
        aria-label="Content Editor"
      />

      {showFloatingAssist && (
        <div className="absolute bottom-6 right-6 animate-in fade-in slide-in-from-bottom-2 duration-300 z-10">
          <button 
            onClick={() => {
              onAIAssist('clarity');
              setShowFloatingAssist(false);
            }}
            className="bg-blue-600 hover:bg-blue-500 text-white px-4 py-2.5 rounded-2xl shadow-2xl flex items-center gap-2 text-[11px] font-black uppercase tracking-widest border border-blue-400/20 active:scale-95 transition-all"
          >
            <Sparkles size={14} className="animate-pulse" /> AI Assist Selection
          </button>
        </div>
      )}

      {showPasteModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/80 backdrop-blur-md p-4" onMouseDown={(e) => e.stopPropagation()}>
          <div className="bg-zinc-900 border border-zinc-800 rounded-[32px] w-full max-w-sm shadow-2xl overflow-hidden p-8 space-y-6 animate-in zoom-in-95 duration-200">
            <div className="text-center">
              <div className="w-16 h-16 bg-blue-600/10 text-blue-500 rounded-3xl flex items-center justify-center mx-auto mb-4">
                <Clipboard size={32} />
              </div>
              <h3 className="font-black text-xl uppercase tracking-tighter text-white">Smart Paste</h3>
              <p className="text-xs text-zinc-500 mt-2 leading-relaxed">External content detected. Choose your preferred processing method.</p>
            </div>
            <div className="space-y-3">
              <button 
                onClick={() => applyPaste('clean')} 
                className="w-full py-4 bg-zinc-800 text-zinc-100 rounded-2xl font-black uppercase text-[10px] tracking-widest border border-zinc-700 hover:bg-zinc-700 hover:border-blue-500/50 transition-all flex items-center justify-center gap-2"
              >
                Clean Formatting
              </button>
              <button 
                onClick={() => applyPaste('plain')} 
                className="w-full py-4 bg-zinc-800 text-zinc-100 rounded-2xl font-black uppercase text-[10px] tracking-widest border border-zinc-700 hover:bg-zinc-700 hover:border-blue-500/50 transition-all flex items-center justify-center gap-2"
              >
                Plain Text
              </button>
              <button 
                onClick={() => applyPaste('original')} 
                className="w-full py-4 bg-blue-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-lg hover:bg-blue-500 transition-all border border-blue-400/30 flex items-center justify-center gap-2"
              >
                Keep Original
              </button>
            </div>
            <button 
              onClick={() => {
                setShowPasteModal(false);
                setPendingPaste(null);
                savedRange.current = null;
              }} 
              className="w-full py-2 text-zinc-500 text-[9px] uppercase font-bold tracking-widest hover:text-white transition-colors"
            >
              Cancel Paste
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

