import React, { useState, useEffect, useMemo, useDeferredValue, startTransition, useRef } from 'react';
import ReactDOM from 'react-dom/client';
import { Mail, Send, X, AlertTriangle, CheckCircle2 } from 'lucide-react';

import { getStats } from './core/text-analysis';
import { getKeywords } from './core/keyword-density';
import { getReadabilityScore } from './core/readability';
import { analyzeSEOHealth } from './core/seo-health';
import { detectIntent } from './core/intent-detector';
import { convertText } from './core/case-converter';
import { rewriteContent, generateMetadata, detectAIContent, RewriteMode, generateFAQs } from './ai/ai-engine';
import { htmlToMarkdown } from './utils/text-cleaner';

import { Toolbar } from './components/editor/Toolbar';
import { Sidebar } from './components/layout/Sidebar';
import { Editor } from './components/editor/Editor';
import { Tab, SEOPhraseTab, KeywordTarget, FAQ } from './types/editor.types';

const App = () => {
  // 1. Content State - Default starts with a paragraph
  const [content, setContent] = useState(() => 
    localStorage.getItem('seo-editor-content') || '<p>Start crafting your optimized, AI-enhanced SEO content here. Focus on quality and keywords to rank higher.</p>'
  );

  // 2. View States
  const [activeTab, setActiveTab] = useState<Tab>('insights'); 
  const [viewMode, setViewMode] = useState<'normal' | 'focus' | 'distraction' | 'split'>('normal');
  const [showHtml, setShowHtml] = useState(false);
  const [wordTarget, setWordTarget] = useState(1000);
  const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [editorInstance, setEditorInstance] = useState<any>(null);
  const [showReportModal, setShowReportModal] = useState(false);
  const [reportEmail, setReportEmail] = useState('');
  const [reportIssue, setReportIssue] = useState('');
  const [metaTitle, setMetaTitle] = useState(() => localStorage.getItem('seo-meta-title') || '');
  const [metaDescription, setMetaDescription] = useState(() => localStorage.getItem('seo-meta') || '');
  const [targets, setTargets] = useState<KeywordTarget>(() => {
    const saved = localStorage.getItem('seo-targets');
    return saved ? JSON.parse(saved) : { primary: '', secondary: ['', '', ''] };
  });
  const [faqs, setFaqs] = useState<FAQ[]>(() => {
    const saved = localStorage.getItem('seo-faqs');
    return saved ? JSON.parse(saved) : [];
  });

  const deferredContent = useDeferredValue(content);

  // Persistence
  useEffect(() => {
    localStorage.setItem('seo-editor-content', content);
    localStorage.setItem('seo-targets', JSON.stringify(targets));
    localStorage.setItem('seo-meta', metaDescription);
    localStorage.setItem('seo-meta-title', metaTitle);
    localStorage.setItem('seo-faqs', JSON.stringify(faqs));
  }, [content, targets, metaDescription, metaTitle, faqs]);

  // Analysis
  const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
  const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
  const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
  const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, targets, metaDescription), [deferredContent, keywords, targets, metaDescription]);
  const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);

  const handleEditorChange = (newContent: string) => {
    startTransition(() => {
      setContent(newContent);
    });
  };

  const onRewrite = async (mode: RewriteMode) => {
    if (!editorInstance) return;
    const selectedText = editorInstance.getSelection();

    if (!selectedText) {
      alert("Please select text to rewrite.");
      return;
    }

    setIsAIProcessing(true);
    try {
      const results = await rewriteContent(selectedText, mode);
      if (results && results.length > 0) {
        editorInstance.insertContent(results[0]);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleReportSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    console.log(`Sending report to rathod.shivang@gmail.com:`, {
      from: reportEmail,
      issue: reportIssue,
      contentPreview: content.substring(0, 100)
    });
    alert("Report sent successfully to rathod.shivang@gmail.com.");
    setReportIssue('');
    setShowReportModal(false);
  };

  return (
    <div className={`h-screen w-screen flex flex-col md:flex-row bg-white text-zinc-900 overflow-hidden ${viewMode === 'focus' ? 'focus-mode' : ''} ${viewMode === 'distraction' ? 'distraction-free' : ''}`}>

      {/* Redesigned Report Modal - Square and Centered */}
      {showReportModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-zinc-900/40 backdrop-blur-sm p-4">
          <div className="bg-white border border-zinc-200 shadow-2xl w-full max-w-[450px] aspect-square flex flex-col animate-in zoom-in-95 duration-200">
            <div className="p-8 flex flex-col h-full">
              <h3 className="text-xl font-black mb-2 flex items-center gap-2 uppercase tracking-tighter text-blue-600">
                <Mail size={24} /> Report Issue
              </h3>
              <p className="text-[11px] font-bold text-zinc-400 uppercase tracking-widest mb-6">Feedback for rathod.shivang@gmail.com</p>

              <form onSubmit={handleReportSubmit} className="flex-1 flex flex-col gap-4">
                <input 
                  type="email" required placeholder="Your email address" value={reportEmail} 
                  onChange={e => setReportEmail(e.target.value)}
                  className="w-full bg-zinc-50 border border-zinc-200 rounded-lg p-4 outline-none focus:border-blue-500 transition-all font-medium text-sm" 
                />
                <textarea 
                  required placeholder="Describe the issue or feedback..." value={reportIssue} 
                  onChange={e => setReportIssue(e.target.value)}
                  className="w-full bg-zinc-50 border border-zinc-200 rounded-lg p-4 flex-1 outline-none focus:border-blue-500 transition-all resize-none text-sm leading-relaxed" 
                />

                <div className="flex gap-3 mt-4">
                  <button 
                    type="button" 
                    onClick={() => setShowReportModal(false)} 
                    className="flex-1 py-4 border border-zinc-200 rounded-lg font-bold text-zinc-500 text-xs uppercase tracking-widest hover:bg-zinc-50 transition-all"
                  >
                    Cancel
                  </button>
                  <button 
                    type="submit" 
                    className="flex-1 bg-blue-600 text-white py-4 rounded-lg font-bold text-xs uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-blue-700 shadow-lg shadow-blue-500/20 transition-all"
                  >
                    <Send size={16} /> Send Report
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}

      <div className="flex-1 flex flex-col relative overflow-hidden">
        <header className="h-16 border-b border-zinc-100 flex items-center justify-between px-6 bg-white/80 backdrop-blur-xl z-30">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-black shadow-lg shadow-blue-500/30">S</div>
            <h1 className="font-black tracking-tight uppercase text-zinc-900">SEO Focus</h1>
          </div>
          <div className="flex items-center gap-4">
            <button onClick={() => setShowReportModal(true)} className="text-[10px] font-black text-zinc-500 hover:text-blue-600 uppercase tracking-widest px-5 py-2.5 bg-zinc-50 border border-zinc-100 rounded-full transition-all">Report Issue</button>
          </div>
        </header>

        <div className="toolbar-wrapper sticky top-0 z-20">
          <Toolbar 
            editorInstance={editorInstance} 
            onUpdate={() => handleEditorChange(editorInstance?.getContent() || '')}
            onNewDocument={() => { if(confirm('Clear all?')) editorInstance?.setContent(''); }}
            onShowHistory={() => {}} 
            onSaveVersion={() => alert('Snapshot saved.')}
            viewMode={viewMode}
            onToggleHtml={() => setShowHtml(!showHtml)}
            showHtml={showHtml}
          />
        </div>

        <main className={`flex-1 p-4 md:p-8 bg-zinc-50/50 flex gap-4 overflow-hidden relative transition-all duration-500`}>
          <div className={`editor-container h-full border border-zinc-100 rounded-[32px] overflow-hidden bg-white shadow-xl shadow-zinc-200/50 transition-all duration-500 w-full max-w-4xl mx-auto`}>
            {showHtml ? (
              <textarea 
                className="w-full h-full bg-zinc-900 text-emerald-400 font-mono p-10 text-sm outline-none resize-none leading-relaxed"
                value={content}
                onChange={(e) => handleEditorChange(e.target.value)}
              />
            ) : (
              <Editor 
                initialContent={content}
                onUpdate={handleEditorChange}
                onInit={setEditorInstance}
                onAIAssist={onRewrite}
              />
            )}
          </div>

          {/* Word Goal Progress Overlay (Floater) */}
          {viewMode !== 'distraction' && (
            <div className="absolute bottom-12 left-1/2 -translate-x-1/2 bg-white/90 backdrop-blur-xl border border-zinc-100 rounded-full px-8 py-3 shadow-2xl flex items-center gap-6 z-40">
              <div className="text-[10px] font-black text-zinc-500 uppercase tracking-tighter">{stats.words} <span className="text-zinc-300 mx-1">/</span> {wordTarget} words</div>
              <div className="w-48 h-2 bg-zinc-100 rounded-full overflow-hidden">
                <div 
                  className={`h-full transition-all duration-1000 ${stats.words >= wordTarget ? 'bg-emerald-500' : 'bg-blue-600'}`} 
                  style={{ width: `${Math.min(100, (stats.words / wordTarget) * 100)}%` }} 
                />
              </div>
              <input 
                type="number" 
                value={wordTarget} 
                onChange={e => setWordTarget(parseInt(e.target.value) || 0)} 
                className="bg-transparent w-16 text-[10px] font-black text-blue-600 outline-none border-b border-blue-200 focus:border-blue-500"
                title="Set Word Goal"
              />
            </div>
          )}
        </main>
      </div>

      <Sidebar 
        activeTab={activeTab} setActiveTab={setActiveTab} 
        stats={stats} readability={readability} health={health} intent={intent} keywords={keywords} 
        seoTab={seoTab} setSeoTab={setSeoTab} isExpanded={isExpanded} setIsExpanded={setIsExpanded} 
        onRewrite={onRewrite} 
        onConvertCase={(type) => {
          if (editorInstance) {
            const selected = editorInstance.getSelection();
            if (selected) {
              editorInstance.insertContent(convertText(selected, type));
            }
          }
        }} 
        onCopy={(type) => {
          let toCopy = '';
          if (type === 'markdown') toCopy = htmlToMarkdown(content);
          else if (type === 'html') toCopy = content;
          else toCopy = content.replace(/<[^>]*>/g, '');

          navigator.clipboard.writeText(toCopy);
          alert(`${type.toUpperCase()} copied to clipboard.`);
        }} 
        onClear={() => { if(confirm('Clear all?')) editorInstance?.setContent(''); }} 
        isAIProcessing={isAIProcessing} targets={targets} setTargets={setTargets}
        metaTitle={metaTitle} setMetaTitle={setMetaTitle} 
        metaDescription={metaDescription} setMetaDescription={setMetaDescription}
        faqs={faqs} setFaqs={setFaqs}
        onGenerateMetadata={async (type) => {
          setIsAIProcessing(true);
          try {
            const res = await generateMetadata(content, type);
            if (type === 'title') setMetaTitle(res); else setMetaDescription(res);
          } finally { setIsAIProcessing(false); }
        }}
        onDetectAI={async () => {
          setIsAIProcessing(true);
          try {
            const res = await detectAIContent(content);
            alert(`AI Content Check\nScore: ${res.score}%\nAnalysis: ${res.analysis}`);
          } finally { setIsAIProcessing(false); }
        }}
        onGenerateFAQs={async () => {
          setIsAIProcessing(true);
          try {
            const res = await generateFAQs(content);
            setFaqs(res);
          } finally { setIsAIProcessing(false); }
        }}
        onExportSchema={() => {
          if (faqs.length === 0) {
            alert("No FAQs found. Please add or generate some first.");
            return;
          }
          const schema = {
            "@context": "https://schema.org",
            "@type": "FAQPage",
            "mainEntity": faqs.map(f => ({
              "@type": "Question",
              "name": f.question,
              "acceptedAnswer": {
                "@type": "Answer",
                "text": f.answer
              }
            }))
          };
          navigator.clipboard.writeText(JSON.stringify(schema, null, 2));
          alert("FAQ Schema (JSON-LD) copied to clipboard.");
        }}
        onNavigateOutline={(text) => {
           if (editorInstance) {
             editorInstance.scrollToText(text);
           }
        }}
      />
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root')!);
root.render(<App />);

