  <h3 className="text-[10px] font-black text-zinc-300 uppercase tracking-[0.25em] mb-5">{title}</h3>
);

const ActionButton = ({ onClick, label, variant = 'primary', icon, className, disabled }: any) => {
  const styles: any = {
    primary: 'bg-white text-zinc-800 border-zinc-200 hover:border-blue-500 shadow-sm hover:text-blue-600',
    secondary: 'bg-zinc-50 text-zinc-500 border-zinc-100 hover:bg-zinc-100',
    danger: 'bg-red-50 text-red-500 border-red-100 hover:bg-red-100',
    ai: 'bg-blue-600 text-white border-transparent hover:bg-blue-700 shadow-lg shadow-blue-500/20'
  };
  return (
    <button 
      onClick={onClick} 
      disabled={disabled}
      className={`w-full py-3.5 px-4 rounded-xl text-[11px] font-black border transition-all flex items-center justify-center gap-2 uppercase tracking-widest disabled:opacity-50 ${styles[variant]} ${className}`}
    >
      {icon}{label}
    </button>
  );
};

