          <div className="flex justify-center mb-10">
            <Link to="/" className="flex items-center gap-2 group">
              <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white font-black shadow-lg shadow-blue-500/30 group-hover:scale-105 transition-transform text-xl">S</div>
