            <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest text-sm flex items-center justify-center gap-3 shadow-xl shadow-blue-500/30 hover:bg-blue-700 transition-all active:scale-95">
              {isVerifying ? 'Verify & Continue' : mode === 'login' ? 'Login' : 'Create Account'} <ArrowRight size={18} />
