import React, { useState, useEffect, useMemo, useDeferredValue, startTransition } from 'react';
import { useParams } from 'react-router-dom';
import { Mail, Send } from 'lucide-react';

import { getStats } from '../../core/text-analysis';
import { getKeywords } from '../../core/keyword-density';
import { getReadabilityScore } from '../../core/readability';
import { analyzeSEOHealth } from '../../core/seo-health';
import { detectIntent } from '../../core/intent-detector';
import { convertText } from '../../core/case-converter';
import { rewriteContent, generateMetadata, detectAIContent, RewriteMode, generateFAQs } from '../../ai/ai-engine';
import { htmlToMarkdown } from '../../utils/text-cleaner';

import { Toolbar } from '../../components/editor/Toolbar';
import { Sidebar } from '../../components/layout/Sidebar';
import { Editor } from '../../components/editor/Editor';
import { Tab, SEOPhraseTab, KeywordTarget, FAQ } from '../../types/editor.types';

export const EditorPage = () => {
  const { id } = useParams();

  // 1. Content State
  const [content, setContent] = useState(() => 
    localStorage.getItem(`seo-editor-content-${id || 'new'}`) || '<p>Start crafting your optimized, AI-enhanced SEO content here.</p>'
  );

  // 2. View States
  const [activeTab, setActiveTab] = useState<Tab>('insights'); 
  const [wordTarget, setWordTarget] = useState(1000);
  const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [editorInstance, setEditorInstance] = useState<any>(null);
  const [showReportModal, setShowReportModal] = useState(false);
  const [reportEmail, setReportEmail] = useState('');
  const [reportIssue, setReportIssue] = useState('');

  const [metaTitle, setMetaTitle] = useState(() => localStorage.getItem(`seo-meta-title-${id || 'new'}`) || '');
  const [metaDescription, setMetaDescription] = useState(() => localStorage.getItem(`seo-meta-${id || 'new'}`) || '');
  const [targets, setTargets] = useState<KeywordTarget>(() => {
    const saved = localStorage.getItem(`seo-targets-${id || 'new'}`);
    return saved ? JSON.parse(saved) : { primary: '', secondary: ['', '', ''] };
  });
  const [faqs, setFaqs] = useState<FAQ[]>(() => {
    const saved = localStorage.getItem(`seo-faqs-${id || 'new'}`);
    return saved ? JSON.parse(saved) : [];
  });

  const deferredContent = useDeferredValue(content);

  // Persistence
  useEffect(() => {
    const key = id || 'new';
    localStorage.setItem(`seo-editor-content-${key}`, content);
    localStorage.setItem(`seo-targets-${key}`, JSON.stringify(targets));
    localStorage.setItem(`seo-meta-${key}`, metaDescription);
    localStorage.setItem(`seo-meta-title-${key}`, metaTitle);
    localStorage.setItem(`seo-faqs-${key}`, JSON.stringify(faqs));
  }, [content, targets, metaDescription, metaTitle, faqs, id]);

  // Analysis
  const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
  const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
  const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
  const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, targets, metaDescription), [deferredContent, keywords, targets, metaDescription]);
  const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);

  const handleEditorChange = (newContent: string) => {
    startTransition(() => {
      setContent(newContent);
    });
  };

  const onRewrite = async (mode: RewriteMode) => {
    if (!editorInstance) return;
    const selectedText = editorInstance.getSelection();
    if (!selectedText) {
      alert("Please select text to rewrite.");
      return;
    }
    setIsAIProcessing(true);
    try {
      const results = await rewriteContent(selectedText, mode);
      if (results && results.length > 0) {
        editorInstance.insertContent(results[0]);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  return (
    <div className="flex-1 flex flex-col h-full relative overflow-hidden bg-white">
      {/* Report Modal */}
      {showReportModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-zinc-900/40 backdrop-blur-sm p-4">
          <div className="bg-white border border-zinc-200 shadow-2xl w-full max-w-[450px] aspect-square flex flex-col">
            <div className="p-8 flex flex-col h-full">
              <h3 className="text-xl font-black mb-2 flex items-center gap-2 uppercase tracking-tighter text-blue-600">Report Issue</h3>
              <form onSubmit={(e) => { e.preventDefault(); setShowReportModal(false); }} className="flex-1 flex flex-col gap-4">
                <input type="email" required placeholder="Your email" value={reportEmail} onChange={e => setReportEmail(e.target.value)} className="w-full bg-zinc-50 border border-zinc-200 rounded-lg p-4 font-medium" />
                <textarea required placeholder="Issue details..." value={reportIssue} onChange={e => setReportIssue(e.target.value)} className="w-full bg-zinc-50 border border-zinc-200 rounded-lg p-4 flex-1 resize-none" />
                <div className="flex gap-3 mt-4">
                  <button type="button" onClick={() => setShowReportModal(false)} className="flex-1 py-4 border border-zinc-200 rounded-lg font-bold text-xs uppercase tracking-widest">Cancel</button>
                  <button type="submit" className="flex-1 bg-blue-600 text-white py-4 rounded-lg font-bold text-xs uppercase tracking-widest">Send</button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}

      {/* Editor Main Section */}
      <div className="flex-1 flex flex-col overflow-hidden">
        <div className="toolbar-wrapper border-b border-zinc-100 bg-white">
          <Toolbar 
            editorInstance={editorInstance} 
            onUpdate={() => handleEditorChange(editorInstance?.getContent() || '')}
            onNewDocument={() => editorInstance?.setContent('')}
            onShowHistory={() => {}} 
            onSaveVersion={() => {}}
            viewMode="normal"
          />
        </div>

        <div className="flex flex-1 overflow-hidden">
          <main className="flex-1 bg-zinc-50/30 p-8 overflow-hidden relative flex justify-center">
            <div className="w-full max-w-4xl h-full border border-zinc-100 rounded-[32px] overflow-hidden bg-white shadow-xl shadow-zinc-200/50">
              <Editor 
                initialContent={content}
                onUpdate={handleEditorChange}
                onInit={setEditorInstance}
                onAIAssist={onRewrite}
              />
            </div>

            {/* Floating Word Count */}
            <div className="absolute bottom-12 bg-white/90 backdrop-blur-xl border border-zinc-100 rounded-full px-8 py-3 shadow-2xl flex items-center gap-6 z-40">
              <div className="text-[10px] font-black text-zinc-500 uppercase tracking-tighter">{stats.words} / {wordTarget} words</div>
              <div className="w-32 h-1.5 bg-zinc-100 rounded-full overflow-hidden">
                <div className="h-full bg-blue-600" style={{ width: `${Math.min(100, (stats.words / wordTarget) * 100)}%` }} />
              </div>
            </div>
          </main>

          <Sidebar 
            activeTab={activeTab} setActiveTab={setActiveTab} 
            stats={stats} readability={readability} health={health} intent={intent} keywords={keywords} 
            seoTab={seoTab} setSeoTab={setSeoTab} isExpanded={isExpanded} setIsExpanded={setIsExpanded} 
            onRewrite={onRewrite} 
            onConvertCase={(type) => editorInstance?.insertContent(convertText(editorInstance?.getSelection(), type))} 
            onCopy={(type) => {
              let res = content;
              if (type === 'markdown') res = htmlToMarkdown(content);
              else if (type === 'plain') res = content.replace(/<[^>]*>/g, '');
              navigator.clipboard.writeText(res);
              alert('Copied');
            }} 
            onClear={() => editorInstance?.setContent('')} 
            isAIProcessing={isAIProcessing} targets={targets} setTargets={setTargets}
            metaTitle={metaTitle} setMetaTitle={setMetaTitle} 
            metaDescription={metaDescription} setMetaDescription={setMetaDescription}
            faqs={faqs} setFaqs={setFaqs}
            onGenerateMetadata={async (type) => {
              setIsAIProcessing(true);
              const res = await generateMetadata(content, type);
              if (type === 'title') setMetaTitle(res); else setMetaDescription(res);
              setIsAIProcessing(false);
            }}
            onDetectAI={async () => {
