import React, { createContext, useContext, useState, ReactNode } from 'react';
import ReactDOM from 'react-dom/client';
import { 
  BrowserRouter, 
  Routes, 
  Route, 
  Navigate, 
  useLocation 
} from 'react-router-dom';

// Layouts
import { PublicLayout } from './components/layout/PublicLayout.tsx';
import { AppLayout } from './components/layout/AppLayout.tsx';

// Public Pages
import { LandingPage } from './pages/public/Landing.tsx';
import { FeaturesPage } from './pages/public/Features.tsx';
import { PricingPage } from './pages/public/Pricing.tsx';
import { AboutPage } from './pages/public/About.tsx';
import { ContactPage } from './pages/public/Contact.tsx';
import { PrivacyPage } from './pages/public/Privacy.tsx';
import { TermsPage } from './pages/public/Terms.tsx';

// Auth Pages
import { AuthPage } from './pages/auth/Auth.tsx';
import { OnboardingPage } from './pages/auth/Onboarding.tsx';

// Protected Pages
import { DashboardPage } from './pages/app/Dashboard.tsx';
import { EditorPage } from './pages/app/EditorPage.tsx';
import { AccountPage } from './pages/app/Account.tsx';
import { BillingPage } from './pages/app/Billing.tsx';
import { UsagePage } from './pages/app/Usage.tsx';

// --- AUTH CONTEXT ---
interface User {
  id: string;
  email: string;
  onboarded?: boolean;
  name?: string;
}

interface AuthContextType {
  user: User | null;
  login: (email: string) => void;
  logout: () => void;
  completeOnboarding: (data: any) => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const AuthProvider = ({ children }: { children: ReactNode }) => {
  const [user, setUser] = useState<User | null>(() => {
    try {
      const saved = localStorage.getItem('seo-auth-user');
      return saved ? JSON.parse(saved) : null;
    } catch {
      return null;
    }
  });

  const login = (email: string) => {
    const newUser = { id: 'usr_' + Math.random().toString(36).substr(2, 9), email, onboarded: false };
    setUser(newUser);
    localStorage.setItem('seo-auth-user', JSON.stringify(newUser));
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem('seo-auth-user');
  };

  const completeOnboarding = (data: any) => {
    if (user) {
      const updatedUser = { ...user, onboarded: true };
      setUser(updatedUser);
      localStorage.setItem('seo-auth-user', JSON.stringify(updatedUser));
      localStorage.setItem(`onboarding_${user.id}`, JSON.stringify(data));
    }
  };

  return (
    <AuthContext.Provider value={{ user, login, logout, completeOnboarding }}>
      {children}
    </AuthContext.Provider>
  );
};

const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

// --- PROTECTED ROUTE COMPONENT ---
const ProtectedRoute = ({ children, requireOnboarding = true }: { children: ReactNode, requireOnboarding?: boolean }) => {
  const { user } = useAuth();
  const location = useLocation();

  if (!user) {
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  if (requireOnboarding && !user.onboarded) {
    return <Navigate to="/onboarding" replace />;
  }

  return <>{children}</>;
};

// --- MAIN APP COMPONENT ---
const App = () => {
  const { user, login, logout, completeOnboarding } = useAuth();

  return (
    <Routes>
      {/* Public Marketing Routes */}
      <Route element={<PublicLayout />}>
        <Route path="/" element={<LandingPage />} />
        <Route path="/features" element={<FeaturesPage />} />
        <Route path="/pricing" element={<PricingPage />} />
        <Route path="/about" element={<AboutPage />} />
        <Route path="/contact" element={<ContactPage />} />
        <Route path="/privacy" element={<PrivacyPage />} />
        <Route path="/terms" element={<TermsPage />} />
      </Route>

      {/* Auth Routes */}
      <Route path="/login" element={<AuthPage mode="login" onAuth={login} />} />
      <Route path="/signup" element={<AuthPage mode="signup" onAuth={login} />} />
      <Route path="/onboarding" element={
        <ProtectedRoute requireOnboarding={false}>
          <OnboardingPage onComplete={completeOnboarding} />
        </ProtectedRoute>
      } />

      {/* Protected App Routes */}
      <Route path="/app" element={
        <ProtectedRoute>
          <AppLayout onLogout={logout} />
        </ProtectedRoute>
      }>
        <Route path="dashboard" element={<DashboardPage />} />
        <Route path="editor" element={<EditorPage />} />
        <Route path="editor/:id" element={<EditorPage />} />
        <Route path="account" element={<AccountPage user={user} />} />
        <Route path="billing" element={<BillingPage />} />
        <Route path="usage" element={<UsagePage />} />
        {/* Redirect /app to /app/dashboard */}
        <Route index element={<Navigate to="dashboard" replace />} />
      </Route>

      {/* Fallback */}
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
};

// --- INITIALIZATION ---
const rootElement = document.getElementById('root');
if (!rootElement) throw new Error('Failed to find the root element');

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <AuthProvider>
      <BrowserRouter>
        <App />
      </BrowserRouter>
    </AuthProvider>
  </React.StrictMode>
);

