import React, { useState, useEffect, useMemo, useDeferredValue, startTransition } from 'react';
import { Sparkles } from 'lucide-react';

// Core Analysis Logic
import { getStats } from './core/text-analysis.ts';
import { getKeywords } from './core/keyword-density.ts';
import { getReadabilityScore } from './core/readability.ts';
import { analyzeSEOHealth } from './core/seo-health.ts';
import { detectIntent } from './core/intent-detector.ts';
import { convertText } from './core/case-converter.ts';

// AI Integration
import { 
  rewriteContent, 
  generateMetadata, 
  detectAIContent, 
  RewriteMode, 
  generateFAQs 
} from './ai/ai-engine.ts';

// Components
import { Toolbar } from './components/editor/Toolbar.tsx';
import { Sidebar } from './components/layout/Sidebar.tsx';
import { Editor } from './components/editor/Editor.tsx';
import { Tab, SEOPhraseTab, KeywordTarget, FAQ } from './types/editor.types.ts';
import { htmlToMarkdown } from './utils/text-cleaner.ts';

export default function App() {
  // 1. Content State
  const [content, setContent] = useState(() => 
    localStorage.getItem('seo-editor-content-v2') || 
    '<h1>Future of Content SEO</h1><p>Start crafting your optimized, AI-enhanced SEO content here. This editor analyzes your text in real-time to ensure maximum search visibility.</p>'
  );

  // 2. Editor & UI State
  const [activeTab, setActiveTab] = useState<Tab>('insights'); 
  const [wordTarget, setWordTarget] = useState(1000);
  const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [editorInstance, setEditorInstance] = useState<any>(null);

  // 3. SEO Metadata State
  const [metaTitle, setMetaTitle] = useState(() => localStorage.getItem('seo-meta-title-v2') || '');
  const [metaDescription, setMetaDescription] = useState(() => localStorage.getItem('seo-meta-desc-v2') || '');
  const [targets, setTargets] = useState<KeywordTarget>(() => {
    const saved = localStorage.getItem('seo-targets-v2');
    return saved ? JSON.parse(saved) : { primary: '', secondary: ['', '', ''] };
  });
  const [faqs, setFaqs] = useState<FAQ[]>(() => {
    const saved = localStorage.getItem('seo-faqs-v2');
    return saved ? JSON.parse(saved) : [];
  });

  const deferredContent = useDeferredValue(content);

  // Persistence
  useEffect(() => {
    localStorage.setItem('seo-editor-content-v2', content);
    localStorage.setItem('seo-targets-v2', JSON.stringify(targets));
    localStorage.setItem('seo-meta-desc-v2', metaDescription);
    localStorage.setItem('seo-meta-title-v2', metaTitle);
    localStorage.setItem('seo-faqs-v2', JSON.stringify(faqs));
  }, [content, targets, metaDescription, metaTitle, faqs]);

  // Analysis Memoization
  const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
  const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
  const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
  const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, targets, metaDescription), [deferredContent, keywords, targets, metaDescription]);
  const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);

  const handleEditorChange = (newContent: string) => {
    startTransition(() => {
      setContent(newContent);
    });
  };

  const onRewrite = async (mode: RewriteMode) => {
    if (!editorInstance) return;
    const selectedText = editorInstance.getSelection();
    if (!selectedText) {
      alert("Please select text within the editor to use AI rewriting features.");
      return;
    }
    setIsAIProcessing(true);
    try {
      const results = await rewriteContent(selectedText, mode);
      if (results && results.length > 0) {
        // Automatically insert the first AI option
        editorInstance.insertContent(results[0]);
      }
    } catch (err) {
      console.error("AI Rewrite Failed:", err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  return (
    <div className="flex h-screen w-full bg-white overflow-hidden text-zinc-900 selection:bg-blue-100">
      {/* Main Editor Viewport */}
      <div className="flex-1 flex flex-col min-w-0 border-r border-zinc-100">
        {/* Navigation & Toolbar Header */}
        <header className="h-16 border-b border-zinc-100 px-8 flex items-center justify-between bg-white shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-black shadow-lg shadow-blue-500/20">S</div>
            <h1 className="font-black tracking-tighter text-lg uppercase">SEO Focus <span className="text-zinc-300 font-medium">Editor</span></h1>
          </div>
          <div className="flex items-center gap-4">
             <div className="flex items-center gap-2 px-3 py-1.5 bg-zinc-50 rounded-full border border-zinc-100">
                <div className={`w-2 h-2 rounded-full ${isAIProcessing ? 'bg-blue-500 animate-pulse' : 'bg-emerald-500'}`} />
                <span className="text-[10px] font-black uppercase tracking-widest text-zinc-500">
                  {isAIProcessing ? 'AI Processing' : 'Engine Ready'}
                </span>
             </div>
          </div>
        </header>

        <div className="flex-1 flex flex-col overflow-hidden relative">
          <div className="toolbar-container bg-white border-b border-zinc-100">
            <Toolbar 
              editorInstance={editorInstance} 
              onUpdate={() => handleEditorChange(editorInstance?.getContent() || '')}
              onNewDocument={() => {
                if(confirm("Start a new document? All current content will be cleared.")) {
                  editorInstance?.setContent('<h1>New Masterpiece</h1><p>Start writing...</p>');
                }
              }}
              onShowHistory={() => {}} 
              onSaveVersion={() => {}}
              viewMode="focused"
            />
          </div>

          <main className="flex-1 bg-zinc-50/20 p-6 md:p-12 overflow-hidden flex justify-center relative">
            <div className="w-full max-w-4xl h-full border border-zinc-100 rounded-[40px] overflow-hidden bg-white shadow-2xl shadow-zinc-200/40 relative">
              <Editor 
                initialContent={content}
                onUpdate={handleEditorChange}
                onInit={setEditorInstance}
                onAIAssist={onRewrite}
              />
            </div>

            {/* Floating Word Counter */}
            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 bg-white/80 backdrop-blur-xl border border-zinc-100 rounded-full px-8 py-3.5 shadow-2xl flex items-center gap-6 z-40 transition-all hover:scale-105">
              <div className="flex flex-col">
                <span className="text-[9px] font-black text-zinc-400 uppercase tracking-widest mb-0.5">Progress</span>
                <div className="text-[11px] font-black text-zinc-800 uppercase tabular-nums">
                  {stats.words} <span className="text-zinc-300">/</span> {wordTarget} words
                </div>
              </div>
              <div className="w-24 h-1.5 bg-zinc-100 rounded-full overflow-hidden">
                <div 
                  className="h-full bg-blue-600 transition-all duration-700 ease-out" 
                  style={{ width: `${Math.min(100, (stats.words / wordTarget) * 100)}%` }} 
                />
              </div>
            </div>
          </main>
        </div>
      </div>

      {/* Analysis Sidebar */}
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        stats={stats} 
        readability={readability} 
        health={health} 
        intent={intent} 
        keywords={keywords} 
        seoTab={seoTab} 
        setSeoTab={setSeoTab} 
        isExpanded={isExpanded} 
        setIsExpanded={setIsExpanded} 
        onRewrite={onRewrite} 
        onConvertCase={(type) => {
          const selected = editorInstance?.getSelection();
          if (selected) {
            editorInstance?.insertContent(convertText(selected, type));
          }
        }} 
        onCopy={(type) => {
          let output = content;
          if (type === 'markdown') output = htmlToMarkdown(content);
          else if (type === 'plain') output = content.replace(/<[^>]*>/g, '');

          navigator.clipboard.writeText(output).then(() => {
             // Visual feedback can be added here
          });
        }} 
        onClear={() => {
           if(confirm("Delete all content?")) editorInstance?.setContent('');
        }} 
        isAIProcessing={isAIProcessing} 
        targets={targets} 
        setTargets={setTargets}
        metaTitle={metaTitle} 
        setMetaTitle={setMetaTitle} 
        metaDescription={metaDescription} 
        setMetaDescription={setMetaDescription}
        faqs={faqs} 
        setFaqs={setFaqs}
        onGenerateMetadata={async (type) => {
          setIsAIProcessing(true);
          try {
            const res = await generateMetadata(content, type);
            if (type === 'title') setMetaTitle(res); 
            else setMetaDescription(res);
          } catch (e) {
            console.error("Metadata Generation Error:", e);
          } finally {
            setIsAIProcessing(false);
          }
        }}
        onDetectAI={async () => {
          setIsAIProcessing(true);
          try {
            const res = await detectAIContent(content);
            alert(`AI Detection Result:\nScore: ${res.score}%\nAnalysis: ${res.analysis}`);
          } catch (e) {
            console.error("AI Detection Error:", e);
          } finally {
            setIsAIProcessing(false);
          }
        }}
        onGenerateFAQs={async () => {
          setIsAIProcessing(true);
          try {
            const res = await generateFAQs(content);
            setFaqs(res);
          } catch (e) {
            console.error("FAQ Generation Error:", e);
          } finally {
            setIsAIProcessing(false);
          }
        }}
        onExportSchema={() => {
           const schema = {
             "@context": "https://schema.org",
             "@type": "Article",
             "headline": metaTitle,
             "description": metaDescription,
             "mainEntityOfPage": {
               "@type": "WebPage",
               "@id": window.location.href
             }
           };
           navigator.clipboard.writeText(JSON.stringify(schema, null, 2));
           alert('Article Schema copied to clipboard.');
        }}
        onNavigateOutline={(text) => editorInstance?.scrollToText(text)}
      />
    </div>
  );
}

import React, { useEffect, useState, useRef, useCallback } from 'react';

interface EditorProps {
  initialContent: string;
  onUpdate: (html: string) => void;
  onInit: (instance: any) => void;
  onAIAssist: (mode: any) => void;
}

export const Editor = ({ initialContent, onUpdate, onInit, onAIAssist }: EditorProps) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const lastContentEmitted = useRef(initialContent);

  const analyzeParagraphs = useCallback(() => {
    if (!editorRef.current) return;
    const paras = editorRef.current.querySelectorAll('p');
    paras.forEach(p => {
      const words = p.innerText.trim().split(/\s+/).filter(Boolean).length;
      if (words > 150) {
        p.classList.add('para-warning');
      } else {
        p.classList.remove('para-warning');
      }
    });
  }, []);

  const emitUpdate = useCallback(() => {
    if (editorRef.current) {
      const html = editorRef.current.innerHTML;
      lastContentEmitted.current = html;
      onUpdate(html);
      analyzeParagraphs();
    }
  }, [onUpdate, analyzeParagraphs]);

  // Expose Editor API to Parent
  useEffect(() => {
    if (editorRef.current) {
      editorRef.current.innerHTML = initialContent;
      lastContentEmitted.current = initialContent;

      const instance = {
        getContent: () => editorRef.current?.innerHTML || '',
        setContent: (html: string) => {
          if (editorRef.current) {
            editorRef.current.innerHTML = html;
            emitUpdate();
          }
        },
        execCommand: (cmd: string, ui: boolean, val: any) => {
          editorRef.current?.focus();
          document.execCommand(cmd, ui, val);
          emitUpdate();
        },
        insertContent: (html: string) => {
          editorRef.current?.focus();
          const sel = window.getSelection();
          if (sel && sel.rangeCount > 0) {
            const range = sel.getRangeAt(0);
            range.deleteContents();
            const el = document.createElement("div");
            el.innerHTML = html;
            const frag = document.createDocumentFragment();
            let node;
            while (node = el.firstChild) frag.appendChild(node);
            range.insertNode(frag);
            range.collapse(false);
            sel.removeAllRanges();
            sel.addRange(range);
          } else {
            editorRef.current!.innerHTML += html;
          }
          emitUpdate();
        },
        getSelection: () => {
          const sel = window.getSelection();
          return sel?.toString() || '';
        },
        scrollToText: (text: string) => {
          if (!editorRef.current) return;
          const walker = document.createTreeWalker(editorRef.current, NodeFilter.SHOW_TEXT);
          let node;
          while (node = walker.nextNode()) {
            if (node.textContent?.toLowerCase().includes(text.toLowerCase())) {
              (node.parentElement as HTMLElement)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
              break;
            }
          }
        }
      };
      onInit(instance);
      analyzeParagraphs();
    }
  }, [onInit, analyzeParagraphs]);

  useEffect(() => {
    if (editorRef.current && initialContent !== lastContentEmitted.current) {
      editorRef.current.innerHTML = initialContent;
      lastContentEmitted.current = initialContent;
      analyzeParagraphs();
    }
  }, [initialContent, analyzeParagraphs]);

  const handleInput = () => {
    emitUpdate();
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    setTimeout(() => {
      emitUpdate();
    }, 0);
  };

  return (
    <div className="relative h-full w-full group overflow-hidden flex flex-col">
      <div 
        ref={editorRef}
        contentEditable
        onInput={handleInput}
        onPaste={handlePaste}
        className="editor-content flex-1 w-full h-full custom-scrollbar overflow-y-auto outline-none select-text"
        spellCheck="true"
        aria-label="Content Editor"
      />
    </div>
  );
};

