export const EditorPage = () => {
  const { id } = useParams();

  // 1. Content State
  const [content, setContent] = useState(() => 
    localStorage.getItem(`seo-editor-content-${id || 'v2'}`) || 
    '<h1>Future of Content SEO</h1><p>Start crafting your optimized, AI-enhanced SEO content here. This editor analyzes your text in real-time to ensure maximum search visibility.</p>'
  );

  // 2. Editor & UI State
  const [activeTab, setActiveTab] = useState<Tab>('insights'); 
  const [wordTarget, setWordTarget] = useState(1000);
  const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [editorInstance, setEditorInstance] = useState<any>(null);

  // 3. SEO Metadata State
  const [metaTitle, setMetaTitle] = useState(() => localStorage.getItem(`seo-meta-title-${id || 'v2'}`) || '');
  const [metaDescription, setMetaDescription] = useState(() => localStorage.getItem(`seo-meta-desc-${id || 'v2'}`) || '');
  const [targets, setTargets] = useState<KeywordTarget>(() => {
    const saved = localStorage.getItem(`seo-targets-${id || 'v2'}`);
    return saved ? JSON.parse(saved) : { primary: '', secondary: ['', '', ''] };
  });
  const [faqs, setFaqs] = useState<FAQ[]>(() => {
    const saved = localStorage.getItem(`seo-faqs-${id || 'v2'}`);
    return saved ? JSON.parse(saved) : [];
  });

  const deferredContent = useDeferredValue(content);

  // Persistence
  useEffect(() => {
    const key = id || 'v2';
    localStorage.setItem(`seo-editor-content-${key}`, content);
    localStorage.setItem(`seo-targets-${key}`, JSON.stringify(targets));
    localStorage.setItem(`seo-meta-desc-${key}`, metaDescription);
    localStorage.setItem(`seo-meta-title-${key}`, metaTitle);
    localStorage.setItem(`seo-faqs-${key}`, JSON.stringify(faqs));
  }, [content, targets, metaDescription, metaTitle, faqs, id]);

  // Analysis Memoization
  const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
  const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
  const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
  const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, targets, metaDescription), [deferredContent, keywords, targets, metaDescription]);
  const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);

  const handleEditorChange = (newContent: string) => {
    startTransition(() => {
      setContent(newContent);
    });
  };

  const onRewrite = async (mode: RewriteMode) => {
    if (!editorInstance) return;
    const selectedText = editorInstance.getSelection();
    if (!selectedText) {
      alert("Please select text within the editor to use AI rewriting features.");
      return;
    }
    setIsAIProcessing(true);
    try {
      const results = await rewriteContent(selectedText, mode);
      if (results && results.length > 0) {
        editorInstance.insertContent(results[0]);
      }
    } catch (err) {
      console.error("AI Rewrite Failed:", err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  return (
    <div className="flex-1 flex flex-col min-w-0 bg-white overflow-hidden relative">
      {/* Internal Navigation Header */}
      <header className="h-16 border-b border-zinc-100 px-8 flex items-center justify-between bg-white shrink-0">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-black shadow-lg shadow-blue-500/20">S</div>
          <h1 className="font-black tracking-tighter text-lg uppercase">
            Document <span className="text-zinc-300 font-medium">{id ? `#${id}` : 'Editor'}</span>
          </h1>
        </div>
        <div className="flex items-center gap-4">
           <div className="flex items-center gap-2 px-3 py-1.5 bg-zinc-50 rounded-full border border-zinc-100">
              <div className={`w-2 h-2 rounded-full ${isAIProcessing ? 'bg-blue-500 animate-pulse' : 'bg-emerald-500'}`} />
              <span className="text-[10px] font-black uppercase tracking-widest text-zinc-500">
                {isAIProcessing ? 'AI Processing' : 'Engine Ready'}
              </span>
           </div>
        </div>
      </header>

      <div className="flex-1 flex flex-col overflow-hidden relative">
        <div className="toolbar-container bg-white border-b border-zinc-100">
          <Toolbar 
            editorInstance={editorInstance} 
            onUpdate={() => handleEditorChange(editorInstance?.getContent() || '')}
            onNewDocument={() => {
              if(confirm("Start a new document? All current content will be cleared.")) {
                editorInstance?.setContent('<h1>New Masterpiece</h1><p>Start writing...</p>');
              }
            }}
            onShowHistory={() => {}} 
            onSaveVersion={() => {}}
            viewMode="focused"
          />
        </div>

        <div className="flex flex-1 overflow-hidden">
          <main className="flex-1 bg-zinc-50/20 p-6 md:p-12 overflow-hidden flex justify-center relative">
            <div className="w-full max-w-4xl h-full border border-zinc-100 rounded-[40px] overflow-hidden bg-white shadow-2xl shadow-zinc-200/40 relative">
              <Editor 
                initialContent={content}
                onUpdate={handleEditorChange}
                onInit={setEditorInstance}
                onAIAssist={onRewrite}
              />
            </div>

            {/* Floating Word Counter */}
            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 bg-white/80 backdrop-blur-xl border border-zinc-100 rounded-full px-8 py-3.5 shadow-2xl flex items-center gap-6 z-40 transition-all hover:scale-105">
              <div className="flex flex-col">
                <span className="text-[9px] font-black text-zinc-400 uppercase tracking-widest mb-0.5">Progress</span>
                <div className="text-[11px] font-black text-zinc-800 uppercase tabular-nums">
                  {stats.words} <span className="text-zinc-300">/</span> {wordTarget} words
                </div>
              </div>
              <div className="w-24 h-1.5 bg-zinc-100 rounded-full overflow-hidden">
                <div 
                  className="h-full bg-blue-600 transition-all duration-700 ease-out" 
                  style={{ width: `${Math.min(100, (stats.words / wordTarget) * 100)}%` }} 
                />
              </div>
            </div>
          </main>

          {/* Analysis Sidebar Integration */}
          <Sidebar 
            activeTab={activeTab} 
            setActiveTab={setActiveTab} 
            stats={stats} 
            readability={readability} 
            health={health} 
            intent={intent} 
            keywords={keywords} 
            seoTab={seoTab} 
            setSeoTab={setSeoTab} 
            isExpanded={isExpanded} 
            setIsExpanded={setIsExpanded} 
            onRewrite={onRewrite} 
            onConvertCase={(type) => {
              const selected = editorInstance?.getSelection();
              if (selected) {
                editorInstance?.insertContent(convertText(selected, type));
              }
            }} 
            onCopy={(type) => {
              let output = content;
              if (type === 'markdown') output = htmlToMarkdown(content);
              else if (type === 'plain') output = content.replace(/<[^>]*>/g, '');
              navigator.clipboard.writeText(output);
            }} 
            onClear={() => {
              if(confirm("Delete all content?")) editorInstance?.setContent('');
            }} 
            isAIProcessing={isAIProcessing} 
            targets={targets} 
            setTargets={setTargets}
            metaTitle={metaTitle} 
            setMetaTitle={setMetaTitle} 
            metaDescription={metaDescription} 
            setMetaDescription={setMetaDescription}
            faqs={faqs} 
            setFaqs={setFaqs}
            onGenerateMetadata={async (type) => {
              setIsAIProcessing(true);
              try {
                const res = await generateMetadata(content, type);
                if (type === 'title') setMetaTitle(res); 
                else setMetaDescription(res);
              } catch (e) {
                console.error(e);
              } finally {
                setIsAIProcessing(false);
              }
            }}
            onDetectAI={async () => {
              setIsAIProcessing(true);
              try {
                const res = await detectAIContent(content);
                alert(`AI Detection Score: ${res.score}%`);
              } catch (e) {
                console.error(e);
              } finally {
                setIsAIProcessing(false);
              }
            }}
            onGenerateFAQs={async () => {
              setIsAIProcessing(true);
              try {
                const res = await generateFAQs(content);
                setFaqs(res);
              } catch (e) {
                console.error(e);
              } finally {
                setIsAIProcessing(false);
              }
            }}
            onExportSchema={() => {
              const schema = {
                "@context": "https://schema.org",
                "@type": "Article",
                "headline": metaTitle,
                "description": metaDescription
              };
              navigator.clipboard.writeText(JSON.stringify(schema, null, 2));
              alert('Copied Article Schema');
            }}
            onNavigateOutline={(text) => editorInstance?.scrollToText(text)}
          />
        </div>
      </div>
    </div>
  );
};

