/**
 * SEO Focus Pro - Analysis Module
 */

export const STOP_WORDS = new Set(['a', 'an', 'and', 'are', 'as', 'at', 'be', 'but', 'by', 'for', 'if', 'in', 'into', 'is', 'it', 'no', 'not', 'of', 'on', 'or', 'such', 'that', 'the', 'their', 'then', 'there', 'these', 'they', 'this', 'to', 'was', 'will', 'with', 'from', 'up', 'down', 'out', 'over', 'under']);

export function getStats(html) {
    const cleanText = html.replace(/<[^>]*>/g, ' ').trim();
    const words = cleanText ? cleanText.split(/\s+/).filter(Boolean) : [];
    const sentences = cleanText ? cleanText.split(/[.!?]+/).filter(Boolean) : [];

    return {
        words: words.length,
        sentences: sentences.length,
        readingTime: Math.ceil(words.length / 200),
        characters: cleanText.length
    };
}

export function getKeywords(html, n = 1) {
    const cleanText = html.replace(/<[^>]*>/g, ' ').toLowerCase();
    const tokens = cleanText.replace(/[^\w\s]/g, '').split(/\s+/).filter(t => t.length > 1);
    const totalTokens = tokens.length;
    if (totalTokens === 0) return [];

    const phrases = {};
    for (let i = 0; i <= tokens.length - n; i++) {
        const phraseWords = tokens.slice(i, i + n);
        if (phraseWords.some(word => STOP_WORDS.has(word))) continue;
        const phrase = phraseWords.join(' ');
        phrases[phrase] = (phrases[phrase] || 0) + 1;
    }

    return Object.entries(phrases)
        .map(([phrase, count]) => ({
            phrase,
            count,
            percentage: Number(((count * n) / totalTokens * 100).toFixed(2))
        }))
        .sort((a, b) => b.count - a.count);
}

const countSyllables = (word) => {
    word = word.toLowerCase().replace(/[^a-z]/g, '');
    if (word.length <= 3) return 1;
    word = word.replace(/(?:[^laeiouy]es|ed|[^laeiouy]e)$/, '');
    word = word.replace(/^y/, '');
    const syllables = word.match(/[aeiouy]{1,2}/g);
    return syllables ? syllables.length : 1;
};

export function getReadability(html) {
    const cleanText = html.replace(/<[^>]*>/g, ' ').trim();
    if (!cleanText) return { score: 0, level: 'Empty', color: 'text-zinc-400' };

    const sentences = cleanText.split(/[.!?]+/).filter(s => s.trim().length > 0);
    const words = cleanText.split(/\s+/).filter(w => w.length > 0);
    if (words.length === 0 || sentences.length === 0) return { score: 0, level: 'N/A', color: 'text-zinc-400' };

    const totalWords = words.length;
    const totalSentences = sentences.length;
    const totalSyllables = words.reduce((acc, word) => acc + countSyllables(word), 0);

    const ASL = totalWords / totalSentences;
    const ASW = totalSyllables / totalWords;
    const score = Math.round(206.835 - (1.015 * ASL) - (84.6 * ASW));
    const clamped = Math.max(0, Math.min(100, score));

    let level = 'Standard';
    let color = 'text-yellow-500';
    if (clamped >= 80) { level = 'Easy'; color = 'text-emerald-500'; }
    else if (clamped < 40) { level = 'Difficult'; color = 'text-red-500'; }

    return { score: clamped, level, color };
}

export function detectIntent(html) {
    const text = html.replace(/<[^>]*>/g, ' ').toLowerCase();
    if (text.includes('how to') || text.includes('guide')) return 'Informational';
    if (text.includes('best') || text.includes('vs')) return 'Commercial';
    if (text.includes('buy') || text.includes('price')) return 'Transactional';
    return 'Navigational';
}

