import { GoogleGenAI, Type } from "@google/genai";

// Initialize AI client using environment variable
const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export type RewriteMode = 
  | 'clarity' 
  | 'concise' 
  | 'expand_examples' 
  | 'add_stats' 
  | 'authoritative' 
  | 'humanize' 
  | 'remove_fluff' 
  | 'conversational' 
  | 'formal' 
  | 'active_voice'
  | 'expand'
  | 'shorten';

/**
 * Rewrites content using Gemini 3 Flash for speed and efficiency
 */
export const rewriteContent = async (text: string, mode: RewriteMode, customPrompt?: string): Promise<string[]> => {
  const ai = getAI();
  const modePrompts: Record<RewriteMode, string> = {
    clarity: "Rewrite the following text for maximum clarity, ensuring it's easy to follow while maintaining the original message.",
    concise: "Make the following text as concise as possible. Remove redundant words and shorten sentences without losing meaning.",
    expand_examples: "Expand the following content by adding relevant, illustrative examples that help clarify the points made.",
    add_stats: "Incorporate realistic (placeholder format like [X%]) statistics and data points into the text to boost its credibility.",
    authoritative: "Rewrite the text in an authoritative, expert tone. Use decisive language and establish high topical authority.",
    humanize: "Adjust the tone of the text to sound more human and less like a machine. Vary sentence length and use more natural expressions.",
    remove_fluff: "Identify and remove all 'filler' content, flowery adjectives, and unnecessary fluff from the following text.",
    conversational: "Rewrite the text in a friendly, conversational tone, as if talking directly to a peer.",
    formal: "Convert the following text into a professional, formal business tone suitable for corporate environments.",
    active_voice: "Convert all passive voice sentences in the following text into active voice for more direct and impactful writing.",
    expand: "Elaborate on the following text to provide more depth, detail, and context while maintaining the original tone.",
    shorten: "Drastically shorten the following text while preserving the core message and primary information."
  };

  const instruction = customPrompt || modePrompts[mode];

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `${instruction}\n\nProvide exactly TWO distinct and high-quality versions of the following text.\n\nText to process:\n"${text}"`,
    config: { 
      temperature: 0.8,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          options: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "An array of two distinct rewritten versions."
          }
        },
        required: ["options"]
      }
    }
  });

  try {
    const data = JSON.parse(response.text || '{"options": []}');
    return data.options || [];
  } catch (e) {
    console.error("Failed to parse AI options", e);
    return [text, text];
  }
};

/**
 * Generates metadata using AI
 */
export const generateMetadata = async (content: string, type: 'title' | 'description'): Promise<string> => {
  const ai = getAI();
  const prompt = type === 'title' 
    ? "Generate a compelling, SEO-optimized Meta Title (max 60 characters) for the following content. Return ONLY the title string, no markdown, no quotes."
    : "Generate a compelling, SEO-optimized Meta Description (max 160 characters) for the following content. Return ONLY the description string, no markdown, no quotes.";

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `${prompt}\n\nContent:\n${content.substring(0, 3000)}`,
    config: { temperature: 0.7 }
  });

  return response.text?.trim() || "";
};

/**
 * Generates FAQ Schema content
 */
export const generateFAQs = async (content: string): Promise<any[]> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Generate 5 relevant Frequently Asked Questions and detailed answers based on the following content. Provide the output in a clean JSON array of objects with 'question' and 'answer' keys. Content: ${content.substring(0, 4000)}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            question: { type: Type.STRING },
            answer: { type: Type.STRING }
          },
          required: ["question", "answer"]
        }
      }
    }
  });

  try {
    return JSON.parse(response.text || "[]");
  } catch (e) {
    console.error("Failed to parse FAQ JSON", e);
    return [];
  }
};

/**
 * Basic AI content pattern detection
 */
export const detectAIContent = async (text: string): Promise<{ score: number, analysis: string }> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Analyze the following text for AI-generated patterns (perplexity, burstiness, linguistic consistency). 
    Provide:
    1. A probability score (0-100) where 100 is definitely AI.
    2. A short 1-sentence explanation of why.

    Return in format: SCORE: [number] | REASON: [text]

    Text: "${text.substring(0, 2000)}"`,
    config: { temperature: 0.1 }
  });

  const raw = response.text || "SCORE: 0 | REASON: Analysis failed";
  const scoreMatch = raw.match(/SCORE:\s*(\d+)/i);
  const reasonMatch = raw.match(/REASON:\s*(.*)/i);

  return {
    score: scoreMatch ? parseInt(scoreMatch[1]) : 0,
    analysis: reasonMatch ? reasonMatch[1].trim() : "Unable to analyze content."
  };
};

import React, { useState, useEffect, useMemo, useDeferredValue, startTransition } from 'react';
import { useParams } from 'react-router-dom';

// Core Analysis Logic
import { getStats } from '../../core/text-analysis.ts';
import { getKeywords } from '../../core/keyword-density.ts';
import { getReadabilityScore } from '../../core/readability.ts';
import { analyzeSEOHealth } from '../../core/seo-health.ts';
import { detectIntent } from '../../core/intent-detector.ts';
import { convertText } from '../../core/case-converter.ts';

// AI Integration
import { 
  rewriteContent, 
  generateMetadata, 
  detectAIContent, 
  RewriteMode, 
  generateFAQs 
} from '../../ai/ai-engine.ts';

// Components
import { Toolbar } from '../../components/editor/Toolbar.tsx';
import { Sidebar } from '../../components/layout/Sidebar.tsx';
import { Editor } from '../../components/editor/Editor.tsx';
import { Tab, SEOPhraseTab, KeywordTarget, FAQ } from '../../types/editor.types.ts';
import { htmlToMarkdown } from '../../utils/text-cleaner.ts';

export const EditorPage = () => {
  const { id } = useParams();

  // 1. Content State - Persisted to LocalStorage
  const [content, setContent] = useState(() => 
    localStorage.getItem(`seo-editor-content-${id || 'default'}`) || 
    '<h1>Future of Content SEO</h1><p>Start crafting your optimized, AI-enhanced SEO content here. This editor analyzes your text in real-time to ensure maximum search visibility.</p>'
  );

  // 2. UI State
  const [activeTab, setActiveTab] = useState<Tab>('insights'); 
  const [wordTarget] = useState(1000);
  const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [editorInstance, setEditorInstance] = useState<any>(null);

  // 3. SEO Metadata State - Persisted to LocalStorage
  const [metaTitle, setMetaTitle] = useState(() => localStorage.getItem(`seo-meta-title-${id || 'default'}`) || '');
  const [metaDescription, setMetaDescription] = useState(() => localStorage.getItem(`seo-meta-desc-${id || 'default'}`) || '');
  const [targets, setTargets] = useState<KeywordTarget>(() => {
    const saved = localStorage.getItem(`seo-targets-${id || 'default'}`);
    return saved ? JSON.parse(saved) : { primary: '', secondary: ['', '', ''] };
  });
  const [faqs, setFaqs] = useState<FAQ[]>(() => {
    const saved = localStorage.getItem(`seo-faqs-${id || 'default'}`);
    return saved ? JSON.parse(saved) : [];
  });

  const deferredContent = useDeferredValue(content);

  // Autosave Effect
  useEffect(() => {
    const key = id || 'default';
    localStorage.setItem(`seo-editor-content-${key}`, content);
    localStorage.setItem(`seo-targets-${key}`, JSON.stringify(targets));
    localStorage.setItem(`seo-meta-desc-${key}`, metaDescription);
    localStorage.setItem(`seo-meta-title-${key}`, metaTitle);
    localStorage.setItem(`seo-faqs-${key}`, JSON.stringify(faqs));
  }, [content, targets, metaDescription, metaTitle, faqs, id]);

  // Real-time Analysis
  const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
  const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
  const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
  const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, targets, metaDescription), [deferredContent, keywords, targets, metaDescription]);
  const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);

  const handleEditorChange = (newContent: string) => {
    startTransition(() => {
      setContent(newContent);
    });
  };

  const onRewrite = async (mode: RewriteMode) => {
    if (!editorInstance) return;
    const selectedText = editorInstance.getSelection() || editorInstance.getContent().replace(/<[^>]*>/g, '');

    setIsAIProcessing(true);
    try {
      const results = await rewriteContent(selectedText, mode);
      if (results && results.length > 0) {
        // Simple heuristic: if something was selected, replace it. Otherwise, replace all.
        if (editorInstance.getSelection()) {
          editorInstance.insertContent(results[0]);
        } else {
          editorInstance.setContent(results[0]);
        }
      }
    } catch (err) {
      console.error("AI Rewrite Failed:", err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  return (
    <div className="flex-1 flex flex-col min-w-0 bg-white overflow-hidden relative">
      {/* Header */}
      <header className="h-16 border-b border-zinc-100 px-8 flex items-center justify-between bg-white shrink-0">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-black shadow-lg shadow-blue-500/20">S</div>
          <h1 className="font-black tracking-tighter text-lg uppercase">
            Workspace <span className="text-zinc-300 font-medium">{id ? `#${id}` : 'Live'}</span>
          </h1>
        </div>
        <div className="flex items-center gap-4">
           <div className="flex items-center gap-2 px-3 py-1.5 bg-zinc-50 rounded-full border border-zinc-100">
              <div className={`w-2 h-2 rounded-full ${isAIProcessing ? 'bg-blue-500 animate-pulse' : 'bg-emerald-500'}`} />
              <span className="text-[10px] font-black uppercase tracking-widest text-zinc-500">
                {isAIProcessing ? 'AI Processing' : 'Engine Ready'}
              </span>
           </div>
        </div>
      </header>

      <div className="flex-1 flex flex-col overflow-hidden relative">
        <div className="toolbar-container bg-white border-b border-zinc-100">
          <Toolbar 
            editorInstance={editorInstance} 
            onUpdate={() => handleEditorChange(editorInstance?.getContent() || '')}
            onNewDocument={() => {
              if(confirm("Start a new document? All current content will be cleared.")) {
                editorInstance?.setContent('<h1>New Masterpiece</h1><p>Start writing...</p>');
              }
            }}
            onShowHistory={() => {}} 
            onSaveVersion={() => {}}
            viewMode="focused"
          />
        </div>

        <div className="flex flex-1 overflow-hidden">
          <main className="flex-1 bg-zinc-50/20 p-6 md:p-12 overflow-hidden flex justify-center relative">
            <div className="w-full max-w-4xl h-full border border-zinc-100 rounded-[40px] overflow-hidden bg-white shadow-2xl shadow-zinc-200/40 relative">
              <Editor 
                initialContent={content}
                onUpdate={handleEditorChange}
                onInit={setEditorInstance}
                onAIAssist={onRewrite}
              />
            </div>

            {/* Floating Word Counter */}
            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 bg-white/80 backdrop-blur-xl border border-zinc-100 rounded-full px-8 py-3.5 shadow-2xl flex items-center gap-6 z-40 transition-all hover:scale-105">
              <div className="flex flex-col">
                <span className="text-[9px] font-black text-zinc-400 uppercase tracking-widest mb-0.5">Progress</span>
                <div className="text-[11px] font-black text-zinc-800 uppercase tabular-nums">
                  {stats.words} <span className="text-zinc-300">/</span> {wordTarget} words
                </div>
              </div>
              <div className="w-24 h-1.5 bg-zinc-100 rounded-full overflow-hidden">
                <div 
                  className="h-full bg-blue-600 transition-all duration-700 ease-out" 
                  style={{ width: `${Math.min(100, (stats.words / wordTarget) * 100)}%` }} 
                />
              </div>
            </div>
          </main>

          <Sidebar 
            activeTab={activeTab} 
            setActiveTab={setActiveTab} 
            stats={stats} 
            readability={readability} 
            health={health} 
            intent={intent} 
            keywords={keywords} 
            seoTab={seoTab} 
            setSeoTab={setSeoTab} 
            isExpanded={isExpanded} 
            setIsExpanded={setIsExpanded} 
            onRewrite={onRewrite} 
            onConvertCase={(type) => {
              const selected = editorInstance?.getSelection();
              if (selected) {
                editorInstance?.insertContent(convertText(selected, type));
              }
            }} 
            onCopy={(type) => {
              let output = content;
              if (type === 'markdown') output = htmlToMarkdown(content);
              else if (type === 'plain') output = content.replace(/<[^>]*>/g, '');
              navigator.clipboard.writeText(output);
            }} 
            onClear={() => {
              if(confirm("Delete all content?")) editorInstance?.setContent('');
