import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export type RewriteMode = 
  | 'clarity' 
  | 'concise' 
  | 'expand_examples' 
  | 'add_stats' 
  | 'authoritative' 
  | 'humanize' 
  | 'remove_fluff' 
  | 'conversational' 
  | 'formal' 
  | 'active_voice'
  | 'expand'
  | 'shorten';

export const rewriteContent = async (text: string, mode: RewriteMode, customPrompt?: string): Promise<string[]> => {
  const ai = getAI();
  const modePrompts: Record<RewriteMode, string> = {
    clarity: "Rewrite for maximum clarity.",
    concise: "Shorten and simplify.",
    expand_examples: "Add illustrative examples.",
    add_stats: "Include realistic data points.",
    authoritative: "Make it sound expert and authoritative.",
    humanize: "Adjust tone to sound more natural and human.",
    remove_fluff: "Remove all filler words.",
    conversational: "Make it friendly and direct.",
    formal: "Professional business tone.",
    active_voice: "Use active voice throughout.",
    expand: "Provide more depth and context.",
    shorten: "Drastically shorten."
  };

  const instruction = customPrompt || modePrompts[mode];

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `${instruction}\n\nProvide two distinct versions.\n\nText:\n"${text}"`,
    config: { 
      temperature: 0.8,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          options: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["options"]
      }
    }
  });

  try {
    const data = JSON.parse(response.text || '{"options": []}');
    return data.options || [];
  } catch (e) {
    return [text, text];
  }
};

export const generateMetadata = async (content: string, type: 'title' | 'description'): Promise<string> => {
  const ai = getAI();
  const prompt = type === 'title' 
    ? "Generate an SEO title (max 60 chars)."
    : "Generate an SEO meta description (max 160 chars).";

  const response = await ai.models.generateContent({
