import { GoogleGenAI, Type } from "@google/genai";

// Initialize the Google GenAI client
const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export type RewriteMode = 
  | 'clarity' 
  | 'concise' 
  | 'expand_examples' 
  | 'add_stats' 
  | 'authoritative' 
  | 'humanize' 
  | 'remove_fluff' 
  | 'conversational' 
  | 'formal' 
  | 'active_voice'
  | 'expand'
  | 'shorten';

/**
 * Rewrites content using Gemini for high-performance content optimization.
 */
export const rewriteContent = async (text: string, mode: RewriteMode, customPrompt?: string): Promise<string[]> => {
  const ai = getAI();
  const modePrompts: Record<RewriteMode, string> = {
    clarity: "Rewrite the following text for maximum clarity, ensuring it's easy to follow while maintaining the original message.",
    concise: "Make the following text as concise as possible. Remove redundant words and shorten sentences without losing meaning.",
    expand_examples: "Expand the following content by adding relevant, illustrative examples that help clarify the points made.",
    add_stats: "Incorporate realistic statistics and data points into the text to boost its credibility.",
    authoritative: "Rewrite the text in an authoritative, expert tone. Use decisive language.",
    humanize: "Adjust the tone of the text to sound more human and less like a machine. Vary sentence length.",
    remove_fluff: "Identify and remove all 'filler' content and unnecessary fluff from the following text.",
    conversational: "Rewrite the text in a friendly, conversational tone.",
    formal: "Convert the following text into a professional, formal business tone.",
    active_voice: "Convert all passive voice sentences in the following text into active voice.",
    expand: "Elaborate on the following text to provide more depth, detail, and context.",
    shorten: "Drastically shorten the following text while preserving the core message."
  };

  const instruction = customPrompt || modePrompts[mode];

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `${instruction}\n\nProvide TWO distinct and high-quality versions of the following text.\n\nText to process:\n"${text}"`,
    config: { 
      temperature: 0.8,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          options: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "An array containing two rewritten versions."
          }
        },
        required: ["options"]
      }
    }
  });

  try {
    const data = JSON.parse(response.text || '{"options": []}');
    return data.options || [];
  } catch (e) {
    console.error("AI Parse Error:", e);
    return [text, text];
  }
};

