import { GoogleGenAI, Type } from "@google/genai";

export type RewriteMode = 
  | 'clarity' 
  | 'concise' 
  | 'expand_examples' 
  | 'add_stats' 
  | 'authoritative' 
  | 'humanize' 
  | 'remove_fluff' 
  | 'conversational' 
  | 'formal' 
  | 'active_voice'
  | 'expand'
  | 'shorten';

/**
 * Rewrites content using Gemini for high-performance content optimization.
 */
export const rewriteContent = async (text: string, mode: RewriteMode, customPrompt?: string): Promise<string[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const modePrompts: Record<RewriteMode, string> = {
    clarity: "Rewrite for maximum clarity and ease of reading.",
    concise: "Shorten and simplify this text while retaining the core message.",
    expand_examples: "Add relevant examples to illustrate the points made in this text.",
    add_stats: "Include realistic data points and statistics to back up the claims.",
    authoritative: "Make the tone expert and authoritative.",
    humanize: "Adjust tone to sound natural, human, and engaging. Vary sentence structure.",
    remove_fluff: "Remove filler words and redundant phrasing.",
    conversational: "Make it friendly, direct, and conversational.",
    formal: "Convert to a professional business tone.",
    active_voice: "Convert passive voice sentences into active voice.",
    expand: "Provide more depth, detail, and context for these points.",
    shorten: "Drastically shorten this text while keeping its essence."
  };

  const instruction = customPrompt || modePrompts[mode];

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [{ 
      role: "user", 
      parts: [{ text: `${instruction}\n\nProvide TWO distinct high-quality versions in JSON format.\n\nText:\n"${text}"` }] 
    }],
    config: { 
      temperature: 0.8,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          options: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["options"]
      }
    }
  });

  try {
    const data = JSON.parse(response.text || '{"options": []}');
    return data.options || [];
  } catch (e) {
    console.error("Failed to parse AI response", e);
    return [text, text];
  }
};

/**
 * Generates SEO metadata.
 */
export const generateMetadata = async (content: string, type: 'title' | 'description'): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const prompt = type === 'title' 
    ? "Generate an SEO title (max 60 chars) that is compelling and relevant. Return as plain text."
    : "Generate an SEO meta description (max 160 chars) that encourages clicks. Return as plain text.";

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [{ 
      role: "user", 
      parts: [{ text: `${prompt}\n\nContent:\n${content.substring(0, 3000)}` }] 
    }]
  });

  return response.text?.trim() || "";
};

