 */
export const generateFAQs = async (content: string): Promise<any[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [{ 
      role: "user", 
      parts: [{ text: `Generate 5 relevant Frequently Asked Questions and answers based on this content. Return as JSON array.\n\nContent: ${content.substring(0, 4000)}` }] 
    }],
    config: {
      responseMimeType: "application/json",
