/**
 * Detects AI-generated content patterns.
 */
export const detectAIContent = async (text: string): Promise<{ score: number, analysis: string }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [{ 
      role: "user", 
      parts: [{ text: `Analyze this text for patterns typical of AI-generated content. Provide a probability score (0-100) and a brief reason. Format the text as 'SCORE: [number] | REASON: [text]'.\n\nText: "${text.substring(0, 2000)}"` }] 
    }]
  });

  const raw = response.text || "SCORE: 0 | REASON: Analysis unavailable.";
  const scoreMatch = raw.match(/SCORE:\s*(\d+)/i);
  const reasonMatch = raw.match(/REASON:\s*(.*)/i);

  return {
    score: scoreMatch ? parseInt(scoreMatch[1]) : 0,
    analysis: reasonMatch ? reasonMatch[1].trim() : "Unable to analyze text."
  };
};

