import { TextStats, HeadingNode } from '../types/editor.types.ts';

export const getStats = (html: string): TextStats => {
  const cleanText = html.replace(/<[^>]*>/g, ' ').trim();
  const words = cleanText ? cleanText.split(/\s+/) : [];
  const sentences = cleanText ? cleanText.split(/[.!?]+/).filter(Boolean) : [];

  const wordCount = words.length;
  const pubWords = Math.ceil(cleanText.length / 6);
  const paragraphsCount = cleanText ? html.split(/<\/p>|<div>/i).filter(p => p.replace(/<[^>]*>/g, '').trim().length > 0).length : 0;

  // Entity detection (Simple heuristic: capitalized words not at start of sentence)
  const entities = extractEntities(cleanText);

  // Heading tree extraction
  const headingTree = extractHeadingTree(html);

  return {
    words: wordCount,
    pubWords: pubWords,
    sentences: sentences.length,
    characters: cleanText.length,
    readingTime: Math.ceil(wordCount / 200),
    speakingTime: Math.ceil(wordCount / 130),
    paragraphs: paragraphsCount || (cleanText ? 1 : 0),
    entities,
    headingTree
  };
};

const extractEntities = (text: string): string[] => {
  // Regex for capitalized words. Avoid first words of sentences roughly.
  // This is a browser-side approximation.
  const words = text.split(/\s+/);
  const detected = new Set<string>();
  const commonExclusions = new Set(['The', 'A', 'An', 'This', 'That', 'These', 'Those', 'It', 'My', 'Your', 'His', 'Her', 'Our', 'They', 'And', 'But', 'Or', 'If']);

  for (let i = 1; i < words.length; i++) {
    const word = words[i].replace(/[^\w]/g, '');
    if (word.length > 2 && /^[A-Z]/.test(word) && !commonExclusions.has(word)) {
      detected.add(word);
    }
  }
  return Array.from(detected).slice(0, 15);
};

const extractHeadingTree = (html: string): HeadingNode[] => {
  const parser = new DOMParser();
  const doc = parser.parseFromString(html, 'text/html');
  const headings = doc.querySelectorAll('h1, h2, h3, h4, h5, h6');
  return Array.from(headings).map(h => ({
    tag: h.tagName.toLowerCase(),
    text: h.textContent?.trim() || 'Empty Heading',
    level: parseInt(h.tagName.substring(1))
  }));
};

import { KeywordDensity } from '../types/editor.types.ts';
import { STOP_WORDS } from './stopwords.ts';

export const getKeywords = (html: string, n: number = 1): KeywordDensity[] => {
  const cleanText = html.replace(/<[^>]*>/g, ' ').toLowerCase();
  // Filter out punctuation and very short words, then tokenize
  const tokens = cleanText.replace(/[^\w\s]/g, '').split(/\s+/).filter(t => t.length > 1);
  const totalTokens = tokens.length;

  if (totalTokens === 0) return [];

  const phrases: Record<string, number> = {};

  for (let i = 0; i <= tokens.length - n; i++) {
    const phraseWords = tokens.slice(i, i + n);

    // Skip the phrase if it contains any stop word
    if (phraseWords.some(word => STOP_WORDS.has(word))) {
      continue;
    }

    const phrase = phraseWords.join(' ');
    phrases[phrase] = (phrases[phrase] || 0) + 1;
  }

  return Object.entries(phrases)
    .map(([phrase, count]) => ({
      phrase,
      count,
      percentage: Number(((count * n) / totalTokens * 100).toFixed(2))
    }))
    .sort((a, b) => b.count - a.count);
};

import { ReadabilityInsights } from '../types/editor.types.ts';

const countSyllables = (word: string): number => {
  word = word.toLowerCase().replace(/[^a-z]/g, '');
  if (word.length <= 3) return 1;
  word = word.replace(/(?:[^laeiouy]es|ed|[^laeiouy]e)$/, '');
  word = word.replace(/^y/, '');
  const syllables = word.match(/[aeiouy]{1,2}/g);
  return syllables ? syllables.length : 1;
};

export const getReadabilityScore = (html: string): ReadabilityInsights | null => {
  const cleanText = html.replace(/<[^>]*>/g, ' ').trim();
  if (!cleanText) return null;

  const sentences = cleanText.split(/[.!?]+/).filter(s => s.trim().length > 0);
  const words = cleanText.split(/\s+/).filter(w => w.length > 0);

  if (words.length === 0 || sentences.length === 0) return null;

  const totalWords = words.length;
  const totalSentences = sentences.length;
  const totalSyllables = words.reduce((acc, word) => acc + countSyllables(word), 0);

  const ASL = totalWords / totalSentences;
  const ASW = totalSyllables / totalWords;

  // Flesch Reading Ease Formula
  const score = Math.round(206.835 - (1.015 * ASL) - (84.6 * ASW));
  const clampedScore = Math.max(0, Math.min(100, score));

  let level = '';
  let color = '';
  let description = '';

  if (clampedScore >= 90) { level = 'Very Easy'; color = 'text-emerald-500'; description = '5th grade level. Easily understood by an average 11-year-old.'; }
  else if (clampedScore >= 80) { level = 'Easy'; color = 'text-emerald-400'; description = '6th grade level. Conversational English for consumers.'; }
  else if (clampedScore >= 70) { level = 'Fairly Easy'; color = 'text-green-400'; description = '7th grade level.'; }
  else if (clampedScore >= 60) { level = 'Standard'; color = 'text-yellow-400'; description = '8th & 9th grade level. Plain English understood by 13-15 year olds.'; }
  else if (clampedScore >= 50) { level = 'Fairly Difficult'; color = 'text-orange-400'; description = 'High school level.'; }
  else if (clampedScore >= 30) { level = 'Difficult'; color = 'text-red-400'; description = 'College level. Best understood by university graduates.'; }
  else { level = 'Very Confusing'; color = 'text-red-600'; description = 'Extremely difficult to read. Best understood by professionals.'; }

  let hardSentences = 0;
  let veryHardSentences = 0;
  sentences.forEach(s => {
    const wordCount = s.trim().split(/\s+/).length;
    if (wordCount > 25) veryHardSentences++;
    else if (wordCount > 18) hardSentences++;
  });

  return {
    score: clampedScore,
    level,
    color,
    description,
    hardSentences,
    veryHardSentences
  };
};

import { SEOHealth, KeywordDensity, SEOChecklistItem, KeywordTarget } from '../types/editor.types.ts';

export const analyzeSEOHealth = (
  html: string, 
  keywords: KeywordDensity[], 
  targets: KeywordTarget,
  metaDescription: string
): SEOHealth => {
  const warnings: string[] = [];
  const checklist: SEOChecklistItem[] = [];
  let score = 100;

  const cleanText = html.replace(/<[^>]*>/g, ' ').trim();
  const first100Words = cleanText.split(/\s+/).slice(0, 100).join(' ').toLowerCase();
  const primaryK = targets.primary.toLowerCase();

  // 1. Primary Keyword Checks
  if (primaryK) {
    // In H1
    const h1Match = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
    const hasInH1 = h1Match ? h1Match[1].toLowerCase().includes(primaryK) : false;
    checklist.push({ label: `Primary keyword in H1`, passed: hasInH1, impact: 'critical' });
    if (!hasInH1) score -= 15;

    // In First 100 words
    const hasInIntro = first100Words.includes(primaryK);
    checklist.push({ label: `Primary keyword in intro (first 100 words)`, passed: hasInIntro, impact: 'moderate' });
    if (!hasInIntro) score -= 10;

    // In Meta Description
    const hasInMeta = metaDescription.toLowerCase().includes(primaryK);
    checklist.push({ label: `Primary keyword in meta description`, passed: hasInMeta, impact: 'moderate' });
    if (!hasInMeta) score -= 10;

    // In at least one H2
    // Added explicit string[] type to avoid 'never[]' inference on empty array fallback
    const h2Matches: string[] = html.match(/<h2[^>]*>([\s\S]*?)<\/h2>/gi) || [];
    const hasInH2 = h2Matches.some(h => h.toLowerCase().includes(primaryK));
    checklist.push({ label: `Primary keyword in at least one H2`, passed: hasInH2, impact: 'moderate' });
    if (!hasInH2) score -= 5;
  }

  // 2. Structural Checks
  const h1Count = (html.match(/<h1/gi) || []).length;
  if (h1Count === 0) { warnings.push("Missing H1 title tag."); score -= 20; }
  if (h1Count > 1) { warnings.push("Multiple H1 tags detected."); score -= 15; }

  const h2Count = (html.match(/<h2/gi) || []).length;
  const h3Count = (html.match(/<h3/gi) || []).length;
  if (h2Count === 0 && h3Count === 0) { warnings.push("Lack of sub-heading structure (H2/H3)."); score -= 10; }

  // 3. Keyword Stuffing
  const overUsed = keywords.filter(k => k.percentage > 3);
  if (overUsed.length > 0) {
    warnings.push(`Keyword stuffing detected: "${overUsed[0].phrase}".`);
    score -= 15;
  }

  // 4. Content Length
  const wordCount = cleanText.split(/\s+/).length;
  if (wordCount < 300) { warnings.push("Content is thin (<300 words)."); score -= 15; }

  score = Math.max(0, score);

  let status: SEOHealth['status'] = 'excellent';
  if (score < 50) status = 'poor';
  else if (score < 70) status = 'fair';
  else if (score < 90) status = 'good';

  return { score, warnings, status, checklist };
};

import { IntentResult } from '../types/editor.types.ts';

const INTENT_PATTERNS = {
  Informational: ['how to', 'guide', 'tutorial', 'tips', 'what is', 'meaning', 'why', 'history', 'example'],
  Commercial: ['best', 'top', 'review', 'comparison', 'vs', 'affordable', 'reliable', 'alternative'],
  Transactional: ['buy', 'price', 'discount', 'order', 'coupon', 'sale', 'checkout', 'get'],
  Navigational: ['login', 'official', 'homepage', 'contact', 'support', 'signin', 'account']
};

export const detectIntent = (html: string): IntentResult => {
  const text = html.replace(/<[^>]*>/g, ' ').toLowerCase();
  const scores: Record<string, number> = { Informational: 0, Commercial: 0, Transactional: 0, Navigational: 0 };
  const signals: string[] = [];

  Object.entries(INTENT_PATTERNS).forEach(([intent, patterns]) => {
    patterns.forEach(pattern => {
      const regex = new RegExp(`\\b${pattern}\\b`, 'g');
      const matches = (text.match(regex) || []).length;
      if (matches > 0) {
        scores[intent] += matches;
        signals.push(pattern);
      }
    });
  });

  const sorted = Object.entries(scores).sort((a, b) => b[1] - a[1]);
  const primary = (sorted[0][1] > 0 ? sorted[0][0] : 'Informational') as IntentResult['primary'];

  const totalScore = Object.values(scores).reduce((a, b) => a + b, 0);
  const confidence = totalScore > 0 ? Math.min(100, Math.round((sorted[0][1] / totalScore) * 100)) : 50;

  return { primary, confidence, signals: Array.from(new Set(signals)).slice(0, 5) };
};

