import React, { useState, useEffect, useMemo, useDeferredValue, startTransition } from 'react';
import { useParams } from 'react-router-dom';

// Core Analysis Logic
import { getStats } from '../../core/text-analysis.ts';
import { getKeywords } from '../../core/keyword-density.ts';
import { getReadabilityScore } from '../../core/readability.ts';
import { analyzeSEOHealth } from '../../core/seo-health.ts';
import { detectIntent } from '../../core/intent-detector.ts';
import { convertText } from '../../core/case-converter.ts';

// AI Integration
import { 
  rewriteContent, 
  generateMetadata, 
  detectAIContent, 
  RewriteMode, 
  generateFAQs 
} from '../../ai/ai-engine.ts';

// Components
import { Toolbar } from '../../components/editor/Toolbar.tsx';
import { Sidebar } from '../../components/layout/Sidebar.tsx';
import { Editor } from '../../components/editor/Editor.tsx';
import { Tab, SEOPhraseTab, KeywordTarget, FAQ } from '../../types/editor.types.ts';
import { htmlToMarkdown } from '../../utils/text-cleaner.ts';

export const EditorPage = () => {
  const { id } = useParams();
  const currentId = id || 'draft';

  // 1. Content State - Persisted to LocalStorage
  const [content, setContent] = useState(() => 
    localStorage.getItem(`seo-editor-content-${currentId}`) || 
    '<h1>Content SEO Intelligence</h1><p>Start writing your optimized content here. The AI engine analyzes your text in real-time...</p>'
  );

  // 2. UI State
  const [activeTab, setActiveTab] = useState<Tab>('insights'); 
  const [wordTarget] = useState(1500);
  const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [editorInstance, setEditorInstance] = useState<any>(null);

  // 3. SEO Metadata State
  const [metaTitle, setMetaTitle] = useState(() => localStorage.getItem(`seo-meta-title-${currentId}`) || '');
  const [metaDescription, setMetaDescription] = useState(() => localStorage.getItem(`seo-meta-desc-${currentId}`) || '');
  const [targets, setTargets] = useState<KeywordTarget>(() => {
    const saved = localStorage.getItem(`seo-targets-${currentId}`);
    return saved ? JSON.parse(saved) : { primary: '', secondary: ['', '', ''] };
  });
  const [faqs, setFaqs] = useState<FAQ[]>(() => {
    const saved = localStorage.getItem(`seo-faqs-${currentId}`);
    return saved ? JSON.parse(saved) : [];
  });

  const deferredContent = useDeferredValue(content);

  // Autosave
  useEffect(() => {
    localStorage.setItem(`seo-editor-content-${currentId}`, content);
    localStorage.setItem(`seo-targets-${currentId}`, JSON.stringify(targets));
    localStorage.setItem(`seo-meta-desc-${currentId}`, metaDescription);
    localStorage.setItem(`seo-meta-title-${currentId}`, metaTitle);
    localStorage.setItem(`seo-faqs-${currentId}`, JSON.stringify(faqs));
  }, [content, targets, metaDescription, metaTitle, faqs, currentId]);

  // Real-time Analysis
  const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
  const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
  const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
  const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, targets, metaDescription), [deferredContent, keywords, targets, metaDescription]);
  const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);

  const handleEditorChange = (newContent: string) => {
    startTransition(() => {
      setContent(newContent);
    });
  };

  const onRewrite = async (mode: RewriteMode) => {
    if (!editorInstance) return;
    const selectedText = editorInstance.getSelection() || editorInstance.getContent().replace(/<[^>]*>/g, '');
    if (!selectedText) {
      alert("Please write or select some text first.");
      return;
    }

    setIsAIProcessing(true);
    try {
      const results = await rewriteContent(selectedText, mode);
      if (results && results.length > 0) {
        if (editorInstance.getSelection()) {
          editorInstance.insertContent(results[0]);
        } else {
          editorInstance.setContent(results[0]);
        }
      }
    } catch (err) {
      console.error("AI Rewrite Failed:", err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleGenerateMetadata = async (type: 'title' | 'description') => {
    setIsAIProcessing(true);
    try {
        const result = await generateMetadata(content, type);
        if (type === 'title') setMetaTitle(result);
        else setMetaDescription(result);
    } catch (error) {
        console.error("Metadata generation failed", error);
    } finally {
        setIsAIProcessing(false);
    }
  };

  const handleDetectAI = async () => {
    setIsAIProcessing(true);
    try {
        const result = await detectAIContent(content);
        alert(`AI Probability Score: ${result.score}%\nAnalysis: ${result.analysis}`);
    } catch (error) {
        console.error("AI detection failed", error);
    } finally {
        setIsAIProcessing(false);
    }
  };

  const handleGenerateFAQs = async () => {
      setIsAIProcessing(true);
      try {
          const result = await generateFAQs(content);
          setFaqs(result);
      } catch (error) {
          console.error("FAQ generation failed", error);
      } finally {
          setIsAIProcessing(false);
      }
  };

  const handleConvertCase = (type: string) => {
      if(!editorInstance) return;
      const selection = editorInstance.getSelection();
      if(selection) {
          const converted = convertText(selection, type);
          editorInstance.insertContent(converted);
      } else {
          alert("Please select text to convert.");
      }
  };

  const handleCopy = (type: 'plain' | 'markdown' | 'html') => {
      let textToCopy = content;
      if (type === 'plain') textToCopy = content.replace(/<[^>]*>/g, ' ');
      if (type === 'markdown') textToCopy = htmlToMarkdown(content);

      navigator.clipboard.writeText(textToCopy).then(() => {
          alert("Copied to clipboard!");
      });
  };

  const handleClear = () => {
      if(confirm("Are you sure you want to clear the document?")) {
          setContent("");
          if(editorInstance) editorInstance.setContent("");
      }
  };

  const handleExportSchema = () => {
    const schema = {
      "@context": "https://schema.org",
      "@type": "Article",
      "headline": metaTitle,
      "description": metaDescription,
      "articleBody": content.replace(/<[^>]*>/g, ' '),
      "wordCount": stats.words,
      "faq": faqs.map(f => ({
        "@type": "Question",
        "name": f.question,
        "acceptedAnswer": {
          "@type": "Answer",
          "text": f.answer
        }
      }))
    };

    const blob = new Blob([JSON.stringify(schema, null, 2)], {type: "application/json"});
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "schema.json";
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="flex h-screen w-screen flex-col bg-white overflow-hidden">
      {/* App Header */}
      <header className="h-14 border-b border-zinc-100 px-6 flex items-center justify-between bg-white shrink-0 z-20">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-black shadow-lg shadow-blue-500/20">S</div>
          <h1 className="font-black tracking-tighter text-lg uppercase text-zinc-900">
            SEO Focus <span className="text-zinc-300 mx-2">|</span> <span className="text-zinc-500 font-medium normal-case tracking-normal">Editor</span>
          </h1>
        </div>

        <div className="flex items-center gap-6">
           {/* Status Indicator */}
           <div className="flex items-center gap-2">
              <div className={`w-1.5 h-1.5 rounded-full ${isAIProcessing ? 'bg-blue-500 animate-pulse' : 'bg-emerald-500'}`} />
              <span className="text-[10px] font-bold uppercase tracking-widest text-zinc-400">
                {isAIProcessing ? 'AI Processing' : 'Live Analysis'}
              </span>
           </div>

           <button 
             onClick={() => {
                const schema = {
                  "@context": "https://schema.org",
                  "@type": "Article",
                  "headline": metaTitle || "Untitled Article",
                  "articleBody": content.replace(/<[^>]*>/g, ' '),
                  "wordCount": stats.words
                };
                console.log(schema);
                alert("Document synced to local storage.");
             }}
             className="bg-zinc-900 text-white px-5 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest hover:bg-black transition-all"
           >
             Save
           </button>
        </div>
      </header>

      {/* Main Workspace */}
      <div className="flex flex-1 overflow-hidden relative">
        <div className="flex-1 flex flex-col min-w-0 bg-white relative">
            <div className="toolbar-container bg-white/80 backdrop-blur-md border-b border-zinc-100 z-10">
              <Toolbar 
                editorInstance={editorInstance} 
                onUpdate={() => handleEditorChange(editorInstance?.getContent() || '')}
                onNewDocument={() => {
                  if(confirm("Start new document? Unsaved changes will be lost.")) {
                      setContent("");
                      if(editorInstance) editorInstance.setContent("");
                  }
                }}
                onShowHistory={() => {}}
                onSaveVersion={() => {}}
                viewMode="edit"
              />
            </div>
            <Editor 
                initialContent={content} 
                onUpdate={handleEditorChange} 
                onInit={setEditorInstance} 
                onAIAssist={onRewrite}
            />
        </div>

        {/* Sidebar */}
        <Sidebar 
            activeTab={activeTab}
            setActiveTab={setActiveTab}
            stats={stats}
            readability={readability}
            health={health}
            intent={intent}
            keywords={keywords}
            seoTab={seoTab}
            setSeoTab={setSeoTab}
            isExpanded={isExpanded}
            setIsExpanded={setIsExpanded}
            onRewrite={onRewrite}
            onConvertCase={handleConvertCase}
            onCopy={handleCopy}
            onClear={handleClear}
            isAIProcessing={isAIProcessing}
            targets={targets}
            setTargets={setTargets}
            metaTitle={metaTitle}
            setMetaTitle={setMetaTitle}
            metaDescription={metaDescription}
            setMetaDescription={setMetaDescription}
            faqs={faqs}
            setFaqs={setFaqs}
            onGenerateMetadata={handleGenerateMetadata}
            onDetectAI={handleDetectAI}
            onGenerateFAQs={handleGenerateFAQs}
            onExportSchema={handleExportSchema}
            onNavigateOutline={(text) => editorInstance?.scrollToText(text)}
        />
      </div>
    </div>
  );
};

