             </button>

             {showDocMenu && (
                 <div className="absolute top-full left-0 mt-2 w-72 bg-white border border-zinc-200 rounded-2xl shadow-xl overflow-hidden flex flex-col animate-in fade-in zoom-in-95 duration-200">
                     <div className="p-3 border-b border-zinc-50 flex items-center justify-between bg-zinc-50/50">
                         <span className="text-[10px] font-black uppercase text-zinc-400 tracking-widest">My Documents</span>
                         <button onClick={handleCreateNew} className="text-blue-600 hover:bg-blue-50 p-1.5 rounded-lg transition-colors" title="New Draft">
                             <Plus size={16} />
                         </button>
                     </div>
                     <div className="max-h-[300px] overflow-y-auto custom-scrollbar p-2 space-y-1">
                         {savedDocs.length === 0 && <div className="text-xs text-zinc-400 p-4 text-center italic">No saved drafts</div>}
                         {savedDocs.map(doc => (
                             <div 
                                key={doc.id} 
                                onClick={() => { navigate(`/editor/${doc.id}`); setShowDocMenu(false); }}
                                className={`group flex items-center justify-between p-2.5 rounded-xl cursor-pointer transition-colors ${currentId === doc.id ? 'bg-blue-50 text-blue-700' : 'hover:bg-zinc-50 text-zinc-600'}`}
                             >
                                 <div className="flex items-center gap-3 overflow-hidden">
                                     <FileText size={14} className="shrink-0 opacity-50"/>
                                     <span className="text-xs font-bold truncate">{doc.title}</span>
                                 </div>
                                 {currentId !== doc.id && (
                                     <button onClick={(e) => handleDeleteDoc(doc.id, e)} className="opacity-0 group-hover:opacity-100 text-zinc-400 hover:text-red-500 p-1 transition-all">
                                         <Trash2 size={12}/>
                                     </button>
                                 )}
                                 {currentId === doc.id && <Check size={12} className="shrink-0"/>}
                             </div>
                         ))}
                     </div>
                 </div>
             )}
          </div>
        </div>

        <div className="flex items-center gap-6">
           {/* Status Indicator */}
           <div className="flex items-center gap-2">
              <div className={`w-1.5 h-1.5 rounded-full ${isAIProcessing ? 'bg-blue-500 animate-pulse' : 'bg-emerald-500'}`} />
              <span className="text-[10px] font-bold uppercase tracking-widest text-zinc-400">
                {isAIProcessing ? 'AI Processing' : 'Live Analysis'}
              </span>
           </div>

           <button 
             onClick={() => {
                const schema = {
                  "@context": "https://schema.org",
                  "@type": "Article",
                  "headline": metaTitle || "Untitled Article",
                  "articleBody": content.replace(/<[^>]*>/g, ' '),
                  "wordCount": stats.words
                };
                console.log(schema);
                alert("Document synced to local storage.");
             }}
             className="bg-zinc-900 text-white px-5 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest hover:bg-black transition-all shadow-lg shadow-zinc-900/10"
           >
             Save Draft
           </button>
        </div>
      </header>

      {/* Main Workspace */}
      <div className="flex flex-1 overflow-hidden relative">
        <div className="flex-1 flex flex-col min-w-0 bg-white relative">
            <div className="toolbar-container bg-white/80 backdrop-blur-md border-b border-zinc-100 z-10">
              <Toolbar 
                editorInstance={editorInstance} 
                onUpdate={() => handleEditorChange(editorInstance?.getContent() || '')}
                onNewDocument={handleCreateNew}
                onShowHistory={() => {}}
                onSaveVersion={() => {}}
                viewMode="edit"
              />
            </div>
            <Editor 
                initialContent={content} 
                onUpdate={handleEditorChange} 
                onInit={setEditorInstance} 
                onAIAssist={onRewrite}
            />
        </div>

        {/* Sidebar */}
        <Sidebar 
            activeTab={activeTab}
            setActiveTab={setActiveTab}
            stats={stats}
            readability={readability}
            health={health}
            intent={intent}
            keywords={keywords}
            seoTab={seoTab}
            setSeoTab={setSeoTab}
            isExpanded={isExpanded}
            setIsExpanded={setIsExpanded}
            onRewrite={onRewrite}
            onConvertCase={handleConvertCase}
            onCopy={handleCopy}
            onClear={handleClear}
            isAIProcessing={isAIProcessing}
            targets={targets}
            setTargets={setTargets}
            metaTitle={metaTitle}
            setMetaTitle={setMetaTitle}
            metaDescription={metaDescription}
            setMetaDescription={setMetaDescription}
            faqs={faqs}
            setFaqs={setFaqs}
            onGenerateMetadata={handleGenerateMetadata}
            onDetectAI={handleDetectAI}
            onGenerateFAQs={handleGenerateFAQs}
            onExportSchema={handleExportSchema}
            onNavigateOutline={(text) => editorInstance?.scrollToText(text)}
        />
      </div>
    </div>
  );
};

export default function App() {
  return (
    <div className="w-screen h-screen bg-white text-zinc-900 overflow-hidden">
      <Routes>
        <Route path="/" element={<SEOEditor />} />
        <Route path="/editor/:id" element={<SEOEditor />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </div>
  );
}

