import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/layout/Sidebar.tsx';
import { Editor } from './components/editor/Editor.tsx';
import { Toolbar } from './components/editor/Toolbar.tsx';
import { getStats } from './core/text-analysis.ts';
import { getReadabilityScore } from './core/readability.ts';
import { analyzeSEOHealth } from './core/seo-health.ts';
import { detectIntent } from './core/intent-detector.ts';
import { getKeywords } from './core/keyword-density.ts';
import { rewriteContent, generateMetadata, generateFAQs, detectAIContent } from './ai/ai-engine.ts';
import { convertText } from './core/case-converter.ts';
import { htmlToMarkdown } from './utils/text-cleaner.ts';
import { TextStats, ReadabilityInsights, SEOHealth, IntentResult, KeywordDensity, Tab, SEOPhraseTab, KeywordTarget, FAQ } from './types/editor.types.ts';

// Default initial content
const DEFAULT_CONTENT = `<h1>The Future of SEO: AI-Driven Content Optimization</h1><p>Search Engine Optimization (SEO) is evolving rapidly. With the rise of artificial intelligence, the way we create and optimize content is changing forever.</p><h2>Why Content Intelligence Matters</h2><p>It's no longer enough to just stuff keywords into a page. Search engines now understand context, sentiment, and user intent. <strong>Content intelligence</strong> tools help writers align their work with what users are actually looking for.</p><h3>Key Takeaways</h3><ul><li>Focus on user intent over exact match keywords.</li><li>Ensure high readability scores.</li><li>Structure content with clear headings.</li></ul>`;

export default function App() {
  const [content, setContent] = useState(DEFAULT_CONTENT);
  const [editorInstance, setEditorInstance] = useState<any>(null);
  const [activeTab, setActiveTab] = useState<Tab>('insights');
  const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
  const [isSidebarExpanded, setIsSidebarExpanded] = useState(true);

  // Analysis State
  const [stats, setStats] = useState<TextStats>({ words: 0, pubWords: 0, sentences: 0, readingTime: 0, speakingTime: 0, characters: 0, paragraphs: 0, entities: [], headingTree: [] });
  const [readability, setReadability] = useState<ReadabilityInsights | null>(null);
  const [health, setHealth] = useState<SEOHealth>({ score: 100, warnings: [], status: 'excellent', checklist: [] });
  const [intent, setIntent] = useState<IntentResult>({ primary: 'Unknown', confidence: 0, signals: [] });
  const [keywords, setKeywords] = useState<KeywordDensity[]>([]);

  // Metadata & Config
  const [targets, setTargets] = useState<KeywordTarget>({ primary: '', secondary: ['', '', ''] });
  const [metaTitle, setMetaTitle] = useState('');
  const [metaDescription, setMetaDescription] = useState('');
  const [faqs, setFaqs] = useState<FAQ[]>([]);

  const [isAIProcessing, setIsAIProcessing] = useState(false);

  // Analysis Effect
  useEffect(() => {
    const timer = setTimeout(() => {
      setStats(getStats(content));
      setReadability(getReadabilityScore(content));
      setKeywords(getKeywords(content, seoTab));
      setIntent(detectIntent(content));
      setHealth(analyzeSEOHealth(content, getKeywords(content, 1), targets, metaDescription));
    }, 500); // Debounce
    return () => clearTimeout(timer);
  }, [content, seoTab, targets, metaDescription]);

  const handleUpdate = (html: string) => {
    setContent(html);
  };

  const handleRewrite = async (mode: any) => {
    if (!editorInstance) return;
    setIsAIProcessing(true);
    const selection = editorInstance.getSelection();
    const textToProcess = selection || content; // Fallback to full content if no selection

    // We only process if there is text
    if (textToProcess.replace(/<[^>]*>/g, '').trim().length === 0) {
        setIsAIProcessing(false);
        return;
    }

    const options = await rewriteContent(textToProcess, mode);
    if (options.length > 0) {
      if (selection) {
        editorInstance.insertContent(options[0]); // Replace selection
      } else {
        // Full replace
        setContent(options[0]);
      }
    }
    setIsAIProcessing(false);
  };

  const handleGenerateMetadata = async (type: 'title' | 'description') => {
      setIsAIProcessing(true);
      const cleanText = content.replace(/<[^>]*>/g, ' ');
      const result = await generateMetadata(cleanText, type);
      if (type === 'title') setMetaTitle(result);
      else setMetaDescription(result);
      setIsAIProcessing(false);
  };

  const handleGenerateFAQs = async () => {
      setIsAIProcessing(true);
      const cleanText = content.replace(/<[^>]*>/g, ' ');
      const results = await generateFAQs(cleanText);
      setFaqs(results);
      setIsAIProcessing(false);
  };

  const handleDetectAI = async () => {
      setIsAIProcessing(true);
      const cleanText = content.replace(/<[^>]*>/g, ' ');
      const result = await detectAIContent(cleanText);
      alert(`AI Probability Score: ${result.score}%\nReason: ${result.analysis}`);
      setIsAIProcessing(false);
  };

  const handleExportSchema = () => {
    const schema = {
      "@context": "https://schema.org",
      "@type": "FAQPage",
      "mainEntity": faqs.map(f => ({
        "@type": "Question",
        "name": f.question,
        "acceptedAnswer": {
          "@type": "Answer",
          "text": f.answer
        }
      }))
    };
    navigator.clipboard.writeText(JSON.stringify(schema, null, 2));
    alert("FAQ Schema JSON-LD copied to clipboard!");
  };

  const handleCopy = (type: 'plain' | 'markdown' | 'html') => {
    let text = "";
    if (type === 'html') text = content;
    else if (type === 'plain') text = content.replace(/<[^>]*>/g, '\n').trim();
    else if (type === 'markdown') text = htmlToMarkdown(content);

    navigator.clipboard.writeText(text);
  };

  const handleConvertCase = (type: string) => {
      if (!editorInstance) return;
      const sel = editorInstance.getSelection();
      if (sel) {
          editorInstance.insertContent(convertText(sel, type));
      }
  };

  return (
    <div className="flex h-screen w-screen bg-white text-zinc-900 font-sans overflow-hidden">
        {/* Main Editor Area */}
        <div className="flex-1 flex flex-col h-full min-w-0 bg-white relative">
            <Toolbar 
                editorInstance={editorInstance}
                onUpdate={() => {}} 
                onNewDocument={() => setContent('')} 
                onShowHistory={() => {}} 
                onSaveVersion={() => {}}
                viewMode="edit"
            />

            <div className="flex-1 overflow-hidden relative">
                <Editor 
                    initialContent={content}
                    onUpdate={handleUpdate}
                    onInit={setEditorInstance}
                    onAIAssist={handleRewrite}
                />
            </div>

            {/* Bottom Status Bar */}
            <div className="h-8 border-t border-zinc-100 bg-white flex items-center px-4 justify-between text-[10px] font-bold text-zinc-400 uppercase tracking-wider">
                <div className="flex gap-4">
                   <span>{stats.words} Words</span>
                   <span>{stats.readingTime} Min Read</span>
                </div>
                <div>
                   {health.status} SEO Score: {health.score}
                </div>
            </div>
        </div>

        {/* Sidebar */}
        <Sidebar 
            activeTab={activeTab}
            setActiveTab={setActiveTab}
            stats={stats}
            readability={readability}
            health={health}
            intent={intent}
            keywords={keywords}
            seoTab={seoTab}
            setSeoTab={setSeoTab}
            isExpanded={isSidebarExpanded}
            setIsExpanded={setIsSidebarExpanded}
            onRewrite={handleRewrite}
            onConvertCase={handleConvertCase}
            onCopy={handleCopy}
            onClear={() => setContent('')}
            isAIProcessing={isAIProcessing}
            targets={targets}
            setTargets={setTargets}
            metaTitle={metaTitle}
            setMetaTitle={setMetaTitle}
            metaDescription={metaDescription}
            setMetaDescription={setMetaDescription}
            faqs={faqs}
            setFaqs={setFaqs}
            onGenerateMetadata={handleGenerateMetadata}
            onDetectAI={handleDetectAI}
            onGenerateFAQs={handleGenerateFAQs}
            onExportSchema={handleExportSchema}
            onNavigateOutline={(text) => editorInstance?.scrollToText(text)}
        />
    </div>
  );
}

