    }
  }, [onUpdate, analyzeParagraphs]);

  // Floating Toolbar Detection
  useEffect(() => {
    const handleSelectionChange = () => {
      const selection = window.getSelection();
      if (
        selection && 
        !selection.isCollapsed && 
        editorRef.current?.contains(selection.anchorNode) &&
        selection.toString().trim().length > 0
      ) {
        const range = selection.getRangeAt(0);
        const rect = range.getBoundingClientRect();
        const wrapperRect = wrapperRef.current?.getBoundingClientRect();

        if (wrapperRect) {
          setToolbar({
            show: true,
            // Position 50px above the selection
            top: rect.top - wrapperRect.top - 55,
            left: rect.left - wrapperRect.left + rect.width / 2
          });
        }
      } else {
        setToolbar(prev => prev.show ? { ...prev, show: false } : prev);
      }
    };

    document.addEventListener('selectionchange', handleSelectionChange);
    return () => document.removeEventListener('selectionchange', handleSelectionChange);
  }, []);

  const handleFormat = (command: string, value: string | null = null) => {
