    <div ref={wrapperRef} className="relative h-full w-full group overflow-hidden flex flex-col bg-white">
      {/* Floating Toolbar */}
      {toolbar.show && (
        <div 
          className="absolute z-[100] flex items-center bg-zinc-900 text-white rounded-xl shadow-2xl p-1 animate-in fade-in zoom-in-95 duration-200 border border-white/10"
          style={{ 
            top: `${toolbar.top}px`, 
