            transform: 'translateX(-50%)'
          }}
          onMouseDown={(e) => e.preventDefault()} // Prevent losing selection when clicking toolbar
        >
          <button 
            onClick={() => handleFormat('bold')}
            className="p-2 hover:bg-white/10 rounded-lg transition-colors"
            title="Bold"
          >
            <Bold size={16} />
          </button>
          <button 
            onClick={() => handleFormat('italic')}
            className="p-2 hover:bg-white/10 rounded-lg transition-colors"
            title="Italic"
          >
            <Italic size={16} />
          </button>
          <div className="w-px h-4 bg-white/10 mx-1" />
          <button 
            onClick={() => handleFormat('formatBlock', 'h2')}
            className="p-2 hover:bg-white/10 rounded-lg transition-colors"
            title="Heading 2"
          >
            <Heading2 size={16} />
          </button>
          <button 
            onClick={() => handleFormat('formatBlock', 'h3')}
            className="p-2 hover:bg-white/10 rounded-lg transition-colors"
            title="Heading 3"
          >
            <Heading3 size={16} />
          </button>
          <div className="w-px h-4 bg-white/10 mx-1" />
          <button 
            onClick={() => handleFormat('removeFormat')}
            className="p-2 hover:bg-red-500/20 text-red-400 rounded-lg transition-colors"
            title="Clear Formatting"
          >
            <XCircle size={16} />
          </button>
        </div>
      )}

      <div 
        ref={editorRef}
        contentEditable
        onInput={handleInput}
        onPaste={handlePaste}
        className="editor-content flex-1 w-full h-full custom-scrollbar overflow-y-auto outline-none select-text bg-white"
        spellCheck="true"
        aria-label="Content Editor"
      />
    </div>
  );
};

import React, { useState, useEffect, useMemo, useDeferredValue, startTransition } from 'react';
import { Sparkles } from 'lucide-react';

// Core Analysis Logic
import { getStats } from './core/text-analysis.ts';
import { getKeywords } from './core/keyword-density.ts';
import { getReadabilityScore } from './core/readability.ts';
import { analyzeSEOHealth } from './core/seo-health.ts';
import { detectIntent } from './core/intent-detector.ts';
import { convertText } from './core/case-converter.ts';

// AI Integration
import { 
  rewriteContent, 
  generateMetadata, 
  detectAIContent, 
  RewriteMode, 
  generateFAQs 
} from './ai/ai-engine.ts';

// Components
import { Toolbar } from './components/editor/Toolbar.tsx';
import { Sidebar } from './components/layout/Sidebar.tsx';
import { Editor } from './components/editor/Editor.tsx';
import { Tab, SEOPhraseTab, KeywordTarget, FAQ } from './types/editor.types.ts';
import { htmlToMarkdown } from './utils/text-cleaner.ts';

export default function App() {
  // 1. Content State
  const [content, setContent] = useState(() => 
    localStorage.getItem('seo-editor-content-v2') || 
    '<h1>Future of Content SEO</h1><p>Start crafting your optimized, AI-enhanced SEO content here. This editor analyzes your text in real-time to ensure maximum search visibility.</p>'
  );

  // 2. Editor & UI State
  const [activeTab, setActiveTab] = useState<Tab>('insights'); 
  const [wordTarget, setWordTarget] = useState(1000);
  const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [editorInstance, setEditorInstance] = useState<any>(null);

  // 3. SEO Metadata State
  const [metaTitle, setMetaTitle] = useState(() => localStorage.getItem('seo-meta-title-v2') || '');
  const [metaDescription, setMetaDescription] = useState(() => localStorage.getItem('seo-meta-desc-v2') || '');
  const [targets, setTargets] = useState<KeywordTarget>(() => {
    const saved = localStorage.getItem('seo-targets-v2');
    return saved ? JSON.parse(saved) : { primary: '', secondary: ['', '', ''] };
  });
  const [faqs, setFaqs] = useState<FAQ[]>(() => {
    const saved = localStorage.getItem('seo-faqs-v2');
    return saved ? JSON.parse(saved) : [];
  });

  const deferredContent = useDeferredValue(content);

  // Persistence
  useEffect(() => {
    localStorage.setItem('seo-editor-content-v2', content);
    localStorage.setItem('seo-targets-v2', JSON.stringify(targets));
    localStorage.setItem('seo-meta-desc-v2', metaDescription);
    localStorage.setItem('seo-meta-title-v2', metaTitle);
    localStorage.setItem('seo-faqs-v2', JSON.stringify(faqs));
  }, [content, targets, metaDescription, metaTitle, faqs]);

  // Analysis Memoization
  const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
  const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
  const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
  const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, targets, metaDescription), [deferredContent, keywords, targets, metaDescription]);
  const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);

  const handleEditorChange = (newContent: string) => {
    startTransition(() => {
      setContent(newContent);
    });
  };

  const onRewrite = async (mode: RewriteMode) => {
    if (!editorInstance) return;
    const selectedText = editorInstance.getSelection();
    if (!selectedText) {
      alert("Please select text within the editor to use AI rewriting features.");
      return;
    }
    setIsAIProcessing(true);
    try {
      const results = await rewriteContent(selectedText, mode);
      if (results && results.length > 0) {
        // Automatically insert the first AI option
        editorInstance.insertContent(results[0]);
      }
    } catch (err) {
      console.error("AI Rewrite Failed:", err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  return (
    <div className="flex h-screen w-full bg-white overflow-hidden text-zinc-900 selection:bg-blue-100">
      {/* Main Editor Viewport */}
      <div className="flex-1 flex flex-col min-w-0 border-r border-zinc-100">
        {/* Navigation & Toolbar Header */}
        <header className="h-16 border-b border-zinc-100 px-8 flex items-center justify-between bg-white shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-black shadow-lg shadow-blue-500/20">S</div>
            <h1 className="font-black tracking-tighter text-lg uppercase">SEO Focus <span className="text-zinc-300 font-medium">Editor</span></h1>
          </div>
          <div className="flex items-center gap-8">
             {/* Word Progress integrated into Header */}
             <div className="hidden sm:flex items-center gap-4">
                <div className="flex flex-col items-end">
                  <span className="text-[9px] font-black text-zinc-400 uppercase tracking-widest mb-0.5">Progress</span>
                  <div className="text-[11px] font-black text-zinc-800 uppercase tabular-nums">
                    {stats.words} <span className="text-zinc-300">/</span> {wordTarget} words
                  </div>
                </div>
                <div className="w-20 h-1 bg-zinc-100 rounded-full overflow-hidden">
                  <div 
                    className="h-full bg-blue-600 transition-all duration-700 ease-out" 
                    style={{ width: `${Math.min(100, (stats.words / wordTarget) * 100)}%` }} 
                  />
                </div>
             </div>

             <div className="flex items-center gap-2 px-3 py-1.5 bg-zinc-50 rounded-full border border-zinc-100">
                <div className={`w-2 h-2 rounded-full ${isAIProcessing ? 'bg-blue-500 animate-pulse' : 'bg-emerald-500'}`} />
                <span className="text-[10px] font-black uppercase tracking-widest text-zinc-500">
                  {isAIProcessing ? 'AI Processing' : 'Engine Ready'}
                </span>
             </div>
          </div>
        </header>

        <div className="flex-1 flex flex-col overflow-hidden relative">
          <div className="toolbar-container bg-white border-b border-zinc-100">
            <Toolbar 
              editorInstance={editorInstance} 
              onUpdate={() => handleEditorChange(editorInstance?.getContent() || '')}
              onNewDocument={() => {
                if(confirm("Start a new document? All current content will be cleared.")) {
                  editorInstance?.setContent('<h1>New Masterpiece</h1><p>Start writing...</p>');
                }
              }}
              onShowHistory={() => {}} 
              onSaveVersion={() => {}}
              viewMode="focused"
            />
          </div>

          <main className="flex-1 bg-white overflow-hidden flex justify-center relative">
            <div className="w-full h-full overflow-hidden bg-white relative">
              <Editor 
                initialContent={content}
                onUpdate={handleEditorChange}
                onInit={setEditorInstance}
                onAIAssist={onRewrite}
              />
            </div>
          </main>
        </div>
      </div>

      {/* Analysis Sidebar */}
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        stats={stats} 
        readability={readability} 
        health={health} 
        intent={intent} 
        keywords={keywords} 
        seoTab={seoTab} 
        setSeoTab={setSeoTab} 
        isExpanded={isExpanded} 
        setIsExpanded={setIsExpanded} 
        onRewrite={onRewrite} 
        onConvertCase={(type) => {
          const selected = editorInstance?.getSelection();
          if (selected) {
            editorInstance?.insertContent(convertText(selected, type));
          }
        }} 
        onCopy={(type) => {
          let output = content;
          if (type === 'markdown') output = htmlToMarkdown(content);
          else if (type === 'plain') output = content.replace(/<[^>]*>/g, '');

          navigator.clipboard.writeText(output).then(() => {
             // Visual feedback can be added here
          });
        }} 
        onClear={() => {
           if(confirm("Delete all content?")) editorInstance?.setContent('');
        }} 
        isAIProcessing={isAIProcessing} 
        targets={targets} 
        setTargets={setTargets}
        metaTitle={metaTitle} 
        setMetaTitle={setMetaTitle} 
        metaDescription={metaDescription} 
        setMetaDescription={setMetaDescription}
        faqs={faqs} 
        setFaqs={setFaqs}
        onGenerateMetadata={async (type) => {
          setIsAIProcessing(true);
          try {
            const res = await generateMetadata(content, type);
            if (type === 'title') setMetaTitle(res); 
            else setMetaDescription(res);
          } catch (e) {
            console.error("Metadata Generation Error:", e);
          } finally {
            setIsAIProcessing(false);
          }
        }}
        onDetectAI={async () => {
          setIsAIProcessing(true);
          try {
            const res = await detectAIContent(content);
            alert(`AI Detection Result:\nScore: ${res.score}%\nAnalysis: ${res.analysis}`);
          } catch (e) {
            console.error("AI Detection Error:", e);
          } finally {
            setIsAIProcessing(false);
          }
        }}
        onGenerateFAQs={async () => {
          setIsAIProcessing(true);
          try {
            const res = await generateFAQs(content);
            setFaqs(res);
          } catch (e) {
            console.error("FAQ Generation Error:", e);
          } finally {
            setIsAIProcessing(false);
          }
        }}
        onExportSchema={() => {
           const schema = {
             "@context": "https://schema.org",
             "@type": "Article",
             "headline": metaTitle,
             "description": metaDescription,
             "mainEntityOfPage": {
               "@type": "WebPage",
               "@id": window.location.href
             }
           };
           navigator.clipboard.writeText(JSON.stringify(schema, null, 2));
           alert('Article Schema copied to clipboard.');
        }}
        onNavigateOutline={(text) => editorInstance?.scrollToText(text)}
      />
    </div>
  );
}

import React, { useRef, useState } from 'react';
import { 
  Bold, Italic, Underline, Link as LinkIcon, 
  ChevronDown, Undo, Redo,
  Table as TableIcon, Image as ImageIcon,
  X, Minus, Edit3
} from 'lucide-react';

interface ToolbarProps {
  editorInstance: any;
  onUpdate: () => void;
  onNewDocument: () => void;
  onShowHistory: () => void;
  onSaveVersion: () => void;
  viewMode: string;
}

const ToolbarGroup = ({ children }: { children?: React.ReactNode }) => (
  <div className="flex bg-zinc-50 p-1.5 rounded-2xl border border-zinc-100 mx-1 items-center shadow-sm">
    {children}
  </div>
);

const ToolbarButton = ({ icon, onClick, title, active = false, disabled = false }: any) => (
  <button 
    onMouseDown={(e) => { 
      e.preventDefault(); 
      onClick(e); 
    }} 
    disabled={disabled}
    className={`w-10 h-10 flex items-center justify-center hover:bg-white hover:shadow-sm rounded-xl transition-all disabled:opacity-20 ${active ? 'text-blue-600 bg-blue-50' : 'text-zinc-500'}`} 
    title={title}
  >
    {icon}
  </button>
);

export const Toolbar = ({ 
  editorInstance,
}: ToolbarProps) => {
  const [showImageModal, setShowImageModal] = useState(false);

  if (!editorInstance) return null;

  const insertTable = () => {
    const rowsInput = prompt("Enter number of rows:", "3");
    const colsInput = prompt("Enter number of columns:", "3");
    const rows = parseInt(rowsInput || "0");
    const cols = parseInt(colsInput || "0");

    if (rows > 0 && cols > 0) {
      let tbl = '<table style="width:100%; border: 1px solid #e2e8f0; border-collapse: collapse; margin-bottom: 2rem;">';
      for (let r = 0; r < rows; r++) {
        tbl += '<tr>';
        for (let c = 0; c < cols; c++) {
          tbl += '<td style="border: 1px solid #e2e8f0; padding: 12px;">&nbsp;</td>';
        }
        tbl += '</tr>';
      }
      tbl += '</table><p>&nbsp;</p>';
      editorInstance.insertContent(tbl);
    }
  };

  const insertImageFromUrl = () => {
    const url = prompt("Paste Image URL:");
    if (url) {
      editorInstance.insertContent(`<img src="${url}" alt="Image" style="max-width:100%; border-radius:1rem; margin: 2rem 0; box-shadow: 0 10px 15px -3px rgba(0,0,0,0.05);" />`);
      setShowImageModal(false);
    }
  };

  const handleFormat = (cmd: string, val: any = null) => {
    editorInstance?.execCommand(cmd, false, val);
  };

  return (
    <>
      <div className="border-b border-zinc-100 bg-white/90 backdrop-blur-md p-3 flex flex-wrap gap-2 sticky top-0 z-20 overflow-x-auto no-scrollbar items-center shrink-0 justify-start px-8">

        <ToolbarGroup>
          <ToolbarButton 
            icon={<Undo size={18} />} 
            onClick={() => handleFormat('undo')} 
            title="Undo" 
          />
          <ToolbarButton 
            icon={<Redo size={18} />} 
            onClick={() => handleFormat('redo')} 
            title="Redo" 
          />
        </ToolbarGroup>

        <ToolbarGroup>
          <div className="relative flex items-center px-4">
            <select 
              onChange={(e) => {
                const val = e.target.value;
                handleFormat('formatBlock', val);
              }} 
              className="bg-transparent appearance-none text-[11px] font-black uppercase outline-none cursor-pointer pr-8 py-2.5 tracking-widest text-zinc-800"
            >
              <option value="p">Paragraph</option>
              <option value="h1">Heading 1</option>
              <option value="h2">Heading 2</option>
              <option value="h3">Heading 3</option>
              <option value="h4">Heading 4</option>
              <option value="h5">Heading 5</option>
              <option value="h6">Heading 6</option>
              <option value="blockquote">Quote</option>
              <option value="pre">Code Block</option>
            </select>
            <ChevronDown size={12} className="absolute right-4 pointer-events-none text-zinc-400" />
          </div>
        </ToolbarGroup>

        <ToolbarGroup>
          <ToolbarButton 
            icon={<Bold size={18} />} 
            onClick={() => handleFormat('bold')} 
            title="Bold" 
          />
          <ToolbarButton 
            icon={<Italic size={18} />} 
            onClick={() => handleFormat('italic')} 
            title="Italic" 
          />
          <ToolbarButton 
            icon={<Underline size={18} />} 
            onClick={() => handleFormat('underline')} 
            title="Underline" 
          />
        </ToolbarGroup>

        <ToolbarGroup>
          <ToolbarButton icon={<TableIcon size={18} />} onClick={insertTable} title="Insert Table" />
          <ToolbarButton icon={<ImageIcon size={18} />} onClick={() => setShowImageModal(true)} title="Insert Image" />
          <ToolbarButton icon={<Minus size={18} />} onClick={() => editorInstance.insertContent('<hr/>')} title="Horizontal Line" />
          <ToolbarButton icon={<LinkIcon size={18} />} onClick={() => {
            const url = prompt("Enter URL:");
            if (url) handleFormat('createLink', url);
          }} title="Insert Link" />
        </ToolbarGroup>

      </div>

      {showImageModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center bg-zinc-900/10 backdrop-blur-sm p-4">
          <div className="bg-white border border-zinc-200 rounded-[40px] w-full max-w-sm shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-10 border-b border-zinc-50 flex items-center justify-between">
              <h3 className="font-black text-xl uppercase tracking-tighter text-zinc-900">Insert Image</h3>
              <button onClick={() => setShowImageModal(false)} className="text-zinc-400 hover:text-zinc-900 transition-colors"><X size={24}/></button>
            </div>
            <div className="p-10">
              <button onClick={insertImageFromUrl} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest flex items-center justify-center gap-3 shadow-xl shadow-blue-500/30 hover:bg-blue-700 transition-all active:scale-95">Enter Image URL</button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

