import React, { useRef, useState } from 'react';
import { 
  Bold, Italic, Underline, Link as LinkIcon, 
  ChevronDown, Undo, Redo,
  Table as TableIcon, Image as ImageIcon,
  X, Minus, Edit3
} from 'lucide-react';
import { TextStats } from '../../types/editor.types';

interface ToolbarProps {
  editorInstance: any;
  stats?: TextStats;
  wordTarget?: number;
  onUpdate: () => void;
  onNewDocument: () => void;
  onShowHistory: () => void;
  onSaveVersion: () => void;
  viewMode: string;
}

const ToolbarGroup = ({ children }: { children?: React.ReactNode }) => (
  <div className="flex bg-zinc-50 p-1.5 rounded-2xl border border-zinc-100 mx-1 items-center shadow-sm">
    {children}
  </div>
);

const ToolbarButton = ({ icon, onClick, title, active = false, disabled = false }: any) => (
  <button 
    onMouseDown={(e) => { 
      e.preventDefault(); 
      onClick(e); 
    }} 
    disabled={disabled}
    className={`w-10 h-10 flex items-center justify-center hover:bg-white hover:shadow-sm rounded-xl transition-all disabled:opacity-20 ${active ? 'text-blue-600 bg-blue-50' : 'text-zinc-500'}`} 
    title={title}
  >
    {icon}
  </button>
);

export const Toolbar = ({ 
  editorInstance,
  stats,
  wordTarget = 1000
}: ToolbarProps) => {
  const [showImageModal, setShowImageModal] = useState(false);

  if (!editorInstance) return null;

  const insertTable = () => {
    const rowsInput = prompt("Enter number of rows:", "3");
    const colsInput = prompt("Enter number of columns:", "3");
    const rows = parseInt(rowsInput || "0");
    const cols = parseInt(colsInput || "0");

    if (rows > 0 && cols > 0) {
      let tbl = '<table style="width:100%; border: 1px solid #e2e8f0; border-collapse: collapse; margin-bottom: 2rem;">';
      for (let r = 0; r < rows; r++) {
        tbl += '<tr>';
        for (let c = 0; c < cols; c++) {
          tbl += '<td style="border: 1px solid #e2e8f0; padding: 12px;">&nbsp;</td>';
        }
        tbl += '</tr>';
      }
      tbl += '</table><p>&nbsp;</p>';
      editorInstance.insertContent(tbl);
    }
  };

  const insertImageFromUrl = () => {
    const url = prompt("Paste Image URL:");
    if (url) {
      editorInstance.insertContent(`<img src="${url}" alt="Image" style="max-width:100%; border-radius:1rem; margin: 2rem 0; box-shadow: 0 10px 15px -3px rgba(0,0,0,0.05);" />`);
      setShowImageModal(false);
    }
  };

  const handleFormat = (cmd: string, val: any = null) => {
    editorInstance?.execCommand(cmd, false, val);
  };

  return (
    <>
      <div className="border-b border-zinc-100 bg-white/90 backdrop-blur-md p-3 flex flex-wrap gap-2 sticky top-0 z-20 overflow-x-auto no-scrollbar items-center shrink-0 justify-start px-8">

        <ToolbarGroup>
          <ToolbarButton 
            icon={<Undo size={18} />} 
            onClick={() => handleFormat('undo')} 
            title="Undo" 
          />
          <ToolbarButton 
            icon={<Redo size={18} />} 
            onClick={() => handleFormat('redo')} 
            title="Redo" 
          />
        </ToolbarGroup>

        <ToolbarGroup>
          <div className="relative flex items-center px-4">
            <select 
              onChange={(e) => {
                const val = e.target.value;
                handleFormat('formatBlock', val);
              }} 
              className="bg-transparent appearance-none text-[11px] font-black uppercase outline-none cursor-pointer pr-8 py-2.5 tracking-widest text-zinc-800"
            >
              <option value="p">Paragraph</option>
              <option value="h1">Heading 1</option>
              <option value="h2">Heading 2</option>
              <option value="h3">Heading 3</option>
              <option value="h4">Heading 4</option>
              <option value="h5">Heading 5</option>
              <option value="h6">Heading 6</option>
              <option value="blockquote">Quote</option>
              <option value="pre">Code Block</option>
            </select>
            <ChevronDown size={12} className="absolute right-4 pointer-events-none text-zinc-400" />
          </div>
        </ToolbarGroup>

        <ToolbarGroup>
          <ToolbarButton 
            icon={<Bold size={18} />} 
            onClick={() => handleFormat('bold')} 
            title="Bold" 
          />
          <ToolbarButton 
            icon={<Italic size={18} />} 
            onClick={() => handleFormat('italic')} 
            title="Italic" 
          />
          <ToolbarButton 
            icon={<Underline size={18} />} 
            onClick={() => handleFormat('underline')} 
            title="Underline" 
          />
        </ToolbarGroup>

        <ToolbarGroup>
          <ToolbarButton icon={<TableIcon size={18} />} onClick={insertTable} title="Insert Table" />
          <ToolbarButton icon={<ImageIcon size={18} />} onClick={() => setShowImageModal(true)} title="Insert Image" />
          <ToolbarButton icon={<Minus size={18} />} onClick={() => editorInstance.insertContent('<hr/>')} title="Horizontal Line" />
          <ToolbarButton icon={<LinkIcon size={18} />} onClick={() => {
            const url = prompt("Enter URL:");
            if (url) handleFormat('createLink', url);
          }} title="Insert Link" />
        </ToolbarGroup>

        {/* Word Progress integrated on the right of toolbar */}
        {stats && (
          <div className="ml-auto hidden sm:flex items-center gap-4 px-4 py-2 bg-zinc-50 border border-zinc-100 rounded-2xl shadow-sm">
            <div className="flex flex-col items-end">
              <span className="text-[9px] font-black text-zinc-400 uppercase tracking-widest mb-0.5">Progress</span>
              <div className="text-[11px] font-black text-zinc-800 uppercase tabular-nums">
                {stats.words} <span className="text-zinc-300">/</span> {wordTarget} words
              </div>
            </div>
            <div className="w-20 h-1 bg-zinc-100 rounded-full overflow-hidden">
              <div 
                className="h-full bg-blue-600 transition-all duration-700 ease-out" 
                style={{ width: `${Math.min(100, (stats.words / wordTarget) * 100)}%` }} 
              />
            </div>
          </div>
        )}

      </div>

      {showImageModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center bg-zinc-900/10 backdrop-blur-sm p-4">
          <div className="bg-white border border-zinc-200 rounded-[40px] w-full max-sm shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-10 border-b border-zinc-50 flex items-center justify-between">
              <h3 className="font-black text-xl uppercase tracking-tighter text-zinc-900">Insert Image</h3>
              <button onClick={() => setShowImageModal(false)} className="text-zinc-400 hover:text-zinc-900 transition-colors"><X size={24}/></button>
            </div>
            <div className="p-10">
              <button onClick={insertImageFromUrl} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest flex items-center justify-center gap-3 shadow-xl shadow-blue-500/30 hover:bg-blue-700 transition-all active:scale-95">Enter Image URL</button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

import React, { useState } from 'react';
import { 
  BarChart3, Target, Activity, Sparkles, Settings, 
  ChevronDown, Copy, 
  Trash2, BookOpen, CheckCircle2,
  ScanEye, PlusCircle,
  Navigation,
  Cpu,
  FileCode,
  HelpCircle,
  Plus,
  Trash
} from 'lucide-react';
import { Tab, SEOPhraseTab, TextStats, ReadabilityInsights, KeywordDensity, SEOHealth, IntentResult, KeywordTarget, FAQ } from '../../types/editor.types';

interface SidebarProps {
  activeTab: Tab;
  setActiveTab: (tab: Tab) => void;
  stats: TextStats;
  readability: ReadabilityInsights | null;
  health: SEOHealth;
  intent: IntentResult;
  keywords: KeywordDensity[];
  seoTab: SEOPhraseTab;
  setSeoTab: (num: SEOPhraseTab) => void;
  isExpanded: boolean;
  setIsExpanded: (val: boolean) => void;
  onRewrite: (mode: any) => void;
  onConvertCase: (type: string) => void;
  onCopy: (type: 'plain' | 'markdown' | 'html') => void;
  onClear: () => void;
  isAIProcessing?: boolean;
  targets: KeywordTarget;
  setTargets: (t: KeywordTarget) => void;
  metaTitle: string;
  setMetaTitle: (s: string) => void;
  metaDescription: string;
  setMetaDescription: (s: string) => void;
  faqs: FAQ[];
  setFaqs: (f: FAQ[]) => void;
  onGenerateMetadata: (type: 'title' | 'description') => void;
  onDetectAI: () => void;
  onGenerateFAQs: () => void;
  onExportSchema: () => void;
  onNavigateOutline?: (text: string) => void;
}

const TabButton = ({ active, onClick, label, icon }: any) => (
  <button onClick={onClick} className={`flex-1 flex flex-col items-center justify-center gap-1 text-[10px] font-black uppercase tracking-tighter relative py-5 transition-all ${active ? 'text-blue-600' : 'text-zinc-400 hover:text-zinc-600'}`}>
    {icon}
    <span className="hidden lg:inline">{label}</span>
    {active && <div className="absolute bottom-0 left-4 right-4 h-0.5 bg-blue-600 rounded-t-full" />}
  </button>
);

const StatCard = ({ label, value }: any) => (
  <div className="p-5 bg-white border border-zinc-100 rounded-2xl shadow-sm shadow-zinc-200/50">
    <div className="text-[10px] font-black text-zinc-400 uppercase mb-1.5 tracking-widest">{label}</div>
    <div className="text-2xl font-black tracking-tighter text-zinc-900">{value}</div>
  </div>
);

const SectionHeader = ({ title, actionLabel, onAction, actionDisabled }: { title: string, actionLabel?: string, onAction?: () => void, actionDisabled?: boolean }) => (
  <div className="flex items-center justify-between mb-5">
    <h3 className="text-[10px] font-black text-zinc-300 uppercase tracking-[0.25em]">{title}</h3>
    {actionLabel && (
      <button 
        onClick={onAction} 
        disabled={actionDisabled}
        className="text-[10px] font-black text-blue-600 uppercase hover:underline disabled:opacity-30 disabled:no-underline transition-all"
      >
        {actionLabel}
      </button>
    )}
  </div>
);

const ActionButton = ({ onClick, label, variant = 'primary', icon, className, disabled }: any) => {
  const styles: any = {
    primary: 'bg-white text-zinc-800 border-zinc-200 hover:border-blue-500 shadow-sm hover:text-blue-600',
    secondary: 'bg-zinc-50 text-zinc-500 border-zinc-100 hover:bg-zinc-100',
    danger: 'bg-red-50 text-red-500 border-red-100 hover:bg-red-100',
    ai: 'bg-blue-600 text-white border-transparent hover:bg-blue-700 shadow-lg shadow-blue-500/20'
  };
  return (
    <button 
      onClick={onClick} 
      disabled={disabled}
      className={`w-full py-3.5 px-4 rounded-xl text-[11px] font-black border transition-all flex items-center justify-center gap-2 uppercase tracking-widest disabled:opacity-50 ${styles[variant]} ${className}`}
    >
      {icon}{label}
    </button>
  );
};

export const Sidebar = ({ 
  activeTab, setActiveTab, stats, readability, health, intent, keywords, 
  seoTab, setSeoTab, isExpanded, setIsExpanded, onRewrite, onConvertCase, onCopy, onClear, isAIProcessing,
  targets, setTargets, metaTitle, setMetaTitle, metaDescription, setMetaDescription, faqs, setFaqs, 
  onGenerateMetadata, onDetectAI, onGenerateFAQs, onExportSchema, onNavigateOutline
}: SidebarProps) => {

  const h1Count = stats.headingTree.filter(h => h.tag === 'h1').length;
  const h2Count = stats.headingTree.filter(h => h.tag === 'h2').length;
  const h3Count = stats.headingTree.filter(h => h.tag === 'h3').length;

  const handleFaqChange = (index: number, field: 'question' | 'answer', value: string) => {
    const newFaqs = [...faqs];
    newFaqs[index] = { ...newFaqs[index], [field]: value };
    setFaqs(newFaqs);
  };

  const removeFaq = (index: number) => {
    setFaqs(faqs.filter((_, i) => i !== index));
  };

  const addManualFaq = () => {
    setFaqs([...faqs, { question: '', answer: '' }]);
  };

  return (
    <aside className="w-full md:w-80 lg:w-[400px] border-l border-zinc-100 flex flex-col bg-white shrink-0 h-screen overflow-hidden">
      <div className="flex border-b border-zinc-100 shrink-0 bg-white">
        <TabButton active={activeTab === 'insights'} onClick={() => setActiveTab('insights')} label="Insights" icon={<BarChart3 size={18} />} />
        <TabButton active={activeTab === 'keywords'} onClick={() => setActiveTab('keywords')} label="Keywords" icon={<Target size={18} />} />
        <TabButton active={activeTab === 'seo'} onClick={() => setActiveTab('seo')} label="SEO" icon={<Activity size={18} />} />
        <TabButton active={activeTab === 'ai'} onClick={() => setActiveTab('ai')} label="AI Assistant" icon={<Sparkles size={18} />} />
        <TabButton active={activeTab === 'tools'} onClick={() => setActiveTab('tools')} label="Tools" icon={<Settings size={18} />} />
      </div>

      <div className="flex-1 overflow-y-auto custom-scrollbar p-8 space-y-10 pb-32">
        {activeTab === 'insights' && (
          <div className="space-y-10 animate-in fade-in slide-in-from-right-4 duration-500">
            <div className="space-y-5">
              <SectionHeader title="Readability Analysis" />
              <div className="grid grid-cols-2 gap-4">
                {readability && (
                  <div className="col-span-2 p-5 bg-white border border-zinc-100 rounded-2xl shadow-sm shadow-zinc-200/50 flex items-center justify-between">
                    <div>
                      <div className="text-[10px] font-black text-zinc-400 uppercase mb-1.5 tracking-widest">Ease Score</div>
                      <div className={`text-4xl font-black tracking-tighter ${readability.color}`}>
                        {readability.score}
                      </div>
                    </div>
                    <div className="text-right flex flex-col items-end">
                      <div className="text-[11px] font-black uppercase text-zinc-900 tracking-wider mb-1">
                        {readability.level}
                      </div>
                      <p className="text-[10px] text-zinc-400 leading-tight italic max-w-[150px]">
                        {readability.description}
                      </p>
                    </div>
                  </div>
                )}
                <StatCard label="Total Words" value={stats.words} />
                <StatCard label="Read Time" value={`${stats.readingTime}m`} />
                <StatCard label="Sentences" value={stats.sentences} />
                <StatCard label="Paragraphs" value={stats.paragraphs} />
              </div>
            </div>

            <div className="space-y-5">
              <SectionHeader title="Heading Structure" />
              <div className="grid grid-cols-3 gap-3">
                <div className={`p-4 border rounded-2xl text-center ${h1Count === 1 ? 'border-emerald-100 bg-emerald-50 text-emerald-600' : 'border-red-100 bg-red-50 text-red-600'}`}>
                   <div className="text-[9px] font-black uppercase tracking-tighter opacity-70">H1 Title</div>
                   <div className="text-lg font-black">{h1Count}</div>
                </div>
                <div className="p-4 border border-zinc-100 rounded-2xl text-center bg-white">
                   <div className="text-[9px] font-black uppercase tracking-tighter text-zinc-400">H2 Sections</div>
                   <div className="text-lg font-black text-zinc-800">{h2Count}</div>
                </div>
                <div className="p-4 border border-zinc-100 rounded-2xl text-center bg-white">
                   <div className="text-[9px] font-black uppercase tracking-tighter text-zinc-400">H3 Subs</div>
                   <div className="text-lg font-black text-zinc-800">{h3Count}</div>
                </div>
              </div>

              <div className="bg-zinc-50 p-6 rounded-[24px] border border-zinc-100">
                <div className="space-y-3">
                  {stats.headingTree.length > 0 ? stats.headingTree.map((h, i) => (
                    <button 
                      key={i} 
                      onClick={() => onNavigateOutline?.(h.text)}
                      className="w-full text-left flex gap-3 items-center group" 
                      style={{ paddingLeft: `${(h.level - 1) * 16}px` }}
                    >
                      <span className="text-[9px] font-black text-blue-600 bg-blue-50 px-1.5 py-0.5 rounded uppercase shrink-0">{h.tag}</span>
                      <span className="text-xs font-bold text-zinc-500 line-clamp-1 group-hover:text-blue-600 transition-colors">{h.text}</span>
                    </button>
                  )) : (
                    <div className="text-[11px] text-zinc-400 italic text-center">No structural headings found.</div>
                  )}
                </div>
              </div>
            </div>

            <div className="space-y-5">
              <SectionHeader title="NLP Terms" />
              <div className="flex flex-wrap gap-2">
                {stats.entities.length > 0 ? stats.entities.map((entity, i) => (
                  <div key={i} className="px-3 py-1.5 bg-white border border-zinc-100 rounded-full text-[10px] font-bold text-zinc-600 flex items-center gap-1.5 shadow-sm">
                    <Cpu size={10} className="text-blue-500" />
                    {entity}
                  </div>
                )) : (
                  <div className="text-[11px] text-zinc-400 italic text-center w-full">No significant entities detected.</div>
                )}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'keywords' && (
          <div className="space-y-10 animate-in fade-in slide-in-from-right-4 duration-500">
            <div>
              <SectionHeader title="Targeting" />
              <div className="space-y-4">
                <div className="relative">
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 text-blue-600"><Target size={16}/></span>
                  <input 
                    type="text" 
                    placeholder="Set Primary Keyword..." 
                    value={targets.primary}
                    onChange={(e) => setTargets({ ...targets, primary: e.target.value })}
                    className="w-full bg-zinc-50 border border-zinc-100 rounded-2xl py-4 pl-12 pr-6 text-sm focus:border-blue-400 outline-none transition-all font-bold text-zinc-800 placeholder:text-zinc-300"
                  />
                </div>
                <div className="space-y-3">
                   {targets.secondary.map((val, idx) => (
                     <input 
                      key={idx}
                      type="text" 
                      placeholder={`Secondary Keyword ${idx + 1}`} 
                      value={val}
                      onChange={(e) => {
                        const newSec = [...targets.secondary];
                        newSec[idx] = e.target.value;
                        setTargets({ ...targets, secondary: newSec });
                      }}
                      className="w-full bg-white border border-zinc-100 rounded-xl py-3 px-5 text-xs focus:border-blue-200 outline-none transition-all text-zinc-600"
                    />
                   ))}
                </div>
              </div>
            </div>

            <div className="pt-6 border-t border-zinc-50">
              <SectionHeader title="Live Density Map" />
              <div className="flex bg-zinc-100 p-1 rounded-2xl gap-1 shrink-0 mb-6">
                {[1, 2, 3, 4].map(num => (
                  <button key={num} onClick={() => { setSeoTab(num as SEOPhraseTab); setIsExpanded(false); }} className={`flex-1 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${seoTab === num ? 'bg-white text-blue-600 shadow-lg shadow-zinc-200/50' : 'text-zinc-400 hover:text-zinc-600'}`}>{num}W</button>
                ))}
              </div>
              <div className={`rounded-3xl border border-zinc-100 bg-white overflow-hidden shadow-sm transition-all duration-300 ${isExpanded ? 'max-h-[500px] overflow-y-auto custom-scrollbar' : ''}`}>
                <table className="w-full text-left text-xs">
                  <thead className="bg-zinc-50 text-[10px] font-black text-zinc-400 border-b border-zinc-100 sticky top-0 z-10">
                    <tr><th className="px-5 py-4">PHRASE</th><th className="px-5 py-4 text-right">QTY</th><th className="px-5 py-4 text-right">DENS</th></tr>
                  </thead>
                  <tbody className="divide-y divide-zinc-50">
                    {(isExpanded ? keywords : keywords.slice(0, 12)).map((item, idx) => (
                      <tr key={idx} className="hover:bg-zinc-50/50 transition-colors">
                        <td className="px-5 py-4 font-bold truncate max-w-[160px] text-zinc-600">{item.phrase}</td>
                        <td className="px-5 py-4 text-right text-zinc-400 font-mono">{item.count}</td>
                        <td className={`px-5 py-4 text-right font-black ${item.percentage > 3 ? 'text-red-500' : 'text-emerald-500'}`}>{item.percentage}%</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              {keywords.length > 12 && (
                <button onClick={() => setIsExpanded(!isExpanded)} className="w-full py-4 text-[10px] font-black uppercase text-blue-600 flex items-center justify-center gap-2 hover:bg-blue-50/5 rounded-2xl transition-all mt-4">
                  {isExpanded ? 'Collapse List' : `Full Analysis (${keywords.length})`}
                  <ChevronDown className={`transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} size={16} />
                </button>
              )}
            </div>
          </div>
        )}

        {activeTab === 'seo' && (
          <div className="space-y-10 animate-in fade-in slide-in-from-right-4 duration-500">
            <div>
              <SectionHeader title="Ranking Potential" />
              <div className="p-10 bg-zinc-50 border border-zinc-100 rounded-[40px] text-center">
                <div className="text-7xl font-black tracking-tighter mb-2" style={{ color: health.score > 80 ? '#10b981' : health.score > 60 ? '#f59e0b' : '#ef4444' }}>{health.score}</div>
                <div className="text-[10px] font-black text-zinc-400 uppercase tracking-widest">Composite SEO Health</div>
              </div>
            </div>

            <div className="space-y-8">
              <SectionHeader 
                title="SERP Preview Elements" 
              />

              <div className="space-y-3">
                <div className="flex items-center justify-between px-1">
                  <label className="text-[10px] font-black text-zinc-400 uppercase tracking-wider">Title Tag</label>
                  <button onClick={() => onGenerateMetadata('title')} className="text-[10px] font-black text-blue-600 uppercase hover:underline disabled:opacity-50" disabled={isAIProcessing}>Generate</button>
                </div>
                <input 
                  type="text" 
                  value={metaTitle}
                  onChange={(e) => setMetaTitle(e.target.value)}
                  placeholder="Enter a compelling SEO title..."
                  className="w-full bg-white border border-zinc-100 rounded-xl py-3 px-4 text-xs font-bold text-zinc-800 focus:border-blue-400 outline-none"
                />
                <div className={`text-[10px] text-right font-bold ${metaTitle.length > 60 ? 'text-red-500' : 'text-zinc-300'}`}>{metaTitle.length} / 60 chars</div>
              </div>

              <div className="space-y-3">
                <div className="flex items-center justify-between px-1">
                  <label className="text-[10px] font-black text-zinc-400 uppercase tracking-wider">Snippet Description</label>
                  <button onClick={() => onGenerateMetadata('description')} className="text-[10px] font-black text-blue-600 uppercase hover:underline disabled:opacity-50" disabled={isAIProcessing}>Generate</button>
                </div>
                <textarea 
                  rows={4}
                  value={metaDescription}
                  onChange={(e) => setMetaDescription(e.target.value)}
                  placeholder="Enter a descriptive meta snippet for search results..."
                  className="w-full bg-white border border-zinc-100 rounded-2xl p-4 text-xs font-medium text-zinc-600 outline-none focus:border-blue-400 transition-all resize-none leading-relaxed"
                />
                <div className={`text-[10px] text-right font-bold ${metaDescription.length > 160 ? 'text-red-500' : 'text-zinc-300'}`}>{metaDescription.length} / 160 chars</div>
              </div>
            </div>

            <div className="pt-8 border-t border-zinc-50 space-y-6">
              <SectionHeader 
                title="FAQs & JSON-LD" 
                actionLabel="Generate" 
                onAction={onGenerateFAQs} 
                actionDisabled={isAIProcessing}
              />

              <div className="space-y-4">
                <div className="space-y-4">
                  {faqs.map((faq, idx) => (
                    <div key={idx} className="bg-zinc-50 border border-zinc-100 rounded-[24px] p-5 space-y-3 relative group/faq">
                      <button 
                        onClick={() => removeFaq(idx)}
                        className="absolute top-4 right-4 text-zinc-300 hover:text-red-500 opacity-0 group-hover/faq:opacity-100 transition-all"
                      >
                        <Trash size={14}/>
                      </button>
                      <div className="space-y-1">
                        <label className="text-[9px] font-black text-zinc-400 uppercase tracking-wider">Question</label>
                        <input 
                          type="text" 
                          value={faq.question}
                          onChange={(e) => handleFaqChange(idx, 'question', e.target.value)}
                          placeholder="Enter a common question..."
                          className="w-full bg-white border border-zinc-100 rounded-lg px-3 py-2 text-xs font-bold text-zinc-800 outline-none focus:border-blue-300"
                        />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[9px] font-black text-zinc-400 uppercase tracking-wider">Answer</label>
                        <textarea 
                          rows={2}
                          value={faq.answer}
                          onChange={(e) => handleFaqChange(idx, 'answer', e.target.value)}
                          placeholder="Provide a helpful, concise answer..."
                          className="w-full bg-white border border-zinc-100 rounded-lg p-3 text-xs font-medium text-zinc-600 outline-none focus:border-blue-300 resize-none"
                        />
                      </div>
                    </div>
                  ))}

                  <button 
                    onClick={addManualFaq}
                    className="w-full py-4 border-2 border-dashed border-zinc-100 rounded-2xl flex items-center justify-center gap-2 text-[10px] font-black text-zinc-400 uppercase tracking-widest hover:bg-zinc-50 hover:border-zinc-200 transition-all"
                  >
                    <Plus size={14}/> Add Manual Question
                  </button>
                </div>

                <ActionButton 
                  onClick={onExportSchema} 
                  label="Export JSON-LD Schema" 
                  icon={<FileCode size={16}/>} 
                  variant="secondary" 
                  className="bg-blue-50 text-blue-600 border-blue-100 hover:bg-blue-100"
                />
              </div>
            </div>
          </div>
        )}

        {activeTab === 'ai' && (
          <div className="space-y-8 animate-in fade-in slide-in-from-right-4 duration-500">
            <div className="flex items-center justify-between">
              <SectionHeader title="Gemini 3 Intelligence" />
              {isAIProcessing && <div className="w-5 h-5 border-3 border-blue-600 border-t-transparent rounded-full animate-spin" />}
            </div>

            <div className="grid grid-cols-1 gap-3">
              <ActionButton onClick={() => onRewrite('clarity')} label="Enhance Clarity" icon={<Sparkles size={16}/>} disabled={isAIProcessing} variant="ai" />
              <ActionButton onClick={() => onRewrite('concise')} label="Make Precise" icon={<BookOpen size={16}/>} disabled={isAIProcessing} variant="secondary" />
              <ActionButton onClick={() => onRewrite('expand_examples')} label="Add Case Studies" icon={<PlusCircle size={16}/>} disabled={isAIProcessing} variant="secondary" />
              <ActionButton onClick={() => onRewrite('humanize')} label="Rewrite Flow" icon={<ScanEye size={16}/>} disabled={isAIProcessing} variant="secondary" />
              <ActionButton onClick={() => onRewrite('authoritative')} label="Tone Up Expert" icon={<CheckCircle2 size={16}/>} disabled={isAIProcessing} variant="secondary" />
            </div>

            <div className="pt-8 border-t border-zinc-50">
              <SectionHeader title="Quality Check" />
              <ActionButton onClick={onDetectAI} label="Run AI Content Scan" icon={<ScanEye size={16}/>} disabled={isAIProcessing} variant="primary" />
            </div>

            <div className="p-6 bg-blue-50 border border-blue-100 rounded-3xl flex items-start gap-4">
              <Sparkles size={20} className="text-blue-600 shrink-0 mt-0.5" />
              <div className="space-y-1">
                <span className="text-[11px] font-black text-blue-700 uppercase tracking-wider block">AI Engine Active</span>
                <p className="text-[10px] text-blue-600/70 font-medium leading-relaxed">Powered by latest Gemini architecture for real-time content optimization.</p>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'tools' && (
          <div className="space-y-10 animate-in fade-in slide-in-from-right-4 duration-500">
             <div>
              <SectionHeader title="Text Processing" />
              <div className="grid grid-cols-2 gap-3">
                <ActionButton onClick={() => onConvertCase('upper')} label="UPPER" variant="secondary" />
                <ActionButton onClick={() => onConvertCase('lower')} label="lower" variant="secondary" />
                <ActionButton onClick={() => onConvertCase('sentence')} label="Sentence Case" variant="secondary" />
                <ActionButton onClick={() => onConvertCase('capitalize')} label="Capitalize" variant="secondary" />
              </div>
            </div>
            <div>
              <SectionHeader title="Export & Backup" />
              <div className="space-y-3">
                <ActionButton onClick={() => onCopy('plain')} label="Copy Clean Text" icon={<Copy size={14}/>} variant="primary" />
                <ActionButton onClick={() => onCopy('markdown')} label="Copy Markdown" icon={<Copy size={14}/>} variant="primary" />
                <ActionButton onClick={() => onCopy('html')} label="Copy HTML Code" icon={<FileCode size={14}/>} variant="primary" />
              </div>
              <div className="pt-8 mt-8 border-t border-zinc-50">
                <ActionButton onClick={onClear} label="Wipe Document" variant="danger" icon={<Trash2 size={16}/>} />
              </div>
            </div>
          </div>
        )}
      </div>
    </aside>
  );
};

