  const [metaDescription, setMetaDescription] = useState(() => localStorage.getItem('seo-meta-desc-v2') || '');
  const [targets, setTargets] = useState<KeywordTarget>(() => {
    const saved = localStorage.getItem('seo-targets-v2');
    return saved ? JSON.parse(saved) : { primary: '', secondary: ['', '', ''] };
  });
  const [faqs, setFaqs] = useState<FAQ[]>(() => {
    const saved = localStorage.getItem('seo-faqs-v2');
    return saved ? JSON.parse(saved) : [];
  });

  const deferredContent = useDeferredValue(content);

  // Persistence
  useEffect(() => {
    localStorage.setItem('seo-editor-content-v2', content);
    localStorage.setItem('seo-targets-v2', JSON.stringify(targets));
    localStorage.setItem('seo-meta-desc-v2', metaDescription);
    localStorage.setItem('seo-meta-title-v2', metaTitle);
    localStorage.setItem('seo-faqs-v2', JSON.stringify(faqs));
  }, [content, targets, metaDescription, metaTitle, faqs]);

  // Analysis Memoization
  const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
  const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
  const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
  const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, targets, metaDescription), [deferredContent, keywords, targets, metaDescription]);
  const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);
  const sentenceWarnings = useMemo(() => analyzeSentenceWarnings(deferredContent), [deferredContent]);

  const handleEditorChange = (newContent: string) => {
    startTransition(() => {
      setContent(newContent);
    });
  };

  const onRewrite = async (mode: RewriteMode) => {
    if (!editorInstance) return;
    const selectedText = editorInstance.getSelection();
    if (!selectedText) {
      alert("Please select text within the editor to use AI rewriting features.");
      return;
    }
    setIsAIProcessing(true);
    try {
      const results = await rewriteContent(selectedText, mode);
      if (results && results.length > 0) {
        editorInstance.insertContent(results[0]);
      }
    } catch (err) {
      console.error("AI Rewrite Failed:", err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleReportSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const adminEmail = 'rathod.shivang@gmail.com';
    const mailtoLink = `mailto:${adminEmail}?subject=Issue Report: ${encodeURIComponent(reportHeadline)}&body=${encodeURIComponent(reportSummary)}`;
    window.location.href = mailtoLink;
    setReportHeadline('');
    setReportSummary('');
    setShowReportModal(false);
    alert('Thank you! Your issue report has been prepared for sending to rathod.shivang@gmail.com.');
  };

  return (
    <div className="flex h-screen w-full bg-white overflow-hidden text-zinc-900 selection:bg-blue-100">
      {/* Report Modal */}
      {showReportModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-md p-4 animate-in fade-in duration-300">
          <div className="bg-white border border-zinc-200 rounded-[32px] w-full max-w-md shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b border-zinc-50 flex items-center justify-between">
              <h3 className="font-black text-xl uppercase tracking-tighter text-zinc-900 flex items-center gap-2">
                <AlertCircle size={24} className="text-red-500" />
                Report Issue
              </h3>
              <button onClick={() => setShowReportModal(false)} className="text-zinc-400 hover:text-zinc-900 transition-colors">
                <X size={24}/>
              </button>
            </div>
            <form onSubmit={handleReportSubmit} className="p-8 space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-zinc-400 ml-1">Headline</label>
                <input required type="text" value={reportHeadline} onChange={(e) => setReportHeadline(e.target.value)} placeholder="Summarize the issue..." className="w-full px-6 py-4 bg-zinc-50 border border-zinc-100 rounded-2xl outline-none focus:border-blue-500 transition-all font-bold" />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-zinc-400 ml-1">Summary</label>
                <textarea required rows={4} value={reportSummary} onChange={(e) => setReportSummary(e.target.value)} placeholder="Describe what happened in detail..." className="w-full px-6 py-4 bg-zinc-50 border border-zinc-100 rounded-2xl outline-none focus:border-blue-500 transition-all font-medium resize-none" />
              </div>
              <button type="submit" className="w-full py-5 bg-zinc-900 text-white rounded-2xl font-black uppercase tracking-widest text-xs flex items-center justify-center gap-3 shadow-xl hover:bg-black transition-all active:scale-95">
                <Send size={16} /> Submit Report
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Main Editor Viewport */}
      <div className="flex-1 flex flex-col min-w-0 border-r border-zinc-100 bg-zinc-50/50">
        <header className="h-16 border-b border-zinc-100 px-8 flex items-center justify-between bg-white shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-black shadow-lg shadow-blue-500/20">S</div>
            <h1 className="font-black tracking-tighter text-lg uppercase">SEO Focus <span className="text-zinc-300 font-medium">Editor</span></h1>
          </div>
          <button onClick={() => setShowReportModal(true)} className="flex items-center gap-2 px-5 py-2 bg-red-50 hover:bg-red-100 rounded-full border border-red-100 transition-all text-red-600 group">
            <AlertCircle size={14} className="group-hover:scale-110 transition-transform" />
            <span className="text-[10px] font-black uppercase tracking-widest">Report Issues</span>
          </button>
        </header>

        <div className="flex-1 flex flex-col overflow-hidden relative">
          <div className="toolbar-container bg-white border-b border-zinc-100">
            <Toolbar 
              editorInstance={editorInstance} 
              stats={stats}
              wordTarget={wordTarget}
              onUpdate={() => handleEditorChange(editorInstance?.getContent() || '')}
              onNewDocument={() => confirm("Clear all content?") && editorInstance?.setContent('')}
              onShowHistory={() => {}} 
              onSaveVersion={() => {}}
              viewMode="focused"
            />
          </div>
          <main className="flex-1 overflow-hidden flex justify-center relative p-8">
            <div className="w-full max-w-[900px] h-full overflow-hidden bg-white relative rounded-[2px] shadow-sm border border-zinc-200/50">
              <Editor initialContent={content} onUpdate={handleEditorChange} onInit={setEditorInstance} onAIAssist={onRewrite} />
            </div>
          </main>
        </div>
      </div>

      <Sidebar 
        activeTab={activeTab} setActiveTab={setActiveTab} 
        stats={stats} readability={readability} health={health} intent={intent} keywords={keywords} 
        seoTab={seoTab} setSeoTab={setSeoTab} isExpanded={isExpanded} setIsExpanded={setIsExpanded} 
        onRewrite={onRewrite} 
        onConvertCase={(type) => editorInstance?.insertContent(convertText(editorInstance?.getSelection(), type))} 
        onCopy={(type) => {
          let output = content;
          if (type === 'markdown') output = htmlToMarkdown(content);
          else if (type === 'plain') output = content.replace(/<[^>]*>/g, '');
          navigator.clipboard.writeText(output);
        }} 
        onClear={() => confirm("Delete all?") && editorInstance?.setContent('')} 
        isAIProcessing={isAIProcessing} targets={targets} setTargets={setTargets}
        metaTitle={metaTitle} setMetaTitle={setMetaTitle} metaDescription={metaDescription} setMetaDescription={setMetaDescription}
        faqs={faqs} setFaqs={setFaqs}
        onGenerateMetadata={async (type) => {
          setIsAIProcessing(true);
          try {
            const res = await generateMetadata(content, type);
            if (type === 'title') setMetaTitle(res); else setMetaDescription(res);
          } finally { setIsAIProcessing(false); }
        }}
        onDetectAI={async () => {
          setIsAIProcessing(true);
          try {
            const res = await detectAIContent(content);
            alert(`AI Detection Score: ${res.score}%`);
          } finally { setIsAIProcessing(false); }
        }}
        onGenerateFAQs={async () => {
          setIsAIProcessing(true);
          try {
            const res = await generateFAQs(content);
            setFaqs(res);
          } finally { setIsAIProcessing(false); }
        }}
        onExportSchema={() => {
           navigator.clipboard.writeText(JSON.stringify({ "@context": "https://schema.org", "@type": "Article", "headline": metaTitle, "description": metaDescription }, null, 2));
           alert('Schema Copied');
        }}
        onNavigateOutline={(text) => editorInstance?.scrollToText(text)}
        sentenceWarnings={sentenceWarnings}
      />
    </div>
  );
}

import React from 'react';
import { BarChart3, Target, Activity, Sparkles, Settings } from 'lucide-react';
import { Tab, SEOPhraseTab, TextStats, ReadabilityInsights, KeywordDensity, SEOHealth, IntentResult, KeywordTarget, FAQ, SentenceWarnings } from '../../types/editor.types';

// Sub-components
import { InsightsTab } from './sidebar/InsightsTab.tsx';
import { KeywordsTab } from './sidebar/KeywordsTab.tsx';
import { SEOTab } from './sidebar/SEOTab.tsx';
import { AITab } from './sidebar/AITab.tsx';
import { ToolsTab } from './sidebar/ToolsTab.tsx';

interface SidebarProps {
  activeTab: Tab;
  setActiveTab: (tab: Tab) => void;
  stats: TextStats;
  readability: ReadabilityInsights | null;
  health: SEOHealth;
  intent: IntentResult;
  keywords: KeywordDensity[];
  seoTab: SEOPhraseTab;
  setSeoTab: (num: SEOPhraseTab) => void;
  isExpanded: boolean;
  setIsExpanded: (val: boolean) => void;
  onRewrite: (mode: any) => void;
  onConvertCase: (type: string) => void;
  onCopy: (type: 'plain' | 'markdown' | 'html') => void;
  onClear: () => void;
  isAIProcessing?: boolean;
  targets: KeywordTarget;
  setTargets: (t: KeywordTarget) => void;
  metaTitle: string;
  setMetaTitle: (s: string) => void;
  metaDescription: string;
  setMetaDescription: (s: string) => void;
  faqs: FAQ[];
  setFaqs: (f: FAQ[]) => void;
  onGenerateMetadata: (type: 'title' | 'description') => void;
  onDetectAI: () => void;
  onGenerateFAQs: () => void;
  onExportSchema: () => void;
  onNavigateOutline?: (text: string) => void;
  sentenceWarnings?: SentenceWarnings;
}

const TabButton = ({ active, onClick, label, icon }: any) => (
  <button onClick={onClick} className={`flex-1 flex flex-col items-center justify-center gap-1 text-[10px] font-black uppercase tracking-tighter relative py-5 transition-all ${active ? 'text-blue-600' : 'text-zinc-400 hover:text-zinc-600'}`}>
    {icon}
    <span className="hidden lg:inline">{label}</span>
    {active && <div className="absolute bottom-0 left-4 right-4 h-0.5 bg-blue-600 rounded-t-full" />}
  </button>
);

export const Sidebar = (props: SidebarProps) => {
  const { activeTab, setActiveTab } = props;

  return (
    <aside className="w-full md:w-80 lg:w-[400px] border-l border-zinc-100 flex flex-col bg-white shrink-0 h-screen overflow-hidden">
      <div className="flex border-b border-zinc-100 shrink-0 bg-white">
        <TabButton active={activeTab === 'insights'} onClick={() => setActiveTab('insights')} label="Insights" icon={<BarChart3 size={18} />} />
        <TabButton active={activeTab === 'keywords'} onClick={() => setActiveTab('keywords')} label="Keywords" icon={<Target size={18} />} />
        <TabButton active={activeTab === 'seo'} onClick={() => setActiveTab('seo')} label="SEO" icon={<Activity size={18} />} />
        <TabButton active={activeTab === 'ai'} onClick={() => setActiveTab('ai')} label="AI Assistant" icon={<Sparkles size={18} />} />
        <TabButton active={activeTab === 'tools'} onClick={() => setActiveTab('tools')} label="Tools" icon={<Settings size={18} />} />
      </div>

      <div className="flex-1 overflow-y-auto custom-scrollbar p-8 space-y-10 pb-32">
        {activeTab === 'insights' && <InsightsTab {...props} />}
        {activeTab === 'keywords' && <KeywordsTab {...props} />}
        {activeTab === 'seo' && <SEOTab {...props} />}
        {activeTab === 'ai' && <AITab {...props} />}
        {activeTab === 'tools' && <ToolsTab {...props} />}
      </div>
    </aside>
  );
};

import React, { useState } from 'react';
import { Sparkles, Cpu, AlertTriangle, Info, ChevronDown, Flag } from 'lucide-react';
import { TextStats, ReadabilityInsights, SEOHealth, SentenceWarnings, SentenceIssue } from '../../../types/editor.types';

interface InsightsTabProps {
  stats: TextStats;
  readability: ReadabilityInsights | null;
  health: SEOHealth;
  onNavigateOutline?: (text: string) => void;
  sentenceWarnings?: SentenceWarnings;
}

const StatCard = ({ label, value }: any) => (
  <div className="p-5 bg-white border border-zinc-100 rounded-2xl shadow-sm shadow-zinc-200/50">
    <div className="text-[10px] font-black text-zinc-400 uppercase mb-1.5 tracking-widest">{label}</div>
    <div className="text-2xl font-black tracking-tighter text-zinc-900">{value}</div>
  </div>
);

const WarningGroup = ({ title, items, colorClass, onNavigate }: { title: string, items: SentenceIssue[], colorClass: string, onNavigate?: (t: string) => void }) => {
  const [isOpen, setIsOpen] = useState(false);
  if (items.length === 0) return null;

  return (
    <div className={`border rounded-2xl overflow-hidden bg-white mb-3 ${colorClass}`}>
      <button 
        onClick={() => setIsOpen(!isOpen)} 
        className="w-full flex items-center justify-between p-4 hover:bg-opacity-50 transition-colors"
      >
        <div className="flex items-center gap-3">
          <div className="w-6 h-6 rounded-full bg-current opacity-10 flex items-center justify-center">
            <span className="text-[10px] font-black opacity-100">{items.length}</span>
          </div>
          <span className="text-[11px] font-black uppercase tracking-wider opacity-80">{title}</span>
        </div>
        <ChevronDown size={14} className={`opacity-50 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
      </button>
      {isOpen && (
        <div className="border-t border-current border-opacity-10">
          {items.map((item, idx) => (
            <button 
              key={idx}
              onClick={() => onNavigate?.(item.text)}
              className="w-full text-left p-3 text-xs hover:bg-black/5 transition-colors border-b last:border-0 border-current border-opacity-5"
            >
              <div className="font-medium opacity-90 line-clamp-2">"...{item.preview}"</div>
              <div className="mt-1 opacity-50 text-[10px] font-bold uppercase tracking-wider">
                {item.count ? `${item.count} items` : `Sentence #${item.index + 1}`}
              </div>
            </button>
          ))}
        </div>
      )}
    </div>
  );
};

export const InsightsTab = ({ stats, readability, health, onNavigateOutline, sentenceWarnings }: InsightsTabProps) => {
  const h1Count = stats.headingTree.filter(h => h.tag === 'h1').length;
  const h2Count = stats.headingTree.filter(h => h.tag === 'h2').length;
  const h3Count = stats.headingTree.filter(h => h.tag === 'h3').length;

  return (
    <div className="space-y-10 animate-in fade-in slide-in-from-right-4 duration-500">
      {/* 1. Content Score Badge */}
      <div className="p-6 bg-white border-2 border-zinc-900 rounded-[32px] text-zinc-900 shadow-xl shadow-zinc-900/5">
        <div className="flex items-center justify-between mb-4">
          <span className="text-[10px] font-black uppercase tracking-[0.25em] text-zinc-400">Content Score</span>
          <Sparkles size={16} className="text-blue-500" />
        </div>
        <div className="flex items-end gap-3 mb-6">
          <div className="text-6xl font-black tracking-tighter leading-none">{health.score}</div>
          <div className="text-xl font-black text-zinc-300 pb-1">/100</div>
        </div>
        <div className="h-1.5 bg-zinc-100 rounded-full overflow-hidden mb-4">
          <div 
            className="h-full bg-zinc-900 transition-all duration-1000 ease-out" 
            style={{ width: `${health.score}%` }} 
          />
        </div>
        <p className="text-[10px] font-bold text-zinc-400 leading-relaxed">
          Aggregated overall health based on structural and semantic analysis.
        </p>
      </div>

      {/* 2. Sentence Warnings Section */}
      {sentenceWarnings && (
        <div className="space-y-4">
          <h3 className="text-[10px] font-black text-zinc-300 uppercase tracking-[0.25em] flex items-center gap-2">
            Sentence Warnings
            <Flag size={12} className="text-zinc-300" />
          </h3>
          <div className="bg-yellow-50/50 p-4 rounded-[24px] border border-yellow-100">
            {/* Very Long Sentences */}
            <WarningGroup 
              title="Very Long (>35w)" 
              items={sentenceWarnings.veryLongSentences} 
              colorClass="border-red-100 text-red-600" 
              onNavigate={onNavigateOutline}
            />
            {/* Long Sentences */}
            <WarningGroup 
              title="Long (>25w)" 
              items={sentenceWarnings.longSentences} 
              colorClass="border-yellow-100 text-yellow-600" 
              onNavigate={onNavigateOutline}
            />
            {/* Consecutive Long */}
            <WarningGroup 
              title="Consecutive Long" 
              items={sentenceWarnings.consecutiveLong} 
              colorClass="border-orange-100 text-orange-600" 
              onNavigate={onNavigateOutline}
            />
            {/* Passive Voice */}
            <WarningGroup 
              title="Passive Voice" 
              items={sentenceWarnings.passiveVoice} 
              colorClass="border-blue-100 text-blue-600" 
              onNavigate={onNavigateOutline}
            />
             {/* Comma Overload */}
            <WarningGroup 
              title="Comma Overload" 
              items={sentenceWarnings.commaOverload} 
              colorClass="border-purple-100 text-purple-600" 
              onNavigate={onNavigateOutline}
            />
             {/* Repetitive Openings */}
            <WarningGroup 
              title="Repetitive Openings" 
              items={sentenceWarnings.repetitiveOpenings} 
              colorClass="border-pink-100 text-pink-600" 
              onNavigate={onNavigateOutline}
            />

            {Object.values(sentenceWarnings).every(arr => arr.length === 0) && (
              <div className="text-center py-4 text-xs font-bold text-yellow-600/50 italic">
                No sentence issues detected. Great writing!
              </div>
            )}
          </div>
        </div>
      )}

      <div className="space-y-5">
        <h3 className="text-[10px] font-black text-zinc-300 uppercase tracking-[0.25em]">Readability Analysis</h3>
        <div className="grid grid-cols-2 gap-4">
          {readability && (
            <div className="col-span-2 p-5 bg-white border border-zinc-100 rounded-2xl shadow-sm shadow-zinc-200/50">
              <div className="flex items-center justify-between mb-4">
                <div>
                  <div className="text-[10px] font-black text-zinc-400 uppercase mb-1.5 tracking-widest">Ease Score</div>
                  <div className={`text-4xl font-black tracking-tighter ${readability.color}`}>
                    {readability.score}
                  </div>
                </div>
                <div className="text-right">
                  <div className="text-[11px] font-black uppercase text-zinc-900 tracking-wider mb-1">
                    {readability.level}
                  </div>
                  <p className="text-[10px] text-zinc-400 leading-tight italic max-w-[150px]">
                    {readability.description}
                  </p>
                </div>
              </div>
              {/* 2. Visual Bar Gradient */}
              <div className="h-2 bg-zinc-100 rounded-full overflow-hidden relative">
                <div className="absolute inset-0 bg-gradient-to-r from-red-500 via-yellow-500 to-green-500 opacity-20" />
                <div 
                  className={`h-full relative z-10 transition-all duration-700 ${readability.score > 60 ? 'bg-emerald-500' : readability.score > 30 ? 'bg-yellow-500' : 'bg-red-500'}`}
                  style={{ width: `${readability.score}%` }}
                />
              </div>
            </div>
          )}
          <StatCard label="Total Words" value={stats.words} />
          <StatCard label="Read Time" value={`${stats.readingTime}m`} />
          <StatCard label="Sentences" value={stats.sentences} />
          <StatCard label="Paragraphs" value={stats.paragraphs} />
        </div>
      </div>

      <div className="space-y-5">
        <h3 className="text-[10px] font-black text-zinc-300 uppercase tracking-[0.25em]">Heading Structure</h3>
        <div className="grid grid-cols-3 gap-3">
          <div className={`p-4 border rounded-2xl text-center ${h1Count === 1 ? 'border-emerald-100 bg-emerald-50 text-emerald-600' : 'border-red-100 bg-red-50 text-red-600'}`}>
             <div className="text-[9px] font-black uppercase tracking-tighter opacity-70">H1</div>
             <div className="text-lg font-black">{h1Count}</div>
          </div>
          <div className="p-4 border border-zinc-100 rounded-2xl text-center bg-white">
             <div className="text-[9px] font-black uppercase tracking-tighter text-zinc-400">H2</div>
             <div className="text-lg font-black text-zinc-800">{h2Count}</div>
          </div>
          <div className="p-4 border border-zinc-100 rounded-2xl text-center bg-white">
             <div className="text-[9px] font-black uppercase tracking-tighter text-zinc-400">H3</div>
             <div className="text-lg font-black text-zinc-800">{h3Count}</div>
          </div>
        </div>

        {/* 4. Heading Alerts */}
        {(h1Count !== 1 || (h3Count > 0 && h2Count === 0)) && (
          <div className="space-y-3 pt-2">
            {h1Count === 0 && (
              <div className="flex items-start gap-3 p-4 bg-red-50 border border-red-100 rounded-xl">
                <AlertTriangle size={16} className="text-red-500 shrink-0 mt-0.5" />
                <div>
                  <div className="text-[11px] font-black text-red-700 uppercase">Missing H1 Title</div>
                  <p className="text-[10px] text-red-600/70 font-medium">Critical for SEO. Every page needs exactly one H1.</p>
