            {h3Count > 0 && h2Count === 0 && (
              <div className="flex items-start gap-3 p-4 bg-zinc-50 border border-zinc-100 rounded-xl">
                <Info size={16} className="text-zinc-400 shrink-0 mt-0.5" />
                <div>
                  <div className="text-[11px] font-black text-zinc-700 uppercase">Improper Nesting</div>
                  <p className="text-[10px] text-zinc-500/70 font-medium">H3 detected without an H2. Use a proper hierarchy.</p>
                </div>
              </div>
            )}
          </div>
        )}

        <div className="bg-zinc-50 p-6 rounded-[24px] border border-zinc-100">
          <div className="space-y-3">
            {stats.headingTree.length > 0 ? stats.headingTree.map((h, i) => (
              <button key={i} onClick={() => onNavigateOutline?.(h.text)} className="w-full text-left flex gap-3 items-center group" style={{ paddingLeft: `${(h.level - 1) * 16}px` }}>
                <span className="text-[9px] font-black text-blue-600 bg-blue-50 px-1.5 py-0.5 rounded uppercase shrink-0">{h.tag}</span>
                <span className="text-xs font-bold text-zinc-500 line-clamp-1 group-hover:text-blue-600 transition-colors">{h.text}</span>
              </button>
            )) : <div className="text-[11px] text-zinc-400 italic text-center">No structure yet.</div>}
          </div>
        </div>
      </div>

      <div className="space-y-5">
        <h3 className="text-[10px] font-black text-zinc-300 uppercase tracking-[0.25em]">NLP Terms</h3>
        <div className="flex flex-wrap gap-2">
          {stats.entities.length > 0 ? stats.entities.map((entity, i) => (
            <div key={i} className="px-3 py-1.5 bg-white border border-zinc-100 rounded-full text-[10px] font-bold text-zinc-600 flex items-center gap-1.5 shadow-sm">
              <Cpu size={10} className="text-blue-500" /> {entity}
            </div>
          )) : <div className="text-[11px] text-zinc-400 italic text-center w-full">No entities detected.</div>}
        </div>
      </div>
    </div>
  );
};

import { SentenceWarnings, SentenceIssue } from '../types/editor.types';

export const analyzeSentenceWarnings = (html: string): SentenceWarnings => {
  const cleanText = html.replace(/<[^>]*>/g, ' ').trim();

  // Split sentences while preserving some structure to identify them later
  // This is a basic split, typically sufficient for in-browser analysis
  const rawSentences: string[] = cleanText.match(/[^.!?]+[.!?]+/g) || [];

  const warnings: SentenceWarnings = {
    longSentences: [],
    veryLongSentences: [],
    consecutiveLong: [],
    commaOverload: [],
    passiveVoice: [],
    repetitiveOpenings: []
  };

  if (rawSentences.length === 0) return warnings;

  let previousWasLong = false;
  let previousStartWord = '';
  let consecutiveStartCount = 0;

  rawSentences.forEach((sentence, index) => {
    const trimmed = sentence.trim();
    if (!trimmed) return;

    const words = trimmed.split(/\s+/).filter(w => w.length > 0);
    const wordCount = words.length;
    const isLong = wordCount > 25;
    const isVeryLong = wordCount > 35;

    // Create Issue Object
    const issue: SentenceIssue = {
      text: trimmed,
      preview: words.slice(0, 6).join(' ') + '...',
      index,
      count: wordCount
    };

    // 1. Long & Very Long Sentences
    if (isVeryLong) {
      warnings.veryLongSentences.push(issue);
    } else if (isLong) {
      warnings.longSentences.push(issue);
    }

    // 2. Consecutive Long Sentences
    if (isLong && previousWasLong) {
      // Avoid duplicating the previous one if it was already flagged in a chain
      // Just flag the current one as part of a chain
      warnings.consecutiveLong.push(issue);
    }
    previousWasLong = isLong;

    // 3. Excessive Commas
    const commaCount = (trimmed.match(/,/g) || []).length;
    if (commaCount >= 4) {
      warnings.commaOverload.push({ ...issue, count: commaCount });
    }

    // 4. Passive Voice
    // Basic detection: form of "to be" + past tense (ending in ed)
    // This is a heuristic and not 100% grammatically accurate but standard for SEO tools
    if (/\b(was|were|is|been|being)\s+\w+ed\b/i.test(trimmed)) {
      warnings.passiveVoice.push(issue);
    }

    // 5. Repetitive Openings
    const startWord = words[0]?.toLowerCase().replace(/[^a-z]/g, '') || '';
    if (startWord && startWord === previousStartWord && startWord.length > 3) {
      consecutiveStartCount++;
      if (consecutiveStartCount >= 2) { // 3rd sentence with same start (0-indexed logic: 1st match makes count 1, 2nd match makes count 2)
         warnings.repetitiveOpenings.push(issue);
      }
    } else {
      consecutiveStartCount = 0;
    }
    previousStartWord = startWord;
  });

  return warnings;
};

