import { KeywordDensity } from '../types/editor.types';
import { STOP_WORDS } from './stopwords';

export const getKeywords = (html: string, n: number = 1): KeywordDensity[] => {
  const cleanText = html.replace(/<[^>]*>/g, ' '); // Keep spaces
  // Tokenize based on word boundaries, ignoring punctuation but keeping structure
  const tokens = cleanText.match(/\b[\w']+\b/g) || [];

  const totalTokens = tokens.length;

  if (totalTokens === 0) return [];

  const phrasesMap: Record<string, { count: number; display: string }> = {};

  for (let i = 0; i <= tokens.length - n; i++) {
    const phraseTokens = tokens.slice(i, i + n);

    // Check stop words - if any word in the phrase is a stop word (for 1-gram) or strictly stop words logic for n-grams
    // For n > 1, we usually allow stop words in between, but let's stick to the previous logic:
    // If it's a 1-word phrase and it's a stop word, skip.
    // If it's an n-gram, usually we don't filter strict stop words unless it starts/ends with them, 
    // but to keep it simple and consistent with previous behavior:
    if (n === 1 && STOP_WORDS.has(phraseTokens[0].toLowerCase())) {
      continue;
    }

    // For n-grams, maybe skip if it's purely stop words? 
    // Let's rely on the previous logic: if ANY word is a stop word, skip (aggressive).
    // Or better: Filter if the phrase is meaningless.
    // Reverting to previous logic: if any word is a stop word, skip.
    if (phraseTokens.some(word => STOP_WORDS.has(word.toLowerCase()))) {
      continue;
    }

    const originalPhrase = phraseTokens.join(' ');
    const lowerPhrase = originalPhrase.toLowerCase();

    if (!phrasesMap[lowerPhrase]) {
      phrasesMap[lowerPhrase] = { count: 0, display: originalPhrase };
    }

    phrasesMap[lowerPhrase].count += 1;
    // Optional: Update display to most frequent casing? For now, first found is fine.
  }

  return Object.values(phrasesMap)
    .map(({ display, count }) => ({
      phrase: display,
      count,
      percentage: Number(((count * n) / totalTokens * 100).toFixed(2))
    }))
    .sort((a, b) => b.count - a.count);
};

import { SEOHealth, KeywordDensity, SEOChecklistItem, KeywordTarget } from '../types/editor.types';

export const analyzeSEOHealth = (
  html: string, 
  keywords: KeywordDensity[], 
  targets: KeywordTarget,
  metaDescription: string,
  metaTitle: string = ""
): SEOHealth => {
  const warnings: string[] = [];
  const checklist: SEOChecklistItem[] = [];
  let score = 100;
  let prominenceScore = 0;

  const cleanText = html.replace(/<[^>]*>/g, ' ').trim();
  const first100Words = cleanText.split(/\s+/).slice(0, 100).join(' ').toLowerCase();
  const primaryK = targets.primary.toLowerCase();

  // --- Prominence Score Calculation (0-100) ---
  if (primaryK) {
    // 1. In H1 (20pts)
    const h1Match = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
    const hasInH1 = h1Match ? h1Match[1].toLowerCase().includes(primaryK) : false;
    if (hasInH1) prominenceScore += 20;

    checklist.push({ label: `Primary keyword in H1`, passed: hasInH1, impact: 'critical' });
    if (!hasInH1) score -= 15;

    // 2. In First 100 Words (20pts)
    const hasInIntro = first100Words.includes(primaryK);
    if (hasInIntro) prominenceScore += 20;

    checklist.push({ label: `Primary keyword in intro`, passed: hasInIntro, impact: 'moderate' });
    if (!hasInIntro) score -= 10;

    // 3. In H2 (20pts)
    const h2Matches: string[] = html.match(/<h2[^>]*>([\s\S]*?)<\/h2>/gi) || [];
    const hasInH2 = h2Matches.some(h => h.toLowerCase().includes(primaryK));
    if (hasInH2) prominenceScore += 20;

    checklist.push({ label: `Primary keyword in H2`, passed: hasInH2, impact: 'moderate' });
    if (!hasInH2) score -= 5;

    // 4. In Meta Title (20pts)
    const hasInTitle = metaTitle.toLowerCase().includes(primaryK);
    if (hasInTitle) prominenceScore += 20;

    // 5. In Meta Description (20pts)
    const hasInMeta = metaDescription.toLowerCase().includes(primaryK);
    if (hasInMeta) prominenceScore += 20;

    checklist.push({ label: `Primary keyword in meta description`, passed: hasInMeta, impact: 'moderate' });
    if (!hasInMeta) score -= 10;
  }

  // Structural Checks
  const h1Count = (html.match(/<h1/gi) || []).length;
  if (h1Count === 0) { warnings.push("Missing H1 title tag."); score -= 20; }
  if (h1Count > 1) { warnings.push("Multiple H1 tags detected."); score -= 15; }

  const h2Count = (html.match(/<h2/gi) || []).length;
  const h3Count = (html.match(/<h3/gi) || []).length;
  if (h2Count === 0 && h3Count === 0) { warnings.push("Lack of sub-heading structure (H2/H3)."); score -= 10; }

  // Keyword Stuffing check (General)
  const overUsed = keywords.filter(k => k.percentage > 3.5); // Relaxed slightly as we have color coding now
  if (overUsed.length > 0) {
    warnings.push(`Keyword stuffing detected: "${overUsed[0].phrase}".`);
    score -= 15;
  }

  // Content Length
  const wordCount = cleanText.split(/\s+/).length;
  if (wordCount < 300) { warnings.push("Content is thin (<300 words)."); score -= 15; }

  score = Math.max(0, score);

  let status: SEOHealth['status'] = 'excellent';
  if (score < 50) status = 'poor';
  else if (score < 70) status = 'fair';
  else if (score < 90) status = 'good';

  return { score, warnings, status, checklist, prominenceScore };
};

import { TextStats, SEOHealth, ReadabilityInsights, SentenceWarnings, KeywordTarget, OptimizationReport, OptimizationItem, KeywordDensity } from '../types/editor.types';

export const generateOptimizationReport = (
    stats: TextStats,
    health: SEOHealth,
    readability: ReadabilityInsights | null,
    sentenceWarnings: SentenceWarnings,
    targets: KeywordTarget,
    metaTitle: string,
    metaDescription: string,
    faqsCount: number,
    keywords: KeywordDensity[]
): OptimizationReport => {
    const critical: OptimizationItem[] = [];
    const improvements: OptimizationItem[] = [];
    const enhancements: OptimizationItem[] = [];

    const primaryK = targets.primary.toLowerCase();
    const primaryDensity = keywords.find(k => k.phrase.toLowerCase() === primaryK)?.percentage || 0;

    // --- Critical Issues (Priority 1) ---
    const h1Count = stats.headingTree.filter(h => h.tag === 'h1').length;
    if (h1Count === 0) {
        critical.push({ id: 'c-h1-missing', title: 'Missing H1 Tag', description: 'Search engines need one main heading to understand the topic.', priority: 1, source: 'heading' });
    } else if (h1Count > 1) {
        critical.push({ id: 'c-h1-multi', title: 'Multiple H1 Tags', description: 'Use only one H1 tag per page to avoid confusion.', priority: 1, source: 'heading' });
    }

    if (!targets.primary) {
        critical.push({ id: 'c-key-missing', title: 'Set Primary Keyword', description: 'Define a target keyword to analyze ranking potential.', priority: 1, source: 'keyword' });
    } else {
        if (primaryDensity < 0.3) {
            critical.push({ id: 'c-dens-low', title: 'Primary Keyword Density Low', description: `Current density is ${primaryDensity}%. Aim for at least 0.8%.`, priority: 1, source: 'keyword' });
        }
        if (primaryDensity > 3) {
            critical.push({ id: 'c-dens-high', title: 'Primary Keyword Stuffing', description: `Density is ${primaryDensity}%. Reduce usage to avoid penalties (aim for < 2.5%).`, priority: 1, source: 'keyword' });
        }
    }

    if (health.score < 50) {
        critical.push({ id: 'c-seo-score', title: 'Critical SEO Score', description: 'Your overall SEO health is very low.', priority: 1, source: 'seo' });
    }

    if (!metaTitle) {
        critical.push({ id: 'c-meta-title', title: 'Missing Meta Title', description: 'Required for search results display.', priority: 1, source: 'seo' });
    }

    if (sentenceWarnings.veryLongSentences.length > 3) {
        critical.push({ id: 'c-long-sent', title: 'Hard to Read', description: `${sentenceWarnings.veryLongSentences.length} sentences are extremely long (>35 words).`, priority: 1, source: 'readability' });
    }

    // --- Improvements (Priority 2) ---

    if (targets.primary) {
        // Prominence checks
        if (health.prominenceScore < 60) {
             improvements.push({ id: 'i-prominence', title: 'Low Keyword Prominence', description: 'Ensure primary keyword appears in Title, H1, and first 100 words.', priority: 2, source: 'keyword' });
        }

        // Secondary checks
        const activeSecondaries = targets.secondary.filter(s => s.trim().length > 0);
        if (activeSecondaries.length === 0) {
             improvements.push({ id: 'i-sec-missing', title: 'Add Secondary Keywords', description: 'Targeting secondary keywords helps capture long-tail traffic.', priority: 2, source: 'keyword' });
        } else {
             // Check if any secondary is unused
             const unused = activeSecondaries.filter(sk => !keywords.some(k => k.phrase.toLowerCase() === sk.toLowerCase()));
             if (unused.length > 0) {
                 improvements.push({ id: 'i-sec-unused', title: 'Unused Secondary Keywords', description: `You haven't used: ${unused.join(', ')}`, priority: 2, source: 'keyword' });
             }
        }
    }

    if (health.score >= 50 && health.score < 80) {
        improvements.push({ id: 'i-seo-score', title: 'Improve SEO Score', description: 'Aim for a score of 80+ for better ranking potential.', priority: 2, source: 'seo' });
    }

    if (readability && readability.score < 60) {
        improvements.push({ id: 'i-readability', title: 'Improve Readability', description: 'Content is difficult to read for general audiences.', priority: 2, source: 'readability' });
    }

    if (sentenceWarnings.passiveVoice.length > 5) {
        improvements.push({ id: 'i-passive', title: 'Reduce Passive Voice', description: 'Active voice is more engaging and direct.', priority: 2, source: 'readability' });
    }

    const h2Count = stats.headingTree.filter(h => h.tag === 'h2').length;
    if (h2Count === 0 && stats.words > 300) {
        improvements.push({ id: 'i-h2-missing', title: 'Add Subheadings (H2)', description: 'Break up text with H2 headers for better scanning.', priority: 2, source: 'heading' });
    }

    if (stats.words < 300) {
        improvements.push({ id: 'i-word-count', title: 'Increase Word Count', description: 'Content is too thin (<300 words) to rank well.', priority: 2, source: 'content' });
    }

    // --- Enhancements (Priority 3) ---
    if (targets.primary && !stats.headingTree.some(h => h.tag === 'h2' && h.text.toLowerCase().includes(primaryK))) {
        enhancements.push({ id: 'e-h2-key', title: 'Keyword in Subheading', description: 'Add primary keyword to at least one H2.', priority: 3, source: 'keyword' });
    }

    if (faqsCount === 0) {
        enhancements.push({ id: 'e-faq', title: 'Add FAQ Schema', description: 'FAQ Schema helps capture rich snippets in SERPs.', priority: 3, source: 'seo' });
    }

    if (metaDescription && metaDescription.length < 120) {
        enhancements.push({ id: 'e-meta-desc', title: 'Expand Meta Description', description: 'Too short. Aim for 150-160 characters.', priority: 3, source: 'seo' });
    }

    return { critical, improvements, enhancements };
}

import React, { useEffect, useState, useRef, useCallback } from 'react';
import { KeywordTarget } from '../../types/editor.types';

interface EditorProps {
  initialContent: string;
  onUpdate: (html: string) => void;
  onInit: (instance: any) => void;
  onAIAssist: (mode: any) => void;
}

export const Editor = ({ initialContent, onUpdate, onInit, onAIAssist }: EditorProps) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const lastContentEmitted = useRef(initialContent);
  const [isHighlighting, setIsHighlighting] = useState(false);

  const analyzeParagraphs = useCallback(() => {
    if (!editorRef.current) return;
    const paras = editorRef.current.querySelectorAll('p');
    paras.forEach(p => {
      const words = p.innerText.trim().split(/\s+/).filter(Boolean).length;
      if (words > 150) {
        p.classList.add('para-warning');
      } else {
        p.classList.remove('para-warning');
      }
    });
  }, []);

  const emitUpdate = useCallback(() => {
    if (editorRef.current) {
      const html = editorRef.current.innerHTML;
      lastContentEmitted.current = html;
      onUpdate(html);
      analyzeParagraphs();
    }
  }, [onUpdate, analyzeParagraphs]);

  // Expose Editor API to Parent
  useEffect(() => {
    if (editorRef.current) {
      editorRef.current.innerHTML = initialContent;
      lastContentEmitted.current = initialContent;

      const instance = {
        getContent: () => editorRef.current?.innerHTML || '',
        setContent: (html: string) => {
          if (editorRef.current) {
            editorRef.current.innerHTML = html;
            emitUpdate();
          }
        },
        execCommand: (cmd: string, ui: boolean, val: any) => {
          editorRef.current?.focus();
          document.execCommand(cmd, ui, val);
          emitUpdate();
        },
        insertContent: (html: string) => {
          editorRef.current?.focus();
          const sel = window.getSelection();
          if (sel && sel.rangeCount > 0) {
            const range = sel.getRangeAt(0);
            range.deleteContents();
            const el = document.createElement("div");
            el.innerHTML = html;
            const frag = document.createDocumentFragment();
            let node;
            while (node = el.firstChild) frag.appendChild(node);
            range.insertNode(frag);
            range.collapse(false);
            sel.removeAllRanges();
            sel.addRange(range);
          } else {
            editorRef.current!.innerHTML += html;
          }
          emitUpdate();
        },
        getSelection: () => {
          const sel = window.getSelection();
          return sel?.toString() || '';
        },
        scrollToText: (text: string) => {
          if (!editorRef.current) return;
          const walker = document.createTreeWalker(editorRef.current, NodeFilter.SHOW_TEXT);
          let node;
          while (node = walker.nextNode()) {
            if (node.textContent?.toLowerCase().includes(text.toLowerCase())) {
              (node.parentElement as HTMLElement)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
              break;
            }
          }
        },
        toggleHighlights: (targets: KeywordTarget, enabled: boolean) => {
          if (!editorRef.current) return;
          setIsHighlighting(enabled);

          const contentDiv = editorRef.current;

          // 1. Remove existing highlights (unwrap)
          const marks = contentDiv.querySelectorAll('mark.seo-highlight');
          marks.forEach(mark => {
            const parent = mark.parentNode;
            if (parent) {
              parent.replaceChild(document.createTextNode(mark.textContent || ''), mark);
              parent.normalize(); // Merge text nodes
            }
          });

          if (!enabled) {
            // If turning off, we just removed them. Emit update to save clean state?
            // Usually highlighting is visual-only, but in contentEditable it changes HTML.
            // Let's emit to keep state consistent.
            emitUpdate();
            return;
          }

          // 2. Apply new highlights
          const terms = [
            { text: targets.primary, color: '#fef08a' }, // yellow-200
            ...targets.secondary.map(s => ({ text: s, color: '#bae6fd' })) // sky-200
          ].filter(t => t.text && t.text.trim().length > 0);

          if (terms.length === 0) return;

          const walker = document.createTreeWalker(contentDiv, NodeFilter.SHOW_TEXT);
          const textNodes: Text[] = [];
          let node;
          while(node = walker.nextNode()) textNodes.push(node as Text);

          // We need to process nodes carefully to avoid invalidating the walker
          textNodes.forEach(textNode => {
             let text = textNode.nodeValue || '';
             let parent = textNode.parentNode;
             if (!parent || parent.nodeName === 'MARK' || parent.nodeName === 'SCRIPT' || parent.nodeName === 'STYLE') return;

             // Simple case-insensitive match replacement
             // Note: This is a destructive operation on text nodes, reconstructing fragments
             let hasMatch = false;
             const fragment = document.createDocumentFragment();
             let lastIndex = 0;

             // Find all matches for all terms in this text node
             // This simple approach iterates terms. Overlapping terms might be an issue.
             // For this editor, we'll prioritize the primary keyword, then secondary.

             // To handle multiple terms correctly, we should find the *first* match among all terms, process it, then continue.

             while (lastIndex < text.length) {
                let bestMatch = { index: -1, term: '', color: '' };

                terms.forEach(({text: termText, color}) => {
                   const regex = new RegExp(`\\b${termText.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i');
                   const subText = text.substring(lastIndex);
                   const match = subText.match(regex);
                   if (match && match.index !== undefined) {
                      const absoluteIndex = lastIndex + match.index;
                      if (bestMatch.index === -1 || absoluteIndex < bestMatch.index) {
                         bestMatch = { index: absoluteIndex, term: match[0], color }; // match[0] to capture actual case
                      }
                   }
                });

                if (bestMatch.index !== -1) {
                   hasMatch = true;
                   // Append text before match
                   fragment.appendChild(document.createTextNode(text.substring(lastIndex, bestMatch.index)));

                   // Append Highlight
                   const mark = document.createElement('mark');
                   mark.className = 'seo-highlight';
                   mark.style.backgroundColor = bestMatch.color;
                   mark.style.borderRadius = '4px';
                   mark.style.padding = '2px 0';
                   mark.textContent = bestMatch.term;
                   fragment.appendChild(mark);

                   lastIndex = bestMatch.index + bestMatch.term.length;
                } else {
                   // No more matches
                   fragment.appendChild(document.createTextNode(text.substring(lastIndex)));
                   break;
                }
             }

             if (hasMatch) {
               parent.replaceChild(fragment, textNode);
             }
          });

          emitUpdate();
        }
      };
      onInit(instance);
      analyzeParagraphs();
    }
  }, [onInit, analyzeParagraphs]);

  useEffect(() => {
    if (editorRef.current && initialContent !== lastContentEmitted.current) {
      // If content changes externally (and not just from our own highlights emitting updates), replace it.
      // NOTE: This might strip highlights if initialContent is "clean". 
      // If highlights are "baked in" to content state, they persist.
      editorRef.current.innerHTML = initialContent;
      lastContentEmitted.current = initialContent;
      analyzeParagraphs();
    }
  }, [initialContent, analyzeParagraphs]);

  const handleInput = () => {
    emitUpdate();
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    setTimeout(() => {
      emitUpdate();
    }, 0);
  };

  return (
    <div className="relative h-full w-full group overflow-hidden flex flex-col">
      <div 
        ref={editorRef}
        contentEditable
        onInput={handleInput}
        onPaste={handlePaste}
        className="editor-content flex-1 w-full h-full custom-scrollbar overflow-y-auto outline-none select-text"
        spellCheck="true"
        aria-label="Content Editor"
      />
    </div>
  );
};

