            </thead>
            <tbody className="divide-y divide-zinc-50">
              {(isExpanded ? keywords : keywords.slice(0, 12)).map((item, idx) => {
                const isPrimary = targets.primary && item.phrase.toLowerCase() === targets.primary.toLowerCase();
                const isSecondary = targets.secondary.some(s => s && item.phrase.toLowerCase() === s.toLowerCase());

                return (
                <tr key={idx} className={`hover:bg-zinc-50/50 transition-colors ${isPrimary ? 'bg-blue-50/30' : isSecondary ? 'bg-purple-50/30' : ''}`}>
