import { generateOptimizationReport } from './core/optimization-engine.ts';

// AI Integration
import { 
  rewriteContent, 
  generateMetadata, 
  detectAIContent, 
  RewriteMode, 
  generateFAQs 
} from './ai/ai-engine.ts';

// Components
import { Toolbar } from './components/editor/Toolbar.tsx';
import { Sidebar } from './components/layout/Sidebar.tsx';
import { Editor } from './components/editor/Editor.tsx';
import { Tab, SEOPhraseTab, KeywordTarget, FAQ } from './types/editor.types.ts';

export default function App() {
  // 1. Content State
  const [content, setContent] = useState(() => 
    localStorage.getItem('seo-editor-content-v2') || 
    '<h1>Future of Content SEO</h1><p>Start crafting your optimized, AI-enhanced SEO content here. This editor analyzes your text in real-time to ensure maximum search visibility.</p>'
  );

  // 2. Editor & UI State
  const [activeTab, setActiveTab] = useState<Tab>('insights'); 
  const [wordTarget, setWordTarget] = useState(1000);
  const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [editorInstance, setEditorInstance] = useState<any>(null);
  const [showReportModal, setShowReportModal] = useState(false);

  // 3. Report State
  const [reportHeadline, setReportHeadline] = useState('');
  const [reportSummary, setReportSummary] = useState('');

  // 4. SEO Metadata State
  const [metaTitle, setMetaTitle] = useState(() => localStorage.getItem('seo-meta-title-v2') || '');
  const [metaDescription, setMetaDescription] = useState(() => localStorage.getItem('seo-meta-desc-v2') || '');
  const [targets, setTargets] = useState<KeywordTarget>(() => {
    const saved = localStorage.getItem('seo-targets-v2');
    return saved ? JSON.parse(saved) : { primary: '', secondary: ['', '', ''] };
  });
  const [faqs, setFaqs] = useState<FAQ[]>(() => {
    const saved = localStorage.getItem('seo-faqs-v2');
    return saved ? JSON.parse(saved) : [];
  });

  const deferredContent = useDeferredValue(content);

  // Persistence
  useEffect(() => {
    localStorage.setItem('seo-editor-content-v2', content);
    localStorage.setItem('seo-targets-v2', JSON.stringify(targets));
    localStorage.setItem('seo-meta-desc-v2', metaDescription);
    localStorage.setItem('seo-meta-title-v2', metaTitle);
    localStorage.setItem('seo-faqs-v2', JSON.stringify(faqs));
  }, [content, targets, metaDescription, metaTitle, faqs]);

  // Analysis Memoization
  const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
  const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
  const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
  const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, targets, metaDescription, metaTitle), [deferredContent, keywords, targets, metaDescription, metaTitle]);
  const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);
  const sentenceWarnings = useMemo(() => analyzeSentenceWarnings(deferredContent), [deferredContent]);

  // Optimization Engine
  const optimizationReport = useMemo(() => generateOptimizationReport(
    stats,
    health,
    readability,
    sentenceWarnings,
    targets,
    metaTitle,
    metaDescription,
    faqs.length,
    keywords
  ), [stats, health, readability, sentenceWarnings, targets, metaTitle, metaDescription, faqs, keywords]);

  const handleEditorChange = (newContent: string) => {
    startTransition(() => {
      setContent(newContent);
    });
  };

  const onRewrite = async (mode: RewriteMode) => {
    if (!editorInstance) return;
    const selectedText = editorInstance.getSelection();
    if (!selectedText) {
      alert("Please select text within the editor to use AI rewriting features.");
      return;
    }
    setIsAIProcessing(true);
    try {
      const results = await rewriteContent(selectedText, mode);
      if (results && results.length > 0) {
        editorInstance.insertContent(results[0]);
      }
    } catch (err) {
      console.error("AI Rewrite Failed:", err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleReportSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const adminEmail = 'rathod.shivang@gmail.com';
    const mailtoLink = `mailto:${adminEmail}?subject=Issue Report: ${encodeURIComponent(reportHeadline)}&body=${encodeURIComponent(reportSummary)}`;
    window.location.href = mailtoLink;
    setReportHeadline('');
    setReportSummary('');
    setShowReportModal(false);
    alert('Thank you! Your issue report has been prepared for sending to rathod.shivang@gmail.com.');
  };

  return (
    <div className="flex h-screen w-full bg-white overflow-hidden text-zinc-900 selection:bg-blue-100">
      {/* Report Modal */}
      {showReportModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-md p-4 animate-in fade-in duration-300">
          <div className="bg-white border border-zinc-200 rounded-[32px] w-full max-w-md shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b border-zinc-50 flex items-center justify-between">
              <h3 className="font-black text-xl uppercase tracking-tighter text-zinc-900 flex items-center gap-2">
                <AlertCircle size={24} className="text-red-500" />
                Report Issue
              </h3>
              <button onClick={() => setShowReportModal(false)} className="text-zinc-400 hover:text-zinc-900 transition-colors">
                <X size={24}/>
              </button>
            </div>
            <form onSubmit={handleReportSubmit} className="p-8 space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-zinc-400 ml-1">Headline</label>
                <input required type="text" value={reportHeadline} onChange={(e) => setReportHeadline(e.target.value)} placeholder="Summarize the issue..." className="w-full px-6 py-4 bg-zinc-50 border border-zinc-100 rounded-2xl outline-none focus:border-blue-500 transition-all font-bold" />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-zinc-400 ml-1">Summary</label>
                <textarea required rows={4} value={reportSummary} onChange={(e) => setReportSummary(e.target.value)} placeholder="Describe what happened in detail..." className="w-full px-6 py-4 bg-zinc-50 border border-zinc-100 rounded-2xl outline-none focus:border-blue-500 transition-all font-medium resize-none" />
              </div>
              <button type="submit" className="w-full py-5 bg-zinc-900 text-white rounded-2xl font-black uppercase tracking-widest text-xs flex items-center justify-center gap-3 shadow-xl hover:bg-black transition-all active:scale-95">
                <Send size={16} /> Submit Report
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Main Editor Viewport */}
      <div className="flex-1 flex flex-col min-w-0 border-r border-zinc-100 bg-zinc-50/50">
        <header className="h-16 border-b border-zinc-100 px-8 flex items-center justify-between bg-white shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-black shadow-lg shadow-blue-500/20">S</div>
            <h1 className="font-black tracking-tighter text-lg uppercase">SEO Focus <span className="text-zinc-300 font-medium">Editor</span></h1>
          </div>
          <button onClick={() => setShowReportModal(true)} className="flex items-center gap-2 px-5 py-2 bg-red-50 hover:bg-red-100 rounded-full border border-red-100 transition-all text-red-600 group">
            <AlertCircle size={14} className="group-hover:scale-110 transition-transform" />
            <span className="text-[10px] font-black uppercase tracking-widest">Report Issues</span>
          </button>
        </header>

        <div className="flex-1 flex flex-col overflow-hidden relative">
          <div className="toolbar-container bg-white border-b border-zinc-100">
            <Toolbar 
              editorInstance={editorInstance} 
              stats={stats}
              wordTarget={wordTarget}
              onUpdate={() => handleEditorChange(editorInstance?.getContent() || '')}
              onNewDocument={() => confirm("Clear all content?") && editorInstance?.setContent('')}
              onShowHistory={() => {}} 
              onSaveVersion={() => {}}
              viewMode="focused"
            />
          </div>
          <main className="flex-1 overflow-hidden flex justify-center relative p-8">
            <div className="w-full max-w-[900px] h-full overflow-hidden bg-white relative rounded-[2px] shadow-sm border border-zinc-200/50">
              <Editor initialContent={content} onUpdate={handleEditorChange} onInit={setEditorInstance} onAIAssist={onRewrite} />
            </div>
          </main>
        </div>
      </div>

      <Sidebar 
        activeTab={activeTab} setActiveTab={setActiveTab} 
        stats={stats} readability={readability} health={health} intent={intent} keywords={keywords} 
        seoTab={seoTab} setSeoTab={setSeoTab} isExpanded={isExpanded} setIsExpanded={setIsExpanded} 
        onRewrite={onRewrite} 
        isAIProcessing={isAIProcessing} targets={targets} setTargets={setTargets}
        metaTitle={metaTitle} setMetaTitle={setMetaTitle} metaDescription={metaDescription} setMetaDescription={setMetaDescription}
        faqs={faqs} setFaqs={setFaqs}
        onGenerateMetadata={async (type) => {
          setIsAIProcessing(true);
          try {
            const res = await generateMetadata(content, type);
            if (type === 'title') setMetaTitle(res); else setMetaDescription(res);
          } finally { setIsAIProcessing(false); }
        }}
        onDetectAI={async () => {
          setIsAIProcessing(true);
          try {
            const res = await detectAIContent(content);
            alert(`AI Detection Score: ${res.score}%`);
          } finally { setIsAIProcessing(false); }
        }}
        onGenerateFAQs={async () => {
          setIsAIProcessing(true);
          try {
            const res = await generateFAQs(content);
            setFaqs(res);
          } finally { setIsAIProcessing(false); }
        }}
        onExportSchema={() => {
           navigator.clipboard.writeText(JSON.stringify({ "@context": "https://schema.org", "@type": "Article", "headline": metaTitle, "description": metaDescription }, null, 2));
           alert('Schema Copied');
        }}
        onNavigateOutline={(text) => editorInstance?.scrollToText(text)}
        sentenceWarnings={sentenceWarnings}
        optimizationReport={optimizationReport}
        onHighlight={(enabled) => editorInstance?.toggleHighlights(targets, enabled)}
      />
    </div>
  );
}

import { KeywordDensity } from '../types/editor.types';
import { STOP_WORDS } from './stopwords';

export const getKeywords = (html: string, n: number = 1): KeywordDensity[] => {
  const cleanText = html.replace(/<[^>]*>/g, ' '); 
  // Tokenize based on word boundaries, ignoring punctuation but keeping structure
  // We remove non-alphanumeric chars at the edges of tokens later if needed, 
  // but matches with \b generally handle words.
  const tokens = cleanText.match(/\b[\w']+\b/g) || [];

  const totalTokens = tokens.length;

  if (totalTokens === 0) return [];

  const phrasesMap: Record<string, { count: number; display: string }> = {};

  // Pre-compile regex for number checking
  const isNumber = /^\d+$/;

  for (let i = 0; i <= tokens.length - n; i++) {
    const phraseTokens = tokens.slice(i, i + n);

    // 1. Filter out phrases that are purely numbers (e.g. "2024", "10")
    // For n=1, check single token. For n>1, check if the combined phrase looks like a math string or just numbers?
    // Usually "Page 1" is fine, but "1 2" is noise. 
    // The prompt asked to remove "just numbers based keywords".
    // We will check if the specific token is a number for 1-gram.
    if (n === 1 && isNumber.test(phraseTokens[0])) {
      continue;
    }

    const firstWord = phraseTokens[0].toLowerCase();
    const lastWord = phraseTokens[phraseTokens.length - 1].toLowerCase();

    // 2. Stop Word Logic
    if (n === 1) {
      if (STOP_WORDS.has(firstWord)) continue;
    } else {
      // For N-grams:
      // Exclude if it STARTS or ENDS with a stop word. 
      // E.g., "in the" (skip), "the house" (skip), "bank of america" (keep - 'of' is in middle).
      if (STOP_WORDS.has(firstWord) || STOP_WORDS.has(lastWord)) {
        continue;
      }
    }

    // 3. Length check: skip 1-character words/numbers unless specific context (usually noise)
    if (phraseTokens.some(t => t.length < 2 && !isNumber.test(t) && t.toLowerCase() !== 'a' && t.toLowerCase() !== 'i')) {
       // Allow 'a' or 'I' potentially, but usually 'a' is a stopword. 
       // If logic above didn't catch it, strict length check might.
       // We'll rely on STOP_WORDS for 'a'.
    }

    const originalPhrase = phraseTokens.join(' ');
    const lowerPhrase = originalPhrase.toLowerCase();

    // Final sanity check for pure numeric phrases in n-grams (e.g. "10 20")
    if (n > 1 && /^\d+(\s+\d+)*$/.test(originalPhrase)) {
        continue;
    }

    if (!phrasesMap[lowerPhrase]) {
      phrasesMap[lowerPhrase] = { count: 0, display: originalPhrase };
    }

    phrasesMap[lowerPhrase].count += 1;
  }

  return Object.values(phrasesMap)
    .map(({ display, count }) => ({
      phrase: display,
      count,
      percentage: Number(((count * n) / totalTokens * 100).toFixed(2))
    }))
    .sort((a, b) => b.count - a.count);
};

import React, { useState } from 'react';
import { Target, ChevronDown, Cpu, Star, Circle, Eye, EyeOff, Search } from 'lucide-react';
import { SEOPhraseTab, KeywordDensity, KeywordTarget, TextStats } from '../../../types/editor.types';

interface KeywordsTabProps {
  targets: KeywordTarget;
  setTargets: (t: KeywordTarget) => void;
  keywords: KeywordDensity[];
  seoTab: SEOPhraseTab;
  setSeoTab: (num: SEOPhraseTab) => void;
  isExpanded: boolean;
  setIsExpanded: (val: boolean) => void;
  stats: TextStats;
  onHighlight: (enabled: boolean) => void;
}

export const KeywordsTab = ({ targets, setTargets, keywords, seoTab, setSeoTab, isExpanded, setIsExpanded, stats, onHighlight }: KeywordsTabProps) => {
  const [highlightsEnabled, setHighlightsEnabled] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  const toggleHighlights = () => {
    const newState = !highlightsEnabled;
    setHighlightsEnabled(newState);
    onHighlight(newState);
  };

  const getDensityColor = (percentage: number) => {
    if (percentage < 0.3) return 'text-zinc-300'; // Gray (Too Low)
    if (percentage < 0.8) return 'text-yellow-500'; // Yellow (Slightly Low)
    if (percentage <= 2) return 'text-emerald-500'; // Green (Ideal)
    if (percentage <= 3) return 'text-orange-500'; // Orange (Slightly High)
    return 'text-red-500'; // Red (Over-Optimized)
  };

  // Filter keywords based on search term
  const filteredKeywords = keywords.filter(k => 
    k.phrase.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-10 animate-in fade-in slide-in-from-right-4 duration-500">
      <div>
        <div className="flex items-center justify-between mb-5">
           <h3 className="text-[10px] font-black text-zinc-300 uppercase tracking-[0.25em]">Targeting</h3>
           <button 
             onClick={toggleHighlights}
             className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-[9px] font-black uppercase tracking-wider transition-all ${highlightsEnabled ? 'bg-blue-600 text-white' : 'bg-zinc-100 text-zinc-500 hover:bg-zinc-200'}`}
           >
             {highlightsEnabled ? <Eye size={12} /> : <EyeOff size={12} />}
             {highlightsEnabled ? 'Highlights On' : 'Highlights Off'}
           </button>
        </div>

        <div className="space-y-4">
          <div className="relative group">
            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-blue-600"><Target size={16}/></span>
            <input 
              type="text" 
              placeholder="Primary Keyword..." 
              value={targets.primary}
              onChange={(e) => setTargets({ ...targets, primary: e.target.value })}
              className="w-full bg-blue-50/50 border border-blue-100 focus:border-blue-400 rounded-2xl py-4 pl-12 pr-6 text-sm focus:bg-white outline-none transition-all font-bold text-zinc-800"
            />
          </div>
          <div className="space-y-3">
             {targets.secondary.map((val, idx) => (
               <div key={idx} className="relative">
                 <input 
                  type="text" 
                  placeholder={`Secondary Keyword ${idx + 1}`} 
                  value={val}
                  onChange={(e) => {
                    const newSec = [...targets.secondary];
                    newSec[idx] = e.target.value;
                    setTargets({ ...targets, secondary: newSec });
                  }}
                  className="w-full bg-white border border-zinc-100 rounded-xl py-3 px-5 text-xs focus:border-purple-200 outline-none transition-all focus:bg-purple-50/30"
                />
               </div>
             ))}
          </div>
        </div>
      </div>

      <div className="pt-6 border-t border-zinc-50">
        <h3 className="text-[10px] font-black text-zinc-300 uppercase tracking-[0.25em] mb-5">Keyword Density</h3>

        {/* Search Input for Density Table */}
        <div className="relative mb-4">
          <span className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-400"><Search size={14}/></span>
          <input 
            type="text" 
            placeholder="Search keywords..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-white border border-zinc-100 rounded-xl py-2.5 pl-10 pr-4 text-xs font-bold focus:border-blue-200 outline-none transition-all"
          />
        </div>

        <div className="flex bg-zinc-100 p-1 rounded-2xl gap-1 shrink-0 mb-6">
          {[1, 2, 3, 4].map(num => (
            <button key={num} onClick={() => { setSeoTab(num as SEOPhraseTab); setIsExpanded(false); }} className={`flex-1 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${seoTab === num ? 'bg-white text-blue-600 shadow-lg' : 'text-zinc-400 hover:text-zinc-600'}`}>{num}W</button>
          ))}
        </div>

        <div className={`rounded-3xl border border-zinc-100 bg-white overflow-hidden shadow-sm transition-all duration-300 ${isExpanded ? 'max-h-[500px] overflow-y-auto custom-scrollbar' : ''}`}>
          {filteredKeywords.length > 0 ? (
            <table className="w-full text-left text-xs">
              <thead className="bg-zinc-50 text-[10px] font-black text-zinc-400 border-b border-zinc-100 sticky top-0 z-10">
                <tr><th className="px-5 py-4">PHRASE</th><th className="px-5 py-4 text-right">QTY</th><th className="px-5 py-4 text-right">DENS</th></tr>
              </thead>
              <tbody className="divide-y divide-zinc-50">
                {(isExpanded ? filteredKeywords : filteredKeywords.slice(0, 12)).map((item, idx) => {
                  const isPrimary = targets.primary && item.phrase.toLowerCase() === targets.primary.toLowerCase();
                  const isSecondary = targets.secondary.some(s => s && item.phrase.toLowerCase() === s.toLowerCase());

                  return (
                  <tr key={idx} className={`hover:bg-zinc-50/50 transition-colors ${isPrimary ? 'bg-blue-50/30' : isSecondary ? 'bg-purple-50/30' : ''}`}>
                    <td className="px-5 py-4 font-bold max-w-[160px] text-zinc-600 flex items-center gap-2">
                      {isPrimary && <Star size={10} className="text-yellow-500 fill-yellow-500 shrink-0" />}
                      {isSecondary && <Circle size={6} className="text-purple-400 fill-purple-400 shrink-0" />}
                      <span className="truncate" title={item.phrase}>{item.phrase}</span>
                    </td>
                    <td className="px-5 py-4 text-right text-zinc-400 font-mono">{item.count}</td>
                    <td className="px-5 py-4 text-right">
                      <div className={`font-black ${getDensityColor(item.percentage)}`}>{item.percentage}%</div>
                    </td>
                  </tr>
                )})}
              </tbody>
            </table>
          ) : (
            <div className="p-8 text-center text-zinc-400 text-xs font-bold italic">
              No keywords found matching "{searchTerm}"
            </div>
          )}
        </div>
        {filteredKeywords.length > 12 && (
          <button onClick={() => setIsExpanded(!isExpanded)} className="w-full py-4 text-[10px] font-black uppercase text-blue-600 flex items-center justify-center gap-2 mt-4">
            {isExpanded ? 'Collapse' : `Full List (${filteredKeywords.length})`}
            <ChevronDown className={`transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} size={16} />
          </button>
        )}
      </div>

      <div className="pt-6 border-t border-zinc-50">
        <h3 className="text-[10px] font-black text-zinc-300 uppercase tracking-[0.25em] mb-5">NLP Terms</h3>
        <div className="flex flex-wrap gap-2">
          {stats.entities.length > 0 ? stats.entities.map((entity, i) => (
            <div key={i} className="px-3 py-1.5 bg-white border border-zinc-100 rounded-full text-[10px] font-bold text-zinc-600 flex items-center gap-1.5 shadow-sm">
              <Cpu size={10} className="text-blue-500" /> {entity}
            </div>
          )) : <div className="text-[11px] text-zinc-400 italic text-center w-full">No entities detected.</div>}
        </div>
      </div>
    </div>
  );
};

export type Tab = 'insights' | 'keywords' | 'seo' | 'ai' | 'optimize';
export type SEOPhraseTab = 1 | 2 | 3 | 4;

export interface KeywordDensity {
  phrase: string;
  count: number;
  percentage: number;
  isPrimary?: boolean;
  isSecondary?: boolean;
}

export interface TextStats {
  words: number;
  pubWords: number;
  sentences: number;
  readingTime: number;
  speakingTime: number;
  characters: number;
  paragraphs: number;
  entities: string[];
  headingTree: HeadingNode[];
}

export interface HeadingNode {
  tag: string;
  text: string;
  level: number;
}

export interface ReadabilityInsights {
  score: number;
  level: string;
  color: string;
  description: string;
  hardSentences: number;
  veryHardSentences: number;
}

export interface LinkStats {
  internal: number;
  external: number;
  broken: string[];
  unchecked: string[];
}

export interface ScoreBreakdown {
  meta: number;
  heading: number;
  keyword: number;
  content: number;
  link: number;
}

export interface SEOHealth {
  score: number;
  warnings: string[];
  status: 'excellent' | 'good' | 'fair' | 'poor';
  checklist: SEOChecklistItem[];
  prominenceScore: number;
  linkStats: LinkStats;
  scoreBreakdown: ScoreBreakdown;
}

export interface SEOChecklistItem {
  label: string;
  passed: boolean;
  impact: 'critical' | 'moderate' | 'low';
}

export interface IntentResult {
  primary: 'Informational' | 'Commercial' | 'Transactional' | 'Navigational' | 'Unknown';
  confidence: number;
  signals: string[];
}

export interface KeywordTarget {
  primary: string;
  secondary: string[];
}

export interface FAQ {
  question: string;
  answer: string;
}

export interface SentenceIssue {
  text: string;
  preview: string;
  index: number;
  count?: number; // Word count or comma count
}

export interface SentenceWarnings {
  longSentences: SentenceIssue[];
  veryLongSentences: SentenceIssue[];
  consecutiveLong: SentenceIssue[];
  commaOverload: SentenceIssue[];
  passiveVoice: SentenceIssue[];
  repetitiveOpenings: SentenceIssue[];
}

export interface OptimizationItem {
  id: string;
  title: string;
  description: string;
  priority: number; // 1 = Critical, 2 = Improvement, 3 = Enhancement
  source: 'readability' | 'heading' | 'keyword' | 'seo' | 'content';
}

export interface OptimizationReport {
  critical: OptimizationItem[];
  improvements: OptimizationItem[];
  enhancements: OptimizationItem[];
}

import { SEOHealth, KeywordDensity, SEOChecklistItem, KeywordTarget, LinkStats, ScoreBreakdown } from '../types/editor.types';
import { getReadabilityScore } from './readability';

export const analyzeSEOHealth = (
  html: string, 
  keywords: KeywordDensity[], 
  targets: KeywordTarget,
  metaDescription: string,
  metaTitle: string = "",
  brokenLinks: string[] = [] // Passed from async check
): SEOHealth => {
  const warnings: string[] = [];
  const checklist: SEOChecklistItem[] = [];
  let prominenceScore = 0;

  const cleanText = html.replace(/<[^>]*>/g, ' ').trim();
  const first100Words = cleanText.split(/\s+/).slice(0, 100).join(' ').toLowerCase();
  const primaryK = targets.primary ? targets.primary.toLowerCase() : '';

  // --- 1. Meta Score (Max 40) ---
  let metaScore = 0;

  // Title (25 pts max)
  const titleLen = metaTitle.length;
  const titleHasKey = primaryK && metaTitle.toLowerCase().includes(primaryK);
  const titleStartsWithKey = primaryK && metaTitle.toLowerCase().startsWith(primaryK);

  if (titleLen >= 50 && titleLen <= 60) metaScore += 15;
  else if (titleLen >= 40 && titleLen <= 70) metaScore += 10; // Slightly off
  else if (titleLen > 0) metaScore += 5; // At least present

  if (titleHasKey) metaScore += 10;
  // Bonus: Start with keyword (included in keyword score usually, but let's keep meta score clean)

  // Description (15 pts max)
  const descLen = metaDescription.length;
  const descHasKey = primaryK && metaDescription.toLowerCase().includes(primaryK);

  if (descLen >= 140 && descLen <= 160) metaScore += 10;
  else if (descLen >= 120 && descLen <= 180) metaScore += 5;
  else if (descLen > 0) metaScore += 2;

  if (descHasKey) metaScore += 5;

  // --- 2. Heading Structure (Max 15) ---
  let headingScore = 0;
  const h1Count = (html.match(/<h1/gi) || []).length;
  const h2Count = (html.match(/<h2/gi) || []).length;
  const h3Count = (html.match(/<h3/gi) || []).length;

  if (h1Count > 0) headingScore += 5;
  if (h1Count === 1) headingScore += 5;
  if (h2Count > 0 || h3Count > 0) headingScore += 5;

  // --- 3. Keyword Optimization (Max 20) ---
  let keywordScore = 0;
  const primaryDensityObj = keywords.find(k => k.phrase.toLowerCase() === primaryK);
  const density = primaryDensityObj ? primaryDensityObj.percentage : 0;

  if (primaryK) {
    keywordScore += 5; // Target set
    if (density >= 0.5 && density <= 2.5) keywordScore += 10;
    else if (density > 0 && density < 0.5) keywordScore += 5;

    // Prominence calc
    let localProminence = 0;
    // In H1
    const h1Match = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
    if (h1Match && h1Match[1].toLowerCase().includes(primaryK)) localProminence++;

    // In Intro
    if (first100Words.includes(primaryK)) localProminence++;

    // In URL (Not applicable here, but maybe we assume Meta Title is proxy? No.)
    // Let's use H2 presence for prominence
    if (h2Count > 0 && html.match(/<h2[^>]*>([\s\S]*?)<\/h2>/gi)?.some(h => h.toLowerCase().includes(primaryK))) localProminence++;

    if (localProminence >= 2) keywordScore += 5;
  }

  // --- 4. Content Quality (Max 15) ---
  let contentScore = 0;
  const wordCount = cleanText.split(/\s+/).length;
  const readScore = getReadabilityScore(html)?.score || 0;

  if (wordCount > 300) contentScore += 5;
  if (wordCount > 600) contentScore += 5;
  if (readScore >= 60) contentScore += 5;

  // --- 5. Link Structure (Max 10) ---
  let linkScore = 0;
  // Parse Links
  const linkMatches = Array.from(html.matchAll(/<a[^>]+href=["']([^"']+)["'][^>]*>/gi));
  const urls = linkMatches.map(m => m[1]);
  const internalLinks = urls.filter(u => u.startsWith('/') || u.startsWith('#')).length;
  const externalLinks = urls.filter(u => u.startsWith('http')).length;

  if (internalLinks > 0) linkScore += 5;
  if (externalLinks > 0) linkScore += 5;

  const linkStats: LinkStats = {
    internal: internalLinks,
    external: externalLinks,
    broken: brokenLinks, // Passed in
    unchecked: [] 
  };

  // --- Scoring & Penalties ---
  let totalScore = metaScore + headingScore + keywordScore + contentScore + linkScore;

  // Penalties
  if (h1Count === 0) { warnings.push("Missing H1 title tag."); totalScore -= 10; }
  if (h1Count > 1) { warnings.push("Multiple H1 tags detected."); totalScore -= 5; }
  if (density > 3.0) { warnings.push("Keyword stuffing detected."); totalScore -= 5; }

  // Broken Link Penalty
  if (brokenLinks.length > 0) {
    const deduction = brokenLinks.length * 5;
    totalScore -= deduction;
    warnings.push(`${brokenLinks.length} broken links detected.`);
  }

  totalScore = Math.max(0, Math.min(100, totalScore));

  const scoreBreakdown: ScoreBreakdown = {
    meta: metaScore,
    heading: headingScore,
    keyword: keywordScore,
    content: contentScore,
    link: linkScore
  };

  // Prominence Score (Legacy/UI compatibility)
  if (primaryK) {
     const h1Match = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
     const hasInH1 = h1Match ? h1Match[1].toLowerCase().includes(primaryK) : false;
     if (hasInH1) prominenceScore += 20;
     if (first100Words.includes(primaryK)) prominenceScore += 20;
     if (metaTitle.toLowerCase().includes(primaryK)) prominenceScore += 20;
     if (metaDescription.toLowerCase().includes(primaryK)) prominenceScore += 20;
     const hasInH2 = (html.match(/<h2[^>]*>([\s\S]*?)<\/h2>/gi) || []).some(h => h.toLowerCase().includes(primaryK));
     if (hasInH2) prominenceScore += 20;
  }

  // Populate Checklist (subset)
  checklist.push({ label: 'Title length optimized', passed: titleLen >= 50 && titleLen <= 60, impact: 'critical' });
  checklist.push({ label: 'Primary keyword in title', passed: !!(primaryK && titleHasKey), impact: 'critical' });
  checklist.push({ label: 'Content length > 600 words', passed: wordCount > 600, impact: 'moderate' });
  checklist.push({ label: 'Internal links present', passed: internalLinks > 0, impact: 'moderate' });

  let status: SEOHealth['status'] = 'excellent';
  if (totalScore < 50) status = 'poor';
  else if (totalScore < 70) status = 'fair';
  else if (totalScore < 85) status = 'good';

  return { score: totalScore, warnings, status, checklist, prominenceScore, linkStats, scoreBreakdown };
};

import React, { useState, useEffect, useMemo, useDeferredValue, startTransition } from 'react';
import { AlertCircle, X, Send } from 'lucide-react';

// Core Analysis Logic
import { getStats } from './core/text-analysis.ts';
import { getKeywords } from './core/keyword-density.ts';
import { getReadabilityScore } from './core/readability.ts';
import { analyzeSEOHealth } from './core/seo-health.ts';
import { detectIntent } from './core/intent-detector.ts';
import { htmlToMarkdown } from './core/text-cleaner.ts';
import { analyzeSentenceWarnings } from './core/sentence-analysis.ts';
import { generateOptimizationReport } from './core/optimization-engine.ts';

// AI Integration
import { 
  rewriteContent, 
  generateMetadata, 
  detectAIContent, 
  RewriteMode, 
  generateFAQs 
} from './ai/ai-engine.ts';

// Components
import { Toolbar } from './components/editor/Toolbar.tsx';
import { Sidebar } from './components/layout/Sidebar.tsx';
import { Editor } from './components/editor/Editor.tsx';
import { Tab, SEOPhraseTab, KeywordTarget, FAQ } from './types/editor.types.ts';

export default function App() {
  // 1. Content State
  const [content, setContent] = useState(() => 
    localStorage.getItem('seo-editor-content-v2') || 
    '<h1>Future of Content SEO</h1><p>Start crafting your optimized, AI-enhanced SEO content here. This editor analyzes your text in real-time to ensure maximum search visibility.</p>'
  );

  // 2. Editor & UI State
  const [activeTab, setActiveTab] = useState<Tab>('insights'); 
  const [wordTarget, setWordTarget] = useState(1000);
  const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [editorInstance, setEditorInstance] = useState<any>(null);
  const [showReportModal, setShowReportModal] = useState(false);

  // 3. Report State
  const [reportHeadline, setReportHeadline] = useState('');
  const [reportSummary, setReportSummary] = useState('');

  // 4. SEO Metadata State
  const [metaTitle, setMetaTitle] = useState(() => localStorage.getItem('seo-meta-title-v2') || '');
  const [metaDescription, setMetaDescription] = useState(() => localStorage.getItem('seo-meta-desc-v2') || '');
  const [targets, setTargets] = useState<KeywordTarget>(() => {
    const saved = localStorage.getItem('seo-targets-v2');
    return saved ? JSON.parse(saved) : { primary: '', secondary: ['', '', ''] };
  });
  const [faqs, setFaqs] = useState<FAQ[]>(() => {
    const saved = localStorage.getItem('seo-faqs-v2');
    return saved ? JSON.parse(saved) : [];
  });
  const [brokenLinks, setBrokenLinks] = useState<string[]>([]);

  const deferredContent = useDeferredValue(content);

  // Persistence
  useEffect(() => {
    localStorage.setItem('seo-editor-content-v2', content);
    localStorage.setItem('seo-targets-v2', JSON.stringify(targets));
    localStorage.setItem('seo-meta-desc-v2', metaDescription);
    localStorage.setItem('seo-meta-title-v2', metaTitle);
    localStorage.setItem('seo-faqs-v2', JSON.stringify(faqs));
  }, [content, targets, metaDescription, metaTitle, faqs]);

  // Analysis Memoization
  const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
  const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
  const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
  const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, targets, metaDescription, metaTitle, brokenLinks), [deferredContent, keywords, targets, metaDescription, metaTitle, brokenLinks]);
  const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);
  const sentenceWarnings = useMemo(() => analyzeSentenceWarnings(deferredContent), [deferredContent]);

  // Optimization Engine
  const optimizationReport = useMemo(() => generateOptimizationReport(
    stats,
    health,
    readability,
    sentenceWarnings,
    targets,
    metaTitle,
    metaDescription,
    faqs.length,
    keywords
  ), [stats, health, readability, sentenceWarnings, targets, metaTitle, metaDescription, faqs, keywords]);

  const handleEditorChange = (newContent: string) => {
    startTransition(() => {
      setContent(newContent);
    });
  };

  const onRewrite = async (mode: RewriteMode) => {
    if (!editorInstance) return;
    const selectedText = editorInstance.getSelection();
    if (!selectedText) {
      alert("Please select text within the editor to use AI rewriting features.");
      return;
    }
    setIsAIProcessing(true);
    try {
      const results = await rewriteContent(selectedText, mode);
      if (results && results.length > 0) {
        editorInstance.insertContent(results[0]);
      }
    } catch (err) {
      console.error("AI Rewrite Failed:", err);
    } finally {
      setIsAIProcessing(false);
    }
  };

  const handleReportSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const adminEmail = 'rathod.shivang@gmail.com';
    const mailtoLink = `mailto:${adminEmail}?subject=Issue Report: ${encodeURIComponent(reportHeadline)}&body=${encodeURIComponent(reportSummary)}`;
    window.location.href = mailtoLink;
    setReportHeadline('');
    setReportSummary('');
    setShowReportModal(false);
    alert('Thank you! Your issue report has been prepared for sending to rathod.shivang@gmail.com.');
  };

  return (
    <div className="flex h-screen w-full bg-white overflow-hidden text-zinc-900 selection:bg-blue-100">
      {/* Report Modal */}
      {showReportModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-md p-4 animate-in fade-in duration-300">
          <div className="bg-white border border-zinc-200 rounded-[32px] w-full max-w-md shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b border-zinc-50 flex items-center justify-between">
              <h3 className="font-black text-xl uppercase tracking-tighter text-zinc-900 flex items-center gap-2">
                <AlertCircle size={24} className="text-red-500" />
                Report Issue
              </h3>
              <button onClick={() => setShowReportModal(false)} className="text-zinc-400 hover:text-zinc-900 transition-colors">
                <X size={24}/>
              </button>
            </div>
            <form onSubmit={handleReportSubmit} className="p-8 space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-zinc-400 ml-1">Headline</label>
                <input required type="text" value={reportHeadline} onChange={(e) => setReportHeadline(e.target.value)} placeholder="Summarize the issue..." className="w-full px-6 py-4 bg-zinc-50 border border-zinc-100 rounded-2xl outline-none focus:border-blue-500 transition-all font-bold" />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-zinc-400 ml-1">Summary</label>
                <textarea required rows={4} value={reportSummary} onChange={(e) => setReportSummary(e.target.value)} placeholder="Describe what happened in detail..." className="w-full px-6 py-4 bg-zinc-50 border border-zinc-100 rounded-2xl outline-none focus:border-blue-500 transition-all font-medium resize-none" />
              </div>
              <button type="submit" className="w-full py-5 bg-zinc-900 text-white rounded-2xl font-black uppercase tracking-widest text-xs flex items-center justify-center gap-3 shadow-xl hover:bg-black transition-all active:scale-95">
                <Send size={16} /> Submit Report
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Main Editor Viewport */}
      <div className="flex-1 flex flex-col min-w-0 border-r border-zinc-100 bg-zinc-50/50">
        <header className="h-16 border-b border-zinc-100 px-8 flex items-center justify-between bg-white shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-black shadow-lg shadow-blue-500/20">S</div>
            <h1 className="font-black tracking-tighter text-lg uppercase">SEO Focus <span className="text-zinc-300 font-medium">Editor</span></h1>
          </div>
          <button onClick={() => setShowReportModal(true)} className="flex items-center gap-2 px-5 py-2 bg-red-50 hover:bg-red-100 rounded-full border border-red-100 transition-all text-red-600 group">
            <AlertCircle size={14} className="group-hover:scale-110 transition-transform" />
            <span className="text-[10px] font-black uppercase tracking-widest">Report Issues</span>
          </button>
        </header>

        <div className="flex-1 flex flex-col overflow-hidden relative">
          <div className="toolbar-container bg-white border-b border-zinc-100">
            <Toolbar 
              editorInstance={editorInstance} 
              stats={stats}
              wordTarget={wordTarget}
              onUpdate={() => handleEditorChange(editorInstance?.getContent() || '')}
              onNewDocument={() => confirm("Clear all content?") && editorInstance?.setContent('')}
              onShowHistory={() => {}} 
              onSaveVersion={() => {}}
              viewMode="focused"
            />
          </div>
          <main className="flex-1 overflow-hidden flex justify-center relative p-8">
            <div className="w-full max-w-[900px] h-full overflow-hidden bg-white relative rounded-[2px] shadow-sm border border-zinc-200/50">
              <Editor initialContent={content} onUpdate={handleEditorChange} onInit={setEditorInstance} onAIAssist={onRewrite} />
            </div>
          </main>
        </div>
      </div>

      <Sidebar 
        activeTab={activeTab} setActiveTab={setActiveTab} 
        stats={stats} readability={readability} health={health} intent={intent} keywords={keywords} 
        seoTab={seoTab} setSeoTab={setSeoTab} isExpanded={isExpanded} setIsExpanded={setIsExpanded} 
        onRewrite={onRewrite} 
        isAIProcessing={isAIProcessing} targets={targets} setTargets={setTargets}
        metaTitle={metaTitle} setMetaTitle={setMetaTitle} metaDescription={metaDescription} setMetaDescription={setMetaDescription}
        faqs={faqs} setFaqs={setFaqs}
        onGenerateMetadata={async (type) => {
          setIsAIProcessing(true);
          try {
            const res = await generateMetadata(content, type);
            if (type === 'title') setMetaTitle(res); else setMetaDescription(res);
          } finally { setIsAIProcessing(false); }
        }}
        onDetectAI={async () => {
          setIsAIProcessing(true);
          try {
            const res = await detectAIContent(content);
            alert(`AI Detection Score: ${res.score}%`);
          } finally { setIsAIProcessing(false); }
        }}
        onGenerateFAQs={async () => {
          setIsAIProcessing(true);
          try {
            const res = await generateFAQs(content);
            setFaqs(res);
          } finally { setIsAIProcessing(false); }
        }}
        onExportSchema={() => {
           navigator.clipboard.writeText(JSON.stringify({ "@context": "https://schema.org", "@type": "Article", "headline": metaTitle, "description": metaDescription }, null, 2));
           alert('Schema Copied');
        }}
        onNavigateOutline={(text) => editorInstance?.scrollToText(text)}
        sentenceWarnings={sentenceWarnings}
        optimizationReport={optimizationReport}
        onHighlight={(enabled) => editorInstance?.toggleHighlights(targets, enabled)}
        setBrokenLinks={setBrokenLinks} // Pass setter for broken links
      />
    </div>
  );
}

