const ScoreRing = ({ score }: { score: number }) => {
  const radius = 40;
  const stroke = 8;
  const normalizedRadius = radius - stroke * 2;
  const circumference = normalizedRadius * 2 * Math.PI;
  const strokeDashoffset = circumference - (score / 100) * circumference;

  let color = '#ef4444'; // Red
  if (score >= 85) color = '#10b981'; // Green
  else if (score >= 70) color = '#f59e0b'; // Yellow (Note: Tailwind yellow-500 usually #eab308, using slightly orange for visibility)
  else if (score >= 50) color = '#f97316'; // Orange

  return (
    <div className="relative w-32 h-32 flex items-center justify-center">
      <svg height={radius * 2} width={radius * 2} className="rotate-[-90deg]">
        <circle
          stroke="#f4f4f5"
          strokeWidth={stroke}
          fill="transparent"
          r={normalizedRadius}
          cx={radius}
          cy={radius}
        />
        <circle
          stroke={color}
          strokeWidth={stroke}
          strokeDasharray={circumference + ' ' + circumference}
          style={{ strokeDashoffset, transition: 'stroke-dashoffset 1s ease-in-out' }}
          strokeLinecap="round"
          fill="transparent"
          r={normalizedRadius}
          cx={radius}
          cy={radius}
        />
      </svg>
      <div className="absolute text-center">
        <div className="text-4xl font-black tracking-tighter" style={{ color }}>{score}</div>
        <div className="text-[9px] font-black text-zinc-300 uppercase">/100</div>
      </div>
    </div>
  );
};

const MetaFeedback = ({ current, min, max, label, hasKey, startsWithKey }: any) => {
  let status = 'Optimal';
  let color = 'text-emerald-500';
  const len = current.length;

  if (len === 0) { status = 'Empty'; color = 'text-red-500'; }
  else if (len < min - 10) { status = 'Too Short'; color = 'text-red-400'; }
  else if (len < min) { status = 'Slightly Short'; color = 'text-yellow-500'; }
  else if (len > max + 10) { status = 'Too Long'; color = 'text-red-400'; }
  else if (len > max) { status = 'Slightly Long'; color = 'text-yellow-500'; }

  return (
    <div className="mt-2 flex items-center justify-between text-[10px] font-bold">
       <div className="flex items-center gap-3">
          <span className={`${color}`}>{len} chars</span>
          <span className="text-zinc-300">|</span>
          <span className={`${color}`}>{status}</span>
       </div>
       <div className="flex items-center gap-2">
          {hasKey !== undefined && (
            <span className={`px-1.5 py-0.5 rounded flex items-center gap-1 ${hasKey ? 'bg-emerald-50 text-emerald-600' : 'bg-zinc-100 text-zinc-400'}`}>
               Key {hasKey ? <CheckCircle2 size={10}/> : <AlertCircle size={10}/>}
            </span>
          )}
          {startsWithKey !== undefined && (
            <span className={`px-1.5 py-0.5 rounded flex items-center gap-1 ${startsWithKey ? 'bg-emerald-50 text-emerald-600' : 'bg-zinc-100 text-zinc-400'}`}>
               Start {startsWithKey ? <CheckCircle2 size={10}/> : <AlertCircle size={10}/>}
            </span>
          )}
