export const SEOTab = ({ 
  health, metaTitle, setMetaTitle, metaDescription, setMetaDescription, 
  faqs, setFaqs, onGenerateMetadata, onGenerateFAQs, onExportSchema, isAIProcessing,
  setBrokenLinks
}: SEOTabProps) => {
  const [checkingLinks, setCheckingLinks] = useState(false);
  const [breakdownOpen, setBreakdownOpen] = useState(false);

  // Extract URLs for checking (simplified extraction here for the checker logic)
  const performLinkCheck = async () => {
    if (!setBrokenLinks) return;
    setCheckingLinks(true);

    // We need to re-scan the DOM or use what we have. 
    // Since we are in Sidebar, we don't have direct access to DOM easily unless passed.
    // However, we can infer from health.linkStats, but that only gives counts.
    // We will cheat slightly and assume the Editor content is sync'd or we scan a virtual DOM.
    // Actually, `analyzeSEOHealth` runs on `html` string in App.tsx. 
    // We can't easily get the list of ALL URLs from `health` prop as it only has stats.

    // To fix this without breaking props interface drastically:
    // We will assume that if the user clicks "Check Links", we might need to parse them from a hidden element or similar.
    // BUT, we can just grab all `a` tags from the `document` if the editor is mounted.
    // The editor is in `div.editor-content`.

    const editorEl = document.querySelector('.editor-content');
    if (!editorEl) {
        setCheckingLinks(false);
        return;
    }

    const anchors = Array.from(editorEl.querySelectorAll('a[href]')) as HTMLAnchorElement[];
    const externalUrls = anchors
        .map(a => a.href)
        .filter(href => href.startsWith('http'));

    const broken: string[] = [];

    // Batch check
    await Promise.allSettled(externalUrls.map(async (url) => {
        try {
            const res = await fetch(url, { method: 'HEAD', mode: 'no-cors' });
            // opaque response type is 'opaque', status is 0. We assume OK if no error thrown.
            // If it throws, it's network error.
        } catch (e) {
            // Likely CORS or Network Error.
            // We can't strictly say it's 404. 
            // BUT for the sake of the feature "Broken Link Check", let's assume network error = broken/unreachable.
            // For a real app, we'd need a proxy.
            broken.push(url);
        }
    }));

    // Remove duplicates
    const uniqueBroken = Array.from(new Set(broken));
    setBrokenLinks(uniqueBroken);
    setCheckingLinks(false);
  };

  return (
    <div className="space-y-10 animate-in fade-in slide-in-from-right-4 duration-500">
