export const generateMetadata = async (
  content: string, 
  type: 'title' | 'description',
  keywords?: KeywordTarget
): Promise<string> => {
  const ai = getAI();

  // 1. Clean and Prepare Content
  // Get enough context (approx 1000-1500 words) to ensure AI understands the topic
  const cleanText = htmlToMarkdown(content);
  const contextText = cleanText.substring(0, 8000); 

  const primary = keywords?.primary || "";
  const secondary = keywords?.secondary?.filter(s => s && s.trim().length > 0) || [];

  // 2. Define Strict System Instructions
  let systemInstruction = "";
  let userPrompt = "";

  if (type === 'title') {
    systemInstruction = `You are an elite SEO expert. Generate a single, high-impact Meta Title.

    CRITICAL RULES:
    1. Length MUST be between 50 and 60 characters. 
    2. Primary Keyword "${primary}" MUST be included.
    3. Place Primary Keyword near the beginning if natural.
    4. Use separators like "|" or "-" for branding logic.
    5. NO quotation marks. NO prefixes like "Title:".
    `;
    userPrompt = `Generate SEO Title based on this content:\n\n${contextText.substring(0, 2000)}`;
  } else {
    systemInstruction = `You are an elite SEO expert. Generate a single, persuasive Meta Description.

    CRITICAL RULES:
    1. Length MUST be between 140 and 160 characters.
    2. Primary Keyword "${primary}" MUST be included.
    3. Include a call-to-action (CTA) or clear benefit.
    4. Write two sentences: Summary + Benefit/CTA.
    5. NO quotation marks. NO prefixes.
    `;
    userPrompt = `Generate SEO Description based on this content:\n\n${contextText.substring(0, 3000)}`;
  }

  // 3. Fallback for Empty Content
  if (contextText.length < 50 && primary) {
      // If content is missing but keyword exists, return a template
      if (type === 'title') return `${primary} - Ultimate Guide | Expert Tips & Strategies`;
      if (type === 'description') return `Discover everything about ${primary}. This comprehensive guide covers key strategies, benefits, and expert tips to help you master ${primary} today.`;
  }

  try {
    // 4. Generate Content
    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userPrompt,
        config: { 
            systemInstruction: systemInstruction,
            temperature: 0.7,
            maxOutputTokens: 200, 
        }
    });

    let result = response.text?.trim() || "";
    // Aggressive cleanup
    result = result.replace(/^["']|["']$/g, '').replace(/^(Meta )?Title:\s*/i, '').replace(/^(Meta )?Description:\s*/i, '');

    // 5. Hard Validation & Retry Logic
    const len = result.length;
    let isValid = true;
    let retryPrompt = "";

    if (type === 'title') {
        if (len < 40) {
            isValid = false;
            retryPrompt = `The title "${result}" is too short (${len} chars). Generate a longer title (min 50 chars) incorporating specific details from the content.`;
        } else if (len > 70) {
            isValid = false;
            retryPrompt = `The title is too long (${len} chars). Shorten it to under 60 characters.`;
        }
    } else {
        if (len < 100) {
            isValid = false;
            retryPrompt = `The description "${result}" is too short (${len} chars). Expand it to 140-160 chars by adding a clear benefit and CTA.`;
        }
    }

    if (!isValid) {
        console.log(`Regenerating ${type} due to validation failure (Length: ${len}).`);
        const retryResp = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: [
                 { role: 'user', parts: [{ text: userPrompt }] },
                 { role: 'model', parts: [{ text: result }] },
                 { role: 'user', parts: [{ text: retryPrompt }] }
            ],
            config: { 
                systemInstruction: systemInstruction,
                temperature: 0.7, 
                maxOutputTokens: 200 
            }
        });

        const retryResult = retryResp.text?.trim();
        if (retryResult) {
             result = retryResult.replace(/^["']|["']$/g, '').replace(/^(Meta )?Title:\s*/i, '').replace(/^(Meta )?Description:\s*/i, '');
        }
    }

    return result;

  } catch (e) {
      console.error("AI Generation Error", e);
      // Return a safe fallback based on primary keyword if AI fails completely
      if (primary) {
          return type === 'title' 
            ? `${primary}: The Ultimate Guide` 
            : `Learn about ${primary} in this detailed guide. We cover everything you need to know about ${primary} to succeed.`;
      }
      return "";
  }
};

