const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export type RewriteMode = 
  | 'clarity' 
  | 'concise' 
  | 'expand_examples' 
  | 'add_stats' 
  | 'authoritative' 
  | 'humanize' 
  | 'remove_fluff' 
  | 'conversational' 
  | 'formal' 
  | 'active_voice'
  | 'expand'
  | 'shorten';

export const rewriteContent = async (text: string, mode: RewriteMode, customPrompt?: string): Promise<string[]> => {
  const ai = getAI();
  const modePrompts: Record<RewriteMode, string> = {
    clarity: "Rewrite the following text for maximum clarity, ensuring it's easy to follow while maintaining the original message.",
    concise: "Make the following text as concise as possible. Remove redundant words and shorten sentences without losing meaning.",
    expand_examples: "Expand the following content by adding relevant, illustrative examples that help clarify the points made.",
    add_stats: "Incorporate realistic (placeholder format like [X%]) statistics and data points into the text to boost its credibility.",
    authoritative: "Rewrite the text in an authoritative, expert tone. Use decisive language and establish high topical authority.",
    humanize: "Adjust the tone of the text to sound more human and less like a machine. Vary sentence length and use more natural expressions.",
    remove_fluff: "Identify and remove all 'filler' content, flowery adjectives, and unnecessary fluff from the following text.",
    conversational: "Rewrite the text in a friendly, conversational tone, as if talking directly to a peer.",
    formal: "Convert the following text into a professional, formal business tone suitable for corporate environments.",
    active_voice: "Convert all passive voice sentences in the following text into active voice for more direct and impactful writing.",
    expand: "Elaborate on the following text to provide more depth, detail, and context while maintaining the original tone.",
    shorten: "Drastically shorten the following text while preserving the core message and primary information."
  };

  const instruction = customPrompt || modePrompts[mode];

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `${instruction}\n\nProvide exactly TWO distinct and high-quality versions of the following text.\n\nText to process:\n"${text}"`,
    config: { 
      temperature: 0.7,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          options: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "An array of two distinct rewritten versions."
          }
        },
        required: ["options"]
      }
    }
  });

  try {
    const data = JSON.parse(response.text || '{"options": []}');
    return data.options || [];
  } catch (e) {
    console.error("Failed to parse AI options", e);
    return [text, text];
  }
};

export const generateMetadata = async (
  content: string, 
  type: 'title' | 'description',
  keywords?: KeywordTarget
): Promise<string> => {
  const ai = getAI();

  // 1. Prepare Context (Raw Text)
  const cleanText = htmlToMarkdown(content);
  // Provide substantial context so AI understands the article
  const contextText = cleanText.substring(0, 8000); 

  const primary = keywords?.primary || "";
  const secondary = keywords?.secondary?.filter(s => s && s.trim().length > 0) || [];
  const secondaryStr = secondary.length > 0 ? secondary.join(', ') : "relevant related terms";

  // 2. Define Simplified, Rule-Based Instructions
  let systemInstruction = "";

  if (type === 'title') {
    systemInstruction = `Generate 1 SEO Meta Title based on the content provided.

    STRICT RULES:
    1. Primary Keyword "${primary}" MUST be included.
    2. Length MUST be between 50 and 70 characters.
    3. Be contextually relevant to the content.
    4. Return ONLY the raw text. No quotes.`;
  } else {
    systemInstruction = `Generate 1 SEO Meta Description based on the content provided.

    STRICT RULES:
    1. Primary Keyword "${primary}" MUST be included.
    2. Try to naturally include these secondary keywords: ${secondaryStr}.
    3. Length MUST be between 140 and 160 characters.
    4. Summarize the content and include a call to action.
    5. Return ONLY the raw text. No quotes.`;
  }

  const userPrompt = `Generate the ${type} for this content:\n\n${contextText}`;

  // 3. Fallback if content is too thin
  if (contextText.length < 50 && primary) {
      if (type === 'title') return `${primary}: The Ultimate Guide & Expert Strategy`;
      if (type === 'description') return `Discover the best strategies for ${primary}. This guide covers everything you need to know about ${secondaryStr} to succeed today.`;
  }

  try {
    // 4. Generate
    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userPrompt,
        config: { 
            systemInstruction: systemInstruction,
            temperature: 0.7,
            maxOutputTokens: 200, 
        }
    });

    let result = response.text?.trim() || "";
    // Clean quotes/labels
    result = result.replace(/^["']|["']$/g, '').replace(/^(Meta )?(Title|Description):\s*/i, '');

    // 5. Validation & Retry Logic
    const len = result.length;
    let isValid = true;
    let retryPrompt = "";

    if (type === 'title') {
        // Title Rule: 50-70 chars
        if (len < 50) {
            isValid = false;
            retryPrompt = `Too short (${len} chars). Expand to at least 50 chars. Keep keyword "${primary}".`;
        } else if (len > 70) {
            isValid = false;
            retryPrompt = `Too long (${len} chars). Shorten to under 70 chars. Keep keyword "${primary}".`;
        }
    } else {
        // Description Rule: 140-160 chars
        if (len < 135) { // Allow slight buffer (135) for retry trigger
            isValid = false;
            retryPrompt = `Too short (${len} chars). Expand to 140-160 chars. Include specific benefits.`;
        } else if (len > 165) { // Allow slight buffer (165)
            isValid = false;
            retryPrompt = `Too long (${len} chars). Shorten to under 160 chars.`;
        }
    }

    if (!isValid) {
        console.log(`Regenerating ${type}. Length ${len} invalid.`);
        const retryResp = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: [
                 { role: 'user', parts: [{ text: userPrompt }] },
                 { role: 'model', parts: [{ text: result }] },
                 { role: 'user', parts: [{ text: retryPrompt }] }
            ],
            config: { 
                systemInstruction: systemInstruction,
                temperature: 0.7, 
                maxOutputTokens: 200 
            }
        });

        const retryResult = retryResp.text?.trim();
        if (retryResult) {
             result = retryResult.replace(/^["']|["']$/g, '').replace(/^(Meta )?(Title|Description):\s*/i, '');
        }
    }

    return result;

  } catch (e) {
      console.error("AI Generation Error", e);
      if (primary) {
          return type === 'title' 
            ? `${primary}: Comprehensive Guide & Insights` 
            : `Learn about ${primary} and ${secondary[0] || 'more'}. This guide provides key insights and strategies to help you succeed.`;
      }
      return "";
  }
};

