export const rewriteContent = async (text: string, mode: RewriteMode, customPrompt?: string): Promise<string[]> => {
  const ai = getAI();
  const modePrompts: Record<RewriteMode, string> = {
    clarity: "Rewrite the following text for maximum clarity, ensuring it's easy to follow while maintaining the original message.",
    concise: "Make the following text as concise as possible. Remove redundant words and shorten sentences without losing meaning.",
    expand_examples: "Expand the following content by adding relevant, illustrative examples that help clarify the points made.",
    add_stats: "Incorporate realistic (placeholder format like [X%]) statistics and data points into the text to boost its credibility.",
    authoritative: "Rewrite the text in an authoritative, expert tone. Use decisive language and establish high topical authority.",
    humanize: "Adjust the tone of the text to sound more human and less like a machine. Vary sentence length and use more natural expressions.",
    remove_fluff: "Identify and remove all 'filler' content, flowery adjectives, and unnecessary fluff from the following text.",
    conversational: "Rewrite the text in a friendly, conversational tone, as if talking directly to a peer.",
    formal: "Convert the following text into a professional, formal business tone suitable for corporate environments.",
    active_voice: "Convert all passive voice sentences in the following text into active voice for more direct and impactful writing.",
    expand: "Elaborate on the following text to provide more depth, detail, and context while maintaining the original tone.",
    shorten: "Drastically shorten the following text while preserving the core message and primary information."
  };

  const instruction = customPrompt || modePrompts[mode];

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `${instruction}\n\nProvide exactly TWO distinct and high-quality versions of the following text.\n\nText to process:\n"${text}"`,
    config: { 
      temperature: 0.7,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          options: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "An array of two distinct rewritten versions."
          }
        },
        required: ["options"]
      }
    }
  });

  try {
    const data = JSON.parse(response.text || '{"options": []}');
    return data.options || [];
  } catch (e) {
    console.error("Failed to parse AI options", e);
    return [text, text];
  }
};

export const generateMetadata = async (
  content: string, 
  type: 'title' | 'description',
  keywords?: KeywordTarget
): Promise<string> => {
  const ai = getAI();

  // 1. Prepare Context & Keywords
  const cleanText = htmlToMarkdown(content);
  // Use a reasonable chunk of text. If text is short, we rely on keywords.
  const contextText = cleanText.substring(0, 6000); 

  const primary = keywords?.primary || "";
  const secondary = keywords?.secondary?.filter(s => s && s.trim().length > 0) || [];
  const secondaryStr = secondary.join(', ');

  // 2. Construct Strong Prompt with Fallback Logic
  // We inject the keywords explicitly into the prompt context to ensure the AI uses them 
  // even if the article content is thin.

  let systemInstruction = "";
  let userPrompt = "";

  if (type === 'title') {
    systemInstruction = `You are an expert SEO Copywriter. 
    Task: Generate a single, click-worthy SEO Meta Title.

    CRITICAL CONSTRAINTS:
    1. Length MUST be between 50 and 65 characters. If the content is short, creatively expand using the keywords.
    2. MUST include the Primary Keyword: "${primary}".
    3. Place the keyword near the beginning if possible.
    4. Use a separator ( | or - ) to structure the title (e.g., "Keyword | Benefit").
    5. Return ONLY the raw title text. No quotes.`;

    userPrompt = `
    PRIMARY KEYWORD: ${primary}
    SECONDARY KEYWORDS: ${secondaryStr}

    CONTENT CONTEXT:
    ${contextText.length < 50 ? "Content is thin. Please generate a title based on the Primary Keyword." : contextText}

    GENERATE META TITLE (50-65 chars):
    `;

  } else {
    systemInstruction = `You are an expert SEO Copywriter.
    Task: Generate a single, persuasive SEO Meta Description.

    CRITICAL CONSTRAINTS:
    1. Length MUST be between 145 and 160 characters. Do not write less than 140.
    2. MUST include the Primary Keyword: "${primary}".
    3. Try to include secondary keywords naturally: ${secondaryStr}.
    4. Structure: Summary + Value Proposition + Call to Action.
    5. Return ONLY the raw description text. No quotes.`;

    userPrompt = `
    PRIMARY KEYWORD: ${primary}
    SECONDARY KEYWORDS: ${secondaryStr}

    CONTENT CONTEXT:
    ${contextText.length < 50 ? "Content is thin. Generate a description based on the Primary Keyword." : contextText}

    GENERATE META DESCRIPTION (145-160 chars):
    `;
  }

  // 3. Fallback for completely empty state (client-side safety)
  if (contextText.length < 10 && !primary) {
      return type === 'title' ? "Enter content or keywords to generate title" : "Enter content or keywords to generate description";
  }

  try {
    // 4. Generate
    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userPrompt,
        config: { 
            systemInstruction: systemInstruction,
            temperature: 0.75, // Slightly higher creativity to help expansion
            maxOutputTokens: 250, 
        }
    });

    let result = response.text?.trim() || "";
    // Clean quotes/labels
    result = result.replace(/^["']|["']$/g, '').replace(/^(Meta )?(Title|Description):\s*/i, '');

    // 5. Strict Validation & Retry Logic
    const len = result.length;
    let isValid = true;
    let retryPrompt = "";

    if (type === 'title') {
        // Title Rule: 50-70 chars (Targeting 50-65 strictly)
        if (len < 45) {
            isValid = false;
            retryPrompt = `The title "${result}" is too short (${len} chars). It MUST be at least 50 characters. Elaborate on the benefit or add a strong modifier (e.g., 'Ultimate Guide', '2025 Strategy'). Keep the keyword "${primary}".`;
        } else if (len > 70) {
            isValid = false;
            retryPrompt = `The title is too long (${len} chars). Shorten it to under 65 characters while keeping "${primary}".`;
        }
    } else {
        // Description Rule: 140-160 chars
        if (len < 130) {
            isValid = false;
            retryPrompt = `The description "${result}" is too short (${len} chars). It MUST be at least 140 characters. Add a second sentence about the benefits or a specific Call to Action.`;
        } else if (len > 170) {
            isValid = false;
            retryPrompt = `The description is too long (${len} chars). Condense it to under 160 characters.`;
        }
    }

    if (!isValid) {
        console.log(`[AI Retry] ${type} validation failed (Length: ${len}). Retrying...`);
        console.log(`[AI Retry Prompt] ${retryPrompt}`);

        const retryResp = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: [
                 { role: 'user', parts: [{ text: userPrompt }] },
                 { role: 'model', parts: [{ text: result }] },
                 { role: 'user', parts: [{ text: retryPrompt }] }
            ],
            config: { 
                systemInstruction: systemInstruction,
                temperature: 0.8, // Increase creativity for the fix
                maxOutputTokens: 250 
            }
        });

        const retryResult = retryResp.text?.trim();
        if (retryResult) {
             result = retryResult.replace(/^["']|["']$/g, '').replace(/^(Meta )?(Title|Description):\s*/i, '');
        }
    }

    return result;

  } catch (e) {
      console.error("AI Generation Error", e);
      if (primary) {
          // Robust Fallback using keywords
          return type === 'title' 
            ? `${primary}: The Ultimate Guide & Expert Strategy (2025)` 
            : `Discover everything about ${primary}. This comprehensive guide covers key strategies, benefits, and expert tips to help you master ${primary} today.`;
      }
      return "";
  }
};

