  metaDescription: string;
  setMetaDescription: (s: string) => void;
  faqs: FAQ[];
  setFaqs: (f: FAQ[]) => void;
  onGenerateMetadata: (type: 'title' | 'description') => Promise<void>;
  onGenerateFAQs: () => void;
  onExportSchema: () => void;
  isAIProcessing?: boolean;
  setBrokenLinks?: (links: string[]) => void;
  content: string; 
  targetDomain?: string;
  setTargetDomain?: (s: string) => void;
}

const MetaFeedback = ({ current, min, max, label, startsWithKey }: any) => {
  let status = 'Optimal';
  let color = 'text-emerald-500';
  const len = current.length;

  if (len === 0) { status = 'Empty'; color = 'text-red-500'; }
  else if (len < min - 10) { status = 'Too Short'; color = 'text-red-400'; }
  else if (len < min) { status = 'Slightly Short'; color = 'text-yellow-500'; }
  else if (len > max + 10) { status = 'Too Long'; color = 'text-red-400'; }
  else if (len > max) { status = 'Slightly Long'; color = 'text-yellow-500'; }

  return (
    <div className="mt-2 flex items-center justify-between text-[10px] font-bold">
       <div className="flex items-center gap-3">
          <span className={`${color}`}>{len} chars</span>
          <span className="text-zinc-300">|</span>
          <span className={`${color}`}>{status}</span>
       </div>
       <div className="flex items-center gap-2">
          {startsWithKey !== undefined && (
            <span className={`px-1.5 py-0.5 rounded flex items-center gap-1 ${startsWithKey ? 'bg-emerald-50 text-emerald-600' : 'bg-zinc-100 text-zinc-400'}`}>
               Start {startsWithKey ? <CheckCircle2 size={10}/> : <AlertCircle size={10}/>}
            </span>
          )}
       </div>
    </div>
  );
};

const LinkChecker = ({ links, onCheck, checking }: { links: string[], onCheck: (l: string[]) => void, checking: boolean }) => {
    return (
       <div className="flex items-center justify-between mt-2">
         <div className="text-[10px] font-bold text-zinc-400">
            {links.length > 0 ? `${links.length} Broken Links Found` : 'No Broken Links Detected'}
         </div>
         <button onClick={() => onCheck([])} disabled={checking} className="flex items-center gap-1 text-[9px] font-black uppercase text-blue-600 bg-blue-50 px-3 py-1.5 rounded-full hover:bg-blue-100 transition-colors disabled:opacity-50">
            {checking ? <RefreshCw size={10} className="animate-spin" /> : <RefreshCw size={10} />}
            {checking ? 'Checking...' : 'Check Links'}
         </button>
       </div>
    );
};

