  // 4. SEO Metadata State
  const [metaTitle, setMetaTitle] = useState(() => localStorage.getItem('seo-meta-title-v2') || '');
  const [metaDescription, setMetaDescription] = useState(() => localStorage.getItem('seo-meta-desc-v2') || '');
  const [targets, setTargets] = useState<KeywordTarget>(() => {
    const saved = localStorage.getItem('seo-targets-v2');
    return saved ? JSON.parse(saved) : { primary: '', secondary: ['', '', ''] };
  });
  const [faqs, setFaqs] = useState<FAQ[]>(() => {
    const saved = localStorage.getItem('seo-faqs-v2');
    return saved ? JSON.parse(saved) : [];
  });
  const [brokenLinks, setBrokenLinks] = useState<string[]>([]);
  const [targetDomain, setTargetDomain] = useState(() => localStorage.getItem('seo-target-domain') || '');

  const deferredContent = useDeferredValue(content);

  // --- IMPORTANT: EMAILJS CONFIGURATION ---
  // To enable the "Report Issue" functionality, you need a free EmailJS account.
  // 1. Go to https://www.emailjs.com/ and sign up.
  // 2. Add an email service (e.g., Gmail).
  // 3. Create an email template. Your template should use variables like {{headline}} and {{summary}}.
  // 4. Find your credentials in your EmailJS account dashboard.
  // 5. Replace the placeholder values below with your actual keys.
  const EMAILJS_SERVICE_ID = 'YOUR_SERVICE_ID'; // Replace with your Service ID
  const EMAILJS_TEMPLATE_ID = 'YOUR_TEMPLATE_ID'; // Replace with your Template ID
  const EMAILJS_PUBLIC_KEY = 'YOUR_PUBLIC_KEY'; // Replace with your Public Key (User ID)

  useEffect(() => {
    if(EMAILJS_PUBLIC_KEY !== 'YOUR_PUBLIC_KEY') {
