  const [metaTitle, setMetaTitle] = useState(() => localStorage.getItem('seo-meta-title-v2') || '');
  const [metaDescription, setMetaDescription] = useState(() => localStorage.getItem('seo-meta-desc-v2') || '');
  const [targets, setTargets] = useState<KeywordTarget>(() => {
    const saved = localStorage.getItem('seo-targets-v2');
    return saved ? JSON.parse(saved) : { primary: '', secondary: ['', '', ''] };
  });
  const [faqs, setFaqs] = useState<FAQ[]>(() => {
    const saved = localStorage.getItem('seo-faqs-v2');
    return saved ? JSON.parse(saved) : [];
  });
  const [brokenLinks, setBrokenLinks] = useState<string[]>([]);
  const [targetDomain, setTargetDomain] = useState(() => localStorage.getItem('seo-target-domain') || '');

  const deferredContent = useDeferredValue(content);

  // Persistence
  useEffect(() => {
    localStorage.setItem('seo-editor-content-v2', content);
    localStorage.setItem('seo-targets-v2', JSON.stringify(targets));
    localStorage.setItem('seo-meta-desc-v2', metaDescription);
    localStorage.setItem('seo-meta-title-v2', metaTitle);
    localStorage.setItem('seo-faqs-v2', JSON.stringify(faqs));
    localStorage.setItem('seo-target-domain', targetDomain);
  }, [content, targets, metaDescription, metaTitle, faqs, targetDomain]);

  // Analysis Memoization
  const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
  const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
  const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
  const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, targets, metaDescription, metaTitle, brokenLinks, targetDomain), [deferredContent, keywords, targets, metaDescription, metaTitle, brokenLinks, targetDomain]);
  const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);
  const sentenceWarnings = useMemo(() => analyzeSentenceWarnings(deferredContent), [deferredContent]);

  // Optimization Engine
  const optimizationReport = useMemo(() => generateOptimizationReport(
    stats,
    health,
    readability,
    sentenceWarnings,
    targets,
    metaTitle,
    metaDescription,
    faqs.length,
    keywords
  ), [stats, health, readability, sentenceWarnings, targets, metaTitle, metaDescription, faqs, keywords]);

  const handleEditorChange = useCallback((newContent: string) => {
    startTransition(() => {
      setContent(newContent);
    });
  }, []);

  const showToast = (msg: string) => {
    setToast({ message: msg, visible: true });
    setTimeout(() => setToast(prev => ({...prev, visible: false})), 3000);
  };

  const onRewrite = useCallback(async (mode: RewriteMode) => {
    if (!editorInstance) return;
    const selectedText = editorInstance.getSelection();
    if (!selectedText) {
      alert("Please select text within the editor to use AI rewriting features.");
      return;
    }
    setIsAIProcessing(true);
    try {
      const results = await rewriteContent(selectedText, mode);
      if (results && results.length > 0) {
        editorInstance.insertContent(results[0]);
      }
    } catch (err) {
      console.error("AI Rewrite Failed:", err);
    } finally {
      setIsAIProcessing(false);
    }
  }, [editorInstance]);

  return (
    <div className="flex h-screen w-full bg-white overflow-hidden text-zinc-900 selection:bg-blue-100 relative">
      {/* Toast Notification */}
      <div className={`fixed top-6 left-1/2 -translate-x-1/2 z-[200] bg-zinc-900 text-white px-6 py-3 rounded-full shadow-2xl flex items-center gap-3 transition-all duration-300 ease-in-out ${toast.visible ? 'translate-y-0 opacity-100' : '-translate-y-12 opacity-0 pointer-events-none'}`}>
           <div className="w-2 h-2 rounded-full bg-emerald-400 shadow-[0_0_10px_rgba(52,211,153,0.5)]"></div>
           <span className="text-[11px] font-black uppercase tracking-widest">{toast.message}</span>
      </div>

      {/* Main Editor Viewport */}
      <div className="flex-1 flex flex-col min-w-0 border-r border-zinc-100 bg-zinc-50/50">
        <header className="h-16 border-b border-zinc-100 px-8 flex items-center justify-between bg-white shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-black shadow-lg shadow-blue-500/20">S</div>
            <h1 className="font-black tracking-tighter text-lg uppercase">SEO Focus <span className="text-zinc-300 font-medium">Editor</span></h1>
          </div>
        </header>

        <div className="flex-1 flex flex-col overflow-hidden relative">
          <div className="toolbar-container bg-white border-b border-zinc-100">
            <Toolbar 
              editorInstance={editorInstance} 
              stats={stats}
              wordTarget={wordTarget}
              onUpdate={() => handleEditorChange(editorInstance?.getContent() || '')}
              onNewDocument={() => confirm("Clear all content?") && editorInstance?.setContent('')}
              onShowHistory={() => {}} 
              onSaveVersion={() => {}}
              viewMode="focused"
              currentBlockType={currentBlockType}
            />
          </div>
          <main className="flex-1 overflow-hidden flex justify-center relative p-8">
            <div className="w-full max-w-[900px] h-full overflow-hidden bg-white relative rounded-[2px] shadow-sm border border-zinc-200/50">
              <Editor 
                initialContent={content} 
                onUpdate={handleEditorChange} 
                onInit={setEditorInstance} 
                onAIAssist={onRewrite} 
                onSelectionChange={setCurrentBlockType}
              />
            </div>
          </main>
        </div>
      </div>

      <Sidebar 
        activeTab={activeTab} setActiveTab={setActiveTab} 
        stats={stats} readability={readability} health={health} intent={intent} keywords={keywords} 
        seoTab={seoTab} setSeoTab={setSeoTab} isExpanded={isExpanded} setIsExpanded={setIsExpanded} 
        onRewrite={onRewrite} 
        isAIProcessing={isAIProcessing} targets={targets} setTargets={setTargets}
        metaTitle={metaTitle} setMetaTitle={setMetaTitle} metaDescription={metaDescription} setMetaDescription={setMetaDescription}
        faqs={faqs} setFaqs={setFaqs}
        onGenerateMetadata={async (type) => {
          // --- STEP 1: VERIFY GENERATION TRIGGER ---
          console.log("Generate button clicked for:", type);
          console.log("Content length:", content.length);
          console.log("Primary keyword:", targets.primary);

          setIsAIProcessing(true);
          try {
            // --- STEP 2: ENSURE FULL CONTENT & KEYWORDS ARE PASSED ---
            // Pass current value to force variation
            const currentValue = type === 'title' ? metaTitle : metaDescription;
            const res = await generateMetadata(content, type, targets, currentValue);

            // --- STEP 5: LOG AI RESPONSE ---
            console.log(`AI ${type} output:`, res);

            if (type === 'title') {
                setMetaTitle(res);
            } else {
                setMetaDescription(res);
            }
            showToast(`Meta ${type === 'title' ? 'Title' : 'Description'} Updated`);
          } catch (error) {
             console.error(error);
             showToast('Generation Failed');
          } finally { 
             setIsAIProcessing(false); 
          }
        }}
        onDetectAI={async () => {
          setIsAIProcessing(true);
          try {
            const res = await detectAIContent(content);
            alert(`AI Detection Score: ${res.score}%`);
          } finally { setIsAIProcessing(false); }
        }}
        onGenerateFAQs={async () => {
          setIsAIProcessing(true);
          try {
            const res = await generateFAQs(content);
            setFaqs(res);
            showToast('FAQs Generated');
          } finally { setIsAIProcessing(false); }
        }}
        onExportSchema={() => {
           navigator.clipboard.writeText(JSON.stringify({ "@context": "https://schema.org", "@type": "Article", "headline": metaTitle, "description": metaDescription }, null, 2));
           showToast('Schema Copied to Clipboard');
        }}
        onNavigateOutline={(text) => editorInstance?.scrollToText(text)}
        sentenceWarnings={sentenceWarnings}
        optimizationReport={optimizationReport}
        onHighlight={(enabled) => editorInstance?.toggleHighlights(targets, enabled)}
        setBrokenLinks={setBrokenLinks} // Pass setter for broken links
        targetDomain={targetDomain}
        setTargetDomain={setTargetDomain}
      />
    </div>
  );
}

import React, { useEffect, useState, useRef, useCallback, memo } from 'react';
import { KeywordTarget } from '../../types/editor.types';

interface EditorProps {
  initialContent: string;
  onUpdate: (html: string) => void;
  onInit: (instance: any) => void;
  onAIAssist: (mode: any) => void;
  onSelectionChange: (blockType: string) => void;
}

export const Editor = memo(({ initialContent, onUpdate, onInit, onAIAssist, onSelectionChange }: EditorProps) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const lastContentEmitted = useRef(initialContent);
  const [isHighlighting, setIsHighlighting] = useState(false);
  const lastBlockType = useRef('p');

  const analyzeParagraphs = useCallback(() => {
    if (!editorRef.current) return;
    const paras = editorRef.current.querySelectorAll('p');
    paras.forEach(p => {
      const words = p.innerText.trim().split(/\s+/).filter(Boolean).length;
      if (words > 150) {
        p.classList.add('para-warning');
      } else {
        p.classList.remove('para-warning');
      }
    });
  }, []);

  const handleSelectionChange = useCallback(() => {
    const selection = window.getSelection();
    if (!selection || selection.rangeCount === 0 || !editorRef.current) return;

    if (!editorRef.current.contains(selection.anchorNode)) {
        return;
    }

    let node = selection.anchorNode;
    let blockType = 'p'; // Default to paragraph

    while (node && node !== editorRef.current) {
        if (node.nodeType === Node.ELEMENT_NODE) {
            const element = node as HTMLElement;
            const tagName = element.tagName.toLowerCase();
            if (['p', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'blockquote', 'pre'].includes(tagName)) {
                blockType = tagName;
                break;
            }
        }
        node = node.parentNode;
    }

    if (blockType !== lastBlockType.current) {
      lastBlockType.current = blockType;
      onSelectionChange(blockType);
    }
  }, [onSelectionChange]);

  useEffect(() => {
    document.addEventListener('selectionchange', handleSelectionChange);
    return () => {
      document.removeEventListener('selectionchange', handleSelectionChange);
    };
  }, [handleSelectionChange]);

  const emitUpdate = useCallback(() => {
    if (editorRef.current) {
      const html = editorRef.current.innerHTML;
      lastContentEmitted.current = html;
      onUpdate(html);
      analyzeParagraphs();
    }
  }, [onUpdate, analyzeParagraphs]);

  // Expose Editor API to Parent
  useEffect(() => {
    if (editorRef.current) {
      editorRef.current.innerHTML = initialContent;
      lastContentEmitted.current = initialContent;

      const instance = {
        getContent: () => editorRef.current?.innerHTML || '',
        setContent: (html: string) => {
          if (editorRef.current) {
            editorRef.current.innerHTML = html;
            emitUpdate();
          }
        },
        execCommand: (cmd: string, ui: boolean, val: any) => {
          editorRef.current?.focus();
          document.execCommand(cmd, ui, val);
          emitUpdate();
          // After a command, the selection might change.
          handleSelectionChange(); 
        },
        insertContent: (html: string) => {
          editorRef.current?.focus();
          const sel = window.getSelection();
          if (sel && sel.rangeCount > 0) {
            const range = sel.getRangeAt(0);
            range.deleteContents();
            const el = document.createElement("div");
            el.innerHTML = html;
            const frag = document.createDocumentFragment();
            let node;
            while (node = el.firstChild) frag.appendChild(node);
            range.insertNode(frag);
            range.collapse(false);
            sel.removeAllRanges();
            sel.addRange(range);
          } else {
            editorRef.current!.innerHTML += html;
          }
          emitUpdate();
        },
        getSelection: () => {
          const sel = window.getSelection();
          return sel?.toString() || '';
        },
        scrollToText: (text: string) => {
          if (!editorRef.current) return;
          const walker = document.createTreeWalker(editorRef.current, NodeFilter.SHOW_TEXT);
          let node;
          while (node = walker.nextNode()) {
            if (node.textContent?.toLowerCase().includes(text.toLowerCase())) {
              (node.parentElement as HTMLElement)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
              break;
            }
          }
        },
        toggleHighlights: (targets: KeywordTarget, enabled: boolean) => {
          if (!editorRef.current) return;
          setIsHighlighting(enabled);

          const contentDiv = editorRef.current;

          // 1. Remove existing highlights (unwrap)
          const marks = contentDiv.querySelectorAll('mark.seo-highlight');
          marks.forEach(mark => {
            const parent = mark.parentNode;
            if (parent) {
              parent.replaceChild(document.createTextNode(mark.textContent || ''), mark);
              parent.normalize(); // Merge text nodes
            }
          });

          if (!enabled) {
            emitUpdate();
            return;
          }

          const terms = [
            { text: targets.primary, color: '#bbf7d0' }, // Green-200 for Primary
            ...targets.secondary.map(s => ({ text: s, color: '#fef08a' })) // Yellow-200 for Secondary
          ].filter(t => t.text && t.text.trim().length > 0);

          if (terms.length === 0) return;

          const walker = document.createTreeWalker(contentDiv, NodeFilter.SHOW_TEXT);
          const textNodes: Text[] = [];
          let node;
          while(node = walker.nextNode()) textNodes.push(node as Text);

          textNodes.forEach(textNode => {
             let text = textNode.nodeValue || '';
             let parent = textNode.parentNode;
             if (!parent || parent.nodeName === 'MARK' || parent.nodeName === 'SCRIPT' || parent.nodeName === 'STYLE') return;

             let hasMatch = false;
             const fragment = document.createDocumentFragment();
             let lastIndex = 0;

             while (lastIndex < text.length) {
                let bestMatch = { index: -1, term: '', color: '' };

                terms.forEach(({text: termText, color}) => {
                   const regex = new RegExp(`\\b${termText.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i');
                   const subText = text.substring(lastIndex);
                   const match = subText.match(regex);
                   if (match && match.index !== undefined) {
                      const absoluteIndex = lastIndex + match.index;
                      if (bestMatch.index === -1 || absoluteIndex < bestMatch.index) {
                         bestMatch = { index: absoluteIndex, term: match[0], color };
                      }
                   }
                });

                if (bestMatch.index !== -1) {
                   hasMatch = true;
                   fragment.appendChild(document.createTextNode(text.substring(lastIndex, bestMatch.index)));

                   const mark = document.createElement('mark');
                   mark.className = 'seo-highlight';
                   mark.style.backgroundColor = bestMatch.color;
                   mark.style.borderRadius = '4px';
                   mark.style.padding = '2px 0';
                   mark.textContent = bestMatch.term;
                   fragment.appendChild(mark);

                   lastIndex = bestMatch.index + bestMatch.term.length;
                } else {
                   fragment.appendChild(document.createTextNode(text.substring(lastIndex)));
                   break;
                }
             }

             if (hasMatch) {
               parent.replaceChild(fragment, textNode);
             }
          });

          emitUpdate();
        }
      };
      onInit(instance);
      analyzeParagraphs();
    }
  }, [onInit, analyzeParagraphs, emitUpdate, handleSelectionChange]);

  useEffect(() => {
    if (editorRef.current && initialContent !== lastContentEmitted.current) {
      editorRef.current.innerHTML = initialContent;
      lastContentEmitted.current = initialContent;
      analyzeParagraphs();
    }
  }, [initialContent, analyzeParagraphs]);

  const handleInput = () => {
    emitUpdate();
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    setTimeout(() => {
      emitUpdate();
    }, 0);
  };

  return (
    <div className="relative h-full w-full group overflow-hidden flex flex-col">
      <div 
        ref={editorRef}
        contentEditable
        onInput={handleInput}
        onPaste={handlePaste}
        className="editor-content flex-1 w-full h-full custom-scrollbar overflow-y-auto outline-none"
        spellCheck="true"
        aria-label="Content Editor"
      />
    </div>
  );
});

import React, { useRef, useState } from 'react';
import { 
  Bold, Italic, Underline, Link as LinkIcon, 
  ChevronDown, Undo, Redo,
  Table as TableIcon, Image as ImageIcon,
  X, Minus, Send, Strikethrough, Subscript, Superscript
} from 'lucide-react';
import { TextStats } from '../../types/editor.types';

interface ToolbarProps {
  editorInstance: any;
  stats?: TextStats;
  wordTarget?: number;
  onUpdate: () => void;
  onNewDocument: () => void;
  onShowHistory: () => void;
  onSaveVersion: () => void;
  viewMode: string;
  currentBlockType?: string;
}

const ToolbarGroup = ({ children }: { children?: React.ReactNode }) => (
  <div className="flex bg-zinc-50 p-1.5 rounded-2xl border border-zinc-100 mx-1 items-center shadow-sm">
    {children}
  </div>
);

const ToolbarButton = ({ icon, onClick, title, active = false, disabled = false }: any) => (
  <button 
    onMouseDown={(e) => { 
      e.preventDefault(); 
      onClick(e); 
    }} 
    disabled={disabled}
    className={`w-10 h-10 flex items-center justify-center hover:bg-white hover:shadow-sm rounded-xl transition-all disabled:opacity-20 ${active ? 'text-blue-600 bg-blue-50' : 'text-zinc-500'}`} 
    title={title}
  >
    {icon}
  </button>
);

export const Toolbar = ({ 
  editorInstance,
  stats,
  wordTarget = 1000,
  currentBlockType
}: ToolbarProps) => {
  const [modalConfig, setModalConfig] = useState<{ type: 'table' | 'image' | 'link' | null; title: string }>({ type: null, title: '' });
  const [input1, setInput1] = useState('');
  const [input2, setInput2] = useState('');

  if (!editorInstance) return null;

  const handleFormat = (cmd: string, val: any = null) => {
    editorInstance?.execCommand(cmd, false, val);
  };

  const openModal = (type: 'table' | 'image' | 'link') => {
    setInput1('');
    setInput2('');
    if (type === 'table') {
      setInput1('3');
      setInput2('3');
      setModalConfig({ type, title: 'Insert Table' });
    } else if (type === 'image') {
      setModalConfig({ type, title: 'Insert Image from URL' });
    } else if (type === 'link') {
      const selectedText = editorInstance.getSelection();
      if (!selectedText) {
          alert("Please select text to create a link.");
          return;
      }
      setModalConfig({ type, title: 'Insert Link' });
    }
  };

  const handleModalSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    switch (modalConfig.type) {
      case 'table':
        const rows = parseInt(input1);
        const cols = parseInt(input2);
        if (rows > 0 && cols > 0) {
          let tbl = '<table style="width:100%; border: 1px solid #e2e8f0; border-collapse: collapse; margin-bottom: 2rem;">';
          for (let r = 0; r < rows; r++) {
            tbl += '<tr>';
            for (let c = 0; c < cols; c++) {
              tbl += '<td style="border: 1px solid #e2e8f0; padding: 12px;">&nbsp;</td>';
            }
            tbl += '</tr>';
          }
          tbl += '</table><p>&nbsp;</p>';
          editorInstance.insertContent(tbl);
        }
        break;

      case 'image':
        if (input1) {
          editorInstance.insertContent(`<img src="${input1}" alt="Image" style="max-width:100%; border-radius:1rem; margin: 2rem 0; box-shadow: 0 10px 15px -3px rgba(0,0,0,0.05);" />`);
        }
        break;

      case 'link':
        if (input1) {
          handleFormat('createLink', input1);
        }
        break;
    }

    setModalConfig({ type: null, title: '' }); // Close modal
  };

  return (
    <>
      <div className="border-b border-zinc-100 bg-white/90 backdrop-blur-md p-3 flex flex-wrap gap-2 sticky top-0 z-20 overflow-x-auto no-scrollbar items-center shrink-0 justify-start px-8">

        <ToolbarGroup>
          <ToolbarButton icon={<Undo size={18} />} onClick={() => handleFormat('undo')} title="Undo" />
          <ToolbarButton icon={<Redo size={18} />} onClick={() => handleFormat('redo')} title="Redo" />
        </ToolbarGroup>

        <ToolbarGroup>
          <div className="relative flex items-center px-4">
            <select 
              value={currentBlockType || 'p'}
              onChange={(e) => handleFormat('formatBlock', e.target.value)} 
              className="bg-transparent appearance-none text-[11px] font-black uppercase outline-none cursor-pointer pr-8 py-2.5 tracking-widest text-zinc-800"
            >
              <option value="p">Paragraph</option>
              <option value="h1">Heading 1</option>
              <option value="h2">Heading 2</option>
              <option value="h3">Heading 3</option>
              <option value="h4">Heading 4</option>
              <option value="h5">Heading 5</option>
              <option value="h6">Heading 6</option>
              <option value="blockquote">Quote</option>
              <option value="pre">Code Block</option>
            </select>
            <ChevronDown size={12} className="absolute right-4 pointer-events-none text-zinc-400" />
          </div>
        </ToolbarGroup>

        <ToolbarGroup>
          <ToolbarButton icon={<Bold size={18} />} onClick={() => handleFormat('bold')} title="Bold" />
          <ToolbarButton icon={<Italic size={18} />} onClick={() => handleFormat('italic')} title="Italic" />
          <ToolbarButton icon={<Underline size={18} />} onClick={() => handleFormat('underline')} title="Underline" />
          <ToolbarButton icon={<Strikethrough size={18} />} onClick={() => handleFormat('strikethrough')} title="Strikethrough" />
          <ToolbarButton icon={<Subscript size={18} />} onClick={() => handleFormat('subscript')} title="Subscript" />
          <ToolbarButton icon={<Superscript size={18} />} onClick={() => handleFormat('superscript')} title="Superscript" />
        </ToolbarGroup>

        <ToolbarGroup>
          <ToolbarButton icon={<TableIcon size={18} />} onClick={() => openModal('table')} title="Insert Table" />
          <ToolbarButton icon={<ImageIcon size={18} />} onClick={() => openModal('image')} title="Insert Image" />
          <ToolbarButton icon={<Minus size={18} />} onClick={() => editorInstance.insertContent('<hr/>')} title="Horizontal Line" />
          <ToolbarButton icon={<LinkIcon size={18} />} onClick={() => openModal('link')} title="Insert Link" />
        </ToolbarGroup>

        {stats && (
          <div className="ml-auto hidden sm:flex items-center gap-4 px-4 py-2 bg-zinc-50 border border-zinc-100 rounded-2xl shadow-sm">
            <div className="flex flex-col items-end">
              <span className="text-[9px] font-black text-zinc-400 uppercase tracking-widest mb-0.5">Progress</span>
              <div className="text-[11px] font-black text-zinc-800 uppercase tabular-nums">
                {stats.words} <span className="text-zinc-300">/</span> {wordTarget} words
              </div>
            </div>
            <div className="w-20 h-1 bg-zinc-100 rounded-full overflow-hidden">
              <div 
                className="h-full bg-blue-600 transition-all duration-700 ease-out" 
                style={{ width: `${Math.min(100, (stats.words / wordTarget) * 100)}%` }} 
              />
            </div>
          </div>
        )}
      </div>

      {modalConfig.type && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-md p-4 animate-in fade-in duration-300">
          <div className="bg-white border border-zinc-200 rounded-[32px] w-full max-w-md shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b border-zinc-50 flex items-center justify-between">
              <h3 className="font-black text-xl uppercase tracking-tighter text-zinc-900 flex items-center gap-2">
                {modalConfig.title}
              </h3>
              <button onClick={() => setModalConfig({ type: null, title: '' })} className="text-zinc-400 hover:text-zinc-900 transition-colors">
                <X size={24}/>
              </button>
            </div>
            <form onSubmit={handleModalSubmit} className="p-8 space-y-6">
              {modalConfig.type === 'table' && (
                <div className="flex gap-4">
                  <div className="w-1/2 space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-zinc-400 ml-1">Rows</label>
                    <input required type="number" value={input1} onChange={(e) => setInput1(e.target.value)} min="1" className="w-full px-6 py-4 bg-zinc-50 border border-zinc-100 rounded-2xl outline-none focus:border-blue-500 transition-all font-bold" />
                  </div>
                  <div className="w-1/2 space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-zinc-400 ml-1">Columns</label>
                    <input required type="number" value={input2} onChange={(e) => setInput2(e.target.value)} min="1" className="w-full px-6 py-4 bg-zinc-50 border border-zinc-100 rounded-2xl outline-none focus:border-blue-500 transition-all font-bold" />
                  </div>
                </div>
