  const now = Date.now();
  return {
    id: crypto.randomUUID(),
    title,
    content: `<h1>${title}</h1><p>Start writing here...</p>`,
    createdAt: now,
    updatedAt: now,
    metaTitle: '',
    metaDescription: '',
    targets: { primary: '', secondary: ['', '', ''] },
    faqs: [],
    targetDomain: '',
  };
};

