<content><![CDATA[import * as React from 'react';
import { useState, useEffect, useCallback } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { LocalDocument } from './types/document.types';
import DashboardPage from './pages/DashboardPage.tsx';
import EditorPage from './pages/EditorPage.tsx';
import { useLocalStorage } from './hooks/useLocalStorage';
import { docManager } from './core/doc-manager';
import { debounce } from './utils/debounce';
import './App.css';

function App() {
  const [documents, setDocuments] = React.useState<LocalDocument[]>([]);
  const { load, save } = useLocalStorage('docs');

  React.useEffect(() => {
    const loadedDocs = load();
    if (loadedDocs) {
      setDocuments(loadedDocs);
    }
  }, []);

  React.useEffect(() => {
    save(documents);
  }, [documents]);

  const handleDeleteDoc = (id: string) => {
    setDocuments((prevDocs) => prevDocs.filter((doc) => doc.id !== id));
    return true;
  };

  const handleCreateDoc = () => {
    const newDocId = docManager.createDoc(documents);
    setDocuments([...documents, { id: newDocId, title: 'New Document', content: '', createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() }]);
    return newDocId;
  };

  const handleRenameDoc = (id: string, newTitle: string) => {
    setDocuments((prevDocs) =>
      prevDocs.map((doc) =>
        doc.id === id ? { ...doc, title: newTitle, updatedAt: new Date().toISOString() } : doc
      )
    );
  };

  const debouncedSave = React.useCallback(debounce((docs: LocalDocument[]) => {
    save(docs);
  }, 500), []);

  const updateDocument = React.useCallback((id: string, updates: Partial<Omit<LocalDocument, 'id' | 'createdAt'>>) => {
    setDocuments((prevDocs) =>
      prevDocs.map((doc) => (doc.id === id ? { ...doc, ...updates, updatedAt: new Date().toISOString() } : doc))
    );
    debouncedSave(
      documents.map((doc) =>
        doc.id === id ? { ...doc, ...updates, updatedAt: new Date().toISOString() } : doc
      )
    );
  }, [debouncedSave]);

  return (
    <Routes>
      <Route
        path="/"
        element={
          <DashboardPage
            documents={documents}
            onCreate={handleCreateDoc}
            onDelete={handleDeleteDoc}
            onRename={handleRenameDoc}
          />
        }
      />
      <Route
        path="/edit/:id"
        element={<EditorPage documents={documents} updateDocument={updateDocument} onRename={handleRenameDoc} />}
      />
      <Route path="*" element={<Navigate to="/" />} />
    </Routes>
  );
}

export default App;
]]></content>
