                    </td>
                  </tr>
                )})}
              </tbody>
            </table>
          ) : (
            <div className="p-8 text-center text-zinc-400 text-xs font-bold italic">
              No keywords found matching "{searchTerm}"
            </div>
          )}
        </div>
        {filteredKeywords.length > 12 && (
          <button onClick={() => setIsExpanded(!isExpanded)} className="w-full py-4 text-[10px] font-black uppercase text-blue-600 flex items-center justify-center gap-2 mt-4">
            {isExpanded ? 'Collapse' : `Full List (${filteredKeywords.length})`}
            <ChevronDown className={`transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} size={16} />
          </button>
        )}
      </div>

      <div className="pt-6 border-t border-zinc-50">
        <h3 className="text-[10px] font-black text-zinc-300 uppercase tracking-[0.25em] mb-5">NLP Terms</h3>
        <div className="flex flex-wrap gap-2">
          {stats.entities.length > 0 ? stats.entities.map((entity, i) => (
            <div key={i} className="px-3 py-1.5 bg-white border border-zinc-100 rounded-full text-[10px] font-bold text-zinc-600 flex items-center gap-1.5 shadow-sm">
              <Cpu size={10} className="text-blue-500" /> {entity}
            </div>
          )) : <div className="text-[11px] text-zinc-400 italic text-center w-full">No entities detected.</div>}
        </div>
      </div>
    </div>
  );
};

import * as React from 'react';
import { Trash, Plus, FileCode, CheckCircle2, AlertCircle, RefreshCw, ChevronDown, ChevronRight, Link as LinkIcon, ExternalLink, Activity, Globe } from 'lucide-react';
import { SEOHealth, FAQ } from '../../../types/editor.types';

interface SEOTabProps {
  health: SEOHealth;
  metaTitle: string;
  setMetaTitle: (s: string) => void;
  metaDescription: string;
  setMetaDescription: (s: string) => void;
  faqs: FAQ[];
  setFaqs: (f: FAQ[]) => void;
  onGenerateMetadata: (type: 'title' | 'description') => Promise<void>;
  onGenerateFAQs: () => void;
  onExportSchema: () => void;
  isAIProcessing?: boolean;
  setBrokenLinks?: (links: string[]) => void;
  content: string; 
  targetDomain?: string;
  setTargetDomain?: (s: string) => void;
}

const MetaFeedback = ({ current, min, max, label, startsWithKey }: any) => {
  let status = 'Optimal';
  let color = 'text-emerald-500';
  const len = current.length;

  if (len === 0) { status = 'Empty'; color = 'text-red-500'; }
  else if (len < min - 10) { status = 'Too Short'; color = 'text-red-400'; }
  else if (len < min) { status = 'Slightly Short'; color = 'text-yellow-500'; }
  else if (len > max + 10) { status = 'Too Long'; color = 'text-red-400'; }
  else if (len > max) { status = 'Slightly Long'; color = 'text-yellow-500'; }

  return (
    <div className="mt-2 flex items-center justify-between text-[10px] font-bold">
       <div className="flex items-center gap-3">
          <span className={`${color}`}>{len} chars</span>
          <span className="text-zinc-300">|</span>
          <span className={`${color}`}>{status}</span>
       </div>
       <div className="flex items-center gap-2">
          {startsWithKey !== undefined && (
            <span className={`px-1.5 py-0.5 rounded flex items-center gap-1 ${startsWithKey ? 'bg-emerald-50 text-emerald-600' : 'bg-zinc-100 text-zinc-400'}`}>
               Start {startsWithKey ? <CheckCircle2 size={10}/> : <AlertCircle size={10}/>}
            </span>
          )}
       </div>
    </div>
  );
};

const LinkChecker = ({ links, onCheck, checking }: { links: string[], onCheck: (l: string[]) => void, checking: boolean }) => {
    return (
       <div className="flex items-center justify-between mt-2">
         <div className="text-[10px] font-bold text-zinc-400">
            {links.length > 0 ? `${links.length} Broken Links Found` : 'No Broken Links Detected'}
         </div>
         <button onClick={() => onCheck([])} disabled={checking} className="flex items-center gap-1 text-[9px] font-black uppercase text-blue-600 bg-blue-50 px-3 py-1.5 rounded-full hover:bg-blue-100 transition-colors disabled:opacity-50">
            {checking ? <RefreshCw size={10} className="animate-spin" /> : <RefreshCw size={10} />}
            {checking ? 'Checking...' : 'Check Links'}
         </button>
       </div>
    );
};

export const SEOTab = ({ 
  health, metaTitle, setMetaTitle, metaDescription, setMetaDescription, 
  faqs, setFaqs, onGenerateMetadata, onGenerateFAQs, onExportSchema, isAIProcessing,
  setBrokenLinks, targetDomain, setTargetDomain
}: SEOTabProps) => {
  const [checkingLinks, setCheckingLinks] = React.useState(false);
  const [breakdownOpen, setBreakdownOpen] = React.useState(false);
  const [generatingType, setGeneratingType] = React.useState<'title' | 'description' | null>(null);

  // Extract URLs for checking (simplified extraction here for the checker logic)
  const performLinkCheck = async () => {
    if (!setBrokenLinks) return;
    setCheckingLinks(true);

    const editorEl = document.querySelector('.editor-content');
    if (!editorEl) {
        setCheckingLinks(false);
        return;
    }

    const anchors = Array.from(editorEl.querySelectorAll('a[href]')) as HTMLAnchorElement[];
    const externalUrls = anchors
        .map(a => a.href)
        .filter(href => href.startsWith('http'));

    const broken: string[] = [];

    // Batch check
    await Promise.allSettled(externalUrls.map(async (url) => {
        try {
            const res = await fetch(url, { method: 'HEAD', mode: 'no-cors' });
        } catch (e) {
            broken.push(url);
        }
    }));

    // Remove duplicates
    const uniqueBroken = Array.from(new Set(broken));
    setBrokenLinks(uniqueBroken);
    setCheckingLinks(false);
  };

  const handleGenerate = async (type: 'title' | 'description') => {
    setGeneratingType(type);
    try {
      await onGenerateMetadata(type);
    } catch (e) {
      console.error(e);
    } finally {
      setGeneratingType(null);
    }
  };

  return (
    <div className="space-y-10 animate-in fade-in slide-in-from-right-4 duration-500">
      {/* 1. SEO Score Badge (Styled like Insights Content Score) */}
      <div className="p-6 bg-white border border-zinc-100 rounded-[32px] text-zinc-900 shadow-lg shadow-zinc-500/5">
        <div className="flex items-center justify-between mb-4">
          <span className="text-[10px] font-black uppercase tracking-[0.25em] text-zinc-400">SEO Score</span>
          <Activity size={16} className="text-blue-500" />
        </div>
        <div className="flex items-end gap-3 mb-6">
          <div className="text-6xl font-black tracking-tighter leading-none">{health.score}</div>
          <div className="text-xl font-black text-zinc-300 pb-1">/100</div>
        </div>
        <div className="h-1.5 bg-zinc-100 rounded-full overflow-hidden mb-4">
          <div 
            className="h-full bg-zinc-900 transition-all duration-1000 ease-out" 
            style={{ width: `${health.score}%` }} 
          />
        </div>
        <div className="flex items-center justify-between">
           <p className="text-[10px] font-bold text-zinc-400 leading-relaxed">
             Optimization level based on structure & meta.
           </p>
            <button 
              onClick={() => setBreakdownOpen(!breakdownOpen)}
              className="flex items-center gap-1 text-[9px] font-black uppercase text-zinc-500 hover:text-zinc-900 transition-colors"
            >
              {breakdownOpen ? 'Hide' : 'Breakdown'}
              {breakdownOpen ? <ChevronDown size={12}/> : <ChevronRight size={12}/>}
            </button>
        </div>

        {breakdownOpen && (
          <div className="mt-6 pt-6 border-t border-zinc-100 space-y-3 animate-in slide-in-from-top-2 duration-300">
            {[
              { label: 'Meta Tags', score: health.scoreBreakdown.meta, max: 40 },
              { label: 'Heading Structure', score: health.scoreBreakdown.heading, max: 15 },
              { label: 'Keyword Opt', score: health.scoreBreakdown.keyword, max: 20 },
              { label: 'Content Quality', score: health.scoreBreakdown.content, max: 15 },
              { label: 'Link Structure', score: health.scoreBreakdown.link, max: 10 }
            ].map((cat, i) => (
              <div key={i} className="flex items-center justify-between text-[10px] font-bold">
                 <span className="text-zinc-400 uppercase tracking-wider">{cat.label}</span>
                 <div className="flex items-center gap-2">
                    <div className="w-24 h-1.5 bg-zinc-100 rounded-full overflow-hidden">
                       <div className="h-full bg-zinc-800" style={{ width: `${(cat.score / cat.max) * 100}%` }}></div>
                    </div>
                    <span className="text-zinc-800 w-8 text-right">{cat.score}/{cat.max}</span>
                 </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="space-y-8">
        <h3 className="text-[10px] font-black text-zinc-300 uppercase tracking-[0.25em] mb-5">Meta Optimization</h3>

        {/* Title */}
        <div className="space-y-3">
