              disabled={isAIProcessing}
            >
              {generatingType === 'title' ? 'Generating...' : 'Generate'}
            </button>
          </div>
          <div className="bg-white border border-zinc-100 rounded-2xl p-4 focus-within:border-blue-300 transition-colors">
             <input 
               type="text" 
               value={metaTitle} 
               onChange={(e) => setMetaTitle(e.target.value)} 
               placeholder="Enter Meta Title..." 
               className="w-full text-xs font-bold outline-none text-zinc-800 placeholder:text-zinc-300" 
             />
             <MetaFeedback 
               current={metaTitle} 
               min={50} max={60} 
               // hasKey removed as requested
             />
          </div>
        </div>

        {/* Description */}
        <div className="space-y-3">
