              <OptimizationGroup 
                title="Improvements" 
                items={report.improvements} 
                variant="improvement" 
                defaultOpen={false}
              />
              <OptimizationGroup 
                title="Enhancements" 
                items={report.enhancements} 
                variant="enhancement" 
                defaultOpen={false}
              />
            </div>
          )}
