};

import * as React from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { LocalDocument } from '../types/document.types';
import { Plus, Search, MoreVertical, Edit, Trash2, ArrowUpDown, FileText, Clock } from 'lucide-react';
import { getStats } from '../core/text-analysis';

interface DashboardProps {
    documents: LocalDocument[];
    onCreate: () => string;
    onDelete: (id: string) => boolean;
    onRename: (id: string, newTitle: string) => void;
}

// Fix: Updated the onDelete prop type to expect a function returning a boolean to match the parent component's prop.
const DocumentCard = ({ doc, onDelete, onRename }: { doc: LocalDocument, onDelete: (id: string) => boolean, onRename: (id: string, newTitle: string) => void }) => {
    const [menuOpen, setMenuOpen] = React.useState(false);
    const [isEditing, setIsEditing] = React.useState(false);
    const [title, setTitle] = React.useState(doc.title);
    const menuRef = React.useRef<HTMLDivElement>(null);

    const wordCount = React.useMemo(() => getStats(doc.content).words, [doc.content]);

    const handleRenameSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (title.trim()) {
            onRename(doc.id, title.trim());
        } else {
            setTitle(doc.title); // revert if empty
        }
        setIsEditing(false);
    };

    return (
        <div className="bg-white border border-zinc-100 rounded-2xl flex flex-col group relative shadow-sm hover:shadow-lg hover:-translate-y-1 transition-all duration-300">
            <Link to={`/editor/${doc.id}`} className="flex-1 p-6 flex flex-col">
                {isEditing ? (
                    <form onSubmit={handleRenameSubmit} className="mb-2">
                        <input
                            type="text"
                            value={title}
                            onChange={(e) => setTitle(e.target.value)}
                            onBlur={handleRenameSubmit}
                            className="w-full text-lg font-black text-zinc-900 bg-zinc-100 p-2 rounded-lg outline-none border-2 border-blue-500"
                            autoFocus
                            onClick={(e) => e.preventDefault()}
                        />
                    </form>
                ) : (
                    <h3 className="text-lg font-black text-zinc-900 mb-2 truncate group-hover:text-blue-600 transition-colors">{doc.title}</h3>
                )}
                <p className="text-xs text-zinc-400 font-medium flex-1">
                    Last updated: {new Date(doc.updatedAt).toLocaleDateString()}
                </p>
            </Link>
            <div className="border-t border-zinc-100 px-6 py-4 flex items-center justify-between text-xs font-bold text-zinc-500">
                <div className="flex items-center gap-2">
                    <FileText size={14} />
                    <span>{wordCount} words</span>
                </div>
                <div className="flex items-center gap-2">
                    <Clock size={14} />
                    <span>{new Date(doc.createdAt).toLocaleDateString()}</span>
                </div>
            </div>

            {!isEditing && (
                <div ref={menuRef} className="absolute top-4 right-4">
                    <button onClick={() => setMenuOpen(!menuOpen)} className="p-2 rounded-full hover:bg-zinc-100 opacity-0 group-hover:opacity-100 transition-opacity">
                        <MoreVertical size={16} className="text-zinc-500" />
                    </button>
                    {menuOpen && (
                        <div className="absolute top-full right-0 mt-1 w-32 bg-white border border-zinc-100 rounded-xl shadow-xl z-10 p-2">
                            <button onClick={(e) => { e.stopPropagation(); setIsEditing(true); setMenuOpen(false); }} className="w-full text-left flex items-center gap-2 p-2 text-xs font-bold text-zinc-700 hover:bg-zinc-100 rounded-lg"><Edit size={14}/> Rename</button>
                            <button onClick={(e) => { e.stopPropagation(); onDelete(doc.id); }} className="w-full text-left flex items-center gap-2 p-2 text-xs font-bold text-red-600 hover:bg-red-50 rounded-lg"><Trash2 size={14}/> Delete</button>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default function DashboardPage({ documents, onCreate, onDelete, onRename }: DashboardProps) {
    const navigate = useNavigate();
    const [searchTerm, setSearchTerm] = React.useState('');
    const [sortOrder, setSortOrder] = React.useState<'updatedAt' | 'createdAt' | 'title'>('updatedAt');

    const handleCreate = () => {
        const newId = onCreate();
        navigate(`/editor/${newId}`);
    };

    const sortedAndFilteredDocs = React.useMemo(() => {
        return documents
            .filter(doc => doc.title.toLowerCase().includes(searchTerm.toLowerCase()))
            .sort((a, b) => {
                if (sortOrder === 'title') {
                    return a.title.localeCompare(b.title);
                }
                return b[sortOrder] - a[sortOrder];
            });
    }, [documents, searchTerm, sortOrder]);

    return (
        <div className="w-full h-full flex flex-col">
            <header className="bg-white border-b border-zinc-100 p-6 flex items-center justify-between sticky top-0 z-10">
                <div className="flex items-center gap-3">
                    <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-black shadow-lg shadow-blue-500/20">S</div>
                    <h1 className="font-black tracking-tighter text-xl uppercase">Dashboard</h1>
                </div>
                <button onClick={handleCreate} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg text-xs font-bold uppercase tracking-wider hover:bg-blue-700 transition-colors shadow-md shadow-blue-500/20">
                    <Plus size={16} /> New Document
                </button>
            </header>
            <main className="flex-1 p-8 overflow-y-auto">
                <div className="max-w-7xl mx-auto">
                    <div className="mb-8 flex items-center justify-between gap-4">
                        <div className="relative flex-1 max-w-lg">
                            <Search size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-400" />
                            <input
                                type="text"
                                placeholder="Search documents..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="w-full bg-white border border-zinc-200 rounded-lg py-3 pl-12 pr-4 text-sm font-bold focus:border-blue-500 outline-none transition-colors"
                            />
                        </div>
                        <div className="relative">
                            <select
                                value={sortOrder}
                                onChange={(e) => setSortOrder(e.target.value as any)}
                                className="appearance-none bg-white border border-zinc-200 rounded-lg py-3 px-4 pr-10 text-sm font-bold text-zinc-600 focus:border-blue-500 outline-none"
                            >
                                <option value="updatedAt">Sort by Updated</option>
                                <option value="createdAt">Sort by Created</option>
                                <option value="title">Sort by Title</option>
                            </select>
                            <ArrowUpDown size={16} className="absolute right-3 top-1/2 -translate-y-1/2 text-zinc-400 pointer-events-none" />
                        </div>
                    </div>
                    {sortedAndFilteredDocs.length > 0 ? (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                            {sortedAndFilteredDocs.map(doc => (
                                <DocumentCard key={doc.id} doc={doc} onDelete={onDelete} onRename={onRename} />
                            ))}
                        </div>
                    ) : (
                        <div className="text-center py-20">
                            <h3 className="text-lg font-bold text-zinc-600">No documents found</h3>
                            <p className="text-sm text-zinc-400 mt-2">Create a new document to get started.</p>
                        </div>
                    )}
                </div>
            </main>
        </div>
    );
}

import * as React from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { X, Send, ArrowLeft, Edit } from 'lucide-react';
import { LocalDocument } from '../types/document.types';

// Core Analysis Logic
import { getStats } from '../core/text-analysis.ts';
import { getKeywords } from '../core/keyword-density.ts';
import { getReadabilityScore } from '../core/readability.ts';
import { analyzeSEOHealth } from '../core/seo-health.ts';
import { detectIntent } from '../core/intent-detector.ts';
import { analyzeSentenceWarnings } from '../core/sentence-analysis.ts';
import { generateOptimizationReport } from '../core/optimization-engine.ts';

// AI Integration
import { rewriteContent, generateMetadata, detectAIContent, RewriteMode, generateFAQs } from '../ai/ai-engine.ts';

// Components
import { Toolbar } from '../components/editor/Toolbar.tsx';
import { Sidebar } from '../components/layout/Sidebar.tsx';
import { Editor } from '../components/editor/Editor.tsx';
import { Tab, SEOPhraseTab } from '../types/editor.types.ts';

interface EditorPageProps {
    documents: LocalDocument[];
    updateDocument: (id: string, updates: Partial<Omit<LocalDocument, 'id' | 'createdAt'>>) => void;
    onRename: (id: string, newTitle: string) => void;
}

export default function EditorPage({ documents, updateDocument, onRename }: EditorPageProps) {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();

    const activeDocument = React.useMemo(() => {
        return documents.find(doc => doc.id === id) || null;
    }, [documents, id]);

    // UI State
    const [activeTab, setActiveTab] = React.useState<Tab>('insights');
    const [wordTarget, setWordTarget] = React.useState(1000);
    const [seoTab, setSeoTab] = React.useState<SEOPhraseTab>(1);
    const [isExpanded, setIsExpanded] = React.useState(false);
    const [isAIProcessing, setIsAIProcessing] = React.useState(false);
    const [editorInstance, setEditorInstance] = React.useState<any>(null);
    const [toast, setToast] = React.useState<{ message: string, visible: boolean }>({ message: '', visible: false });
    const [currentBlockType, setCurrentBlockType] = React.useState('p');
    const [isLinkActive, setIsLinkActive] = React.useState(false);
    const [brokenLinks, setBrokenLinks] = React.useState<string[]>([]);
    const [isEditingTitle, setIsEditingTitle] = React.useState(false);
    const [headerTitle, setHeaderTitle] = React.useState(activeDocument?.title || '');
    const titleInputRef = React.useRef<HTMLInputElement>(null);

    React.useEffect(() => {
        if (activeDocument) {
            setHeaderTitle(activeDocument.title);
        }
    }, [activeDocument]);

    React.useEffect(() => {
        if (isEditingTitle && titleInputRef.current) {
            titleInputRef.current.focus();
            titleInputRef.current.select();
        }
    }, [isEditingTitle]);

    const deferredContent = React.useDeferredValue(activeDocument?.content || '');

    // Analysis Memoization
    const stats = React.useMemo(() => getStats(deferredContent), [deferredContent]);
    const keywords = React.useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
    const readability = React.useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
    const health = React.useMemo(() => analyzeSEOHealth(deferredContent, keywords, activeDocument?.targets || { primary: '', secondary: [] }, activeDocument?.metaDescription || '', activeDocument?.metaTitle || '', brokenLinks, activeDocument?.targetDomain || ''), [deferredContent, keywords, activeDocument, brokenLinks]);
    const intent = React.useMemo(() => detectIntent(deferredContent), [deferredContent]);
    const sentenceWarnings = React.useMemo(() => analyzeSentenceWarnings(deferredContent), [deferredContent]);

    const optimizationReport = React.useMemo(() => {
        if (!activeDocument) return { critical: [], improvements: [], enhancements: [] };
        return generateOptimizationReport(
            stats, health, readability, sentenceWarnings,
            activeDocument.targets, activeDocument.metaTitle, activeDocument.metaDescription, activeDocument.faqs.length, keywords
        );
    }, [stats, health, readability, sentenceWarnings, activeDocument, keywords]);

    const handlePropUpdate = React.useCallback((updates: Partial<Omit<LocalDocument, 'id' | 'createdAt'>>) => {
        if (id) {
            updateDocument(id, updates);
        }
    }, [id, updateDocument]);

    const handleEditorChange = React.useCallback((newContent: string) => {
        if(id) {
            React.startTransition(() => {
                updateDocument(id, { content: newContent });
            });
        }
    }, [id, updateDocument]);

    const handleSelectionChange = React.useCallback((blockType: string, isLink: boolean) => {
        setCurrentBlockType(blockType);
        setIsLinkActive(isLink);
    }, []);

    const handleTitleRename = (e: React.FormEvent) => {
        e.preventDefault();
        if(id && headerTitle.trim()){
            onRename(id, headerTitle.trim());
        } else {
            setHeaderTitle(activeDocument?.title || '');
        }
        setIsEditingTitle(false);
    };

    const showToast = (msg: string) => {
        setToast({ message: msg, visible: true });
        setTimeout(() => setToast(prev => ({ ...prev, visible: false })), 3000);
    };

    const onRewrite = React.useCallback(async (mode: RewriteMode) => {
        if (!editorInstance) return;
        const selectedText = editorInstance.getSelection();
        if (!selectedText) {
            alert("Please select text to use AI rewriting features.");
            return;
        }
        setIsAIProcessing(true);
        try {
            const results = await rewriteContent(selectedText, mode);
            if (results && results.length > 0) editorInstance.insertContent(results[0]);
        } catch (err) { console.error("AI Rewrite Failed:", err); }
        finally { setIsAIProcessing(false); }
    }, [editorInstance]);

    if (!activeDocument) {
        return (
            <div className="w-screen h-screen bg-zinc-100 flex items-center justify-center flex-col gap-4">
                <h2 className="text-xl font-bold">Document not found</h2>
                <Link to="/dashboard" className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-bold hover:bg-blue-700">Go to Dashboard</Link>
            </div>
        );
    }

    return (
        <div className="flex h-screen w-full bg-white overflow-hidden text-zinc-900 selection:bg-blue-100 relative">
             <div className={`fixed top-6 left-1/2 -translate-x-1/2 z-[200] bg-zinc-900 text-white px-6 py-3 rounded-full shadow-2xl flex items-center gap-3 transition-all duration-300 ease-in-out ${toast.visible ? 'translate-y-0 opacity-100' : '-translate-y-12 opacity-0 pointer-events-none'}`}>
                 <div className="w-2 h-2 rounded-full bg-emerald-400 shadow-[0_0_10px_rgba(52,211,153,0.5)]"></div>
                 <span className="text-[11px] font-black uppercase tracking-widest">{toast.message}</span>
             </div>

            <div className="flex-1 flex flex-col min-w-0 bg-zinc-50/50">
                <header className="h-16 border-b border-zinc-100 px-6 flex items-center justify-between bg-white shrink-0">
                    <div className="flex items-center gap-2">
                         <Link to="/dashboard" className="p-2 rounded-lg hover:bg-zinc-100 text-zinc-500 transition-colors" title="Back to Dashboard">
                           <ArrowLeft size={18} />
                         </Link>
                         <div className="w-px h-6 bg-zinc-200 mx-2"></div>
                         {isEditingTitle ? (
                             <form onSubmit={handleTitleRename}>
                                 <input
                                     ref={titleInputRef}
                                     type="text"
                                     value={headerTitle}
                                     onChange={(e) => setHeaderTitle(e.target.value)}
                                     onBlur={handleTitleRename}
                                     className="font-black tracking-tighter text-lg uppercase bg-zinc-100 p-1 rounded-md outline-none"
                                 />
                             </form>
                         ) : (
                             <div className="flex items-center gap-2 group" onClick={() => setIsEditingTitle(true)}>
                                <h1 className="font-black tracking-tighter text-lg uppercase truncate max-w-xs cursor-pointer">{headerTitle}</h1>
                                <Edit size={14} className="text-zinc-400 opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer" />
                             </div>
                         )}
                    </div>
                </header>

                <div className="flex-1 flex flex-col overflow-hidden relative">
                    <div className="toolbar-container bg-white border-b border-zinc-100">
                        <Toolbar
                            editorInstance={editorInstance} stats={stats} wordTarget={wordTarget}
                            onUpdate={() => handleEditorChange(editorInstance?.getContent() || '')}
                            onNewDocument={() => { }} onShowHistory={() => { }} onSaveVersion={() => { }}
                            viewMode="focused" currentBlockType={currentBlockType} isLinkActive={isLinkActive}
                        />
                    </div>
                    <main className="flex-1 overflow-hidden flex justify-center relative p-8">
                        <div className="w-full max-w-[900px] h-full overflow-hidden bg-white relative rounded-[2px] shadow-sm border border-zinc-200/50">
                            <Editor
                                key={activeDocument.id}
                                initialContent={activeDocument.content}
                                onUpdate={handleEditorChange}
                                onInit={setEditorInstance}
                                onAIAssist={onRewrite}
                                onSelectionChange={handleSelectionChange}
                            />
                        </div>
                    </main>
                </div>
            </div>

            <Sidebar
                activeTab={activeTab} setActiveTab={setActiveTab}
                stats={stats} readability={readability} health={health} intent={intent} keywords={keywords}
                seoTab={seoTab} setSeoTab={setSeoTab} isExpanded={isExpanded} setIsExpanded={setIsExpanded}
                onRewrite={onRewrite}
                isAIProcessing={isAIProcessing} targets={activeDocument.targets} setTargets={(t) => handlePropUpdate({ targets: t })}
                metaTitle={activeDocument.metaTitle} setMetaTitle={(s) => handlePropUpdate({ metaTitle: s })}
                metaDescription={activeDocument.metaDescription} setMetaDescription={(s) => handlePropUpdate({ metaDescription: s })}
                faqs={activeDocument.faqs} setFaqs={(f) => handlePropUpdate({ faqs: f })}
                onGenerateMetadata={async (type) => {
                    setIsAIProcessing(true);
                    try {
                        const currentValue = type === 'title' ? activeDocument.metaTitle : activeDocument.metaDescription;
                        const res = await generateMetadata(activeDocument.content, type, activeDocument.targets, currentValue);
                        handlePropUpdate(type === 'title' ? { metaTitle: res } : { metaDescription: res });
                        showToast(`Meta ${type === 'title' ? 'Title' : 'Description'} Updated`);
                    } catch (error) {
                        console.error(error); showToast('Generation Failed');
                    } finally { setIsAIProcessing(false); }
                }}
                onDetectAI={async () => {
                    setIsAIProcessing(true);
                    try {
                        const res = await detectAIContent(activeDocument.content);
                        alert(`AI Detection Score: ${res.score}%`);
                    } finally { setIsAIProcessing(false); }
                }}
                onGenerateFAQs={async () => {
                    setIsAIProcessing(true);
                    try {
                        const res = await generateFAQs(activeDocument.content);
                        handlePropUpdate({ faqs: res });
                        showToast('FAQs Generated');
                    } finally { setIsAIProcessing(false); }
                }}
                onExportSchema={() => {
                    navigator.clipboard.writeText(JSON.stringify({ "@context": "https://schema.org", "@type": "Article", "headline": activeDocument.metaTitle, "description": activeDocument.metaDescription }, null, 2));
                    showToast('Schema Copied to Clipboard');
                }}
                onNavigateOutline={(text) => editorInstance?.scrollToText(text)}
                sentenceWarnings={sentenceWarnings}
                optimizationReport={optimizationReport}
                onHighlight={(enabled) => editorInstance?.toggleHighlights(activeDocument.targets, enabled)}
                setBrokenLinks={setBrokenLinks}
                targetDomain={activeDocument.targetDomain}
                setTargetDomain={(s) => handlePropUpdate({ targetDomain: s })}
            />
        </div>
    );
}

