import * as React from 'react';
import { FilePlus, FileText, MoreVertical, Edit, Trash2, Download, Upload } from 'lucide-react';
import { LocalDocument } from '../../types/document.types';

interface DocumentSidebarProps {
  documents: LocalDocument[];
  activeDocId: string | null;
  onSelect: (id: string) => void;
  onCreate: () => void;
  onDelete: (id: string) => void;
  onRename: (id: string, newTitle: string) => void;
  onImport: (doc: LocalDocument) => void;
  onExport: (id: string) => void;
}

export const DocumentSidebar = ({
  documents,
  activeDocId,
  onSelect,
  onCreate,
  onDelete,
  onRename,
  onImport,
  onExport
}: DocumentSidebarProps) => {
  const [editingId, setEditingId] = React.useState<string | null>(null);
  const [renameValue, setRenameValue] = React.useState('');
  const [menuId, setMenuId] = React.useState<string | null>(null);

  const handleRename = (doc: LocalDocument) => {
    setEditingId(doc.id);
    setRenameValue(doc.title);
    setMenuId(null);
  };

  const handleRenameSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId && renameValue.trim()) {
      onRename(editingId, renameValue.trim());
      setEditingId(null);
    }
  };

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        try {
          const doc = JSON.parse(e.target?.result as string) as LocalDocument;
          // Basic validation
          if (doc.id && doc.title && doc.content) {
            onImport(doc);
          } else {
            alert('Invalid document format.');
          }
        } catch (error) {
          alert('Failed to import document.');
        }
      };
      reader.readAsText(file);
    }
  };

  return (
    <aside className="w-64 border-r border-zinc-100 flex flex-col bg-zinc-50 shrink-0 h-screen">
      <div className="p-4 border-b border-zinc-100 flex items-center justify-between h-16">
        <h2 className="text-sm font-black uppercase tracking-widest text-zinc-500">Documents</h2>
        <button
          onClick={onCreate}
          className="p-2 rounded-lg hover:bg-zinc-200 transition-colors text-zinc-500"
          title="New Document"
        >
          <FilePlus size={18} />
        </button>
      </div>
      <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
        {documents.map(doc => (
          <div
            key={doc.id}
            className={`group relative rounded-lg mb-1 ${activeDocId === doc.id ? 'bg-blue-50' : 'hover:bg-white'}`}
          >
            {editingId === doc.id ? (
              <form onSubmit={handleRenameSubmit}>
                <input
                  type="text"
                  value={renameValue}
                  onChange={(e) => setRenameValue(e.target.value)}
                  onBlur={handleRenameSubmit}
                  className="w-full bg-white text-sm font-bold p-3 rounded-lg border-2 border-blue-500 outline-none"
                  autoFocus
                />
              </form>
            ) : (
              <button
                onClick={() => onSelect(doc.id)}
                className="w-full text-left p-3 flex items-start gap-3"
              >
                <FileText size={16} className={`mt-0.5 shrink-0 ${activeDocId === doc.id ? 'text-blue-600' : 'text-zinc-400'}`} />
                <div>
                  <p className={`text-sm font-bold truncate ${activeDocId === doc.id ? 'text-blue-900' : 'text-zinc-800'}`}>{doc.title}</p>
                  <p className="text-[10px] text-zinc-400">
                    Updated {new Date(doc.updatedAt).toLocaleDateString()}
                  </p>
                </div>
              </button>
            )}

            {editingId !== doc.id && (
              <div className="absolute top-1/2 -translate-y-1/2 right-2">
                <button onClick={() => setMenuId(menuId === doc.id ? null : doc.id)} className="opacity-0 group-hover:opacity-100 p-1.5 rounded-md hover:bg-zinc-200 transition-opacity">
                  <MoreVertical size={16} className="text-zinc-500" />
                </button>
                {menuId === doc.id && (
                  <div className="absolute top-full right-0 mt-1 w-40 bg-white border border-zinc-100 rounded-xl shadow-xl z-10 p-2">
                    <button onClick={() => handleRename(doc)} className="w-full text-left flex items-center gap-2 p-2 text-xs font-bold text-zinc-700 hover:bg-zinc-100 rounded-lg"><Edit size={14}/> Rename</button>
                    <button onClick={() => onExport(doc.id)} className="w-full text-left flex items-center gap-2 p-2 text-xs font-bold text-zinc-700 hover:bg-zinc-100 rounded-lg"><Download size={14}/> Export</button>
                    <button onClick={() => onDelete(doc.id)} className="w-full text-left flex items-center gap-2 p-2 text-xs font-bold text-red-600 hover:bg-red-50 rounded-lg"><Trash2 size={14}/> Delete</button>
                  </div>
                )}
              </div>
            )}
          </div>
        ))}
      </div>
       <div className="p-2 border-t border-zinc-100">
        <label className="w-full text-center cursor-pointer flex items-center justify-center gap-2 p-3 text-xs font-bold text-zinc-500 hover:bg-zinc-200 rounded-lg transition-colors">
            <Upload size={14}/> Import Document
            <input type="file" accept=".json" className="hidden" onChange={handleFileImport} />
        </label>
       </div>
    </aside>
  );
};

