        <div className="space-y-3">
           <label className="text-[10px] font-black text-zinc-400 uppercase tracking-wider px-1">Website URL</label>
           <div className="relative group">
            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-400"><Globe size={16}/></span>
            <input 
              type="text" 
              placeholder="e.g. jisr.net" 
              value={targetDomain || ''}
              onChange={(e) => setTargetDomain?.(e.target.value)}
              className="w-full bg-white border border-zinc-100 focus:border-blue-400 rounded-2xl py-3 pl-12 pr-6 text-xs focus:bg-white outline-none transition-all font-bold text-zinc-800"
            />
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4">
           {/* Internal Links Card - White Theme */}
           <div className="p-5 bg-white border border-zinc-100 rounded-2xl shadow-sm shadow-zinc-200/50">
              <div className="flex items-center justify-between mb-3">
