    const [wordTarget, setWordTarget] = useState(1000);
    const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
    const [isExpanded, setIsExpanded] = useState(false);
    const [isAIProcessing, setIsAIProcessing] = useState(false);
    const [editorInstance, setEditorInstance] = useState<any>(null);
    const [toast, setToast] = useState<{ message: string, visible: boolean }>({ message: '', visible: false });
    const [currentBlockType, setCurrentBlockType] = useState('p');
    const [isLinkActive, setIsLinkActive] = useState(false);
    const [brokenLinks, setBrokenLinks] = useState<string[]>([]);
    const [isEditingTitle, setIsEditingTitle] = useState(false);
    const [headerTitle, setHeaderTitle] = useState(activeDocument?.title || '');
    const titleInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        if (activeDocument) {
            setHeaderTitle(activeDocument.title);
        }
    }, [activeDocument]);

    useEffect(() => {
        if (isEditingTitle && titleInputRef.current) {
            titleInputRef.current.focus();
            titleInputRef.current.select();
        }
    }, [isEditingTitle]);

    const deferredContent = useDeferredValue(activeDocument?.content || '');

    // Analysis Memoization
    const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
    const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
    const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
    const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, activeDocument?.targets || { primary: '', secondary: [] }, activeDocument?.metaDescription || '', activeDocument?.metaTitle || '', brokenLinks, activeDocument?.targetDomain || ''), [deferredContent, keywords, activeDocument, brokenLinks]);
    const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);
    const sentenceWarnings = useMemo(() => analyzeSentenceWarnings(deferredContent), [deferredContent]);

    const optimizationReport = useMemo(() => {
        if (!activeDocument) return { critical: [], improvements: [], enhancements: [] };
        return generateOptimizationReport(
            stats, health, readability, sentenceWarnings,
            activeDocument.targets, activeDocument.metaTitle, activeDocument.metaDescription, activeDocument.faqs.length, keywords
        );
    }, [stats, health, readability, sentenceWarnings, activeDocument, keywords]);

    const handlePropUpdate = useCallback((updates: Partial<Omit<LocalDocument, 'id' | 'createdAt'>>) => {
        if (id) {
            updateDocument(id, updates);
        }
    }, [id, updateDocument]);

    const handleEditorChange = useCallback((newContent: string) => {
        if(id) {
            startTransition(() => {
                updateDocument(id, { content: newContent });
            });
        }
    }, [id, updateDocument]);

    const handleSelectionChange = useCallback((blockType: string, isLink: boolean) => {
        setCurrentBlockType(blockType);
        setIsLinkActive(isLink);
    }, []);

    const handleTitleRename = (e: React.FormEvent) => {
        e.preventDefault();
        if(id && headerTitle.trim()){
            onRename(id, headerTitle.trim());
        } else {
            setHeaderTitle(activeDocument?.title || '');
        }
        setIsEditingTitle(false);
    };

    const showToast = (msg: string) => {
        setToast({ message: msg, visible: true });
        setTimeout(() => setToast(prev => ({ ...prev, visible: false })), 3000);
    };

    const onRewrite = useCallback(async (mode: RewriteMode) => {
        if (!editorInstance) return;
        const selectedText = editorInstance.getSelection();
        if (!selectedText) {
            alert("Please select text to use AI rewriting features.");
            return;
        }
        setIsAIProcessing(true);
        try {
            const results = await rewriteContent(selectedText, mode);
            if (results && results.length > 0) editorInstance.insertContent(results[0]);
        } catch (err) { console.error("AI Rewrite Failed:", err); }
        finally { setIsAIProcessing(false); }
    }, [editorInstance]);

    if (!activeDocument) {
        return (
            <div className="w-screen h-screen bg-zinc-100 flex items-center justify-center flex-col gap-4">
                <h2 className="text-xl font-bold">Document not found</h2>
                <Link to="/dashboard" className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-bold hover:bg-blue-700">Go to Dashboard</Link>
            </div>
        );
    }

    return (
        <div className="flex h-screen w-full bg-white overflow-hidden text-zinc-900 selection:bg-blue-100 relative">
             <div className={`fixed top-6 left-1/2 -translate-x-1/2 z-[200] bg-zinc-900 text-white px-6 py-3 rounded-full shadow-2xl flex items-center gap-3 transition-all duration-300 ease-in-out ${toast.visible ? 'translate-y-0 opacity-100' : '-translate-y-12 opacity-0 pointer-events-none'}`}>
                 <div className="w-2 h-2 rounded-full bg-emerald-400 shadow-[0_0_10px_rgba(52,211,153,0.5)]"></div>
                 <span className="text-[11px] font-black uppercase tracking-widest">{toast.message}</span>
             </div>

            <div className="flex-1 flex flex-col min-w-0 bg-zinc-50/50">
                <header className="h-16 border-b border-zinc-100 px-6 flex items-center justify-between bg-white shrink-0">
                    <div className="flex items-center gap-2">
                         <Link to="/dashboard" className="p-2 rounded-lg hover:bg-zinc-100 text-zinc-500 transition-colors" title="Back to Dashboard">
                           <ArrowLeft size={18} />
                         </Link>
                         <div className="w-px h-6 bg-zinc-200 mx-2"></div>
                         {isEditingTitle ? (
                             <form onSubmit={handleTitleRename}>
                                 <input
                                     ref={titleInputRef}
                                     type="text"
                                     value={headerTitle}
                                     onChange={(e) => setHeaderTitle(e.target.value)}
                                     onBlur={handleTitleRename}
                                     className="font-black tracking-tighter text-lg uppercase bg-zinc-100 p-1 rounded-md outline-none"
                                 />
                             </form>
                         ) : (
                             <div className="flex items-center gap-2 group" onClick={() => setIsEditingTitle(true)}>
                                <h1 className="font-black tracking-tighter text-lg uppercase truncate max-w-xs cursor-pointer">{headerTitle}</h1>
                                <Edit size={14} className="text-zinc-400 opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer" />
                             </div>
                         )}
                    </div>
                </header>

                <div className="flex-1 flex flex-col overflow-hidden relative">
                    <div className="toolbar-container bg-white border-b border-zinc-100">
                        <Toolbar
                            editorInstance={editorInstance} stats={stats} wordTarget={wordTarget}
                            onUpdate={() => handleEditorChange(editorInstance?.getContent() || '')}
                            onNewDocument={() => { }} onShowHistory={() => { }} onSaveVersion={() => { }}
                            viewMode="focused" currentBlockType={currentBlockType} isLinkActive={isLinkActive}
                        />
                    </div>
                    <main className="flex-1 overflow-hidden flex justify-center relative p-8">
                        <div className="w-full max-w-[900px] h-full overflow-hidden bg-white relative rounded-[2px] shadow-sm border border-zinc-200/50">
                            <Editor
                                key={activeDocument.id}
                                initialContent={activeDocument.content}
                                onUpdate={handleEditorChange}
                                onInit={setEditorInstance}
                                onAIAssist={onRewrite}
                                onSelectionChange={handleSelectionChange}
                            />
                        </div>
                    </main>
                </div>
            </div>

            <Sidebar
                activeTab={activeTab} setActiveTab={setActiveTab}
                stats={stats} readability={readability} health={health} intent={intent} keywords={keywords}
                seoTab={seoTab} setSeoTab={setSeoTab} isExpanded={isExpanded} setIsExpanded={setIsExpanded}
                onRewrite={onRewrite}
                isAIProcessing={isAIProcessing} targets={activeDocument.targets} setTargets={(t) => handlePropUpdate({ targets: t })}
                metaTitle={activeDocument.metaTitle} setMetaTitle={(s) => handlePropUpdate({ metaTitle: s })}
                metaDescription={activeDocument.metaDescription} setMetaDescription={(s) => handlePropUpdate({ metaDescription: s })}
                faqs={activeDocument.faqs} setFaqs={(f) => handlePropUpdate({ faqs: f })}
                onGenerateMetadata={async (type) => {
                    setIsAIProcessing(true);
                    try {
                        const currentValue = type === 'title' ? activeDocument.metaTitle : activeDocument.metaDescription;
                        const res = await generateMetadata(activeDocument.content, type, activeDocument.targets, currentValue);
                        handlePropUpdate(type === 'title' ? { metaTitle: res } : { metaDescription: res });
                        showToast(`Meta ${type === 'title' ? 'Title' : 'Description'} Updated`);
                    } catch (error) {
                        console.error(error); showToast('Generation Failed');
                    } finally { setIsAIProcessing(false); }
                }}
                onDetectAI={async () => {
                    setIsAIProcessing(true);
                    try {
                        const res = await detectAIContent(activeDocument.content);
                        alert(`AI Detection Score: ${res.score}%`);
                    } finally { setIsAIProcessing(false); }
                }}
                onGenerateFAQs={async () => {
                    setIsAIProcessing(true);
                    try {
                        const res = await generateFAQs(activeDocument.content);
                        handlePropUpdate({ faqs: res });
                        showToast('FAQs Generated');
                    } finally { setIsAIProcessing(false); }
                }}
                onExportSchema={() => {
                    navigator.clipboard.writeText(JSON.stringify({ "@context": "https://schema.org", "@type": "Article", "headline": activeDocument.metaTitle, "description": activeDocument.metaDescription }, null, 2));
                    showToast('Schema Copied to Clipboard');
                }}
