import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import * as auth from '../utils/auth.ts';

interface AuthPageProps {
  onLoginSuccess: () => void;
}

export default function AuthPage({ onLoginSuccess }: AuthPageProps) {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [error, setError] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    if (auth.getCurrentUserId()) {
      navigate('/dashboard');
    }
  }, [navigate]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (isLogin) {
      const user = auth.login(email, password);
      if (user) {
        auth.establishSession(user.id);
        onLoginSuccess();
        navigate('/dashboard');
      } else {
        setError('Invalid email or password.');
      }
    } else {
      if (password.length < 6) {
        setError('Password must be at least 6 characters long.');
        return;
      }
      if (password !== confirmPassword) {
        setError('Passwords do not match.');
        return;
      }
      const newUser = auth.signup(email, password);
      if (newUser) {
        auth.establishSession(newUser.id);
        onLoginSuccess();
        navigate('/dashboard');
      } else {
        setError('An account with this email already exists.');
      }
    }
  };

  return (
    <div className="w-screen h-screen bg-zinc-50 flex items-center justify-center">
      <div className="w-full max-w-sm p-8 bg-white rounded-2xl shadow-lg border border-zinc-100">
        <div className="flex justify-center mb-6">
          <div className="flex bg-zinc-100 p-1 rounded-full">
            <button onClick={() => setIsLogin(true)} className={`px-6 py-2 rounded-full text-sm font-bold ${isLogin ? 'bg-white shadow' : 'text-zinc-500'}`}>Login</button>
            <button onClick={() => setIsLogin(false)} className={`px-6 py-2 rounded-full text-sm font-bold ${!isLogin ? 'bg-white shadow' : 'text-zinc-500'}`}>Sign Up</button>
          </div>
        </div>
        <h2 className="text-2xl font-black text-center text-zinc-900 mb-6">{isLogin ? 'Welcome Back' : 'Create Account'}</h2>
        <form onSubmit={handleSubmit} className="space-y-4">
          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="Email"
            required
            className="w-full px-4 py-3 bg-zinc-100 border border-zinc-200 rounded-lg outline-none focus:border-blue-500"
          />
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="Password"
            required
            className="w-full px-4 py-3 bg-zinc-100 border border-zinc-200 rounded-lg outline-none focus:border-blue-500"
          />
          {!isLogin && (
            <input
              type="password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              placeholder="Confirm Password"
              required
              className="w-full px-4 py-3 bg-zinc-100 border border-zinc-200 rounded-lg outline-none focus:border-blue-500"
            />
          )}
          {error && <p className="text-red-500 text-xs text-center">{error}</p>}
          <button type="submit" className="w-full py-3 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 transition-colors">
            {isLogin ? 'Login' : 'Sign Up'}
          </button>
        </form>
        <p className="text-center text-xs text-zinc-400 mt-4">
          <Link to="/" className="hover:underline">Back to Home</Link>
        </p>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { Routes, Route, Navigate, useNavigate } from 'react-router-dom';
import { LocalDocument } from './types/document.types.ts';
import * as docManager from './utils/document-manager.ts';
import * as auth from './utils/auth.ts';
import DashboardPage from './pages/DashboardPage.tsx';
import EditorPage from './pages/EditorPage.tsx';
import HomePage from './pages/HomePage.tsx';
import AuthPage from './pages/AuthPage.tsx';
import AboutPage from './pages/AboutPage.tsx';
import RequireAuth from './components/auth/RequireAuth.tsx';

function debounce<F extends (...args: any[]) => any>(func: F, waitFor: number) {
  let timeout: ReturnType<typeof setTimeout> | null = null;
  return (...args: Parameters<F>): void => {
    if (timeout) clearTimeout(timeout);
    timeout = setTimeout(() => func(...args), waitFor);
  };
}

export default function App() {
  const [userId, setUserId] = useState<string | null>(auth.getCurrentUserId());
  const [documents, setDocuments] = useState<LocalDocument[]>([]);
  const navigate = useNavigate();

  useEffect(() => {
    if (userId) {
      let docs = docManager.getDocuments(userId);
      if (docs.length === 0) {
        const newDoc = docManager.createDocument('My First Article');
        docs = [newDoc];
        docManager.saveDocuments(docs, userId);
      }
      setDocuments(docs);
    } else {
      setDocuments([]);
    }
  }, [userId]);

  const debouncedSave = useCallback(debounce((docs: LocalDocument[], currentUserId: string) => {
    docManager.saveDocuments(docs, currentUserId);
  }, 1000), []);

  const updateDocument = useCallback((id: string, updates: Partial<Omit<LocalDocument, 'id' | 'createdAt'>>) => {
    if (!userId) return;
    setDocuments(prevDocs => {
      const newDocs = prevDocs.map(doc => 
        doc.id === id ? { ...doc, ...updates, updatedAt: Date.now() } : doc
      );
      debouncedSave(newDocs, userId);
      return newDocs;
    });
  }, [userId, debouncedSave]);

  const handleCreateDoc = () => {
    if (!userId) return '';
    const newDoc = docManager.createDocument('Untitled Document');
    const newDocs = [...documents, newDoc];
    setDocuments(newDocs);
    docManager.saveDocuments(newDocs, userId);
    return newDoc.id;
  };

  const handleDeleteDoc = (id: string) => {
    if (!userId) return false;
    if (documents.length <= 1) {
        alert("Cannot delete the last document.");
        return false;
    }
    if (confirm("Are you sure you want to delete this document? This action cannot be undone.")) {
        const newDocs = documents.filter(doc => doc.id !== id);
        setDocuments(newDocs);
        docManager.saveDocuments(newDocs, userId);
        return true;
    }
    return false;
  };

  const handleRenameDoc = (id: string, newTitle: string) => {
    if (!userId) return;
    const newDocs = documents.map(doc => doc.id === id ? { ...doc, title: newTitle, updatedAt: Date.now() } : doc);
    setDocuments(newDocs);
    docManager.saveDocuments(newDocs, userId);
  };

  const handleLogin = () => {
    setUserId(auth.getCurrentUserId());
  };

  const handleLogout = () => {
    auth.logout();
    setUserId(null);
    navigate('/');
  };

  return (
    <div className="w-screen h-screen bg-zinc-100">
      <Routes>
        <Route path="/" element={<HomePage />} />
        <Route path="/auth" element={<AuthPage onLoginSuccess={handleLogin} />} />
        <Route path="/about" element={<AboutPage />} />

        <Route element={<RequireAuth />}>
          <Route 
            path="/dashboard" 
            element={
              <DashboardPage 
                documents={documents}
                onCreate={handleCreateDoc}
                onDelete={handleDeleteDoc}
                onRename={handleRenameDoc}
                onLogout={handleLogout}
              />
            } 
          />
          <Route 
            path="/editor/:id" 
            element={
              <EditorPage
                documents={documents}
                updateDocument={updateDocument}
                onRename={handleRenameDoc}
              />
            } 
          />
        </Route>
      </Routes>
    </div>
  );
}

