import React, { useState, useMemo, useRef, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { LocalDocument } from '../../types/document.types.ts';
import { Plus, Search, MoreVertical, Edit, Trash2, ArrowUpDown, FileText, Clock, Loader } from 'lucide-react';
import { getStats } from '../../core/text-analysis.ts';

interface FilesPageProps {
    documents: LocalDocument[];
    onCreate: () => string;
    onTrash: (id: string) => boolean;
    onRename: (id: string, newTitle: string) => void;
}

const DocumentCard = ({ doc, onTrash, onRename }: { doc: LocalDocument, onTrash: (id: string) => boolean, onRename: (id: string, newTitle: string) => void }) => {
    const [menuOpen, setMenuOpen] = useState(false);
    const [isEditing, setIsEditing] = useState(false);
    const [title, setTitle] = useState(doc.title);
    const menuRef = useRef<HTMLDivElement>(null);
    const wordCount = useMemo(() => getStats(doc.content).words, [doc.content]);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
                setMenuOpen(false);
            }
        };
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    const handleRenameSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (title.trim()) {
            onRename(doc.id, title.trim());
        } else {
            setTitle(doc.title);
        }
        setIsEditing(false);
    };

    return (
        <div className="bg-white border border-zinc-200 rounded-2xl flex flex-col group relative shadow-sm hover:shadow-lg hover:-translate-y-1 transition-all duration-300">
            <Link to={`/editor/${doc.id}`} className="flex-1 p-6 flex flex-col">
                {isEditing ? (
                    <form onSubmit={handleRenameSubmit} className="mb-2">
                        <input
                            type="text"
                            value={title}
                            onChange={(e) => setTitle(e.target.value)}
                            onBlur={handleRenameSubmit}
                            className="w-full text-lg font-black text-zinc-900 bg-zinc-100 p-2 rounded-lg outline-none border-2 border-blue-500"
                            autoFocus
                            onClick={(e) => e.preventDefault()}
                        />
                    </form>
                ) : (
                    <h3 className="text-lg font-black text-zinc-900 mb-2 truncate group-hover:text-blue-600 transition-colors">{doc.title}</h3>
                )}
                <div className="flex-1" />
                 <p className="text-xs text-zinc-400 font-medium mt-2">
                    Updated {new Date(doc.updatedAt).toLocaleDateString()}
                </p>
            </Link>
            <div className="border-t border-zinc-100 px-6 py-4 text-xs font-bold text-zinc-500">
                <div className="flex items-center gap-2">
                    <FileText size={14} />
                    <span>{wordCount} words</span>
                </div>
            </div>
            {!isEditing && (
                <div ref={menuRef} className="absolute top-4 right-4">
                    <button onClick={() => setMenuOpen(!menuOpen)} className="p-2 rounded-full hover:bg-zinc-200 opacity-0 group-hover:opacity-100 transition-opacity">
                        <MoreVertical size={16} className="text-zinc-500" />
                    </button>
                    {menuOpen && (
                        <div className="absolute top-full right-0 mt-1 w-40 bg-white border border-zinc-200 rounded-xl shadow-xl z-10 p-2">
                            <button onClick={(e) => { e.stopPropagation(); setIsEditing(true); setMenuOpen(false); }} className="w-full text-left flex items-center gap-2 p-2 text-xs font-bold text-zinc-700 hover:bg-zinc-100 rounded-lg"><Edit size={14}/> Rename</button>
                            <button onClick={(e) => { e.stopPropagation(); onTrash(doc.id); }} className="w-full text-left flex items-center gap-2 p-2 text-xs font-bold text-red-600 hover:bg-red-50 rounded-lg"><Trash2 size={14}/> Move to Trash</button>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default function FilesPage({ documents, onCreate, onTrash, onRename }: FilesPageProps) {
