                        ) : (
                            <div className="text-center py-20">
                                <FileX size={48} className="mx-auto text-zinc-300 mb-4" />
                                <h3 className="text-lg font-bold text-zinc-600">Trash is empty</h3>
                                <p className="text-sm text-zinc-400 mt-2">Deleted files will appear here.</p>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { ApiKey, getApiKeys, saveApiKeys } from '../../utils/api-manager.ts';
import { Plus, Trash2, Key, Save } from 'lucide-react';

interface APIsPageProps {
  userId: string;
}

export default function APIsPage({ userId }: APIsPageProps) {
  const [apiKeys, setApiKeys] = useState<ApiKey[]>([]);
  const [isDirty, setIsDirty] = useState(false);

  useEffect(() => {
    if (userId) {
      setApiKeys(getApiKeys(userId));
    }
  }, [userId]);

  const handleAddKey = () => {
    const newKey: ApiKey = {
      id: crypto.randomUUID(),
      provider: 'Gemini',
      key: '',
      isActive: true,
    };
    setApiKeys([...apiKeys, newKey]);
    setIsDirty(true);
  };

  const handleUpdateKey = (id: string, field: keyof ApiKey, value: any) => {
    setApiKeys(apiKeys.map(k => (k.id === id ? { ...k, [field]: value } : k)));
    setIsDirty(true);
  };

  const handleRemoveKey = (id: string) => {
    setApiKeys(apiKeys.filter(k => k.id !== id));
    setIsDirty(true);
  };

  const handleSave = () => {
    saveApiKeys(apiKeys, userId);
    setIsDirty(false);
  };

  const maskKey = (key: string) => {
    if (key.length < 8) return '****';
    return `${key.substring(0, 4)}...${key.substring(key.length - 4)}`;
  }

  return (
    <div className="w-full h-full flex flex-col">
      <header className="bg-white/80 backdrop-blur-md border-b border-zinc-200 p-6 flex items-center justify-between sticky top-0 z-10">
        <h1 className="font-black tracking-tighter text-2xl uppercase text-zinc-800">API Keys</h1>
        {isDirty && (
            <button onClick={handleSave} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg text-xs font-bold uppercase tracking-wider hover:bg-blue-700 transition-colors shadow-md shadow-blue-500/20">
                <Save size={16} /> Save Changes
            </button>
        )}
      </header>
      <div className="flex-1 p-8">
        <div className="max-w-4xl mx-auto">
            <div className="bg-white p-8 border border-zinc-200 rounded-2xl shadow-sm space-y-6">
                <div className="space-y-4">
                {apiKeys.map(apiKey => (
                    <div key={apiKey.id} className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center p-4 bg-zinc-50 rounded-lg border border-zinc-200">
                        <input
                            type="text"
                            value={apiKey.provider}
                            onChange={e => handleUpdateKey(apiKey.id, 'provider', e.target.value)}
                            placeholder="Provider (e.g., Gemini)"
                            className="font-bold text-sm bg-white border border-zinc-200 rounded-md p-2 outline-none focus:border-blue-500"
                        />
                        <input
                            type="password"
                            value={apiKey.key}
                            onChange={e => handleUpdateKey(apiKey.id, 'key', e.target.value)}
                            placeholder="Enter API Key"
                            className="md:col-span-1 font-mono text-sm bg-white border border-zinc-200 rounded-md p-2 outline-none focus:border-blue-500"
                        />
                         <div className="flex items-center justify-end gap-4">
                             <label className="flex items-center gap-2 text-xs font-bold text-zinc-600 cursor-pointer">
                                 <input
                                     type="checkbox"
                                     checked={apiKey.isActive}
                                     onChange={e => handleUpdateKey(apiKey.id, 'isActive', e.target.checked)}
                                     className="h-4 w-4 rounded text-blue-600 focus:ring-blue-500 border-zinc-300"
                                 />
                                 Active
                             </label>
                             <button onClick={() => handleRemoveKey(apiKey.id)} className="p-2 text-zinc-400 hover:text-red-500 transition-colors">
                                 <Trash2 size={16} />
                             </button>
                         </div>
                    </div>
                ))}
                </div>

                <button onClick={handleAddKey} className="w-full flex items-center justify-center gap-2 py-3 border-2 border-dashed border-zinc-300 rounded-lg text-sm font-bold text-zinc-500 hover:bg-zinc-100 hover:border-zinc-400 transition-colors">
                    <Plus size={16}/> Add API Key
                </button>
            </div>
            <p className="text-xs text-zinc-400 mt-4 text-center">API keys are stored securely in your browser's local storage and are never sent to our servers.</p>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useRef } from 'react';
import { 
  Bold, Italic, Underline, Link as LinkIcon, 
  ChevronDown, Undo, Redo,
  Table as TableIcon, Image as ImageIcon,
  X, Minus, Send, Strikethrough, Subscript, Superscript, Trash2
} from 'lucide-react';
import { TextStats } from '../../types/editor.types';

interface ToolbarProps {
  editorInstance: any;
  stats?: TextStats;
  wordTarget?: number;
  onUpdate: () => void;
  onNewDocument: () => void;
  onShowHistory: () => void;
  onSaveVersion: () => void;
  viewMode: string;
  currentBlockType?: string;
  isLinkActive?: boolean;
}

const ToolbarGroup = ({ children }: { children?: React.ReactNode }) => (
  <div className="flex bg-zinc-50 p-1.5 rounded-2xl border border-zinc-100 mx-1 items-center shadow-sm">
    {children}
  </div>
);

const ToolbarButton = ({ icon, onClick, title, active = false, disabled = false }: any) => (
  <button 
    onMouseDown={(e) => { 
      e.preventDefault(); 
      onClick(e); 
    }} 
    disabled={disabled}
    className={`w-10 h-10 flex items-center justify-center hover:bg-white hover:shadow-sm rounded-xl transition-all disabled:opacity-20 ${active ? 'text-blue-600 bg-blue-50' : 'text-zinc-500'}`} 
    title={title}
  >
    {icon}
  </button>
);

export const Toolbar = ({ 
  editorInstance,
  stats,
  wordTarget = 1000,
  currentBlockType,
  isLinkActive
}: ToolbarProps) => {
  const [modalConfig, setModalConfig] = useState<{ type: 'table' | 'image' | 'link' | null; title: string }>({ type: null, title: '' });
  const [input1, setInput1] = useState(''); // Re-used for URL
  const [input2, setInput2] = useState(''); // Re-used for Table Cols
  const [linkText, setLinkText] = useState('');
  const [isEditingLink, setIsEditingLink] = useState(false);
  const savedRange = useRef<Range | null>(null);

  if (!editorInstance) return null;

  const handleFormat = (cmd: string, val: any = null) => {
    editorInstance?.execCommand(cmd, false, val);
  };

  const getParentAnchor = (): HTMLAnchorElement | null => {
    let node = window.getSelection()?.anchorNode;
    while (node && node.nodeName !== 'BODY') {
      if (node.nodeName === 'A') {
        return node as HTMLAnchorElement;
      }
      node = node.parentNode;
    }
    return null;
  };

  const openModal = (type: 'table' | 'image' | 'link') => {
    const selection = window.getSelection();
    if (!selection || selection.rangeCount === 0) return;

    savedRange.current = selection.getRangeAt(0).cloneRange();

    if (type === 'table') {
      setInput1('3');
      setInput2('3');
      setModalConfig({ type, title: 'Insert Table' });
    } else if (type === 'image') {
      setModalConfig({ type, title: 'Insert Image from URL' });
    } else if (type === 'link') {
       const parentAnchor = getParentAnchor();
       if (!savedRange.current.toString() && !parentAnchor) {
          alert("Please select text to create a link.");
          return;
       }

       if (parentAnchor) {
         const range = document.createRange();
         range.selectNode(parentAnchor);
         selection.removeAllRanges();
         selection.addRange(range);
         savedRange.current = range.cloneRange();

         setIsEditingLink(true);
         setInput1(parentAnchor.getAttribute('href') || '');
         setLinkText(parentAnchor.innerText);
       } else {
         setIsEditingLink(false);
         setInput1('');
         setLinkText(savedRange.current.toString());
       }
       setModalConfig({ type, title: 'Manage Link' });
    }
  };

  const handleRemoveLink = () => {
    editorInstance.focus();
    if (savedRange.current) {
        const selection = window.getSelection();
        selection?.removeAllRanges();
        selection?.addRange(savedRange.current);
        editorInstance.execCommand('unlink', false, null);
    }
    setModalConfig({ type: null, title: '' });
  };

  const handleModalSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    editorInstance.focus();

    const selection = window.getSelection();
    if (savedRange.current && selection) {
      selection.removeAllRanges();
      selection.addRange(savedRange.current);
    }

    switch (modalConfig.type) {
      case 'table':
        const rows = parseInt(input1);
        const cols = parseInt(input2);
        if (rows > 0 && cols > 0) {
          let tbl = '<table style="width:100%; border: 1px solid #e2e8f0; border-collapse: collapse; margin-bottom: 2rem;">';
          for (let r = 0; r < rows; r++) {
            tbl += '<tr>';
            for (let c = 0; c < cols; c++) {
              tbl += '<td style="border: 1px solid #e2e8f0; padding: 12px;">&nbsp;</td>';
            }
            tbl += '</tr>';
          }
          tbl += '</table><p>&nbsp;</p>';
          editorInstance.insertContent(tbl);
        }
        break;

      case 'image':
        if (input1) {
          editorInstance.insertContent(`<img src="${input1}" alt="Image" style="max-width:100%; border-radius:1rem; margin: 2rem 0; box-shadow: 0 10px 15px -3px rgba(0,0,0,0.05);" />`);
        }
        break;

      case 'link':
        if (input1 && linkText) {
          const linkHTML = `<a href="${input1}" target="_blank" rel="noopener noreferrer">${linkText}</a>`;
          editorInstance.insertContent(linkHTML);
        }
        break;
    }

    setModalConfig({ type: null, title: '' });
  };

  return (
    <>
      <div className="border-b border-zinc-100 bg-white/90 backdrop-blur-md p-3 flex flex-wrap gap-2 sticky top-0 z-20 overflow-x-auto no-scrollbar items-center shrink-0 justify-between w-full px-6">
        <div className="flex items-center flex-wrap gap-2">
            <ToolbarGroup>
              <ToolbarButton icon={<Undo size={18} />} onClick={() => handleFormat('undo')} title="Undo" />
              <ToolbarButton icon={<Redo size={18} />} onClick={() => handleFormat('redo')} title="Redo" />
            </ToolbarGroup>

            <ToolbarGroup>
              <div className="relative flex items-center px-4">
                <select 
                  value={currentBlockType || 'p'}
                  onChange={(e) => handleFormat('formatBlock', e.target.value)} 
                  className="bg-transparent appearance-none text-[11px] font-black uppercase outline-none cursor-pointer pr-8 py-2.5 tracking-widest text-zinc-800"
                >
                  <option value="p">Paragraph</option>
                  <option value="h1">Heading 1</option>
                  <option value="h2">Heading 2</option>
                  <option value="h3">Heading 3</option>
                  <option value="h4">Heading 4</option>
                  <option value="h5">Heading 5</option>
                  <option value="h6">Heading 6</option>
                  <option value="blockquote">Quote</option>
                  <option value="pre">Code Block</option>
                </select>
                <ChevronDown size={12} className="absolute right-4 pointer-events-none text-zinc-400" />
              </div>
            </ToolbarGroup>

            <ToolbarGroup>
              <ToolbarButton icon={<Bold size={18} />} onClick={() => handleFormat('bold')} title="Bold" />
              <ToolbarButton icon={<Italic size={18} />} onClick={() => handleFormat('italic')} title="Italic" />
              <ToolbarButton icon={<Underline size={18} />} onClick={() => handleFormat('underline')} title="Underline" />
              <ToolbarButton icon={<Strikethrough size={18} />} onClick={() => handleFormat('strikethrough')} title="Strikethrough" />
              <ToolbarButton icon={<Subscript size={18} />} onClick={() => handleFormat('subscript')} title="Subscript" />
              <ToolbarButton icon={<Superscript size={18} />} onClick={() => handleFormat('superscript')} title="Superscript" />
            </ToolbarGroup>

            <ToolbarGroup>
              <ToolbarButton icon={<TableIcon size={18} />} onClick={() => openModal('table')} title="Insert Table" />
              <ToolbarButton icon={<ImageIcon size={18} />} onClick={() => openModal('image')} title="Insert Image" />
              <ToolbarButton icon={<Minus size={18} />} onClick={() => editorInstance.insertContent('<hr/>')} title="Horizontal Line" />
              <ToolbarButton icon={<LinkIcon size={18} />} onClick={() => openModal('link')} title="Insert Link" active={isLinkActive} />
            </ToolbarGroup>
        </div>

        {stats && (
          <div className="hidden sm:flex items-center gap-4 px-4 py-2 bg-zinc-50 border border-zinc-100 rounded-2xl shadow-sm">
            <div className="flex flex-col items-end">
              <span className="text-[9px] font-black text-zinc-400 uppercase tracking-widest mb-0.5">Progress</span>
              <div className="text-[11px] font-black text-zinc-800 uppercase tabular-nums">
                {stats.words} <span className="text-zinc-300">/</span> {wordTarget} words
              </div>
            </div>
            <div className="w-20 h-1 bg-zinc-100 rounded-full overflow-hidden">
              <div 
                className="h-full bg-blue-600 transition-all duration-700 ease-out" 
                style={{ width: `${Math.min(100, (stats.words / wordTarget) * 100)}%` }} 
              />
            </div>
          </div>
        )}
      </div>

      {modalConfig.type && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-md p-4 animate-in fade-in duration-300">
          <div className="bg-white border border-zinc-200 rounded-[32px] w-full max-w-md shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b border-zinc-50 flex items-center justify-between">
              <h3 className="font-black text-xl uppercase tracking-tighter text-zinc-900 flex items-center gap-2">
                {modalConfig.title}
              </h3>
              <button onClick={() => setModalConfig({ type: null, title: '' })} className="text-zinc-400 hover:text-zinc-900 transition-colors">
                <X size={24}/>
              </button>
            </div>
            <form onSubmit={handleModalSubmit} className="p-8 space-y-6">
              {modalConfig.type === 'table' && (
                <div className="flex gap-4">
                  <div className="w-1/2 space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-zinc-400 ml-1">Rows</label>
                    <input required type="number" value={input1} onChange={(e) => setInput1(e.target.value)} min="1" className="w-full px-6 py-4 bg-zinc-50 border border-zinc-100 rounded-2xl outline-none focus:border-blue-500 transition-all font-bold" />
                  </div>
                  <div className="w-1/2 space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-zinc-400 ml-1">Columns</label>
                    <input required type="number" value={input2} onChange={(e) => setInput2(e.target.value)} min="1" className="w-full px-6 py-4 bg-zinc-50 border border-zinc-100 rounded-2xl outline-none focus:border-blue-500 transition-all font-bold" />
                  </div>
                </div>
              )}

              {modalConfig.type === 'image' && (
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase tracking-widest text-zinc-400 ml-1">URL</label>
                  <input required type="url" value={input1} onChange={(e) => setInput1(e.target.value)} placeholder="https://..." className="w-full px-6 py-4 bg-zinc-50 border border-zinc-100 rounded-2xl outline-none focus:border-blue-500 transition-all font-bold" />
                </div>
              )}

              {modalConfig.type === 'link' && (
                <>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-zinc-400 ml-1">URL</label>
                    <input required type="url" value={input1} onChange={(e) => setInput1(e.target.value)} placeholder="https://..." className="w-full px-6 py-4 bg-zinc-50 border border-zinc-100 rounded-2xl outline-none focus:border-blue-500 transition-all font-bold" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-zinc-400 ml-1">Text to display</label>
                    <input required type="text" value={linkText} onChange={(e) => setLinkText(e.target.value)} className="w-full px-6 py-4 bg-zinc-50 border border-zinc-100 rounded-2xl outline-none focus:border-blue-500 transition-all font-bold" />
                  </div>
                </>
              )}

              <div className="flex gap-3">
                {modalConfig.type === 'link' && isEditingLink && (
                  <button type="button" onClick={handleRemoveLink} className="w-auto px-6 py-5 bg-red-50 text-red-600 rounded-2xl font-black uppercase tracking-widest text-xs flex items-center justify-center gap-2 hover:bg-red-100 transition-all active:scale-95">
                    <Trash2 size={16} />
                  </button>
                )}
                <button type="submit" className="w-full py-5 bg-zinc-900 text-white rounded-2xl font-black uppercase tracking-widest text-xs flex items-center justify-center gap-3 shadow-xl hover:bg-black transition-all active:scale-95">
                  <Send size={16} /> {modalConfig.type === 'link' ? 'Apply' : 'Insert'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </>
  );
};

import React, { useState, useEffect, useMemo, useDeferredValue, startTransition, useCallback, useRef } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { X, Send, ArrowLeft, Edit } from 'lucide-react';
import { LocalDocument } from '../types/document.types';

// Core Analysis Logic
import { getStats } from '../core/text-analysis.ts';
import { getKeywords } from '../core/keyword-density.ts';
import { getReadabilityScore } from '../core/readability.ts';
import { analyzeSEOHealth } from '../core/seo-health.ts';
import { detectIntent } from '../core/intent-detector.ts';
import { analyzeSentenceWarnings } from '../core/sentence-analysis.ts';
import { generateOptimizationReport } from '../core/optimization-engine.ts';

// AI Integration
import { rewriteContent, generateMetadata, detectAIContent, RewriteMode, generateFAQs } from '../ai/ai-engine.ts';

// Components
import { Toolbar } from '../components/editor/Toolbar.tsx';
import { Sidebar } from '../components/layout/Sidebar.tsx';
import { Editor } from '../components/editor/Editor.tsx';
import { Tab, SEOPhraseTab } from '../types/editor.types.ts';

interface EditorPageProps {
    documents: LocalDocument[];
    updateDocument: (id: string, updates: Partial<Omit<LocalDocument, 'id' | 'createdAt'>>) => void;
    onRename: (id: string, newTitle: string) => void;
}

export default function EditorPage({ documents, updateDocument, onRename }: EditorPageProps) {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();

    const activeDocument = useMemo(() => {
        return documents.find(doc => doc.id === id) || null;
    }, [documents, id]);

    // UI State
    const [activeTab, setActiveTab] = useState<Tab>('insights');
    const [wordTarget, setWordTarget] = useState(1000);
    const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
    const [isExpanded, setIsExpanded] = useState(false);
    const [isAIProcessing, setIsAIProcessing] = useState(false);
    const [editorInstance, setEditorInstance] = useState<any>(null);
    const [toast, setToast] = useState<{ message: string, visible: boolean }>({ message: '', visible: false });
    const [currentBlockType, setCurrentBlockType] = useState('p');
    const [isLinkActive, setIsLinkActive] = useState(false);
    const [brokenLinks, setBrokenLinks] = useState<string[]>([]);
    const [isEditingTitle, setIsEditingTitle] = useState(false);
    const [headerTitle, setHeaderTitle] = useState(activeDocument?.title || '');
    const titleInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        if (activeDocument) {
            setHeaderTitle(activeDocument.title);
        }
    }, [activeDocument]);

    useEffect(() => {
        if (isEditingTitle && titleInputRef.current) {
            titleInputRef.current.focus();
            titleInputRef.current.select();
        }
    }, [isEditingTitle]);

    const deferredContent = useDeferredValue(activeDocument?.content || '');

    // Analysis Memoization
    const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
    const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
    const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
    const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, activeDocument?.targets || { primary: '', secondary: [] }, activeDocument?.metaDescription || '', activeDocument?.metaTitle || '', brokenLinks, activeDocument?.targetDomain || ''), [deferredContent, keywords, activeDocument, brokenLinks]);
    const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);
    const sentenceWarnings = useMemo(() => analyzeSentenceWarnings(deferredContent), [deferredContent]);

    const optimizationReport = useMemo(() => {
        if (!activeDocument) return { critical: [], improvements: [], enhancements: [] };
        return generateOptimizationReport(
            stats, health, readability, sentenceWarnings,
            activeDocument.targets, activeDocument.metaTitle, activeDocument.metaDescription, activeDocument.faqs.length, keywords
        );
    }, [stats, health, readability, sentenceWarnings, activeDocument, keywords]);

    const handlePropUpdate = useCallback((updates: Partial<Omit<LocalDocument, 'id' | 'createdAt'>>) => {
        if (id) {
            updateDocument(id, updates);
        }
    }, [id, updateDocument]);

    const handleEditorChange = useCallback((newContent: string) => {
        if(id) {
            startTransition(() => {
                updateDocument(id, { content: newContent });
            });
        }
    }, [id, updateDocument]);

    const handleSelectionChange = useCallback((blockType: string, isLink: boolean) => {
        setCurrentBlockType(blockType);
        setIsLinkActive(isLink);
    }, []);

    const handleTitleRename = (e: React.FormEvent) => {
        e.preventDefault();
        if(id && headerTitle.trim()){
            onRename(id, headerTitle.trim());
        } else {
            setHeaderTitle(activeDocument?.title || '');
        }
        setIsEditingTitle(false);
    };

    const showToast = (msg: string) => {
        setToast({ message: msg, visible: true });
        setTimeout(() => setToast(prev => ({ ...prev, visible: false })), 3000);
    };

    const onRewrite = useCallback(async (mode: RewriteMode) => {
        if (!editorInstance) return;
        const selectedText = editorInstance.getSelection();
        if (!selectedText) {
            alert("Please select text to use AI rewriting features.");
            return;
        }
        setIsAIProcessing(true);
        try {
            const results = await rewriteContent(selectedText, mode);
            if (results && results.length > 0) editorInstance.insertContent(results[0]);
        } catch (err) { console.error("AI Rewrite Failed:", err); }
        finally { setIsAIProcessing(false); }
    }, [editorInstance]);

    if (!activeDocument) {
        return (
            <div className="w-screen h-screen bg-zinc-100 flex items-center justify-center flex-col gap-4">
                <h2 className="text-xl font-bold">Document not found</h2>
                <Link to="/dashboard" className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-bold hover:bg-blue-700">Go to Dashboard</Link>
            </div>
        );
    }

    return (
        <div className="flex h-screen w-full bg-white overflow-hidden text-zinc-900 selection:bg-blue-100 relative">
             <div className={`fixed top-6 left-1/2 -translate-x-1/2 z-[200] bg-zinc-900 text-white px-6 py-3 rounded-full shadow-2xl flex items-center gap-3 transition-all duration-300 ease-in-out ${toast.visible ? 'translate-y-0 opacity-100' : '-translate-y-12 opacity-0 pointer-events-none'}`}>
                 <div className="w-2 h-2 rounded-full bg-emerald-400 shadow-[0_0_10px_rgba(52,211,153,0.5)]"></div>
                 <span className="text-[11px] font-black uppercase tracking-widest">{toast.message}</span>
             </div>

            <div className="flex-1 flex flex-col min-w-0 bg-zinc-50/50">
                <header className="h-16 border-b border-zinc-100 px-6 flex items-center justify-between bg-white shrink-0">
                    <div className="flex items-center gap-2">
                         <Link to="/dashboard" className="p-2 rounded-lg hover:bg-zinc-100 text-zinc-500 transition-colors" title="Back to Dashboard">
                           <ArrowLeft size={18} />
                         </Link>
                         <div className="w-px h-6 bg-zinc-200 mx-2"></div>
