export interface User {
  id: string;
  email: string;
  name: string;
  password: string; // Storing plaintext as per "no backend" constraint
}

import { User } from '../types/user.types.ts';

const USERS_KEY = 'seoFocus_users';
const SESSION_KEY = 'seoFocus_session';

export const getUsers = (): User[] => {
  try {
    const data = localStorage.getItem(USERS_KEY);
    return data ? JSON.parse(data) : [];
  } catch (error) {
    console.error("Failed to load users:", error);
    return [];
  }
};

const saveUsers = (users: User[]): void => {
  try {
    localStorage.setItem(USERS_KEY, JSON.stringify(users));
  } catch (error) {
    console.error("Failed to save users:", error);
  }
};

export const getUser = (userId: string): User | null => {
  const users = getUsers();
  return users.find(u => u.id === userId) || null;
};

export const signup = (email: string, password: string): User | null => {
  const users = getUsers();
  const existingUser = users.find(user => user.email === email);
  if (existingUser) {
    return null; // Email already exists
  }
  const newUser: User = {
    id: crypto.randomUUID(),
    email,
    password,
    name: email.split('@')[0] || 'User',
  };
  users.push(newUser);
  saveUsers(users);
  return newUser;
};

export const login = (email: string, password: string): User | null => {
  const users = getUsers();
  const user = users.find(u => u.email === email && u.password === password);
  return user || null;
};

export const updateUser = (userId: string, updates: Partial<User>): boolean => {
    const users = getUsers();
    const userIndex = users.findIndex(u => u.id === userId);
    if (userIndex === -1) return false;

    // Check for email collision if email is being updated
    if (updates.email && users.some(u => u.email === updates.email && u.id !== userId)) {
        return false; // Email already taken
    }

    users[userIndex] = { ...users[userIndex], ...updates };
    saveUsers(users);
    return true;
};

export const deleteUser = (userId: string): void => {
    let users = getUsers();
    users = users.filter(u => u.id !== userId);
    saveUsers(users);
};

export const getCurrentUserId = (): string | null => {
  return localStorage.getItem(SESSION_KEY);
};

export const establishSession = (userId: string): void => {
  localStorage.setItem(SESSION_KEY, userId);
};

export const logout = (): void => {
  localStorage.removeItem(SESSION_KEY);
};

import { LocalDocument } from '../types/document.types.ts';

const getStorageKey = (userId: string) => `seoFocus_docs_${userId}`;

const getAllDocuments = (userId: string): LocalDocument[] => {
  if (!userId) return [];
  try {
    const data = localStorage.getItem(getStorageKey(userId));
    return data ? JSON.parse(data) : [];
  } catch (error) {
    console.error("Failed to load documents:", error);
    return [];
  }
};

export const getDocuments = (userId: string): LocalDocument[] => {
  return getAllDocuments(userId).filter(doc => !doc.isTrashed);
};

export const getTrashedDocuments = (userId: string): LocalDocument[] => {
  return getAllDocuments(userId).filter(doc => doc.isTrashed);
};

export const saveDocuments = (documents: LocalDocument[], userId: string): void => {
  if (!userId) return;
  try {
    localStorage.setItem(getStorageKey(userId), JSON.stringify(documents));
  } catch (error) {
    console.error("Failed to save documents:", error);
  }
};

export const deleteAllDocumentsForUser = (userId: string): void => {
  if (!userId) return;
  try {
    localStorage.removeItem(getStorageKey(userId));
  } catch (error) {
    console.error("Failed to delete user documents:", error);
  }
};

export const createDocument = (title: string): LocalDocument => {
  const now = Date.now();
  return {
    id: crypto.randomUUID(),
    title,
    content: `<h1>${title}</h1><p>Start writing here...</p>`,
    createdAt: now,
    updatedAt: now,
    metaTitle: '',
    metaDescription: '',
    targets: { primary: '', secondary: ['', '', ''] },
    faqs: [],
    targetDomain: '',
    isTrashed: false,
    goal: {
      wordCount: 1000,
      intent: 'General',
      audience: 'General',
      tone: 'Professional'
    }
  };
};

export const trashDocument = (id: string, userId: string): void => {
  const docs = getAllDocuments(userId);
  const updatedDocs = docs.map(doc => doc.id === id ? { ...doc, isTrashed: true, updatedAt: Date.now() } : doc);
  saveDocuments(updatedDocs, userId);
};

export const restoreDocument = (id: string, userId: string): void => {
  const docs = getAllDocuments(userId);
  const updatedDocs = docs.map(doc => doc.id === id ? { ...doc, isTrashed: false, updatedAt: Date.now() } : doc);
  saveDocuments(updatedDocs, userId);
};

export const deleteDocumentPermanently = (id: string, userId: string): void => {
  const docs = getAllDocuments(userId);
  const updatedDocs = docs.filter(doc => doc.id !== id);
  saveDocuments(updatedDocs, userId);
};

import React, { useState, useEffect, useCallback } from 'react';
import { Routes, Route, Navigate, useNavigate } from 'react-router-dom';
import { LocalDocument } from './types/document.types.ts';
import { User } from './types/user.types.ts';
import * as docManager from './utils/document-manager.ts';
import * as auth from './utils/auth.ts';

import EditorPage from './pages/EditorPage.tsx';
import HomePage from './pages/HomePage.tsx';
import AuthPage from './pages/AuthPage.tsx';
import AboutPage from './pages/AboutPage.tsx';
import PricingPage from './pages/PricingPage.tsx';
import ContactPage from './pages/ContactPage.tsx';
import LegalPage from './pages/LegalPage.tsx';
import PrivacyPage from './pages/PrivacyPage.tsx';
import TermsPage from './pages/TermsPage.tsx';
import RefundPage from './pages/RefundPage.tsx';
