import TrashPage from './pages/dashboard/TrashPage.tsx';
import APIsPage from './pages/dashboard/APIsPage.tsx';
import SettingsPage from './pages/dashboard/SettingsPage.tsx';

function debounce<F extends (...args: any[]) => any>(func: F, waitFor: number) {
  let timeout: ReturnType<typeof setTimeout> | null = null;
  return (...args: Parameters<F>): void => {
    if (timeout) clearTimeout(timeout);
    timeout = setTimeout(() => func(...args), waitFor);
  };
}

export default function App() {
  const [userId, setUserId] = useState<string | null>(auth.getCurrentUserId());
  const [user, setUser] = useState<User | null>(null);
  const [documents, setDocuments] = useState<LocalDocument[]>([]);
  const [trashedDocuments, setTrashedDocuments] = useState<LocalDocument[]>([]);
  const navigate = useNavigate();

  useEffect(() => {
    if (userId) {
      setUser(auth.getUser(userId));
    } else {
      setUser(null);
    }
  }, [userId]);

  const loadDocs = useCallback(() => {
    if (userId) {
      let activeDocs = docManager.getDocuments(userId);
      if (activeDocs.length === 0 && docManager.getTrashedDocuments(userId).length === 0) {
        const newDoc = docManager.createDocument('My First Article');
        activeDocs = [newDoc];
        docManager.saveDocuments([...activeDocs, ...docManager.getTrashedDocuments(userId)], userId);
      }
      setDocuments(activeDocs);
      setTrashedDocuments(docManager.getTrashedDocuments(userId));
    } else {
      setDocuments([]);
      setTrashedDocuments([]);
    }
  }, [userId]);

  useEffect(() => {
    loadDocs();
  }, [userId, loadDocs]);

  const debouncedSave = useCallback(debounce((docs: LocalDocument[], currentUserId: string) => {
    docManager.saveDocuments(docs, currentUserId);
  }, 1000), []);

  const updateDocument = useCallback((id: string, updates: Partial<Omit<LocalDocument, 'id' | 'createdAt'>>) => {
    if (!userId) return;
    const allDocs = [...documents, ...trashedDocuments];
    const newDocs = allDocs.map(doc => 
        doc.id === id ? { ...doc, ...updates, updatedAt: Date.now() } : doc
    );
    debouncedSave(newDocs, userId);
    setDocuments(newDocs.filter(d => !d.isTrashed));
  }, [userId, documents, trashedDocuments, debouncedSave]);

  const handleCreateDoc = () => {
    if (!userId) return '';
    const newDoc = docManager.createDocument('Untitled Document');
    const newDocs = [...documents, newDoc];
    setDocuments(newDocs);
    docManager.saveDocuments([...newDocs, ...trashedDocuments], userId);
    return newDoc.id;
  };

  const handleTrashDoc = (id: string) => {
    if (!userId) return false;
    docManager.trashDocument(id, userId);
    loadDocs();
    return true;
  };

  const handleRestoreDoc = (id: string) => {
    if (!userId) return;
    docManager.restoreDocument(id, userId);
    loadDocs();
  };

  const handlePermanentDelete = (id: string) => {
    if(!userId) return;
    if (confirm("Are you sure you want to permanently delete this document? This action cannot be undone.")) {
      docManager.deleteDocumentPermanently(id, userId);
      loadDocs();
    }
  };

  const handleRenameDoc = (id: string, newTitle: string) => {
    if (!userId) return;
    const allDocs = [...documents, ...trashedDocuments];
    const newDocs = allDocs.map(doc => doc.id === id ? { ...doc, title: newTitle, updatedAt: Date.now() } : doc);
    setDocuments(newDocs.filter(d => !d.isTrashed));
    setTrashedDocuments(newDocs.filter(d => d.isTrashed));
    docManager.saveDocuments(newDocs, userId);
  };

  const handleUpdateUser = (updates: Partial<User>): boolean => {
    if (!userId) return false;
    const success = auth.updateUser(userId, updates);
    if (success) {
      setUser(auth.getUser(userId));
    }
    return success;
  };

  const handleDeleteAccount = () => {
    if (!userId) return;
    auth.deleteUser(userId);
    docManager.deleteAllDocumentsForUser(userId);
    handleLogout();
  };

  const handleLogin = () => {
    setUserId(auth.getCurrentUserId());
  };

  const handleLogout = () => {
    auth.logout();
    setUserId(null);
    setUser(null);
    navigate('/');
  };

  return (
    <div className="w-screen h-screen bg-zinc-100">
      <Routes>
        {/* Public Pages */}
        <Route path="/" element={<HomePage />} />
        <Route path="/auth" element={<AuthPage onLoginSuccess={handleLogin} />} />
        <Route path="/about" element={<AboutPage />} />
        <Route path="/pricing" element={<PricingPage />} />
        <Route path="/contact" element={<ContactPage />} />
        <Route path="/legal" element={<LegalPage />} />
        <Route path="/privacy" element={<PrivacyPage />} />
        <Route path="/terms" element={<TermsPage />} />
        <Route path="/refund" element={<RefundPage />} />

        {/* Authenticated Routes */}
        <Route element={<RequireAuth />}>
          <Route path="/dashboard" element={<DashboardLayout user={user} onLogout={handleLogout} />}>
            <Route index element={
              <FilesPage 
                documents={documents}
                onCreate={handleCreateDoc}
                onTrash={handleTrashDoc}
                onRename={handleRenameDoc}
              />
            }/>
            <Route path="trash" element={
              <TrashPage
                trashedDocuments={trashedDocuments}
                onRestore={handleRestoreDoc}
                onPermanentDelete={handlePermanentDelete}
              />
            }/>
            <Route path="apis" element={<APIsPage userId={userId || ''} />} />
            <Route path="settings" element={
              <SettingsPage 
                user={user}
                onUpdateUser={handleUpdateUser}
                onDeleteAccount={handleDeleteAccount}
              />
            } />
          </Route>

          <Route 
            path="/editor/:id" 
            element={
              <EditorPage
                documents={[...documents, ...trashedDocuments]}
                updateDocument={updateDocument}
                onRename={handleRenameDoc}
              />
            } 
          />
        </Route>

        {/* Not Found */}
        <Route path="*" element={<NotFound />} />
      </Routes>
    </div>
  );
}

