import React, { useState, useRef, useEffect } from 'react';
import { NavLink, Link } from 'react-router-dom';
import { FileText, Trash2, Code, LifeBuoy, User, Settings, LogOut, X } from 'lucide-react';
import { User as UserType } from '../../types/user.types.ts';

interface SidebarProps {
    user: UserType | null;
    onLogout: () => void;
}

const NavItem = ({ to, icon, label }: { to: string, icon: React.ReactNode, label: string }) => (
    <NavLink 
        to={to} 
        end
        className={({ isActive }) => `flex items-center gap-3 px-4 py-2.5 rounded-lg text-sm font-bold transition-colors ${isActive ? 'bg-blue-50 text-blue-700' : 'text-zinc-600 hover:bg-zinc-100'}`}
    >
        {icon}
        <span>{label}</span>
    </NavLink>
);

export function Sidebar({ user, onLogout }: SidebarProps) {
    const [isAccountMenuOpen, setIsAccountMenuOpen] = useState(false);
    const menuRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
                setIsAccountMenuOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    return (
        <aside className="w-64 h-screen bg-white border-r border-zinc-200 flex flex-col shrink-0 p-4">
            <Link to="/dashboard" className="flex items-center gap-2 px-2 mb-8">
                <div className="w-8 h-8 bg-zinc-800 rounded-lg flex items-center justify-center text-white font-black">S</div>
                <span className="font-black text-zinc-800 text-lg">SEO Focus</span>
            </Link>

            <nav className="flex-1 flex flex-col gap-2">
                <NavItem to="/dashboard" icon={<FileText size={18}/>} label="Files" />
                <NavItem to="/dashboard/trash" icon={<Trash2 size={18}/>} label="Trash" />
                <NavItem to="/dashboard/apis" icon={<Code size={18}/>} label="APIs" />
            </nav>

            <div className="flex flex-col gap-2">
                <Link to="/contact" className="flex items-center gap-3 px-4 py-2.5 rounded-lg text-sm font-bold text-zinc-600 hover:bg-zinc-100">
                    <LifeBuoy size={18}/> Support
                </Link>

                <div className="relative" ref={menuRef}>
                    <button onClick={() => setIsAccountMenuOpen(!isAccountMenuOpen)} className="w-full flex items-center gap-3 px-4 py-2.5 rounded-lg text-sm font-bold text-zinc-600 hover:bg-zinc-100">
                        <User size={18}/> Account
                    </button>
                    {isAccountMenuOpen && (
                        <div className="absolute bottom-full left-0 mb-2 w-56 bg-white border border-zinc-200 rounded-xl shadow-2xl p-2 z-20">
                           <div className="p-3 border-b border-zinc-100 mb-2">
                               <p className="text-xs font-bold text-zinc-800">{user?.name || 'User'}</p>
                               <p className="text-xs text-zinc-500 truncate">{user?.email}</p>
                           </div>
                           <Link to="/dashboard/settings" onClick={() => setIsAccountMenuOpen(false)} className="flex items-center gap-3 w-full p-2 rounded-md text-sm text-zinc-700 font-semibold hover:bg-zinc-100"><Settings size={16}/> Settings</Link>
                           <button onClick={() => { onLogout(); setIsAccountMenuOpen(false); }} className="flex items-center gap-3 w-full p-2 rounded-md text-sm text-red-600 font-semibold hover:bg-red-50"><LogOut size={16}/> Logout</button>
                        </div>
                    )}
                </div>
            </div>
        </aside>
    );
}

import React, { useState, useEffect } from 'react';
import { User } from '../../types/user.types.ts';
import { Save, AlertTriangle, Trash2 } from 'lucide-react';

interface SettingsPageProps {
  user: User | null;
  onUpdateUser: (updates: Partial<User>) => boolean;
  onDeleteAccount: () => void;
}

const SettingsCard = ({ title, children }: { title: string, children: React.ReactNode }) => (
    <div className="bg-white border border-zinc-200 rounded-2xl shadow-sm">
        <div className="p-6 border-b border-zinc-100">
            <h3 className="text-lg font-bold text-zinc-800">{title}</h3>
        </div>
        <div className="p-6 space-y-4">
            {children}
        </div>
    </div>
);

const Label = ({ children, htmlFor }: { children: React.ReactNode, htmlFor?: string }) => (
    <label htmlFor={htmlFor} className="text-sm font-bold text-zinc-600 block mb-2">{children}</label>
);

const Input = (props: React.InputHTMLAttributes<HTMLInputElement>) => (
    <input {...props} className="w-full bg-zinc-100 border border-zinc-200 rounded-lg p-3 text-sm outline-none focus:border-blue-500 transition-colors" />
);


export default function SettingsPage({ user, onUpdateUser, onDeleteAccount }: SettingsPageProps) {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [deleteConfirm, setDeleteConfirm] = useState('');
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  useEffect(() => {
    if (user) {
      setName(user.name);
      setEmail(user.email);
    }
  }, [user]);

  const showMessage = (text: string, type: 'success' | 'error') => {
    setMessage({ text, type });
    setTimeout(() => setMessage(null), 3000);
  };

  const handleProfileUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    const success = onUpdateUser({ name });
    if (success) {
      showMessage('Profile updated successfully!', 'success');
    } else {
      showMessage('Failed to update profile.', 'error');
    }
  };

  const handleAccountUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    const updates: Partial<User> = { email };
    if (password) {
        if(password.length < 6) {
            showMessage('Password must be at least 6 characters.', 'error');
            return;
        }
        if (password !== confirmPassword) {
            showMessage('Passwords do not match.', 'error');
            return;
        }
        updates.password = password;
    }
    const success = onUpdateUser(updates);
    if(success) {
        showMessage('Account details updated!', 'success');
        setPassword('');
        setConfirmPassword('');
    } else {
        showMessage('Email may already be taken.', 'error');
    }
  };

  const handleDelete = () => {
      if(deleteConfirm === 'DELETE') {
          onDeleteAccount();
      } else {
          showMessage('Please type DELETE to confirm.', 'error');
      }
  };


  if (!user) return null;

  return (
    <div className="w-full h-full flex flex-col">
      <header className="bg-white/80 backdrop-blur-md border-b border-zinc-200 p-6 flex items-center justify-between sticky top-0 z-10">
        <h1 className="font-black tracking-tighter text-2xl uppercase text-zinc-800">Settings</h1>
      </header>
      <div className="flex-1 p-8 overflow-y-auto">
        <div className="max-w-4xl mx-auto space-y-8">

          {message && (
             <div className={`p-4 rounded-lg text-sm font-bold ${message.type === 'success' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>
                {message.text}
             </div>
          )}

          <SettingsCard title="Profile">
            <form onSubmit={handleProfileUpdate}>
              <Label htmlFor="name">Name</Label>
              <Input id="name" type="text" value={name} onChange={(e) => setName(e.target.value)} />
              <button type="submit" className="mt-4 flex items-center gap-2 px-4 py-2 bg-zinc-800 text-white rounded-lg text-xs font-bold uppercase tracking-wider hover:bg-black transition-colors">
                <Save size={14} /> Save Profile
              </button>
            </form>
          </SettingsCard>

          <SettingsCard title="Account">
            <form onSubmit={handleAccountUpdate}>
              <Label htmlFor="email">Email Address</Label>
              <Input id="email" type="email" value={email} onChange={(e) => setEmail(e.target.value)} />
              <div className="mt-6 pt-6 border-t border-zinc-100">
                <p className="text-sm font-bold text-zinc-600 mb-2">Update Password</p>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <Label htmlFor="password">New Password</Label>
                        <Input id="password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Leave blank to keep current" />
                    </div>
                     <div>
                        <Label htmlFor="confirmPassword">Confirm New Password</Label>
                        <Input id="confirmPassword" type="password" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} />
                    </div>
                </div>
              </div>
              <button type="submit" className="mt-4 flex items-center gap-2 px-4 py-2 bg-zinc-800 text-white rounded-lg text-xs font-bold uppercase tracking-wider hover:bg-black transition-colors">
                <Save size={14} /> Save Account
              </button>
            </form>
          </SettingsCard>

          <div className="bg-red-50 border border-red-200 rounded-2xl p-6">
            <h3 className="text-lg font-bold text-red-800 flex items-center gap-2"><AlertTriangle size={20}/> Danger Zone</h3>
            <p className="text-sm text-red-700 mt-2 mb-4">Deleting your account is permanent and cannot be undone. All your documents and data will be permanently erased.</p>
            <div>
                <Label htmlFor="deleteConfirm">Type "DELETE" to confirm:</Label>
                <Input id="deleteConfirm" type="text" value={deleteConfirm} onChange={(e) => setDeleteConfirm(e.target.value)} className="bg-white border-red-200 focus:border-red-500" />
            </div>
            <button 
                onClick={handleDelete}
                className="mt-4 flex items-center gap-2 px-4 py-2 bg-red-600 text-white rounded-lg text-xs font-bold uppercase tracking-wider hover:bg-red-700 transition-colors disabled:opacity-50"
                disabled={deleteConfirm !== 'DELETE'}
            >
                <Trash2 size={14} /> Delete My Account
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

