import { 
    doc, 
    setDoc, 
    getDoc, 
    collection, 
    addDoc,
    serverTimestamp,
    onSnapshot,
    query,
    orderBy,
    deleteDoc,
    Timestamp,
    updateDoc,
    writeBatch
} from 'firebase/firestore';
import { User as FirebaseUser } from 'firebase/auth';
import { db } from '../lib/firebase';
import { LocalDocument } from '../types/document.types';

export interface UserProfile {
    uid: string;
    email: string;
    name: string;
    createdAt: Timestamp;
    plan: 'free' | 'pro';
    usage: number;
}

export const createUserProfile = async (user: FirebaseUser) => {
    const userRef = doc(db, 'users', user.uid);
    const userProfile: UserProfile = {
        uid: user.uid,
        email: user.email || '',
        name: user.displayName || user.email?.split('@')[0] || 'New User',
        createdAt: Timestamp.now(),
        plan: 'free',
        usage: 0
    };
    await setDoc(userRef, userProfile);
};

export const getUserProfile = async (userId: string): Promise<UserProfile | null> => {
    const userRef = doc(db, 'users', userId);
    const docSnap = await getDoc(userRef);
    if (docSnap.exists()) {
        return docSnap.data() as UserProfile;
    }
    return null;
};

export const updateUserProfile = (userId: string, data: Partial<UserProfile>) => {
    const userRef = doc(db, 'users', userId);
    return updateDoc(userRef, data);
};

export const createDocument = async (userId: string, title: string): Promise<string> => {
    const collectionRef = collection(db, 'users', userId, 'documents');
    const newDoc: Omit<LocalDocument, 'id'> = {
        title,
        content: `<h1>${title}</h1><p>Start writing here...</p>`,
        createdAt: Date.now(), // Using client-side timestamp for consistency with old model, but serverTimestamp() is better
        updatedAt: Date.now(),
        metaTitle: '',
        metaDescription: '',
        targets: { primary: '', secondary: ['', '', ''] },
        faqs: [],
        targetDomain: '',
        isTrashed: false,
        goal: {
            wordCount: 1000,
            intent: 'General',
            audience: 'General',
            tone: 'Professional'
        }
    };
    const docRef = await addDoc(collectionRef, {
        ...newDoc,
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp()
    });
    return docRef.id;
};

export const getDocuments = (userId: string, callback: (docs: LocalDocument[]) => void) => {
    const collectionRef = collection(db, 'users', userId, 'documents');
    const q = query(collectionRef, orderBy('updatedAt', 'desc'));

    return onSnapshot(q, (querySnapshot) => {
        const documents = querySnapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data()
        } as LocalDocument));
        callback(documents);
    });
};

export const getDocument = (userId: string, docId: string, callback: (doc: LocalDocument | null) => void) => {
    const docRef = doc(db, 'users', userId, 'documents', docId);
    return onSnapshot(docRef, (docSnap) => {
        if(docSnap.exists()) {
            callback({ id: docSnap.id, ...docSnap.data() } as LocalDocument);
        } else {
            callback(null);
        }
    });
};

export const saveDocument = (userId: string, docId: string, data: Partial<LocalDocument>) => {
    const docRef = doc(db, 'users', userId, 'documents', docId);
    return updateDoc(docRef, { ...data, updatedAt: serverTimestamp() });
};

export const deleteDocument = (userId: string, docId: string) => {
    const docRef = doc(db, 'users', userId, 'documents', docId);
    return deleteDoc(docRef);
};


export const deleteUserDocuments = async (userId: string) => {
    const collectionRef = collection(db, 'users', userId, 'documents');
    const userProfileRef = doc(db, 'users', userId);

    const querySnapshot = await getDoc(collectionRef);
    const batch = writeBatch(db);

    querySnapshot.docs.forEach((doc) => {
        batch.delete(doc.ref);
    });

    // Also delete the user profile doc
    batch.delete(userProfileRef);

    return batch.commit();
};

