            {!isEditing && (
                <div ref={menuRef} className="absolute top-4 right-4">
                    <button onClick={() => setMenuOpen(!menuOpen)} className="p-2 rounded-full hover:bg-zinc-200 opacity-0 group-hover:opacity-100 transition-opacity">
                        <MoreVertical size={16} className="text-zinc-500" />
                    </button>
                    {menuOpen && (
                        <div className="absolute top-full right-0 mt-1 w-40 bg-white border border-zinc-200 rounded-xl shadow-xl z-10 p-2">
                            <button onClick={(e) => { e.stopPropagation(); setIsEditing(true); setMenuOpen(false); }} className="w-full text-left flex items-center gap-2 p-2 text-xs font-bold text-zinc-700 hover:bg-zinc-100 rounded-lg"><Edit size={14}/> Rename</button>
                            <button onClick={(e) => { e.stopPropagation(); onTrash(doc.id); }} className="w-full text-left flex items-center gap-2 p-2 text-xs font-bold text-red-600 hover:bg-red-50 rounded-lg"><Trash2 size={14}/> Move to Trash</button>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default function FilesPage() {
    const navigate = useNavigate();
    const { currentUser } = useAuth();
    const [documents, setDocuments] = useState<LocalDocument[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');
    const [sortOrder, setSortOrder] = useState<'updatedAt' | 'createdAt' | 'title'>('updatedAt');

    useEffect(() => {
        if (!currentUser) return;
        setLoading(true);
        const unsubscribe = firestoreService.getDocuments(currentUser.uid, (docs) => {
            const nonTrashedDocs = docs.filter(d => !d.isTrashed);
            setDocuments(nonTrashedDocs);
            setLoading(false);
        });
        return () => unsubscribe();
    }, [currentUser]);

    const handleCreate = async () => {
        if (!currentUser) return;
        const newDocId = await firestoreService.createDocument(currentUser.uid, 'Untitled Document');
        navigate(`/editor/${newDocId}`);
    };

    const handleTrash = (id: string) => {
        if (!currentUser) return;
        firestoreService.saveDocument(currentUser.uid, id, { isTrashed: true });
    };

    const handleRename = (id: string, newTitle: string) => {
        if (!currentUser) return;
        firestoreService.saveDocument(currentUser.uid, id, { title: newTitle });
    };

    const sortedAndFilteredDocs = useMemo(() => {
        return documents
            .filter(doc => doc.title.toLowerCase().includes(searchTerm.toLowerCase()))
            .sort((a, b) => {
                if (sortOrder === 'title') return a.title.localeCompare(b.title);
                if (sortOrder === 'updatedAt' || sortOrder === 'createdAt') {
                    // Assuming they are numbers (timestamps)
                    return (b[sortOrder] || 0) - (a[sortOrder] || 0);
                }
                return 0;
            });
    }, [documents, searchTerm, sortOrder]);

    if (loading) {
        return <div className="flex items-center justify-center h-full"><Loader className="animate-spin text-blue-500" /></div>
    }

    return (
        <div className="w-full h-full flex flex-col">
            <header className="bg-white/80 backdrop-blur-md border-b border-zinc-200 p-6 flex items-center justify-between sticky top-0 z-10">
                <h1 className="font-black tracking-tighter text-2xl uppercase text-zinc-800">Files</h1>
                 <button onClick={handleCreate} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg text-xs font-bold uppercase tracking-wider hover:bg-blue-700 transition-colors shadow-md shadow-blue-500/20">
                    <Plus size={16} /> New Document
                </button>
            </header>
            <div className="flex-1 p-8 overflow-y-auto">
                <div className="max-w-7xl mx-auto">
                    <div className="mb-8 flex items-center justify-between gap-4">
                        <div className="relative flex-1 max-w-lg">
                            <Search size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-400" />
                            <input
                                type="text"
                                placeholder="Search documents..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="w-full bg-white border border-zinc-200 rounded-lg py-3 pl-12 pr-4 text-sm font-bold focus:border-blue-500 outline-none transition-colors"
                            />
                        </div>
                        <div className="relative">
                            <select
                                value={sortOrder}
                                onChange={(e) => setSortOrder(e.target.value as any)}
                                className="appearance-none bg-white border border-zinc-200 rounded-lg py-3 px-4 pr-10 text-sm font-bold text-zinc-600 focus:border-blue-500 outline-none"
                            >
                                <option value="updatedAt">Sort by Updated</option>
                                <option value="createdAt">Sort by Created</option>
                                <option value="title">Sort by Title</option>
                            </select>
                            <ArrowUpDown size={16} className="absolute right-3 top-1/2 -translate-y-1/2 text-zinc-400 pointer-events-none" />
                        </div>
                    </div>
                    {sortedAndFilteredDocs.length > 0 ? (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                            {sortedAndFilteredDocs.map(doc => (
                                <DocumentCard key={doc.id} doc={doc} onTrash={handleTrash} onRename={handleRename} />
                            ))}
                        </div>
                    ) : (
                        <div className="text-center py-20 bg-white rounded-2xl border border-zinc-200">
                            <h3 className="text-lg font-bold text-zinc-600">No files yet</h3>
                            <p className="text-sm text-zinc-400 mt-2 mb-6">Create your first document to get started.</p>
                            <button onClick={handleCreate} className="flex items-center gap-2 mx-auto px-4 py-2 bg-blue-600 text-white rounded-lg text-xs font-bold uppercase tracking-wider hover:bg-blue-700 transition-colors">
                                <Plus size={16} /> Create First File
                            </button>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

import React, { useState, useEffect, useMemo, useDeferredValue, startTransition, useCallback, useRef } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { X, Send, ArrowLeft, Edit, Goal, Loader } from 'lucide-react';
import { LocalDocument, DocumentGoal } from '../types/document.types';

// Core Analysis Logic
import { getStats } from '../core/text-analysis.ts';
import { getKeywords } from '../core/keyword-density.ts';
import { getReadabilityScore } from '../core/readability.ts';
import { analyzeSEOHealth } from '../core/seo-health.ts';
import { detectIntent } from '../core/intent-detector.ts';
import { analyzeSentenceWarnings } from '../core/sentence-analysis.ts';
import { generateOptimizationReport } from '../core/optimization-engine.ts';

// AI Integration
import { rewriteContent, generateMetadata, detectAIContent, RewriteMode, generateFAQs } from '../ai/ai-engine.ts';

// Components & Services
import { Toolbar } from '../components/editor/Toolbar.tsx';
import { Sidebar } from '../components/layout/Sidebar.tsx';
import { Editor } from '../components/editor/Editor.tsx';
import { GoalModal } from '../components/editor/GoalModal.tsx';
import { Tab, SEOPhraseTab } from '../types/editor.types.ts';
import { useAuth } from '../context/AuthContext.tsx';
import { getDocument, saveDocument } from '../services/firestore.ts';

function debounce<F extends (...args: any[]) => any>(func: F, waitFor: number) {
  let timeout: ReturnType<typeof setTimeout> | null = null;
  return (...args: Parameters<F>): void => {
    if (timeout) clearTimeout(timeout);
    timeout = setTimeout(() => func(...args), waitFor);
  };
}

export default function EditorPage() {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();
    const { currentUser } = useAuth();

    const [activeDocument, setActiveDocument] = useState<LocalDocument | null>(null);
    const [loading, setLoading] = useState(true);

    // UI State
    const [activeTab, setActiveTab] = useState<Tab>('insights');
    const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
    const [isExpanded, setIsExpanded] = useState(false);
    const [isAIProcessing, setIsAIProcessing] = useState(false);
    const [editorInstance, setEditorInstance] = useState<any>(null);
    const [toast, setToast] = useState<{ message: string, visible: boolean }>({ message: '', visible: false });
    const [currentBlockType, setCurrentBlockType] = useState('p');
    const [isLinkActive, setIsLinkActive] = useState(false);
    const [brokenLinks, setBrokenLinks] = useState<string[]>([]);
    const [isEditingTitle, setIsEditingTitle] = useState(false);
    const [headerTitle, setHeaderTitle] = useState('');
    const [isGoalModalOpen, setGoalModalOpen] = useState(false);
    const titleInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        if (!currentUser || !id) return;
        setLoading(true);
        const unsubscribe = getDocument(currentUser.uid, id, (doc) => {
            if (doc) {
                setActiveDocument(doc);
                setHeaderTitle(doc.title);
            } else {
                navigate('/dashboard'); // Or a not-found page
            }
            setLoading(false);
        });
        return () => unsubscribe();
    }, [currentUser, id, navigate]);

    useEffect(() => {
        if (isEditingTitle && titleInputRef.current) {
            titleInputRef.current.focus();
            titleInputRef.current.select();
        }
    }, [isEditingTitle]);

    const deferredContent = useDeferredValue(activeDocument?.content || '');

    // Analysis Memoization
    const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
    const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
    const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
    const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, activeDocument?.targets || { primary: '', secondary: [] }, activeDocument?.metaDescription || '', activeDocument?.metaTitle || '', brokenLinks, activeDocument?.targetDomain || ''), [deferredContent, keywords, activeDocument, brokenLinks]);
    const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);
    const sentenceWarnings = useMemo(() => analyzeSentenceWarnings(deferredContent), [deferredContent]);

    const optimizationReport = useMemo(() => {
        if (!activeDocument) return { critical: [], improvements: [], enhancements: [] };
        return generateOptimizationReport(
            stats, health, readability, sentenceWarnings,
            activeDocument.targets, activeDocument.metaTitle, activeDocument.metaDescription, activeDocument.faqs.length, keywords
        );
    }, [stats, health, readability, sentenceWarnings, activeDocument, keywords]);

    const handlePropUpdate = useCallback((updates: Partial<Omit<LocalDocument, 'id' | 'createdAt'>>) => {
        if (id && currentUser) {
            saveDocument(currentUser.uid, id, updates);
        }
    }, [id, currentUser]);

    const debouncedSave = useCallback(debounce((userId: string, docId: string, updates: Partial<LocalDocument>) => {
        saveDocument(userId, docId, updates);
    }, 1000), []);

    const handleEditorChange = useCallback((newContent: string) => {
        if(id && currentUser) {
            startTransition(() => {
                // Optimistically update local state for responsiveness
                setActiveDocument(prev => prev ? { ...prev, content: newContent } : null);
                debouncedSave(currentUser.uid, id, { content: newContent });
            });
        }
    }, [id, currentUser, debouncedSave]);

    const handleSelectionChange = useCallback((blockType: string, isLink: boolean) => {
        setCurrentBlockType(blockType);
        setIsLinkActive(isLink);
    }, []);

    const handleTitleRename = (e: React.FormEvent) => {
        e.preventDefault();
        if(id && headerTitle.trim() && currentUser){
            saveDocument(currentUser.uid, id, { title: headerTitle.trim() });
        } else {
            setHeaderTitle(activeDocument?.title || '');
        }
        setIsEditingTitle(false);
    };

    const handleSaveGoals = (newGoal: DocumentGoal) => {
        if (id && currentUser) {
            saveDocument(currentUser.uid, id, { goal: newGoal });
            showToast("Content goals updated!");
        }
    };

    const showToast = (msg: string) => {
        setToast({ message: msg, visible: true });
        setTimeout(() => setToast(prev => ({ ...prev, visible: false })), 3000);
    };

    const onRewrite = useCallback(async (mode: RewriteMode) => {
        if (!editorInstance) return;
        const selectedText = editorInstance.getSelection();
        if (!selectedText) {
            alert("Please select text to use AI rewriting features.");
            return;
        }
        setIsAIProcessing(true);
        try {
            const results = await rewriteContent(selectedText, mode);
            if (results && results.length > 0) editorInstance.insertContent(results[0]);
        } catch (err) { console.error("AI Rewrite Failed:", err); }
        finally { setIsAIProcessing(false); }
    }, [editorInstance]);

    if (loading || !activeDocument) {
        return (
            <div className="w-screen h-screen bg-zinc-100 flex items-center justify-center flex-col gap-4">
                <Loader className="animate-spin text-blue-500" />
                <p className="text-zinc-500 font-semibold">Loading Document...</p>
            </div>
        );
    }

    return (
        <div className="flex flex-col h-screen w-full bg-white overflow-hidden text-zinc-900 selection:bg-blue-100 relative">
             <div className={`fixed top-6 left-1/2 -translate-x-1/2 z-[200] bg-zinc-900 text-white px-6 py-3 rounded-full shadow-2xl flex items-center gap-3 transition-all duration-300 ease-in-out ${toast.visible ? 'translate-y-0 opacity-100' : '-translate-y-12 opacity-0 pointer-events-none'}`}>
                 <div className="w-2 h-2 rounded-full bg-emerald-400 shadow-[0_0_10px_rgba(52,211,153,0.5)]"></div>
                 <span className="text-[11px] font-black uppercase tracking-widest">{toast.message}</span>
             </div>

            <header className="h-16 border-b border-zinc-100 px-6 flex items-center justify-between bg-white shrink-0">
                <div className="flex items-center gap-2">
                     <Link to="/dashboard" className="p-2 rounded-lg hover:bg-zinc-100 text-zinc-500 transition-colors" title="Back to Dashboard">
                       <ArrowLeft size={18} />
                     </Link>
                     <div className="w-px h-6 bg-zinc-200 mx-2"></div>
                     {isEditingTitle ? (
                         <form onSubmit={handleTitleRename}>
                             <input
                                 ref={titleInputRef}
                                 type="text"
                                 value={headerTitle}
                                 onChange={(e) => setHeaderTitle(e.target.value)}
                                 onBlur={handleTitleRename}
                                 className="font-black tracking-tighter text-lg uppercase bg-zinc-100 p-1 rounded-md outline-none"
                             />
                         </form>
                     ) : (
                         <div className="flex items-center gap-2 group" onClick={() => setIsEditingTitle(true)}>
                            <h1 className="font-black tracking-tighter text-lg uppercase truncate max-w-xs cursor-pointer">{headerTitle}</h1>
                            <Edit size={14} className="text-zinc-400 opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer" />
                         </div>
                     )}
                </div>
                <button 
                    onClick={() => setGoalModalOpen(true)}
                    className="flex items-center gap-2 px-4 py-2 bg-white border border-zinc-200 text-zinc-600 rounded-lg text-xs font-bold uppercase tracking-wider hover:bg-zinc-50 transition-colors"
                >
                    <Goal size={14} /> Goal
                </button>
            </header>

            <div className="flex flex-1 overflow-hidden">
                <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
                    <div className="toolbar-container bg-white border-b border-zinc-100">
                        <Toolbar
                            editorInstance={editorInstance}
                            onUpdate={() => handleEditorChange(editorInstance?.getContent() || '')}
                            onNewDocument={() => { }} onShowHistory={() => { }} onSaveVersion={() => { }}
                            viewMode="focused" currentBlockType={currentBlockType} isLinkActive={isLinkActive}
                        />
                    </div>
                    <main className="flex-1 flex justify-center relative bg-zinc-50/50">
                        <div className="w-full max-w-[900px] h-full bg-white">
                            <Editor
                                key={activeDocument.id}
                                initialContent={activeDocument.content}
                                onUpdate={handleEditorChange}
                                onInit={setEditorInstance}
                                onAIAssist={onRewrite}
                                onSelectionChange={handleSelectionChange}
                            />
                        </div>
                    </main>
                </div>

                <Sidebar
                    activeTab={activeTab} setActiveTab={setActiveTab}
                    stats={stats} readability={readability} health={health} intent={intent} keywords={keywords}
                    seoTab={seoTab} setSeoTab={setSeoTab} isExpanded={isExpanded} setIsExpanded={setIsExpanded}
                    onRewrite={onRewrite}
                    isAIProcessing={isAIProcessing} targets={activeDocument.targets} setTargets={(t) => handlePropUpdate({ targets: t })}
                    metaTitle={activeDocument.metaTitle} setMetaTitle={(s) => handlePropUpdate({ metaTitle: s })}
                    metaDescription={activeDocument.metaDescription} setMetaDescription={(s) => handlePropUpdate({ metaDescription: s })}
                    faqs={activeDocument.faqs} setFaqs={(f) => handlePropUpdate({ faqs: f })}
                    onGenerateMetadata={async (type) => {
                        setIsAIProcessing(true);
                        try {
                            const currentValue = type === 'title' ? activeDocument.metaTitle : activeDocument.metaDescription;
                            const res = await generateMetadata(activeDocument.content, type, activeDocument.targets, currentValue);
                            handlePropUpdate(type === 'title' ? { metaTitle: res } : { metaDescription: res });
                            showToast(`Meta ${type === 'title' ? 'Title' : 'Description'} Updated`);
                        } catch (error) {
                            console.error(error); showToast('Generation Failed');
                        } finally { setIsAIProcessing(false); }
                    }}
                    onDetectAI={async () => {
                        setIsAIProcessing(true);
                        try {
                            const res = await detectAIContent(activeDocument.content);
                            alert(`AI Detection Score: ${res.score}%`);
                        } finally { setIsAIProcessing(false); }
                    }}
                    onGenerateFAQs={async () => {
                        setIsAIProcessing(true);
                        try {
                            const res = await generateFAQs(activeDocument.content);
                            handlePropUpdate({ faqs: res });
                            showToast('FAQs Generated');
                        } finally { setIsAIProcessing(false); }
                    }}
                    onExportSchema={() => {
                        navigator.clipboard.writeText(JSON.stringify({ "@context": "https://schema.org", "@type": "Article", "headline": activeDocument.metaTitle, "description": activeDocument.metaDescription }, null, 2));
                        showToast('Schema Copied to Clipboard');
                    }}
                    onNavigateOutline={(text) => editorInstance?.scrollToText(text)}
                    sentenceWarnings={sentenceWarnings}
                    optimizationReport={optimizationReport}
                    onHighlight={(enabled) => editorInstance?.toggleHighlights(activeDocument.targets, enabled)}
                    setBrokenLinks={setBrokenLinks}
                    targetDomain={activeDocument.targetDomain}
                    setTargetDomain={(s) => handlePropUpdate({ targetDomain: s })}
                />
            </div>
             {isGoalModalOpen && activeDocument && (
                <GoalModal
                    isOpen={isGoalModalOpen}
                    onClose={() => setGoalModalOpen(false)}
                    document={activeDocument}
                    onSave={handleSaveGoals}
                />
            )}
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Save, AlertTriangle, Trash2 } from 'lucide-react';
import { useAuth } from '../../context/AuthContext.tsx';
import * as authService from '../../services/auth.ts';
