const TrashedDocRow = ({ doc, onRestore, onPermanentDelete }: { doc: LocalDocument, onRestore: (id: string) => void, onPermanentDelete: (id: string) => void }) => (
    <div className="flex items-center justify-between p-4 bg-white border-b border-zinc-100 group">
        <div>
            <p className="font-bold text-sm text-zinc-800">{doc.title}</p>
            <p className="text-xs text-zinc-400">Trashed on: {doc.updatedAt && new Date(doc.updatedAt).toLocaleDateString()}</p>
        </div>
        <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
            <button onClick={() => onRestore(doc.id)} className="p-2 rounded-lg text-zinc-500 hover:bg-green-50 hover:text-green-600 transition-colors" title="Restore">
                <RotateCcw size={16} />
            </button>
            <button onClick={() => onPermanentDelete(doc.id)} className="p-2 rounded-lg text-zinc-500 hover:bg-red-50 hover:text-red-600 transition-colors" title="Delete Permanently">
                <Trash2 size={16} />
            </button>
        </div>
    </div>
);

export default function TrashPage() {
    const { currentUser } = useAuth();
    const [trashedDocuments, setTrashedDocuments] = useState<LocalDocument[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (!currentUser) {
            setLoading(false);
            return;
        }
        setLoading(true);
        const unsubscribe = firestoreService.getDocuments(currentUser.uid, (docs) => {
            const trashed = docs.filter(d => d.isTrashed);
            setTrashedDocuments(trashed);
            setLoading(false);
        });
        return () => unsubscribe();
    }, [currentUser]);

    const handleRestore = (id: string) => {
        if (!currentUser) return;
        firestoreService.saveDocument(currentUser.uid, id, { isTrashed: false });
    };

    const handlePermanentDelete = (id: string) => {
        if (!currentUser) return;
        if (window.confirm('Are you sure you want to permanently delete this document? This cannot be undone.')) {
            firestoreService.deleteDocument(currentUser.uid, id);
        }
    };

    if (loading) {
        return <div className="flex items-center justify-center h-full"><Loader className="animate-spin text-blue-500" /></div>
    }

    return (
        <div className="w-full h-full flex flex-col">
            <header className="bg-white/80 backdrop-blur-md border-b border-zinc-200 p-6 flex items-center justify-between sticky top-0 z-10">
                <h1 className="font-black tracking-tighter text-2xl uppercase text-zinc-800">Trash</h1>
            </header>
            <div className="flex-1 p-8 overflow-y-auto">
                <div className="max-w-4xl mx-auto">
                    <div className="bg-white border border-zinc-200 rounded-2xl overflow-hidden shadow-sm">
                        {trashedDocuments.length > 0 ? (
                            <div>
                                {trashedDocuments.map(doc => (
                                    <TrashedDocRow key={doc.id} doc={doc} onRestore={handleRestore} onPermanentDelete={handlePermanentDelete} />
                                ))}
                            </div>
                        ) : (
                            <div className="text-center py-20">
                                <FileX size={48} className="mx-auto text-zinc-300 mb-4" />
                                <h3 className="text-lg font-bold text-zinc-600">Trash is empty</h3>
                                <p className="text-sm text-zinc-400 mt-2">Deleted files will appear here.</p>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}

import { 
    doc, 
    setDoc, 
    getDoc, 
    collection, 
    addDoc,
    serverTimestamp,
    onSnapshot,
    query,
    orderBy,
    deleteDoc,
    Timestamp,
    updateDoc,
    writeBatch
} from 'firebase/firestore';
import { User as FirebaseUser } from 'firebase/auth';
import { db } from '../lib/firebase';
import { LocalDocument } from '../types/document.types';

export interface UserProfile {
    uid: string;
    email: string;
    name: string;
    createdAt: Timestamp;
    plan: 'free' | 'pro';
    usage: number;
}

export const createUserProfile = async (user: FirebaseUser) => {
    const userRef = doc(db, 'users', user.uid);
    const userProfile: UserProfile = {
        uid: user.uid,
        email: user.email || '',
        name: user.displayName || user.email?.split('@')[0] || 'New User',
        createdAt: Timestamp.now(),
        plan: 'free',
        usage: 0
    };
    await setDoc(userRef, userProfile);
};

export const getUserProfile = async (userId: string): Promise<UserProfile | null> => {
    const userRef = doc(db, 'users', userId);
    const docSnap = await getDoc(userRef);
    if (docSnap.exists()) {
        return docSnap.data() as UserProfile;
    }
    return null;
};

export const updateUserProfile = (userId: string, data: Partial<UserProfile>) => {
    const userRef = doc(db, 'users', userId);
    return updateDoc(userRef, data);
};

export const createDocument = async (userId: string, title: string): Promise<string> => {
    const collectionRef = collection(db, 'users', userId, 'documents');
    const newDoc: Omit<LocalDocument, 'id'> = {
        title,
        content: `<h1>${title}</h1><p>Start writing here...</p>`,
        createdAt: Date.now(), // Using client-side timestamp for consistency with old model, but serverTimestamp() is better
        updatedAt: Date.now(),
        metaTitle: '',
        metaDescription: '',
        targets: { primary: '', secondary: ['', '', ''] },
        faqs: [],
        targetDomain: '',
        isTrashed: false,
        goal: {
            wordCount: 1000,
            intent: 'General',
            audience: 'General',
            tone: 'Professional'
        }
    };
    const docRef = await addDoc(collectionRef, {
        ...newDoc,
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp()
    });
    return docRef.id;
};

export const getDocuments = (userId: string, callback: (docs: LocalDocument[]) => void) => {
    const collectionRef = collection(db, 'users', userId, 'documents');
    const q = query(collectionRef, orderBy('updatedAt', 'desc'));

    return onSnapshot(q, (querySnapshot) => {
        const documents = querySnapshot.docs.map(d => {
            const data = d.data();
            // Manually convert Timestamps to numbers to match LocalDocument type
            const createdAt = data.createdAt?.toMillis ? data.createdAt.toMillis() : data.createdAt;
            const updatedAt = data.updatedAt?.toMillis ? data.updatedAt.toMillis() : data.updatedAt;

            return {
                ...data,
                id: d.id,
                createdAt,
                updatedAt,
            } as LocalDocument;
        });
        callback(documents);
    });
};

export const getDocument = (userId: string, docId: string, callback: (doc: LocalDocument | null) => void) => {
    const docRef = doc(db, 'users', userId, 'documents', docId);
    return onSnapshot(docRef, (docSnap) => {
        if(docSnap.exists()) {
            const data = docSnap.data();
            // Manually convert Timestamps to numbers to match LocalDocument type
            const createdAt = data.createdAt?.toMillis ? data.createdAt.toMillis() : data.createdAt;
            const updatedAt = data.updatedAt?.toMillis ? data.updatedAt.toMillis() : data.updatedAt;

            callback({ 
                ...data,
                id: docSnap.id,
                createdAt,
                updatedAt,
            } as LocalDocument);
        } else {
            callback(null);
        }
    });
};

export const saveDocument = (userId: string, docId: string, data: Partial<LocalDocument>) => {
    const docRef = doc(db, 'users', userId, 'documents', docId);
    return updateDoc(docRef, { ...data, updatedAt: serverTimestamp() });
};

export const deleteDocument = (userId: string, docId: string) => {
    const docRef = doc(db, 'users', userId, 'documents', docId);
    return deleteDoc(docRef);
};


