import { 
    collection, 
    getDocs, 
    onSnapshot,
    query,
    where,
    Timestamp,
    getCountFromServer,
    collectionGroup,
    orderBy,
    FirestoreError
} from 'firebase/firestore';
import { db } from '../lib/firebase';
import { UserProfile } from './firestore';
import { LocalDocument } from '../types/document.types';

export interface GlobalStats {
    totalUsers: number;
    activeUsers: number;
    totalDocuments: number;
    freeUsers: number;
    paidUsers: number;
}

export const getGlobalStats = async (): Promise<GlobalStats> => {
    const usersCollection = collection(db, 'users');

    // Total, Free, Paid Users
    const usersSnapshot = await getDocs(usersCollection);
    const totalUsers = usersSnapshot.size;
    let freeUsers = 0;
    let paidUsers = 0;
    usersSnapshot.forEach(doc => {
        if (doc.data().plan === 'pro') {
            paidUsers++;
        } else {
            freeUsers++;
        }
    });

    // Active Users (last 7 days)
    const sevenDaysAgo = Timestamp.fromMillis(Date.now() - 7 * 24 * 60 * 60 * 1000);
    const activeUsersQuery = query(usersCollection, where('lastLogin', '>=', sevenDaysAgo));
    const activeUsersSnapshot = await getCountFromServer(activeUsersQuery);
    const activeUsers = activeUsersSnapshot.data().count;

    // Total Documents (using collectionGroup for efficiency)
    const documentsQuery = query(collectionGroup(db, 'documents'));
    const documentsSnapshot = await getCountFromServer(documentsQuery);
    const totalDocuments = documentsSnapshot.data().count;

    return { totalUsers, activeUsers, totalDocuments, freeUsers, paidUsers };
};

export const listenToUsersWithDocCount = (
    onNext: (users: (UserProfile & { docCount: number })[]) => void,
    onError: (error: FirestoreError) => void
) => {
    const usersCollection = collection(db, 'users');
    const q = query(usersCollection, orderBy('createdAt', 'desc'));

    return onSnapshot(q, async (querySnapshot) => {
        const usersData = await Promise.all(querySnapshot.docs.map(async (userDoc) => {
            const user = userDoc.data() as UserProfile;
            const documentsCollection = collection(db, 'users', user.uid, 'documents');
            const docCountSnapshot = await getCountFromServer(documentsCollection);
            return {
                ...user,
                id: userDoc.id,
                docCount: docCountSnapshot.data().count,
            };
        }));
        onNext(usersData);
    }, (error) => {
        console.error("Snapshot listener error:", error);
        onError(error);
    });
};


export const getUserDocuments = async (userId: string): Promise<LocalDocument[]> => {
    const documentsCollection = collection(db, 'users', userId, 'documents');
    const q = query(documentsCollection, orderBy('updatedAt', 'desc'));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as LocalDocument));
};

import React, { useState, useEffect } from 'react';
import { useAuth } from '../../context/AuthContext';
import * as adminService from '../../services/adminService';
import { UserProfile } from '../../services/firestore';
import { MetricsCards } from '../../components/admin/MetricsCards';
import { UsersTable } from '../../components/admin/UsersTable';
import { UserDetailModal } from '../../components/admin/UserDetailModal';
import { Loader } from 'lucide-react';

type UserWithDocCount = UserProfile & { docCount: number };

export default function AdminDashboard() {
  const { userProfile } = useAuth();
  const [stats, setStats] = useState<adminService.GlobalStats | null>(null);
  const [users, setUsers] = useState<UserWithDocCount[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedUser, setSelectedUser] = useState<UserWithDocCount | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  useEffect(() => {
    const fetchAdminData = async () => {
      try {
        setError(null);
        setLoading(true);

        const newStats = await adminService.getGlobalStats();
        setStats(newStats);

        const unsubscribeUsers = adminService.listenToUsersWithDocCount(
          (newUsers) => {
            setUsers(newUsers);
            if (loading) setLoading(false);
          },
          (err) => {
            const msg = err.message || 'An unknown error occurred.';
            if (msg.includes('permission-denied')) {
              setError('Permission Denied: Could not listen for user data. Ensure your admin role is configured.');
            } else {
              setError(`Listener Error: ${msg}`);
            }
            setLoading(false);
          }
        );
        return () => unsubscribeUsers();

      } catch (err: any) {
        console.error("Failed to fetch admin stats:", err);
        const msg = err.message || 'An unknown error occurred.';
        if (msg.includes('permission-denied')) {
          setError('Permission Denied: Could not fetch global stats. Ensure your admin role is configured.');
        } else {
          setError(`Fetch Error: ${msg}`);
        }
        setLoading(false);
      }
    };

    const unsubscribePromise = fetchAdminData();

    return () => {
      unsubscribePromise.then(unsubscribe => unsubscribe && unsubscribe());
    };
  }, []);

  const handleViewUser = (user: UserWithDocCount) => {
    setSelectedUser(user);
    setIsModalOpen(true);
  };

  return (
    <div className="w-full h-screen flex flex-col bg-zinc-50">
      <header className="bg-white/80 backdrop-blur-md border-b border-zinc-200 p-6 flex items-center justify-between sticky top-0 z-10 shrink-0">
        <h1 className="font-black tracking-tighter text-2xl uppercase text-zinc-800">Admin Dashboard</h1>
        <div className="text-sm font-bold text-zinc-600">
          Welcome, {userProfile?.name}
        </div>
      </header>

      <main className="flex-1 p-8 overflow-y-auto">
        <div className="max-w-7xl mx-auto space-y-8">
          {loading ? (
             <div className="flex h-64 w-full items-center justify-center"><Loader className="animate-spin text-blue-500"/></div>
          ) : error ? (
            <div className="bg-red-50 text-red-800 p-6 rounded-2xl border border-red-200">
              <h3 className="font-bold text-lg">Error Loading Dashboard</h3>
              <p className="text-sm mt-2">{error}</p>
            </div>
          ) : (
            <>
              <MetricsCards stats={stats} />
              <UsersTable users={users} onViewUser={handleViewUser} />
            </>
          )}
        </div>
      </main>

      {isModalOpen && selectedUser && (
        <UserDetailModal 
          user={selectedUser} 
          onClose={() => setIsModalOpen(false)} 
        />
      )}
    </div>
  );
}

