export interface UserProfile {
    uid: string;
    email: string;
    name: string;
    createdAt: Timestamp;
    plan: 'free' | 'pro';
    usage: number; // General usage, can be deprecated or repurposed
    aiUsage: number;
    status: 'active' | 'disabled';
    role?: 'admin' | 'user';
    lastLogin?: Timestamp;
}

export const createUserProfile = async (user: FirebaseUser) => {
    const userRef = doc(db, 'users', user.uid);
    const isAdmin = user.email?.toLowerCase() === 'rathod.shivang@gmail.com';
    const userProfile: Omit<UserProfile, 'uid' | 'email' | 'name' | 'createdAt' | 'lastLogin' | 'role'> & { uid: string, email: string, name: string, createdAt: any, lastLogin: any, role: 'admin' | 'user' } = {
        uid: user.uid,
        email: user.email || '',
        name: user.displayName || user.email?.split('@')[0] || 'New User',
        createdAt: serverTimestamp(),
        plan: 'free',
        usage: 0,
        aiUsage: 0,
        status: 'active',
        role: isAdmin ? 'admin' : 'user',
        lastLogin: serverTimestamp(),
    };
    await setDoc(userRef, userProfile);
};

export const getUserProfile = async (userId: string): Promise<UserProfile | null> => {
    const userRef = doc(db, 'users', userId);

    const docSnap = await getDoc(userRef);
    if (!docSnap.exists()) {
        return null;
    }

    const profile = docSnap.data() as UserProfile;

    // Check if an admin role upgrade is needed.
    if (profile.email.toLowerCase() === 'rathod.shivang@gmail.com' && profile.role !== 'admin') {
        // Perform the role update.
        await setDoc(userRef, { role: 'admin' }, { merge: true });

        // Poll the server to confirm the write has propagated, to prevent security rule race conditions.
        for (let attempt = 1; attempt <= 5; attempt++) {
             await new Promise(resolve => setTimeout(resolve, 150 * attempt));
             const serverSnap = await getDocFromServer(userRef);
             if (serverSnap.exists() && serverSnap.data().role === 'admin') {
                 // Success! The server confirms the admin role. Return the fresh profile.
                 return serverSnap.data() as UserProfile;
             }
        }

        // If polling fails, log an error. The user will be treated as non-admin.
        console.error("Admin role update could not be confirmed on the server after several retries.");
    }

    return profile;
};


