export const createDocument = async (userId: string, title: string): Promise<string> => {
    const collectionRef = collection(db, 'users', userId, 'documents');
    const newDoc: Omit<LocalDocument, 'id'> = {
        title,
        content: `<h1>${title}</h1><p>Start writing here...</p>`,
        createdAt: Date.now(),
        updatedAt: Date.now(),
        metaTitle: '',
        metaDescription: '',
        targets: { primary: '', secondary: ['', '', ''] },
        faqs: [],
        targetDomain: '',
        isTrashed: false,
        goal: {
            wordCount: 1000,
            intent: 'General',
            audience: 'General',
            tone: 'Professional'
        }
    };
    const docRef = await addDoc(collectionRef, {
        ...newDoc,
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp()
    });
    return docRef.id;
};

export const getDocuments = (userId: string, callback: (docs: LocalDocument[]) => void) => {
    const collectionRef = collection(db, 'users', userId, 'documents');
    const q = query(collectionRef, orderBy('updatedAt', 'desc'));

    return onSnapshot(q, (querySnapshot) => {
        const documents = querySnapshot.docs.map(d => {
            const data = d.data();
            const createdAt = data.createdAt?.toMillis ? data.createdAt.toMillis() : data.createdAt;
            const updatedAt = data.updatedAt?.toMillis ? data.updatedAt.toMillis() : data.updatedAt;

            return {
                ...data,
                id: d.id,
                createdAt,
                updatedAt,
            } as LocalDocument;
        });
        callback(documents);
    });
};

export const getDocument = (userId: string, docId: string, callback: (doc: LocalDocument | null) => void) => {
    const docRef = doc(db, 'users', userId, 'documents', docId);
    return onSnapshot(docRef, (docSnap) => {
        if(docSnap.exists()) {
            const data = docSnap.data();
            const createdAt = data.createdAt?.toMillis ? data.createdAt.toMillis() : data.createdAt;
            const updatedAt = data.updatedAt?.toMillis ? data.updatedAt.toMillis() : data.updatedAt;

            callback({ 
                ...data,
                id: docSnap.id,
                createdAt,
                updatedAt,
            } as LocalDocument);
        } else {
            callback(null);
        }
    });
};

export const saveDocument = (userId: string, docId: string, data: Partial<LocalDocument>) => {
    const docRef = doc(db, 'users', userId, 'documents', docId);
    return updateDoc(docRef, { ...data, updatedAt: serverTimestamp() });
};

export const deleteDocument = (userId: string, docId: string) => {
