type UserWithDocCount = UserProfile & { docCount: number };
type SortKey = 'name' | 'email' | 'plan' | 'docCount' | 'aiUsage' | 'createdAt' | 'lastLogin' | 'status';

const ActionMenu = ({ user, onAction }: { user: UserWithDocCount, onAction: (action: string, userId: string, data?: any) => void }) => {
    const [isOpen, setIsOpen] = useState(false);
    const menuRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    const handleAction = (action: string, data?: any) => {
        onAction(action, user.uid, data);
        setIsOpen(false);
    };

    return (
        <div className="relative" ref={menuRef}>
            <button onClick={() => setIsOpen(!isOpen)} className="p-2 rounded-full hover:bg-zinc-200">
                <MoreVertical size={16} />
            </button>
            {isOpen && (
                <div className="absolute right-0 mt-2 w-48 bg-white border border-zinc-200 rounded-lg shadow-xl z-10 p-2">
                    <button onClick={() => handleAction('view')} className="w-full flex items-center gap-2 p-2 text-xs font-bold text-zinc-700 hover:bg-zinc-100 rounded-md"><Eye size={14}/> View Details</button>
                    <button onClick={() => handleAction('change_plan', user.plan === 'pro' ? 'free' : 'pro')} className="w-full flex items-center gap-2 p-2 text-xs font-bold text-zinc-700 hover:bg-zinc-100 rounded-md"><Edit size={14}/> Change Plan</button>
                    <button onClick={() => handleAction('reset_usage')} className="w-full flex items-center gap-2 p-2 text-xs font-bold text-zinc-700 hover:bg-zinc-100 rounded-md"><Zap size={14}/> Reset Usage</button>
                    <button onClick={() => handleAction('toggle_status')} className="w-full flex items-center gap-2 p-2 text-xs font-bold text-zinc-700 hover:bg-zinc-100 rounded-md">
                        {user.status === 'active' ? <><PowerOff size={14}/> Disable User</> : <><Power size={14}/> Enable User</>}
                    </button>
                    <div className="my-1 h-px bg-zinc-100"></div>
                    <button onClick={() => handleAction('delete')} className="w-full flex items-center gap-2 p-2 text-xs font-bold text-red-600 hover:bg-red-50 rounded-md"><Trash2 size={14}/> Delete User</button>
                </div>
            )}
        </div>
    );
};


export default function UsersTab() {
    const [users, setUsers] = useState<UserWithDocCount[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [sortKey, setSortKey] = useState<SortKey>('createdAt');
    const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');
    const [selectedUser, setSelectedUser] = useState<UserWithDocCount | null>(null);

    useEffect(() => {
        const unsubscribe = adminService.listenToUsers(
            (newUsers) => {
                setUsers(newUsers);
                setLoading(false);
            },
            (err) => {
                setError("Failed to listen to user data. Check Firestore rules.");
                setLoading(false);
            }
        );
        return () => unsubscribe();
    }, []);

    const handleAction = async (action: string, userId: string, data?: any) => {
        try {
            switch(action) {
                case 'view':
                    setSelectedUser(users.find(u => u.uid === userId) || null);
                    break;
                case 'change_plan':
                    await adminService.updateUserPlan(userId, data);
                    break;
                case 'reset_usage':
                    await adminService.resetUserUsage(userId);
                    break;
                case 'toggle_status':
                    const user = users.find(u => u.uid === userId);
                    if (user) {
                        await adminService.updateUserStatus(userId, user.status === 'active' ? 'disabled' : 'active');
                    }
                    break;
                case 'delete':
                     if (window.confirm("Are you sure? This will delete the user and all their documents permanently.")) {
                        await adminService.deleteUserAndData(userId);
                     }
                    break;
            }
        } catch (err) {
            console.error(`Action ${action} failed for user ${userId}`, err);
            alert(`Could not perform action. See console for details.`);
        }
    };

    const Th = ({ children, sortableKey }: { children: React.ReactNode; sortableKey: SortKey; }) => (
        <th className="px-6 py-3 text-left text-xs font-medium text-zinc-500 uppercase tracking-wider">
            <button onClick={() => {
                 setSortKey(sortableKey);
                 setSortOrder(sortKey === sortableKey && sortOrder === 'desc' ? 'asc' : 'desc');
            }} className="flex items-center gap-2 group">
                {children}
                <ArrowUpDown size={12} className="text-zinc-400 group-hover:text-zinc-800" />
            </button>
        </th>
    );

    const sortedUsers = useMemo(() => {
        // ... sorting logic ...
        return [...users].sort((a, b) => {
             const valA = a[sortKey];
             const valB = b[sortKey];
             if (valA === undefined || valA === null) return 1;
             if (valB === undefined || valB === null) return -1;
             let comparison = 0;
             if (typeof valA === 'string' && typeof valB === 'string') {
                 comparison = valA.localeCompare(valB);
             } else if (typeof valA === 'number' && typeof valB === 'number') {
                 comparison = valA - valB;
             } else if (valA.toMillis && valB.toMillis) {
                 comparison = valA.toMillis() - valB.toMillis();
             }
             return sortOrder === 'asc' ? comparison : -comparison;
        });
    }, [users, sortKey, sortOrder]);

    const formatDate = (ts: any) => ts?.toDate ? ts.toDate().toLocaleDateString() : 'N/A';

    if (loading) return <div className="flex justify-center items-center h-full"><Loader className="animate-spin text-blue-500" /></div>;
    if (error) return <div className="text-red-500 p-4 bg-red-50 rounded-lg">{error}</div>;

    return (
        <div className="space-y-8 animate-in fade-in duration-300">
            <h2 className="text-xl font-bold text-zinc-800">User Management</h2>
            <div className="bg-white border border-zinc-200 rounded-2xl shadow-sm overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="min-w-full divide-y divide-zinc-200">
                        <thead className="bg-zinc-50">
                            <tr>
                                <Th sortableKey="name">Name</Th>
                                <Th sortableKey="email">Email</Th>
                                <Th sortableKey="plan">Plan</Th>
                                <Th sortableKey="docCount">Docs</Th>
                                <Th sortableKey="aiUsage">AI Usage</Th>
                                <Th sortableKey="createdAt">Created</Th>
                                <Th sortableKey="lastLogin">Last Login</Th>
                                <Th sortableKey="status">Status</Th>
                                <th className="px-6 py-3 text-right text-xs font-medium text-zinc-500 uppercase tracking-wider">Actions</th>
                            </tr>
                        </thead>
                         <tbody className="bg-white divide-y divide-zinc-200">
                            {sortedUsers.map(user => (
                                <tr key={user.uid} className="hover:bg-zinc-50">
                                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-zinc-900">{user.name}</td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-zinc-500">{user.email}</td>
                                    <td className="px-6 py-4 whitespace-nowrap"><span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${user.plan === 'pro' ? 'bg-green-100 text-green-800' : 'bg-zinc-100 text-zinc-800'}`}>{user.plan}</span></td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-zinc-500 text-center">{user.docCount}</td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-zinc-500 text-center">{user.aiUsage}</td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-zinc-500">{formatDate(user.createdAt)}</td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-zinc-500">{formatDate(user.lastLogin)}</td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm"><span className={`flex items-center gap-1.5 text-xs font-semibold ${user.status === 'active' ? 'text-green-800' : 'text-zinc-500'}`}><CheckCircle size={12}/>{user.status}</span></td>
                                    <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium"><ActionMenu user={user} onAction={handleAction} /></td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
             {selectedUser && <UserDetailModal user={selectedUser} onClose={() => setSelectedUser(null)} />}
        </div>
    );
}

