// --- Overview Stats ---
export interface OverviewStats {
    totalUsers: number;
    newUsersToday: number;
    newUsersThisWeek: number;
    activeUsers7d: number;
    activeUsers30d: number;
    totalDocuments: number;
    documentsCreatedToday: number;
    totalAIRequests: number;
    avgDocsPerUser: number;
}

export const getOverviewStats = async (): Promise<OverviewStats> => {
    const usersCollection = collection(db, 'users');
    const docsCollectionGroup = collectionGroup(db, 'documents');

    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const todayTimestamp = Timestamp.fromDate(today);

    const sevenDaysAgo = new Date(today);
    sevenDaysAgo.setDate(today.getDate() - 7);
    const sevenDaysAgoTimestamp = Timestamp.fromDate(sevenDaysAgo);

    const thirtyDaysAgo = new Date(today);
    thirtyDaysAgo.setDate(today.getDate() - 30);
    const thirtyDaysAgoTimestamp = Timestamp.fromDate(thirtyDaysAgo);

    // User counts
    const totalUsersSnap = await getCountFromServer(usersCollection);
    const newUsersTodaySnap = await getCountFromServer(query(usersCollection, where('createdAt', '>=', todayTimestamp)));
    const newUsersThisWeekSnap = await getCountFromServer(query(usersCollection, where('createdAt', '>=', sevenDaysAgoTimestamp)));
    const activeUsers7dSnap = await getCountFromServer(query(usersCollection, where('lastLogin', '>=', sevenDaysAgoTimestamp)));
    const activeUsers30dSnap = await getCountFromServer(query(usersCollection, where('lastLogin', '>=', thirtyDaysAgoTimestamp)));

    // Document counts
    const totalDocsSnap = await getCountFromServer(docsCollectionGroup);

    // To avoid a collection group index, we'll iterate through users.
    // This is less performant at scale but works without manual index creation.
    let documentsCreatedTodayCount = 0;
    const usersSnap = await getDocs(query(usersCollection));
    for (const userDoc of usersSnap.docs) {
        const userDocsCollection = collection(db, 'users', userDoc.id, 'documents');
        const docsTodayQuery = query(userDocsCollection, where('createdAt', '>=', todayTimestamp));
        const countSnap = await getCountFromServer(docsTodayQuery);
        documentsCreatedTodayCount += countSnap.data().count;
    }

    // AI Requests (from analytics collection)
    const dailyAnalyticsCollection = collection(db, 'analytics', 'summary', 'daily');
    const aiRequestsSnap = await getDocs(dailyAnalyticsCollection);
    const totalAIRequests = aiRequestsSnap.docs.reduce((sum, doc) => sum + (doc.data().aiRequests || 0), 0);

    const totalUsers = totalUsersSnap.data().count;
    const totalDocuments = totalDocsSnap.data().count;

    return {
        totalUsers,
        newUsersToday: newUsersTodaySnap.data().count,
        newUsersThisWeek: newUsersThisWeekSnap.data().count,
        activeUsers7d: activeUsers7dSnap.data().count,
        activeUsers30d: activeUsers30dSnap.data().count,
        totalDocuments,
        documentsCreatedToday: documentsCreatedTodayCount,
        totalAIRequests,
        avgDocsPerUser: totalUsers > 0 ? parseFloat((totalDocuments / totalUsers).toFixed(2)) : 0,
    };
};


// --- Users Management ---
export type UserWithDocCount = UserProfile & { docCount: number };

export const listenToUsers = (
    onNext: (users: UserWithDocCount[]) => void,
    onError: (error: FirestoreError) => void
) => {
    const usersCollection = collection(db, 'users');
    const q = query(usersCollection, orderBy('createdAt', 'desc'));

    return onSnapshot(q, async (querySnapshot) => {
        const usersData = await Promise.all(querySnapshot.docs.map(async (userDoc) => {
            const user = userDoc.data() as UserProfile;
            const documentsCollection = collection(db, 'users', user.uid, 'documents');
            const docCountSnapshot = await getCountFromServer(documentsCollection);
            return {
                ...user,
                docCount: docCountSnapshot.data().count,
            };
        }));
        onNext(usersData);
    }, (error) => {
        console.error("User snapshot listener error:", error);
        onError(error);
    });
};

export const updateUserPlan = (userId: string, plan: 'free' | 'pro') => {
    return updateDoc(doc(db, 'users', userId), { plan });
};

export const updateUserStatus = (userId: string, status: 'active' | 'disabled') => {
    return updateDoc(doc(db, 'users', userId), { status });
};

export const resetUserUsage = (userId: string) => {
    return updateDoc(doc(db, 'users', userId), { aiUsage: 0 });
};

export const deleteUserAndData = async (userId: string) => {
    // Note: This deletes Firestore data, but not the Firebase Auth user.
    // That should be handled with a Cloud Function for security.
    const userRef = doc(db, 'users', userId);
    const docsCollection = collection(db, 'users', userId, 'documents');

    const batch = writeBatch(db);

    // Delete all documents
    const docsSnap = await getDocs(docsCollection);
    docsSnap.forEach(doc => batch.delete(doc.ref));

    // Delete user profile
    batch.delete(userRef);

    return batch.commit();
};

export const getUserDocuments = async (userId: string): Promise<LocalDocument[]> => {
    const documentsCollection = collection(db, 'users', userId, 'documents');
    const q = query(documentsCollection, orderBy('updatedAt', 'desc'), limit(50));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(d => ({ id: d.id, ...d.data() } as LocalDocument));
};


// --- Usage Analytics ---
export interface DailyUsage {
    date: string; // YYYY-MM-DD
    aiRequests: number;
}

export const getUsageAnalytics = async (days: number = 30): Promise<DailyUsage[]> => {
    const analyticsCollection = collection(db, 'analytics', 'summary', 'daily');

    const endDate = new Date();
    const startDate = new Date();
    startDate.setDate(endDate.getDate() - days);

    const dailyData: Record<string, DailyUsage> = {};

    // Initialize date range
    for (let d = new Date(startDate); d <= endDate; d.setDate(d.getDate() + 1)) {
        const dateStr = d.toISOString().split('T')[0];
        dailyData[dateStr] = { date: dateStr, aiRequests: 0 };
    }

    const q = query(analyticsCollection, where('date', '>=', startDate.toISOString().split('T')[0]));
    const snapshot = await getDocs(q);
    snapshot.forEach(doc => {
        const data = doc.data();
        if (dailyData[data.date]) {
            dailyData[data.date].aiRequests = data.aiRequests || 0;
        }
    });

    return Object.values(dailyData).sort((a,b) => a.date.localeCompare(b.date));
};

export const getTopUsersByUsage = async (count: number = 10): Promise<UserProfile[]> => {
    const q = query(collection(db, 'users'), orderBy('aiUsage', 'desc'), limit(count));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(doc => doc.data() as UserProfile);
};


