import { doc, getDoc, updateDoc } from 'firebase/firestore';
import  { db } from '../lib/firebase';
import { UserProfile } from './firestore';
import { getPlanById } from  './planService';

const getCurrentUsageMonth = (): string => {
    const now = new Date();
    return `${ now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
};

export const checkAndResetUsage = async (user: UserProfile): Promise<UserProfile> => {
    const currentMonth = getCurrentUsageMonth();
    const usage = user.usage || { aiUsed: 0, usageMonth: currentMonth };

    if (usage.usageMonth !== currentMonth) {
        const updatedUsage = { aiUsed: 0, usageMonth: currentMonth };
        const userRef = doc(db, 'users', user.uid);
        await updateDoc(userRef, { usage: updatedUsage });
        return { ...user, usage: updatedUsage };
    }
