    onSnapshot,
    query,
    orderBy,
    deleteDoc,
    Timestamp,
    updateDoc,
    writeBatch,
    getDocFromServer
} from 'firebase/firestore';
import { User as FirebaseUser } from 'firebase/auth';
import { db } from '../lib/firebase';
import { LocalDocument } from '../types/document.types';
