                setStats(data);
            } catch (err) {
                console.error(err);
                setError("Failed to load overview statistics. This might be due to Firestore permissions or missing indexes.");
            } finally {
                setLoading(false);
            }
        };

        fetchStats();
    }, []);

    if (error) {
        return <div className="text-red-500 p-4 bg-red-50 rounded-lg">{error}</div>;
    }

    return (
        <div className="space-y-8 animate-in fade-in duration-300">
            <h2 className="text-xl font-bold text-zinc-800">Platform Overview</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <MetricCard title="Total Users" value={stats?.totalUsers ?? 0} icon={<Users size={24} />} isLoading={loading} />
                <MetricCard title="Active Users (30d)" value={stats?.activeUsers30d ?? 0} icon={<Zap size={24} />} isLoading={loading} />
                <MetricCard title="Total Documents" value={stats?.totalDocuments ?? 0} icon={<FileStack size={24} />} isLoading={loading} />
                <MetricCard title="Total AI Requests" value={stats?.totalAIRequests ?? 0} icon={<Bot size={24} />} isLoading={loading} />

                <MetricCard title="Free Users" value={stats?.planDistribution.free ?? 0} icon={<Shield size={24} />} isLoading={loading} />
                <MetricCard title="Pro Users" value={stats?.planDistribution.pro ?? 0} icon={<Star size={24} />} isLoading={loading} />
                <MetricCard title="Ultimate Users" value={stats?.planDistribution.ultimate ?? 0} icon={<Gem size={24} />} isLoading={loading} />
                <MetricCard title="New Users (Week)" value={stats?.newUsersThisWeek ?? 0} icon={<UserPlus size={24} />} isLoading={loading} />
            </div>
        </div>
    );
}

