const DailyChart = ({ data, isLoading }: { data: adminService.DailyUsage[], isLoading: boolean }) => {
    if (isLoading) {
        return <div className="bg-white p-6 rounded-2xl border border-zinc-200 shadow-sm h-80 animate-pulse"></div>;
