export default function UsageTab() {
    const [dailyUsage, setDailyUsage] = useState<adminService.DailyUsage[]>([]);
    const [topUsers, setTopUsers] = useState<UserProfile[]>([]);
    const [totalRequestsMonth, setTotalRequestsMonth] = useState(0);
    const [requestsToday, setRequestsToday] = useState(0);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        const fetchData = async () => {
            try {
                setLoading(true);
                const [usageData, topUsersData] = await Promise.all([
                    adminService.getUsageAnalytics(30),
                    adminService.getTopUsersByUsage(10)
                ]);

                setDailyUsage(usageData);
                setTopUsers(topUsersData);

                const total = usageData.reduce((sum, day) => sum + day.aiRequests, 0);
                const todayStr = new Date().toISOString().split('T')[0];
                const todayData = usageData.find(d => d.date === todayStr);

                setTotalRequestsMonth(total);
                setRequestsToday(todayData?.aiRequests || 0);

            } catch (err) {
                console.error(err);
                setError("Failed to load usage analytics.");
            } finally {
                setLoading(false);
            }
        };

        fetchData();
    }, []);

    if (error) return <div className="text-red-500 p-4 bg-red-50 rounded-lg">{error}</div>;

    return (
        <div className="space-y-8 animate-in fade-in duration-300">
            <h2 className="text-xl font-bold text-zinc-800">Usage Analytics</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <MetricCard title="AI Requests (Month)" value={totalRequestsMonth} isLoading={loading} />
                <MetricCard title="AI Requests (Today)" value={requestsToday} isLoading={loading} />
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                <DailyChart data={dailyUsage} isLoading={loading} />
                <TopUsersList users={topUsers} isLoading={loading} />
            </div>
        </div>
    );
}

