type UserWithDocCount = UserProfile & { docCount: number };

interface UserDetailModalProps {
    user: UserWithDocCount;
    onClose: () => void;
    onAction: (action: string, userId: string, data?: any) => void;
}

const ActionButton = ({ onClick, children, className }: { onClick: () => void, children: React.ReactNode, className?: string }) => (
    <button
        onClick={onClick}
        className={`flex items-center justify-center gap-2 px-3 py-2 text-xs font-bold rounded-md transition-colors ${className}`}
    >
        {children}
    </button>
);


export const UserDetailModal: React.FC<UserDetailModalProps> = ({ user, onClose, onAction }) => {
    const [documents, setDocuments] = useState<LocalDocument[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchDocs = async () => {
            setLoading(true);
            try {
                const userDocs = await adminService.getUserDocuments(user.uid);
                setDocuments(userDocs);
            } catch (error) {
                console.error("Failed to fetch user documents:", error);
            } finally {
                setLoading(false);
            }
        };

        fetchDocs();
    }, [user.uid]);

    const formatDate = (timestamp: any) => {
        if (!timestamp?.toDate) return 'N/A';
        return timestamp.toDate().toLocaleString();
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-in fade-in duration-300">
            <div className="bg-white rounded-2xl w-full max-w-2xl shadow-xl border border-zinc-200 flex flex-col max-h-[90vh] animate-in zoom-in-95 duration-200">
                <header className="p-6 border-b border-zinc-200 flex items-center justify-between shrink-0">
                    <h2 className="text-lg font-bold text-zinc-900">User Details</h2>
                    <button onClick={onClose} className="p-1 rounded-full text-zinc-400 hover:bg-zinc-100">
                        <X size={20} />
                    </button>
                </header>

                <main className="p-6 flex-1 overflow-y-auto space-y-6">
                    {/* User Info Section */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="bg-zinc-50 p-4 rounded-xl border border-zinc-200 space-y-3">
                            <div className="flex items-center gap-3">
                                <User size={16} className="text-zinc-500"/>
                                <span className="text-sm font-semibold text-zinc-800">{user.name}</span>
                            </div>
                            <p className="text-xs text-zinc-500 truncate">{user.email}</p>
                            <p className="text-xs font-bold uppercase tracking-wider">
                                <span className={`px-2 py-1 rounded-full capitalize ${user.plan === 'pro' || user.plan === 'ultimate' ? 'bg-green-100 text-green-800' : 'bg-zinc-200 text-zinc-800'}`}>
