                            <div className="flex items-center gap-3">
                                <Zap size={14} className="text-zinc-500"/>
                                <span className="font-semibold text-zinc-800">Last Login:</span>
                                <span className="text-zinc-600">{formatDate(user.lastLogin)}</span>
                            </div>
                             <div className="flex items-center gap-3">
                                <FileText size={14} className="text-zinc-500"/>
                                <span className="font-semibold text-zinc-800">Documents:</span>
                                <span className="text-zinc-600">{user.docCount}</span>
                            </div>
                        </div>
                    </div>

                    {/* Documents List */}
                    <div>
                        <h3 className="text-sm font-bold text-zinc-600 mb-4">Documents ({documents.length})</h3>
                        <div className="border border-zinc-200 rounded-xl max-h-60 overflow-y-auto">
                           {loading ? (
                                <div className="p-8 flex items-center justify-center"><Loader className="animate-spin text-blue-500"/></div>
                           ) : documents.length > 0 ? (
                               <ul className="divide-y divide-zinc-200">
                                   {documents.map(doc => (
                                       <li key={doc.id} className="p-4 flex items-center justify-between text-sm">
                                           <span className="font-medium text-zinc-800 truncate pr-4">{doc.title}</span>
                                           <span className="text-xs text-zinc-400 shrink-0">
                                               Updated: {doc.updatedAt && new Date(doc.updatedAt).toLocaleDateString()}
