                           ) : (
                               <p className="p-8 text-center text-sm text-zinc-500">No documents found for this user.</p>
                           )}
                        </div>
                    </div>
                </main>

                 <footer className="p-4 bg-zinc-50 border-t border-zinc-200 flex flex-wrap items-center justify-between gap-2">
                    <div className="flex flex-wrap gap-2">
                         <select 
                            value={user.plan}
                            onChange={(e) => onAction('change_plan', user.uid, e.target.value)}
                            className="bg-white border border-zinc-300 rounded-md p-2 text-xs font-bold"
                         >
                             <option value="free">Free</option>
                             <option value="pro">Pro</option>
                             <option value="ultimate">Ultimate</option>
