import { collection, getDocs, query, where, orderBy, addDoc, updateDoc, deleteDoc, doc, serverTimestamp, onSnapshot } from 'firebase/firestore';
import { db } from '../lib/firebase';
import { AIProvider } from '../types/ai.types.ts';

const providersCollection = collection(db, 'ai_providers');

// For Admin Panel (real-time updates)
export const listenToAIProviders = (callback: (providers: AIProvider[]) => void) => {
    const q = query(providersCollection, orderBy('priority', 'asc'));
    return onSnapshot(q, (snapshot) => {
        const providers = snapshot.docs.map(d => ({ id: d.id, ...d.data() } as AIProvider));
        callback(providers);
    });
};

export const addAIProvider = (provider: Omit<AIProvider, 'id' | 'createdAt'>) => {
    return addDoc(providersCollection, { ...provider, createdAt: serverTimestamp() });
};

export const updateAIProvider = (id: string, updates: Partial<AIProvider>) => {
    const { id: providerId, ...rest } = updates;
    return updateDoc(doc(db, 'ai_providers', id), rest);
};

export const deleteAIProvider = (id: string) => {
    return deleteDoc(doc(db, 'ai_providers', id));
};

// For AI Gateway (one-time fetch)
export const getActiveAIProviders = async (): Promise<AIProvider[]> => {
    const q = query(providersCollection, where('isActive', '==', true), orderBy('priority', 'asc'));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(d => ({ id: d.id, ...d.data() } as AIProvider));
};

import { getActiveAIProviders } from './aiProviderService.ts';
import * as gemini from './providers/gemini.ts';
import * as openai from './providers/openai.ts';
import * as custom from './providers/custom.ts';
import { ProviderResponse } from './providers/gemini.ts';

export const generateContent = async (prompt: string, config: any = {}): Promise<ProviderResponse> => {
    console.log('[AIGateway] Initiating content generation...');

    let activeProviders;
    try {
        activeProviders = await getActiveAIProviders();
    } catch (e: any) {
        console.error('[AIGateway] Failed to fetch AI providers from Firestore:', e);
        return { success: false, content: '', error: 'Could not fetch AI provider configuration.' };
    }

    if (activeProviders.length === 0) {
        console.warn('[AIGateway] No active AI providers configured.');
        return { success: false, content: '', error: 'No active AI providers are configured.' };
    }

    console.log(`[AIGateway] Found ${activeProviders.length} active providers. Trying in order of priority.`);

    for (const provider of activeProviders) {
        console.log(`[AIGateway] Attempting provider: ${provider.name} (Priority: ${provider.priority})`);
        let result: ProviderResponse;

        switch (provider.provider) {
            case 'gemini':
                result = await gemini.generate(provider.apiKey, provider.model, prompt, config);
                break;
            case 'openai':
                result = await openai.generate(provider.apiKey, provider.model, prompt, config);
                 break;
            case 'custom':
                result = await custom.generate(provider.apiKey, provider.model, prompt, config);
                break;
            default:
                console.warn(`[AIGateway] Provider type "${provider.provider}" is not supported. Skipping.`);
                continue;
        }

        if (result.success) {
            console.log(`[AIGateway] Success with provider: ${provider.name}`);
            return result;
        } else {
            console.warn(`[AIGateway] Provider ${provider.name} failed. Reason: ${result.error}. Trying next provider...`);
        }
    }

    console.error('[AIGateway] All AI providers failed.');
    return { success: false, content: '', error: 'All available AI providers failed to generate a response.' };
};

import { GoogleGenAI } from "@google/genai";

export interface ProviderResponse {
    success: boolean;
    content: string;
    error?: string;
}

export const generate = async (apiKey: string, model: string, prompt: string, config: any = {}): Promise<ProviderResponse> => {
    try {
        if (!apiKey) {
             return { success: false, content: '', error: 'API Key is missing for Gemini provider.' };
        }
        const ai = new GoogleGenAI({ apiKey });
        const response = await ai.models.generateContent({
            model: model,
            contents: prompt,
            config: config
        });

        const content = response.text;
        if (content) {
            return { success: true, content };
        } else {
            // Check for safety ratings or other block reasons
            const blockReason = response.candidates?.[0]?.finishReason;
            const safetyRatings = response.candidates?.[0]?.safetyRatings;
            if (blockReason) {
                 return { success: false, content: '', error: `Gemini request blocked. Reason: ${blockReason}. Safety: ${JSON.stringify(safetyRatings)}` };
            }
            return { success: false, content: '', error: 'Empty response from Gemini.' };
        }
    } catch (e: any) {
        console.error("Gemini Provider Error:", e);
        return { success: false, content: '', error: e.message };
    }
};

