import { collection, getDocs, query, where, orderBy, addDoc, updateDoc, deleteDoc, doc, serverTimestamp, onSnapshot, FirestoreError } from 'firebase/firestore';
import { db } from '../lib/firebase';
import { AIProvider } from '../types/ai.types.ts';

const providersCollection = collection(db, 'ai_providers');

// For Admin Panel (real-time updates)
// FIX: Added onError callback to handle potential Firestore errors during snapshot listening.
export const listenToAIProviders = (onNext: (providers: AIProvider[]) => void, onError: (error: FirestoreError) => void) => {
    const q = query(providersCollection, orderBy('priority', 'asc'));
    return onSnapshot(q, (snapshot) => {
        const providers = snapshot.docs.map(d => ({ id: d.id, ...d.data() } as AIProvider));
        onNext(providers);
    }, onError);
};

export const addAIProvider = (provider: Omit<AIProvider, 'id' | 'createdAt'>) => {
    return addDoc(providersCollection, { ...provider, createdAt: serverTimestamp() });
};

export const updateAIProvider = (id: string, updates: Partial<AIProvider>) => {
    const { id: providerId, ...rest } = updates;
    return updateDoc(doc(db, 'ai_providers', id), rest);
};

export const deleteAIProvider = (id: string) => {
    return deleteDoc(doc(db, 'ai_providers', id));
};

// For AI Gateway (one-time fetch)
export const getActiveAIProviders = async (): Promise<AIProvider[]> => {
    const q = query(providersCollection, where('isActive', '==', true), orderBy('priority', 'asc'));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(d => ({ id: d.id, ...d.data() } as AIProvider));
};

import { Timestamp } from 'firebase/firestore';

export type AIProviderType = 'gemini' | 'openai' | 'custom';

export interface AIProvider {
    id: string;
    provider: AIProviderType;
    apiKey: string;
    model: string;
    invokeUrl?: string; // For custom providers
    isActive: boolean;
    priority: number;
    createdAt?: Timestamp;
    name: string;
}

import { getActiveAIProviders } from './aiProviderService.ts';
import { AIProvider } from '../types/ai.types';
import * as gemini from './providers/gemini.ts';
import * as openai from './providers/openai.ts';
import * as custom from './providers/custom.ts';
import { ProviderResponse } from './providers/gemini.ts';

export const generateContent = async (prompt: string, config: any = {}): Promise<ProviderResponse> => {
    console.log('[AIGateway] Initiating content generation...');

    let activeProviders: AIProvider[];
    try {
        activeProviders = await getActiveAIProviders();
    } catch (e: any) {
        console.error('[AIGateway] Failed to fetch AI providers from Firestore:', e);
        return { success: false, content: '', error: 'Could not fetch AI provider configuration.' };
    }

    if (activeProviders.length === 0) {
        console.warn('[AIGateway] No active AI providers configured.');
        return { success: false, content: '', error: 'No active AI providers are configured.' };
    }

    console.log(`[AIGateway] Found ${activeProviders.length} active providers. Trying in order of priority.`);

    for (const provider of activeProviders) {
        console.log(`[AIGateway] Attempting provider: ${provider.name} (Priority: ${provider.priority})`);
        let result: ProviderResponse;

        switch (provider.provider) {
            case 'gemini':
                result = await gemini.generate(provider, prompt, config);
                break;
            case 'openai':
                result = await openai.generate(provider, prompt, config);
                 break;
            case 'custom':
                result = await custom.generate(provider, prompt, config);
                break;
            default:
                console.warn(`[AIGateway] Provider type "${provider.provider}" is not supported. Skipping.`);
                continue;
        }

        if (result.success) {
            console.log(`[AIGateway] Success with provider: ${provider.name}`);
            return result;
        } else {
            console.warn(`[AIGateway] Provider ${provider.name} failed. Reason: ${result.error}. Trying next provider...`);
        }
    }

    console.error('[AIGateway] All AI providers failed.');
    return { success: false, content: '', error: 'All available AI providers failed to generate a response.' };
};

import { GoogleGenAI } from "@google/genai";
import { AIProvider } from "../../types/ai.types";

export interface ProviderResponse {
    success: boolean;
    content: string;
    error?: string;
}

export const generate = async (provider: AIProvider, prompt: string, config: any = {}): Promise<ProviderResponse> => {
    const { apiKey, model } = provider;
    try {
        if (!apiKey) {
             return { success: false, content: '', error: 'API Key is missing for Gemini provider.' };
        }
        const ai = new GoogleGenAI({ apiKey });
        const response = await ai.models.generateContent({
            model: model,
            contents: prompt,
            config: config
        });

        const content = response.text;
        if (content) {
            return { success: true, content };
        } else {
            // Check for safety ratings or other block reasons
            const blockReason = response.candidates?.[0]?.finishReason;
            const safetyRatings = response.candidates?.[0]?.safetyRatings;
            if (blockReason) {
                 return { success: false, content: '', error: `Gemini request blocked. Reason: ${blockReason}. Safety: ${JSON.stringify(safetyRatings)}` };
            }
            return { success: false, content: '', error: 'Empty response from Gemini.' };
        }
    } catch (e: any)
        console.error("Gemini Provider Error:", e);
        // Handle specific Gemini errors if needed, e.g. 429
        const errorMessage = e.message || 'An unknown error occurred with the Gemini provider.';
        return { success: false, content: '', error: errorMessage };
    }
};

import { ProviderResponse } from './gemini';
import { AIProvider } from '../../types/ai.types';

export const generate = async (provider: AIProvider, prompt: string, config: any = {}): Promise<ProviderResponse> => {
    const { apiKey, model } = provider;
    try {
        if (!apiKey) {
            return { success: false, content: '', error: 'API Key is missing for OpenAI provider.' };
        }

        const body: any = {
            model: model,
            messages: [{ role: 'user', content: prompt }],
            temperature: config.temperature || 0.7,
        };

        // Adapt Gemini's JSON mode for OpenAI
        if (config.responseMimeType === 'application/json') {
            body.response_format = { type: 'json_object' };
        }

        const response = await fetch('https://api.openai.com/v1/chat/completions', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${apiKey}`
            },
            body: JSON.stringify(body)
        });

        if (!response.ok) {
            const errorData = await response.json();
            const errorMessage = errorData.error?.message || `HTTP error! status: ${response.status}`;
            // For failover, specifically check for rate limit or quota errors
            if (response.status === 429) {
                return { success: false, content: '', error: `OpenAI Rate Limit/Quota Exceeded: ${errorMessage}` };
            }
            throw new Error(`OpenAI API error: ${errorMessage}`);
        }

        const data = await response.json();
        let content = data.choices[0]?.message?.content;

        if (content) {
            // If JSON mode was requested, the content is a stringified JSON.
            // No need to parse it here; the caller (ai-engine) will parse.
            return { success: true, content };
        } else {
            return { success: false, content: '', error: 'Empty response from OpenAI.' };
        }
    } catch (e: any) {
        console.error("OpenAI Provider Error:", e);
        return { success: false, content: '', error: e.message };
    }
};

import { ProviderResponse } from './gemini';
import { AIProvider } from '../../types/ai.types';

export const generate = async (provider: AIProvider, prompt: string, config: any = {}): Promise<ProviderResponse> => {
    const { apiKey, model, invokeUrl } = provider;

    if (!invokeUrl) {
        return { success: false, content: '', error: 'Invoke URL is missing for custom provider.' };
    }

    try {
        const response = await fetch(invokeUrl, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${apiKey}`
            },
            body: JSON.stringify({
                prompt,
                model,
                ...config
            })
        });

        if (!response.ok) {
            // For failover, check for common server error codes
            if (response.status === 429 || response.status >= 500) {
                 return { success: false, content: '', error: `Custom API request failed with status: ${response.status}` };
            }
            throw new Error(`Custom API error: ${response.status} ${response.statusText}`);
        }

        const data = await response.json();
        // Assuming the custom API returns { content: "..." }
        const content = data.content;

        if (content) {
            return { success: true, content };
        }
        return { success: false, content: '', error: 'Empty or invalid response from custom endpoint. Expected { "content": "..." }.' };

    } catch (e: any) {
        console.error("Custom Provider Error:", e);
        return { success: false, content: '', error: e.message };
    }
};

