export default function AIProvidersTab() {
    const [providers, setProviders] = useState<AIProvider[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [editingProvider, setEditingProvider] = useState<Partial<AIProvider> | null>(null);

    useEffect(() => {
        const unsubscribe = aiProviderService.listenToAIProviders(
            (newProviders) => {
                setProviders(newProviders);
                setLoading(false);
            },
            (err) => {
                setError("Failed to listen to provider data. Check Firestore rules.");
                setLoading(false);
            }
        );
        return () => unsubscribe();
    }, []);

    const handleSave = async (provider: Partial<AIProvider>) => {
        try {
            if (provider.id) {
                await aiProviderService.updateAIProvider(provider.id, provider);
            } else {
                await aiProviderService.addAIProvider(provider as Omit<AIProvider, 'id'>);
            }
        } catch(e) {
            console.error(e);
            alert('Failed to save provider.');
        }
        setEditingProvider(null);
    };

    const handleDelete = async (id: string) => {
        if (window.confirm('Are you sure you want to delete this provider?')) {
            await aiProviderService.deleteAIProvider(id);
        }
    };

    const handleToggleActive = async (provider: AIProvider) => {
        await aiProviderService.updateAIProvider(provider.id, { isActive: !provider.isActive });
    };

    if (loading) return <div className="flex justify-center items-center h-full"><Loader className="animate-spin text-blue-500" /></div>;
    if (error) return <div className="text-red-500 p-4 bg-red-50 rounded-lg">{error}</div>;

    return (
        <div className="space-y-8 animate-in fade-in duration-300">
             <div className="flex items-center justify-between">
