            <div className="p-4 bg-yellow-50 border border-yellow-200 rounded-lg text-sm text-yellow-800 font-medium flex items-start gap-3">
                <AlertTriangle className="flex-shrink-0 mt-0.5"/>
                <div><strong>Security Warning:</strong> API keys are stored in Firestore. Ensure your Firestore Security Rules strictly limit read/write access to this collection to admins only.</div>
            </div>

            <div className="bg-white border border-zinc-200 rounded-2xl shadow-sm overflow-hidden">
                {providers.length === 0 && (
                    <p className="text-center text-sm text-zinc-500 p-8">No AI providers configured. Add one to enable AI features.</p>
                )}
                {providers.map(p => (
                    <div key={p.id} className="flex items-center justify-between p-4 border-b border-zinc-100 last:border-0">
                        <div className="flex items-center gap-4">
                             <span className="font-mono text-xs bg-zinc-100 text-zinc-500 font-bold p-2 rounded-md">{p.priority}</span>
                             <div>
                                <p className="font-bold text-zinc-800">{p.name}</p>
                                <p className="text-xs text-zinc-500 capitalize">{p.provider} ({p.model})</p>
                                {p.provider === 'custom' && <p className="text-xs text-zinc-400 truncate max-w-xs">@ {p.invokeUrl}</p>}
                             </div>
                        </div>
                        <div className="flex items-center gap-4">
                            <button onClick={() => handleToggleActive(p)} title={p.isActive ? 'Deactivate' : 'Activate'}>
                                {p.isActive ? <ToggleRight size={24} className="text-green-500"/> : <ToggleLeft size={24} className="text-zinc-400"/>}
                            </button>
                             <button onClick={() => setEditingProvider(p)} className="p-2 text-zinc-500 hover:text-blue-600"><Edit size={16}/></button>
                             <button onClick={() => handleDelete(p.id)} className="p-2 text-zinc-500 hover:text-red-600"><Trash2 size={16}/></button>
                        </div>
                    </div>
                ))}
            </div>

            {editingProvider && <ProviderModal provider={editingProvider} onClose={() => setEditingProvider(null)} onSave={handleSave} />}
        </div>
    );
}

import { GoogleGenAI } from "@google/genai";
import { AIProvider } from "../../types/ai.types";

export interface ProviderResponse {
    success: boolean;
    content: string;
    error?: string;
}

export const generate = async (provider: AIProvider, prompt: string, config: any = {}): Promise<ProviderResponse> => {
    const { apiKey, model } = provider;
    try {
        if (!apiKey) {
             return { success: false, content: '', error: 'API Key is missing for Gemini provider.' };
        }
        const ai = new GoogleGenAI({ apiKey });
        const response = await ai.models.generateContent({
            model: model,
            contents: prompt,
            config: config
        });

        const content = response.text;
        if (content) {
            return { success: true, content };
        } else {
            // Check for safety ratings or other block reasons
            const blockReason = response.candidates?.[0]?.finishReason;
            const safetyRatings = response.candidates?.[0]?.safetyRatings;
            if (blockReason) {
                 return { success: false, content: '', error: `Gemini request blocked. Reason: ${blockReason}. Safety: ${JSON.stringify(safetyRatings)}` };
            }
            return { success: false, content: '', error: 'Empty response from Gemini.' };
        }
    // FIX: Added curly braces to the catch block to correctly scope the error variable 'e'.
    } catch (e: any) {
        console.error("Gemini Provider Error:", e);
        // Handle specific Gemini errors if needed, e.g. 429
        const errorMessage = e.message || 'An unknown error occurred with the Gemini provider.';
        return { success: false, content: '', error: errorMessage };
    }
};

