rules_version = '2';

service cloud.firestore {
  match /databases/{database}/documents {

    // Helper function to check for admin role
    function isAdmin() {
      return request.auth != null && get(/databases/$(database)/documents/users/$(request.auth.uid)).data.role == 'admin';
    }

    // Rules for user profiles and their subcollections
    match /users/{userId} {
      // Users can manage their own profile. Admins can manage any user profile.
      allow read, write: if request.auth != null && (request.auth.uid == userId || isAdmin());

      // Users can only access their own documents subcollection.
      match /documents/{docId=**} {
        allow read, write: if request.auth != null && request.auth.uid == userId;
      }
    }

    // Rules for the AI Providers collection
    match /ai_providers/{providerId} {
      // Any authenticated user can read the provider list to use the AI Gateway.
      // This is necessary for the client-side architecture but exposes API keys.
      allow read: if request.auth != null;

      // Only administrators can create, update, or delete AI providers.
      allow write: if isAdmin();
    }

    // Rules for the Analytics collection
    match /analytics/{path=**} {
       // Only administrators can read or write analytics data.
       allow read, write: if isAdmin();
    }
  }
}

import React, { useState, useEffect } from 'react';
import { Loader, Plus, Edit, Trash2, Save, X, BrainCircuit, ToggleLeft, ToggleRight, AlertTriangle, TestTube, CheckCircle, XCircle } from 'lucide-react';
import { AIProvider, AIProviderType } from '../../../types/ai.types';
import * as aiProviderService from '../../../services/aiProviderService';
import * as geminiProvider from '../../../services/providers/gemini.ts';
import * as openaiProvider from '../../../services/providers/openai.ts';
import * as customProvider from '../../../services/providers/custom.ts';

const ProviderModal = ({ provider, onClose, onSave }: { provider: Partial<AIProvider> | null, onClose: () => void, onSave: (p: Partial<AIProvider>) => void }) => {
    const [editedProvider, setEditedProvider] = useState<Partial<AIProvider>>({
        name: '',
        provider: 'gemini',
        apiKey: '',
        model: 'gemini-3-flash-preview',
        invokeUrl: '',
        isActive: true,
        priority: 1,
        ...provider,
    });
    const [testStatus, setTestStatus] = useState<'idle' | 'testing' | 'success' | 'error'>('idle');
    const [testMessage, setTestMessage] = useState('');

    useEffect(() => {
        // Reset test status when modal opens or provider changes
        setTestStatus('idle');
        setTestMessage('');
    }, [provider]);

    if (!provider) return null;

    const handleSave = () => {
        onSave(editedProvider);
    };

    const handleChange = (field: keyof AIProvider, value: any) => {
        setEditedProvider(p => ({ ...p, [field]: value }));
    };

    const handleTest = async () => {
        setTestStatus('testing');
        setTestMessage('');

        const providerToTest = editedProvider as AIProvider;
        if (!providerToTest.apiKey || !providerToTest.model) {
            setTestStatus('error');
            setTestMessage('API Key and Model are required for testing.');
            return;
        }
        if (providerToTest.provider === 'custom' && !providerToTest.invokeUrl) {
            setTestStatus('error');
            setTestMessage('Invoke URL is required for custom providers.');
            return;
        }

        let result;
        const testPrompt = "Respond with only the word: 'test'";

        try {
            switch (providerToTest.provider) {
                case 'gemini':
                    result = await geminiProvider.generate(providerToTest, testPrompt);
                    break;
                case 'openai':
                    result = await openaiProvider.generate(providerToTest, testPrompt);
                    break;
                case 'custom':
                    result = await customProvider.generate(providerToTest, testPrompt);
                    break;
                default:
                    throw new Error("Invalid provider type");
            }

            if (result.success && result.content.toLowerCase().includes('test')) {
                setTestStatus('success');
                setTestMessage('Connection successful!');
            } else {
