        onSave(editedProvider);
    };

    const handleChange = (field: keyof AIProvider, value: any) => {
        setEditedProvider(p => ({ ...p, [field]: value }));
    };

    const handleTest = async () => {
        setTestStatus('testing');
        setTestMessage('');

        const providerToTest = editedProvider as AIProvider;
        if (!providerToTest.apiKey || !providerToTest.model) {
            setTestStatus('error');
            setTestMessage('API Key and Model are required for testing.');
            return;
        }
        if (providerToTest.provider === 'custom' && !providerToTest.invokeUrl) {
            setTestStatus('error');
            setTestMessage('Invoke URL is required for custom providers.');
            return;
        }

        let result;
