        try {
            switch (providerToTest.provider) {
                case 'gemini':
                    result = await geminiProvider.generate(providerToTest, testPrompt);
                    break;
                case 'openai':
                    result = await openaiProvider.generate(providerToTest, testPrompt);
                    break;
                case 'custom':
                    result = await customProvider.generate(providerToTest, testPrompt);
                    break;
                default:
                    throw new Error("Invalid provider type");
            }

            if (result.success && result.content.toLowerCase().includes('test')) {
                setTestStatus('success');
                setTestMessage('Connection successful!');
            } else {
                setTestStatus('error');
                setTestMessage(result.error || 'Test failed: Unexpected response.');
            }
