            setTestStatus('error');
            if (e.message.includes('Failed to fetch')) {
                setTestMessage('Test failed due to a network error, likely a CORS issue. Please check the instructions and your server configuration.');
            } else {
                setTestMessage(e.message || 'An unknown error occurred.');
