                        <input type="text" value={editedProvider.model || ''} onChange={e => handleChange('model', e.target.value)} className="w-full mt-1 bg-zinc-100 border border-zinc-200 rounded-lg p-3 text-sm" placeholder="e.g., gemini-3-flash-preview or gpt-4o" />
                    </div>
                    {editedProvider.provider === 'custom' && (
