};

export const getUserProfile = async (userId: string): Promise<UserProfile | null> => {
    const userRef = doc(db, 'users', userId);

    const docSnap = await getDoc(userRef);
    if (!docSnap.exists()) {
        return null;
    }

    const profile = docSnap.data() as UserProfile;

    // Check if an admin role upgrade is needed.
    if (profile.email.toLowerCase() === 'rathod.shivang@gmail.com' && profile.role !== 'admin') {
        await setDoc(userRef, { role: 'admin' }, { merge: true });
        for (let attempt = 1; attempt <= 5; attempt++) {
             await new Promise(resolve => setTimeout(resolve, 150 * attempt));
             const serverSnap = await getDocFromServer(userRef);
             if (serverSnap.exists() && serverSnap.data().role === 'admin') {
                 return serverSnap.data() as UserProfile;
             }
        }
        console.error("Admin role update could not be confirmed on the server after several retries.");
    }

    return profile;
};


