const getCurrentUsageMonth = (): string => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
};

export const checkAndResetUsage = async (user: UserProfile): Promise<UserProfile> => {
    const currentMonth = getCurrentUsageMonth();
    const usage = user.usage || { rewritesUsed: 0, metaGenerationsUsed: 0, usageMonth: currentMonth };

    if (usage.usageMonth !== currentMonth) {
        const updatedUsage = { rewritesUsed: 0, metaGenerationsUsed: 0, usageMonth: currentMonth };
        const userRef = doc(db, 'users', user.uid);
        await updateDoc(userRef, { usage: updatedUsage });
        return { ...user, usage: updatedUsage };
    }
    return user;
};

export const canUseAI = async (userId: string, type: 'rewrite' | 'meta'): Promise<{ canUse: boolean, profile: UserProfile | null }> => {
    const userRef = doc(db, 'users', userId);
    const docSnap = await getDoc(userRef);

    if (!docSnap.exists()) {
        console.error("User profile not found for usage check.");
        return { canUse: false, profile: null };
    }

    let userProfile = docSnap.data() as UserProfile;
    userProfile = await checkAndResetUsage(userProfile);

    const plan = getPlanById(userProfile.plan);
    const usage = userProfile.usage || { rewritesUsed: 0, metaGenerationsUsed: 0, usageMonth: '' };

    if (type === 'rewrite') {
        return { canUse: usage.rewritesUsed < plan.limits.aiRewrites, profile: userProfile };
    } else { // 'meta'
        return { canUse: usage.metaGenerationsUsed < plan.limits.metaGenerations, profile: userProfile };
    }
};

export const incrementAIUsage = async (userId: string, type: 'rewrite' | 'meta', amount: number = 1) => {
    const userRef = doc(db, 'users', userId);
    const docSnap = await getDoc(userRef);

    if (!docSnap.exists()) {
        console.error("User profile not found for usage increment.");
        return;
    }

    const userProfile = docSnap.data() as UserProfile;
    const currentMonth = getCurrentUsageMonth();
    let usage = userProfile.usage || { rewritesUsed: 0, metaGenerationsUsed: 0, usageMonth: currentMonth };

    const updates: { [key: string]: any } = {};

    // Safety check: ensure usage is for current month before incrementing
    if (usage.usageMonth !== currentMonth) {
        usage = { rewritesUsed: 0, metaGenerationsUsed: 0, usageMonth: currentMonth };
    }

    if (type === 'rewrite') {
        usage.rewritesUsed = (usage.rewritesUsed || 0) + amount;
    } else { // 'meta'
        usage.metaGenerationsUsed = (usage.metaGenerationsUsed || 0) + amount;
    }

    updates.usage = usage;
    updates.aiUsage = (userProfile.aiUsage || 0) + amount; // Keep legacy total for admin panel

    await updateDoc(userRef, updates);
};

