import { GoogleGenAI } from "@google/genai";
import { AIProvider } from "../../types/ai.types";

export interface ProviderResponse {
    success: boolean;
    content: string;
    error?: string;
}

export const generate = async (provider: AIProvider, prompt: string, config: any = {}): Promise<ProviderResponse> => {
    const { apiKey, model } = provider;
    try {
        if (!apiKey) {
             return { success: false, content: '', error: 'API Key is missing for Gemini provider.' };
        }
        const ai = new GoogleGenAI({ apiKey });
        const response = await ai.models.generateContent({
            model: model,
            contents: prompt,
            config: config
        });

        const content = response.text;
        if (content) {
            return { success: true, content };
        } else {
            const blockReason = response.candidates?.[0]?.finishReason;
            const safetyRatings = response.candidates?.[0]?.safetyRatings;
            if (blockReason) {
                 return { success: false, content: '', error: `Gemini request blocked. Reason: ${blockReason}. Safety: ${JSON.stringify(safetyRatings)}` };
            }
            return { success: false, content: '', error: 'Empty response from Gemini.' };
        }
    } catch (e: any) {
        console.error("Gemini Provider Error:", e);
        const errorMessage = e.message || 'An unknown error occurred with the Gemini provider.';
        return { success: false, content: '', error: errorMessage };
    }
};

