import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import * as authService from '../services/auth.ts';
import { Loader, Mail, RefreshCw, LogOut } from 'lucide-react';

export default function VerifyEmailPage() {
    const { currentUser, loading: authLoading } = useAuth();
    const navigate = useNavigate();
    const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);
    const [isResending, setIsResending] = useState(false);
    const [isRefreshing, setIsRefreshing] = useState(false);

    useEffect(() => {
        if (!authLoading) {
            if (!currentUser) {
                navigate('/auth', { replace: true });
            } else if (currentUser.emailVerified) {
                navigate('/dashboard', { replace: true });
            }
        }
    }, [currentUser, authLoading, navigate]);

    const handleResend = async () => {
        setIsResending(true);
        setMessage(null);
        try {
            await authService.resendVerificationEmail();
            setMessage({ type: 'success', text: 'A new verification email has been sent.' });
        } catch (error: any) {
            setMessage({ type: 'error', text: error.message || 'Failed to send verification email.' });
        } finally {
            setIsResending(false);
        }
    };

    const handleRefresh = async () => {
        if (!currentUser) return;
        setIsRefreshing(true);
        await currentUser.reload();
        // The AuthContext listener will handle the redirect if verification is successful
        // We add a small delay to give the context time to update
        setTimeout(() => {
            if (!currentUser.emailVerified) {
                setMessage({ type: 'error', text: 'Your email is still not verified.' });
            }
            setIsRefreshing(false);
        }, 1000);
    };

    const handleLogout = async () => {
        await authService.signOutUser();
        navigate('/auth');
    };

    if (authLoading || !currentUser || currentUser.emailVerified) {
        return (
            <div className="w-screen h-screen bg-zinc-50 flex items-center justify-center">
                <Loader className="animate-spin text-blue-500" />
            </div>
        );
    }

    return (
        <div className="w-screen h-screen bg-zinc-50 flex items-center justify-center p-4">
            <div className="w-full max-w-md p-8 bg-white rounded-2xl shadow-lg border border-zinc-100 text-center">
                <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mx-auto mb-6">
                    <Mail size={32} />
                </div>
                <h1 className="text-2xl font-black text-zinc-900 mb-2">Verify Your Email</h1>
                <p className="text-zinc-600 mb-6">
                    We've sent a verification link to <strong>{currentUser.email}</strong>. Please check your inbox (and spam folder) to continue.
                </p>

                {message && (
                    <div className={`p-3 rounded-lg text-sm font-bold mb-4 ${message.type === 'success' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>
                        {message.text}
                    </div>
                )}

                <div className="space-y-3">
                    <button 
                        onClick={handleRefresh} 
                        disabled={isRefreshing}
                        className="w-full py-3 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 transition-colors flex items-center justify-center gap-2 disabled:opacity-50"
                    >
                        {isRefreshing ? <Loader size={16} className="animate-spin" /> : <RefreshCw size={16} />}
                        I've Verified My Email
                    </button>
                    <button 
                        onClick={handleResend} 
                        disabled={isResending}
                        className="w-full py-3 bg-zinc-200 text-zinc-800 rounded-lg font-bold hover:bg-zinc-300 transition-colors disabled:opacity-50"
                    >
                        {isResending ? 'Sending...' : 'Resend Email'}
                    </button>
                </div>

                <button onClick={handleLogout} className="text-sm text-zinc-500 hover:text-zinc-800 mt-8 flex items-center justify-center gap-2 mx-auto">
                    <LogOut size={14} /> Log Out
                </button>
            </div>
        </div>
    );
}

import React from 'react';
import { Navigate, Outlet, useLocation } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { Loader } from 'lucide-react';

const RequireAuth = () => {
  const { currentUser, loading } = useAuth();
  const location = useLocation();

  if (loading) {
    return (
      <div className="w-screen h-screen flex items-center justify-center bg-zinc-100">
        <Loader className="animate-spin text-blue-500" />
      </div>
    );
  }

  if (!currentUser) {
    // Redirect them to the /auth page, but save the current location they were
    // trying to go to. This allows us to send them along to that page after they login.
    return <Navigate to="/auth" state={{ from: location }} replace />;
  }

  if (!currentUser.emailVerified) {
    // If user is logged in but email is not verified, send them to the verification page.
    return <Navigate to="/verify-email" state={{ from: location }} replace />;
  }

  // If user is logged in and verified, let them through.
  return <Outlet />;
};

export default RequireAuth;

