import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { onAuthStateChanged, User as FirebaseUser } from 'firebase/auth';
import { auth } from '../lib/firebase';
import { getUserProfile, createUserProfile, UserProfile } from '../services/firestore';

interface AuthContextType {
  currentUser: FirebaseUser | null;
  userProfile: UserProfile | null;
  loading: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider = ({ children }: { children: ReactNode }) => {
  const [currentUser, setCurrentUser] = useState<FirebaseUser | null>(null);
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // FIX: Corrected a potential typo from 'Auth' to the imported 'auth' instance.
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      setLoading(true);
      if (user) {
        await user.reload(); // Get the latest user data from Firebase
        setCurrentUser(user);

        if (user.emailVerified) {
          try {
            let profile = await getUserProfile(user.uid);
            // If the user is verified but has no profile, it's their first verified login. Create the profile.
            if (!profile) {
              await createUserProfile(user);
              profile = await getUserProfile(user.uid); // Re-fetch the newly created profile
            }
            setUserProfile(profile);
          } catch (error) {
            console.error("Error fetching or creating user profile:", error);
            setUserProfile(null);
          }
        } else {
          // User is logged in but not verified
          setUserProfile(null);
        }
      } else {
        setCurrentUser(null);
        setUserProfile(null);
      }
      setLoading(false);
    });
    return unsubscribe;
  }, []);

  const value = {
    currentUser,
    userProfile,
    loading,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import { 
    doc, 
    setDoc, 
    getDoc, 
    getDocs,
    collection, 
    addDoc,
    serverTimestamp,
    onSnapshot,
    query,
    orderBy,
    deleteDoc,
    Timestamp,
    updateDoc,
    writeBatch,
    getDocFromServer
} from 'firebase/firestore';
import { User as FirebaseUser } from 'firebase/auth';
import { db } from '../lib/firebase';
import { LocalDocument } from '../types/document.types';
import { PlanId } from '../types/plan.types.ts';

export interface UserProfile {
    uid: string;
    email: string;
    name: string;
    createdAt: Timestamp;
    plan: PlanId;
    usage: {
        rewritesUsed: number;
        metaGenerationsUsed: number;
        usageMonth: string; // Format: YYYY-MM
    };
    aiUsage: number; // Legacy lifetime total, for admin panel display
    status: 'active' | 'disabled';
    role?: 'admin' | 'user';
    lastLogin?: Timestamp;
}

export const createUserProfile = async (user: FirebaseUser) => {
    const userRef = doc(db, 'users', user.uid);
    const isAdmin = user.email?.toLowerCase() === 'rathod.shivang@gmail.com';
    const currentMonth = new Date().toISOString().slice(0, 7); // YYYY-MM

    const userProfileData: UserProfile = {
        uid: user.uid,
        email: user.email || '',
        name: user.displayName || user.email?.split('@')[0] || 'New User',
        createdAt: serverTimestamp() as Timestamp,
        plan: 'free' as PlanId,
        usage: {
            rewritesUsed: 0,
            metaGenerationsUsed: 0,
            usageMonth: currentMonth,
        },
        aiUsage: 0,
        status: 'active' as 'active' | 'disabled',
        role: isAdmin ? 'admin' as const : 'user' as const,
    };
    await setDoc(userRef, userProfileData);
};

export const getUserProfile = async (userId: string): Promise<UserProfile | null> => {
    const userRef = doc(db, 'users', userId);

    const docSnap = await getDoc(userRef);
    if (!docSnap.exists()) {
        return null;
    }

    const profile = docSnap.data() as UserProfile;

    // Check if an admin role upgrade is needed.
    if (profile.email.toLowerCase() === 'rathod.shivang@gmail.com' && profile.role !== 'admin') {
        await setDoc(userRef, { role: 'admin' }, { merge: true });
        for (let attempt = 1; attempt <= 5; attempt++) {
             await new Promise(resolve => setTimeout(resolve, 150 * attempt));
             const serverSnap = await getDocFromServer(userRef);
             if (serverSnap.exists() && serverSnap.data().role === 'admin') {
                 return serverSnap.data() as UserProfile;
             }
        }
        console.error("Admin role update could not be confirmed on the server after several retries.");
    }

    return profile;
};


export const updateUserProfile = (userId: string, data: Partial<UserProfile>) => {
    const userRef = doc(db, 'users', userId);
    return updateDoc(userRef, data);
};

export const createDocument = async (userId: string, title: string): Promise<string> => {
    const collectionRef = collection(db, 'users', userId, 'documents');
    const newDoc: Omit<LocalDocument, 'id'> = {
        title,
        content: `<h1>${title}</h1><p>Start writing here...</p>`,
        createdAt: Date.now(),
        updatedAt: Date.now(),
        metaTitle: '',
        metaDescription: '',
        targets: { primary: '', secondary: ['', '', ''] },
        faqs: [],
        targetDomain: '',
        isTrashed: false,
        goal: {
            wordCount: 1000,
            intent: 'General',
            audience: 'General',
            tone: 'Professional'
        }
    };
    const docRef = await addDoc(collectionRef, {
        ...newDoc,
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp()
    });
    return docRef.id;
};

export const getDocuments = (userId: string, callback: (docs: LocalDocument[]) => void) => {
    const collectionRef = collection(db, 'users', userId, 'documents');
    const q = query(collectionRef, orderBy('updatedAt', 'desc'));

    return onSnapshot(q, (querySnapshot) => {
        const documents = querySnapshot.docs.map(d => {
            const data = d.data();
            return {
                id: d.id,
                title: data.title || '',
                content: data.content || '',
                createdAt: data.createdAt?.toMillis ? data.createdAt.toMillis() : (data.createdAt || 0),
                updatedAt: data.updatedAt?.toMillis ? data.updatedAt.toMillis() : (data.updatedAt || 0),
                metaTitle: data.metaTitle || '',
                metaDescription: data.metaDescription || '',
                targets: data.targets || { primary: '', secondary: ['', '', ''] },
                faqs: data.faqs || [],
                targetDomain: data.targetDomain || '',
                isTrashed: data.isTrashed || false,
                goal: data.goal || { wordCount: 1000, intent: 'General', audience: 'General', tone: 'Professional' }
            } as LocalDocument;
        });
        callback(documents);
    });
};

export const getDocument = (userId: string, docId: string, callback: (doc: LocalDocument | null) => void) => {
    const docRef = doc(db, 'users', userId, 'documents', docId);
    return onSnapshot(docRef, (docSnap) => {
        if(docSnap.exists()) {
            const data = docSnap.data();
            const docData: LocalDocument = {
                id: docSnap.id,
                title: data.title || '',
                content: data.content || '',
                createdAt: data.createdAt?.toMillis ? data.createdAt.toMillis() : (data.createdAt || 0),
                updatedAt: data.updatedAt?.toMillis ? data.updatedAt.toMillis() : (data.updatedAt || 0),
                metaTitle: data.metaTitle || '',
                metaDescription: data.metaDescription || '',
                targets: data.targets || { primary: '', secondary: ['', '', ''] },
                faqs: data.faqs || [],
                targetDomain: data.targetDomain || '',
                isTrashed: data.isTrashed || false,
                goal: data.goal || { wordCount: 1000, intent: 'General', audience: 'General', tone: 'Professional' }
            };
            callback(docData);
        } else {
            callback(null);
        }
    });
};

export const saveDocument = (userId: string, docId: string, data: Partial<LocalDocument>) => {
    const docRef = doc(db, 'users', userId, 'documents', docId);
    return updateDoc(docRef, { ...data, updatedAt: serverTimestamp() });
};

export const deleteDocument = (userId: string, docId: string) => {
    const docRef = doc(db, 'users', userId, 'documents', docId);
    return deleteDoc(docRef);
};


export const deleteUserDocuments = async (userId: string) => {
    const documentsCollectionRef = collection(db, 'users', userId, 'documents');
    const userProfileRef = doc(db, 'users', userId);

    const batch = writeBatch(db);

    const q = query(documentsCollectionRef);
    const documentsSnapshot = await getDocs(q);
    documentsSnapshot.forEach((doc) => {
        batch.delete(doc.ref);
    });

    batch.delete(userProfileRef);

    return batch.commit();
};

