import React, { useState, useMemo, useRef, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { LocalDocument } from '../../types/document.types.ts';
import { Plus, Search, MoreVertical, Edit, Trash2, ArrowUpDown, FileText, Loader } from 'lucide-react';
import { getStats } from '../../core/text-analysis.ts';
import { useAuth } from '../../context/AuthContext.tsx';
import * as firestoreService from '../../services/firestore.ts';
import { getPlanById } from '../../services/planService.ts';

// FIX: Extracted props to an interface to solve TS issue with 'key' prop
interface DocumentCardProps {
    doc: LocalDocument;
    onTrash: (id: string) => void;
    onRename: (id: string, newTitle: string) => void;
}

const DocumentCard = ({ doc, onTrash, onRename }: DocumentCardProps) => {
    const [menuOpen, setMenuOpen] = useState(false);
    const [isEditing, setIsEditing] = useState(false);
    const [title, setTitle] = useState(doc.title);
    const menuRef = useRef<HTMLDivElement>(null);
    const wordCount = useMemo(() => getStats(doc.content).words, [doc.content]);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
                setMenuOpen(false);
            }
        };
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    const handleRenameSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (title.trim()) {
            onRename(doc.id, title.trim());
        } else {
            setTitle(doc.title);
        }
        setIsEditing(false);
    };

    return (
        <div className="bg-white border border-zinc-200 rounded-2xl flex flex-col group relative shadow-sm hover:shadow-lg hover:-translate-y-1 transition-all duration-300">
            <Link to={`/editor/${doc.id}`} className="flex-1 p-6 flex flex-col">
                {isEditing ? (
                    <form onSubmit={handleRenameSubmit} className="mb-2">
                        <input
                            type="text"
                            value={title}
                            onChange={(e) => setTitle(e.target.value)}
                            onBlur={handleRenameSubmit}
                            className="w-full text-lg font-black text-zinc-900 bg-zinc-100 p-2 rounded-lg outline-none border-2 border-blue-500"
                            autoFocus
                            onClick={(e) => e.preventDefault()}
                        />
                    </form>
                ) : (
                    <h3 className="text-lg font-black text-zinc-900 mb-2 truncate group-hover:text-blue-600 transition-colors">{doc.title}</h3>
                )}
                <div className="flex-1" />
                 <p className="text-xs text-zinc-400 font-medium mt-2">
                    Updated {doc.updatedAt && new Date(doc.updatedAt).toLocaleDateString()}
                </p>
            </Link>
            <div className="border-t border-zinc-100 px-6 py-4 text-xs font-bold text-zinc-500">
                <div className="flex items-center gap-2">
                    <FileText size={14} />
                    <span>{wordCount} words</span>
                </div>
            </div>
            {!isEditing && (
                <div ref={menuRef} className="absolute top-4 right-4">
                    <button onClick={() => setMenuOpen(!menuOpen)} className="p-2 rounded-full hover:bg-zinc-200 opacity-0 group-hover:opacity-100 transition-opacity">
                        <MoreVertical size={16} className="text-zinc-500" />
                    </button>
                    {menuOpen && (
                        <div className="absolute top-full right-0 mt-1 w-40 bg-white border border-zinc-200 rounded-xl shadow-xl z-10 p-2">
                            <button onClick={(e) => { e.stopPropagation(); setIsEditing(true); setMenuOpen(false); }} className="w-full text-left flex items-center gap-2 p-2 text-xs font-bold text-zinc-700 hover:bg-zinc-100 rounded-lg"><Edit size={14}/> Rename</button>
                            <button onClick={(e) => { e.stopPropagation(); onTrash(doc.id); }} className="w-full text-left flex items-center gap-2 p-2 text-xs font-bold text-red-600 hover:bg-red-50 rounded-lg"><Trash2 size={14}/> Move to Trash</button>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default function FilesPage() {
    const navigate = useNavigate();
    const { currentUser, userProfile } = useAuth();
    const [documents, setDocuments] = useState<LocalDocument[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');
    const [sortOrder, setSortOrder] = useState<'updatedAt' | 'createdAt' | 'title'>('updatedAt');

    const userPlan = useMemo(() => getPlanById(userProfile?.plan), [userProfile]);
    const canCreate = useMemo(() => documents.length < userPlan.limits.maxDocs, [documents, userPlan]);

    useEffect(() => {
        if (!currentUser) return;
        setLoading(true);
        const unsubscribe = firestoreService.getDocuments(currentUser.uid, (docs) => {
            const nonTrashedDocs = docs.filter(d => !d.isTrashed);
            setDocuments(nonTrashedDocs);
            setLoading(false);
        });
        return () => unsubscribe();
    }, [currentUser]);

    const handleCreate = async () => {
        if (!currentUser || !canCreate) return;
        const newDocId = await firestoreService.createDocument(currentUser.uid, 'Untitled Document');
        navigate(`/editor/${newDocId}`);
    };

    const handleTrash = (id: string) => {
        if (!currentUser) return;
        firestoreService.saveDocument(currentUser.uid, id, { isTrashed: true });
    };

    const handleRename = (id: string, newTitle: string) => {
        if (!currentUser) return;
        firestoreService.saveDocument(currentUser.uid, id, { title: newTitle });
    };

    const sortedAndFilteredDocs = useMemo(() => {
        return documents
            .filter(doc => doc.title.toLowerCase().includes(searchTerm.toLowerCase()))
            .sort((a, b) => {
                if (sortOrder === 'title') return a.title.localeCompare(b.title);
                return (b[sortOrder] || 0) - (a[sortOrder] || 0);
            });
    }, [documents, searchTerm, sortOrder]);

    if (loading) {
        return <div className="flex items-center justify-center h-full"><Loader className="animate-spin text-blue-500" /></div>
    }

    return (
        <div className="w-full h-full flex flex-col">
            <header className="bg-white/80 backdrop-blur-md border-b border-zinc-200 p-6 flex items-center justify-between sticky top-0 z-10">
                <h1 className="font-black tracking-tighter text-2xl uppercase text-zinc-800">Files</h1>
                 <div className="relative group">
                    <button 
                        onClick={handleCreate} 
                        disabled={!canCreate}
                        className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg text-xs font-bold uppercase tracking-wider hover:bg-blue-700 transition-colors shadow-md shadow-blue-500/20 disabled:bg-zinc-400 disabled:cursor-not-allowed disabled:shadow-none"
                    >
                        <Plus size={16} /> New Document
                    </button>
                    {!canCreate && (
                        <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 w-48 bg-zinc-800 text-white text-xs rounded-lg p-2 text-center opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
                            Document limit reached. Upgrade to create more.
                        </div>
                    )}
                </div>
            </header>
            <div className="flex-1 p-8 overflow-y-auto">
                <div className="max-w-7xl mx-auto">
                    <div className="mb-8 flex items-center justify-between gap-4">
                        <div className="relative flex-1 max-w-lg">
                            <Search size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-400" />
                            <input
                                type="text"
                                placeholder="Search documents..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="w-full bg-white border border-zinc-200 rounded-lg py-3 pl-12 pr-4 text-sm font-bold focus:border-blue-500 outline-none transition-colors"
                            />
                        </div>
                        <div className="relative">
                            <select
                                value={sortOrder}
                                onChange={(e) => setSortOrder(e.target.value as any)}
                                className="appearance-none bg-white border border-zinc-200 rounded-lg py-3 px-4 pr-10 text-sm font-bold text-zinc-600 focus:border-blue-500 outline-none"
                            >
                                <option value="updatedAt">Sort by Updated</option>
                                <option value="createdAt">Sort by Created</option>
                                <option value="title">Sort by Title</option>
                            </select>
                            <ArrowUpDown size={16} className="absolute right-3 top-1/2 -translate-y-1/2 text-zinc-400 pointer-events-none" />
                        </div>
                    </div>
                    {sortedAndFilteredDocs.length > 0 ? (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                            {sortedAndFilteredDocs.map(doc => (
                                <DocumentCard key={doc.id} doc={doc} onTrash={handleTrash} onRename={handleRename} />
                            ))}
                        </div>
                    ) : (
                        <div className="text-center py-20 bg-white rounded-2xl border border-zinc-200">
                            <h3 className="text-lg font-bold text-zinc-600">No files yet</h3>
                            <p className="text-sm text-zinc-400 mt-2 mb-6">Create your first document to get started.</p>
                            <button onClick={handleCreate} className="flex items-center gap-2 mx-auto px-4 py-2 bg-blue-600 text-white rounded-lg text-xs font-bold uppercase tracking-wider hover:bg-blue-700 transition-colors disabled:bg-zinc-400" disabled={!canCreate}>
                                <Plus size={16} /> Create First File
                            </button>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { LocalDocument } from '../../types/document.types.ts';
import { RotateCcw, Trash2, FileX, Loader } from 'lucide-react';
import { useAuth } from '../../context/AuthContext.tsx';
import * as firestoreService from '../../services/firestore.ts';

// FIX: Extracted props to an interface to solve TS issue with 'key' prop
interface TrashedDocRowProps {
    doc: LocalDocument;
    onRestore: (id: string) => void;
    onPermanentDelete: (id: string) => void;
}

const TrashedDocRow = ({ doc, onRestore, onPermanentDelete }: TrashedDocRowProps) => (
    <div className="flex items-center justify-between p-4 bg-white border-b border-zinc-100 group">
        <div>
            <p className="font-bold text-sm text-zinc-800">{doc.title}</p>
            <p className="text-xs text-zinc-400">Trashed on: {doc.updatedAt && new Date(doc.updatedAt).toLocaleDateString()}</p>
        </div>
        <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
            <button onClick={() => onRestore(doc.id)} className="p-2 rounded-lg text-zinc-500 hover:bg-green-50 hover:text-green-600 transition-colors" title="Restore">
                <RotateCcw size={16} />
            </button>
            <button onClick={() => onPermanentDelete(doc.id)} className="p-2 rounded-lg text-zinc-500 hover:bg-red-50 hover:text-red-600 transition-colors" title="Delete Permanently">
                <Trash2 size={16} />
            </button>
        </div>
    </div>
);

export default function TrashPage() {
    const { currentUser } = useAuth();
    const [trashedDocuments, setTrashedDocuments] = useState<LocalDocument[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (!currentUser) {
            setLoading(false);
            return;
        }
        setLoading(true);
        const unsubscribe = firestoreService.getDocuments(currentUser.uid, (docs) => {
            const trashed = docs.filter(d => d.isTrashed);
            setTrashedDocuments(trashed);
            setLoading(false);
        });
        return () => unsubscribe();
    }, [currentUser]);

    const handleRestore = (id: string) => {
        if (!currentUser) return;
        firestoreService.saveDocument(currentUser.uid, id, { isTrashed: false });
    };

    const handlePermanentDelete = (id: string) => {
        if (!currentUser) return;
        if (window.confirm('Are you sure you want to permanently delete this document? This cannot be undone.')) {
            firestoreService.deleteDocument(currentUser.uid, id);
        }
    };

    if (loading) {
        return <div className="flex items-center justify-center h-full"><Loader className="animate-spin text-blue-500" /></div>
    }

    return (
        <div className="w-full h-full flex flex-col">
            <header className="bg-white/80 backdrop-blur-md border-b border-zinc-200 p-6 flex items-center justify-between sticky top-0 z-10">
                <h1 className="font-black tracking-tighter text-2xl uppercase text-zinc-800">Trash</h1>
            </header>
            <div className="flex-1 p-8 overflow-y-auto">
                <div className="max-w-4xl mx-auto">
                    <div className="bg-white border border-zinc-200 rounded-2xl overflow-hidden shadow-sm">
                        {trashedDocuments.length > 0 ? (
                            <div>
                                {trashedDocuments.map(doc => (
                                    <TrashedDocRow key={doc.id} doc={doc} onRestore={handleRestore} onPermanentDelete={handlePermanentDelete} />
                                ))}
                            </div>
                        ) : (
                            <div className="text-center py-20">
                                <FileX size={48} className="mx-auto text-zinc-300 mb-4" />
                                <h3 className="text-lg font-bold text-zinc-600">Trash is empty</h3>
                                <p className="text-sm text-zinc-400 mt-2">Deleted files will appear here.</p>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}

