export default function SettingsPage() {
  const { currentUser, userProfile } = useAuth();
  const navigate = useNavigate();
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [deleteConfirm, setDeleteConfirm] = useState('');
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (userProfile) {
      setName(userProfile.name);
      setEmail(userProfile.email);
    }
  }, [userProfile]);

  const showMessage = (text: string, type: 'success' | 'error') => {
    setMessage({ text, type });
    setTimeout(() => setMessage(null), 4000);
  };

  const handleProfileUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser) return;
    setLoading(true);
    try {
      await firestoreService.updateUserProfile(currentUser.uid, { name });
      showMessage('Profile updated successfully!', 'success');
    } catch (error: any) {
      showMessage(error.message, 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleAccountUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser) return;
    setLoading(true);

    try {
        if (email !== currentUser.email) {
            await authService.updateUserEmail(email);
            await firestoreService.updateUserProfile(currentUser.uid, { email });
        }
        if (password) {
            if(password.length < 6) throw new Error('Password must be at least 6 characters.');
            if (password !== confirmPassword) throw new Error('Passwords do not match.');
            await authService.updateUserPassword(password);
        }
        showMessage('Account details updated!', 'success');
        setPassword('');
        setConfirmPassword('');
    } catch(error: any) {
        showMessage(error.message, 'error');
    } finally {
        setLoading(false);
    }
  };

  const handleDelete = async () => {
      if(deleteConfirm !== 'DELETE') {
          showMessage('Please type DELETE to confirm.', 'error');
          return;
      }
      setLoading(true);
      try {
          await authService.deleteUserAccount();
          navigate('/');
      } catch (error: any) {
          showMessage(`Deletion failed: ${error.message}`, 'error');
          setLoading(false);
      }
  };

  if (!userProfile) return null;

  return (
    <div className="w-full h-full flex flex-col">
      <header className="bg-white/80 backdrop-blur-md border-b border-zinc-200 p-6 flex items-center justify-between sticky top-0 z-10">
        <h1 className="font-black tracking-tighter text-2xl uppercase text-zinc-800">Settings</h1>
      </header>
      <div className="flex-1 p-8 overflow-y-auto">
        <div className="max-w-4xl mx-auto space-y-8">

          {message && (
             <div className={`p-4 rounded-lg text-sm font-bold ${message.type === 'success' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>
                {message.text}
             </div>
          )}

          <SettingsCard title="Profile">
            <form onSubmit={handleProfileUpdate}>
              <Label htmlFor="name">Name</Label>
              <Input id="name" type="text" value={name} onChange={(e) => setName(e.target.value)} />
              <button type="submit" disabled={loading} className="mt-4 flex items-center gap-2 px-4 py-2 bg-zinc-800 text-white rounded-lg text-xs font-bold uppercase tracking-wider hover:bg-black transition-colors disabled:opacity-50">
                <Save size={14} /> {loading ? 'Saving...' : 'Save Profile'}
              </button>
            </form>
          </SettingsCard>

          <SettingsCard title="Account">
            <form onSubmit={handleAccountUpdate}>
              <Label htmlFor="email">Email Address</Label>
              <Input id="email" type="email" value={email} onChange={(e) => setEmail(e.target.value)} />
              <div className="mt-6 pt-6 border-t border-zinc-100">
                <p className="text-sm font-bold text-zinc-600 mb-2">Update Password</p>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <Label htmlFor="password">New Password</Label>
                        <Input id="password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Leave blank to keep current" />
                    </div>
                     <div>
                        <Label htmlFor="confirmPassword">Confirm New Password</Label>
                        <Input id="confirmPassword" type="password" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} />
                    </div>
                </div>
              </div>
              <button type="submit" disabled={loading} className="mt-4 flex items-center gap-2 px-4 py-2 bg-zinc-800 text-white rounded-lg text-xs font-bold uppercase tracking-wider hover:bg-black transition-colors disabled:opacity-50">
                <Save size={14} /> {loading ? 'Saving...' : 'Save Account'}
              </button>
            </form>
          </SettingsCard>

          <div className="bg-red-50 border border-red-200 rounded-2xl p-6">
            <h3 className="text-lg font-bold text-red-800 flex items-center gap-2"><AlertTriangle size={20}/> Danger Zone</h3>
            <p className="text-sm text-red-700 mt-2 mb-4">Deleting your account is permanent and cannot be undone. All your documents and data will be permanently erased.</p>
            <div>
                <Label htmlFor="deleteConfirm">Type "DELETE" to confirm:</Label>
                <Input id="deleteConfirm" type="text" value={deleteConfirm} onChange={(e) => setDeleteConfirm(e.target.value)} className="bg-white border-red-200 focus:border-red-500" />
            </div>
            <button 
                onClick={handleDelete}
                className="mt-4 flex items-center gap-2 px-4 py-2 bg-red-600 text-white rounded-lg text-xs font-bold uppercase tracking-wider hover:bg-red-700 transition-colors disabled:opacity-50"
                disabled={deleteConfirm !== 'DELETE' || loading}
            >
                <Trash2 size={14} /> {loading ? 'Deleting...' : 'Delete My Account'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

