    const plan = getPlanById(userProfile.plan);
    const usage = userProfile.usage || { rewritesUsed: 0, metaGenerationsUsed: 0 };

    const rewriteLimit = plan.limits.aiRewrites;
    const metaLimit = plan.limits.metaGenerations;

    const rewriteUsagePercent = (usage.rewritesUsed / rewriteLimit) * 100;
    const metaUsagePercent = (usage.metaGenerationsUsed / metaLimit) * 100;

    const isPro = userProfile.plan === 'pro' || userProfile.plan === 'ultimate';

    return (
