                                    {isPro ? <Star size={24} /> : <Shield size={24} />}
                                </div>
                                <div>
                                    <p className="text-2xl font-black capitalize">{plan.name}</p>
                                    <p className="text-sm text-zinc-500">
                                        {isPro ? 'You have access to premium features.' : 'Upgrade for more power.'}
                                    </p>
                                </div>
                            </div>
                            {plan.id !== 'ultimate' && (
                                <Link to="/pricing" className="flex items-center justify-center gap-2 px-4 py-3 bg-blue-600 text-white rounded-lg text-xs font-bold uppercase tracking-wider hover:bg-blue-700 transition-colors">
                                    Upgrade Plan <ArrowRight size={14} />
