                                <div className="h-2 bg-zinc-200 rounded-full overflow-hidden">
                                    <div className="h-full bg-blue-500" style={{ width: `${Math.min(rewriteUsagePercent, 100)}%` }} />
                                </div>
                            </div>
                             <div>
                                <div className="flex justify-between items-center mb-2">
                                    <p className="text-sm font-bold text-zinc-700 flex items-center gap-2"><FileText size={14}/> Meta Generations</p>
                                    <p className="text-sm font-semibold">{`${usage.metaGenerationsUsed} / ${metaLimit}`}</p>
                                </div>
                                <div className="h-2 bg-zinc-200 rounded-full overflow-hidden">
                                    <div className="h-full bg-indigo-500" style={{ width: `${Math.min(metaUsagePercent, 100)}%` }} />
                                </div>
                            </div>
                        </div>
                    </InfoCard>

                    <InfoCard title="Your Plan Features">
                         <ul className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-4 text-sm text-zinc-700">
