import { Routes, Route, useNavigate } from 'react-router-dom';

import EditorPage from './pages/EditorPage.tsx';
import HomePage from './pages/HomePage.tsx';
import AuthPage from './pages/AuthPage.tsx';
import AboutPage from './pages/AboutPage.tsx';
import PricingPage from './pages/PricingPage.tsx';
import LegalPage from './pages/LegalPage.tsx';
import PrivacyPage from './pages/PrivacyPage.tsx';
import TermsPage from './pages/TermsPage.tsx';
import RefundPage from './pages/RefundPage.tsx';
import NotFound from './pages/NotFound.tsx';
import VerifyEmailPage from './pages/VerifyEmailPage.tsx';
import RequireAuth from './components/auth/RequireAuth.tsx';

import DashboardLayout from './layouts/DashboardLayout.tsx';
import FilesPage from './pages/dashboard/FilesPage.tsx';
import TrashPage from './pages/dashboard/TrashPage.tsx';
import SettingsPage from './pages/dashboard/SettingsPage.tsx';
import UsagePage from './pages/dashboard/UsagePage.tsx';
import HelpCenterPage from './pages/dashboard/HelpCenterPage.tsx';
import ChangelogPage from './pages/dashboard/ChangelogPage.tsx';
import AdminPanel from './pages/admin/AdminPanel.tsx';
import AdminRoute from './components/auth/AdminRoute.tsx';

export default function App() {
  return (
    // FIX: Removed redundant AuthProvider. It's already wrapping the App in index.tsx
    <div className="w-screen h-screen bg-zinc-100">
      <Routes>
        {/* Public Pages */}
        <Route path="/" element={<HomePage />} />
        <Route path="/auth" element={<AuthPage />} />
        <Route path="/about" element={<AboutPage />} />
        <Route path="/pricing" element={<PricingPage />} />
        <Route path="/support" element={<HelpCenterPage isPublic={true} />} />
        <Route path="/legal" element={<LegalPage />} />
        <Route path="/privacy" element={<PrivacyPage />} />
        <Route path="/terms" element={<TermsPage />} />
        <Route path="/refund" element={<RefundPage />} />
        <Route path="/verify-email" element={<VerifyEmailPage />} />

        {/* Authenticated Routes */}
        <Route element={<RequireAuth />}>
          <Route path="/dashboard" element={<DashboardLayout />}>
            <Route index element={<FilesPage />}/>
            <Route path="trash" element={<TrashPage />}/>
            <Route path="settings" element={<SettingsPage />} />
            <Route path="usage" element={<UsagePage />} />
            <Route path="support" element={<HelpCenterPage />} />
            <Route path="changelog" element={<ChangelogPage />} />
          </Route>

          <Route path="/editor/:id" element={<EditorPage />} />

          {/* Admin Routes */}
          <Route element={<AdminRoute />}>
            <Route path="/admin" element={<AdminPanel />} />
          </Route>
        </Route>

        {/* Not Found */}
        <Route path="*" element={<NotFound />} />
      </Routes>
    </div>
  );
}

