import { useAuth } from '../context/AuthContext.tsx';
import { getDocument, saveDocument } from '../services/firestore.ts';
import { getPlanById, hasFeatureAccess } from '../services/planService.ts';
import * as usageService from '../services/usageService.ts';

function debounce<F extends (...args: any[]) => any>(func: F, waitFor: number) {
  let timeout: ReturnType<typeof setTimeout> | null = null;
  return (...args: Parameters<F>): void => {
    if (timeout) clearTimeout(timeout);
    timeout = setTimeout(() => func(...args), waitFor);
  };
}

export default function EditorPage() {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();
    const { currentUser, userProfile } = useAuth();

    const [activeDocument, setActiveDocument] = useState<LocalDocument | null>(null);
    const [loading, setLoading] = useState(true);

    // UI State
    const [activeTab, setActiveTab] = useState<Tab>('insights');
    const [seoTab, setSeoTab] = useState<SEOPhraseTab>(1);
    const [isExpanded, setIsExpanded] = useState(false);
    const [isAIProcessing, setIsAIProcessing] = useState(false);
    const [editorInstance, setEditorInstance] = useState<any>(null);
    const [toast, setToast] = useState<{ message: string, visible: boolean }>({ message: '', visible: false });
    const [currentBlockType, setCurrentBlockType] = useState('p');
    const [isLinkActive, setIsLinkActive] = useState(false);
    const [brokenLinks, setBrokenLinks] = useState<string[]>([]);
    const [isEditingTitle, setIsEditingTitle] = useState(false);
    const [headerTitle, setHeaderTitle] = useState('');
    const [isGoalModalOpen, setGoalModalOpen] = useState(false);
    const [isUpgradeModalOpen, setIsUpgradeModalOpen] = useState(false);
    const titleInputRef = useRef<HTMLInputElement>(null);

    const userPlan = useMemo(() => getPlanById(userProfile?.plan), [userProfile]);

    useEffect(() => {
        if (!currentUser || !id) return;
        setLoading(true);
        const unsubscribe = getDocument(currentUser.uid, id, (doc) => {
            if (doc) {
                setActiveDocument(doc);
                setHeaderTitle(doc.title);
            } else {
                navigate('/dashboard');
            }
            setLoading(false);
        });
        return () => unsubscribe();
    }, [currentUser, id, navigate]);

    useEffect(() => {
        if (isEditingTitle && titleInputRef.current) {
            titleInputRef.current.focus();
            titleInputRef.current.select();
        }
    }, [isEditingTitle]);

    const deferredContent = useDeferredValue(activeDocument?.content || '');

    const stats = useMemo(() => getStats(deferredContent), [deferredContent]);
    const keywords = useMemo(() => getKeywords(deferredContent, seoTab), [deferredContent, seoTab]);
    const readability = useMemo(() => getReadabilityScore(deferredContent), [deferredContent]);
    const health = useMemo(() => analyzeSEOHealth(deferredContent, keywords, activeDocument?.targets || { primary: '', secondary: [] }, activeDocument?.metaDescription || '', activeDocument?.metaTitle || '', brokenLinks, activeDocument?.targetDomain || ''), [deferredContent, keywords, activeDocument, brokenLinks]);
    const intent = useMemo(() => detectIntent(deferredContent), [deferredContent]);
    const sentenceWarnings = useMemo(() => analyzeSentenceWarnings(deferredContent), [deferredContent]);

    const optimizationReport = useMemo(() => {
        if (!activeDocument) return { critical: [], improvements: [], enhancements: [] };
        return generateOptimizationReport(
            stats, health, readability, sentenceWarnings,
            activeDocument.targets, activeDocument.metaTitle, activeDocument.metaDescription, activeDocument.faqs.length, keywords
        );
    }, [stats, health, readability, sentenceWarnings, activeDocument, keywords]);

    const handlePropUpdate = useCallback((updates: Partial<Omit<LocalDocument, 'id' | 'createdAt'>>) => {
        if (id && currentUser) {
            saveDocument(currentUser.uid, id, updates);
        }
    }, [id, currentUser]);

    const debouncedSave = useCallback(debounce((userId: string, docId: string, updates: Partial<LocalDocument>) => {
        saveDocument(userId, docId, updates);
    }, 1000), []);

    const handleEditorChange = useCallback((newContent: string) => {
        if(id && currentUser) {
            startTransition(() => {
                setActiveDocument(prev => prev ? { ...prev, content: newContent } : null);
                debouncedSave(currentUser.uid, id, { content: newContent });
            });
        }
    }, [id, currentUser, debouncedSave]);

    const handleSelectionChange = useCallback((blockType: string, isLink: boolean) => {
        setCurrentBlockType(blockType);
        setIsLinkActive(isLink);
    }, []);

    const handleTitleRename = (e: React.FormEvent) => {
        e.preventDefault();
        if(id && headerTitle.trim() && currentUser){
            saveDocument(currentUser.uid, id, { title: headerTitle.trim() });
        } else {
            setHeaderTitle(activeDocument?.title || '');
        }
        setIsEditingTitle(false);
    };

    const handleSaveGoals = (newGoal: DocumentGoal) => {
        if (id && currentUser) {
            saveDocument(currentUser.uid, id, { goal: newGoal });
            showToast("Content goals updated!");
        }
    };

    const showToast = (msg: string) => {
        setToast({ message: msg, visible: true });
        setTimeout(() => setToast(prev => ({ ...prev, visible: false })), 3000);
    };

    const runAIAction = async (type: 'rewrite' | 'meta', action: () => Promise<void>) => {
        if (!currentUser) return;

        const { canUse } = await usageService.canUseAI(currentUser.uid, type);
        if (!canUse) {
            setIsUpgradeModalOpen(true);
            return;
        }

        setIsAIProcessing(true);
        try {
            await action();
            await usageService.incrementAIUsage(currentUser.uid, type);
        } catch (err) {
            console.error("AI Action Failed:", err);
            showToast('AI operation failed.');
        } finally {
            setIsAIProcessing(false);
        }
    };

    const onRewrite = useCallback(async (mode: RewriteMode) => {
        if (!editorInstance) return;
        const selectedText = editorInstance.getSelection();
        if (!selectedText) {
            alert("Please select text to use AI rewriting features.");
            return;
        }
        await runAIAction('rewrite', async () => {
            const results = await rewriteContent(selectedText, mode);
            if (results && results.length > 0) editorInstance.insertContent(results[0]);
        });
    }, [editorInstance, currentUser]);

    const onGenerateMetadata = async (type: 'title' | 'description') => {
        if (!activeDocument) return;
        await runAIAction('meta', async () => {
            const currentValue = type === 'title' ? activeDocument.metaTitle : activeDocument.metaDescription;
            const res = await generateMetadata(activeDocument.content, type, activeDocument.targets, currentValue);
            handlePropUpdate(type === 'title' ? { metaTitle: res } : { metaDescription: res });
            showToast(`Meta ${type === 'title' ? 'Title' : 'Description'} Updated`);
        });
    };

    const onGenerateFAQs = async () => {
        if (!hasFeatureAccess(userPlan.id, 'hasFaqsSchema')) {
            setIsUpgradeModalOpen(true);
            return;
        }
        if (!activeDocument) return;
        await runAIAction('meta', async () => {
            const res = await generateFAQs(activeDocument.content);
            handlePropUpdate({ faqs: res });
            showToast('FAQs Generated');
        });
    };

    const handleExport = () => {
        if (!hasFeatureAccess(userPlan.id, 'canExport')) {
            setIsUpgradeModalOpen(true);
            return;
        }
        // Dummy export logic
        showToast("Export feature is available on Pro plan!");
    };

    const wordCount = stats.words;
    const wordLimit = userPlan.limits.wordLimit;
    const isOverLimit = wordCount > wordLimit;

    if (loading || !activeDocument || !userProfile) {
        return <div className="w-screen h-screen bg-zinc-100 flex items-center justify-center flex-col gap-4"><Loader className="animate-spin text-blue-500" /><p className="text-zinc-500 font-semibold">Loading Document...</p></div>;
    }

    return (
        <div className="flex flex-col h-screen w-full bg-white overflow-hidden text-zinc-900 selection:bg-blue-100 relative">
             <div className={`fixed top-6 left-1/2 -translate-x-1/2 z-[200] bg-zinc-900 text-white px-6 py-3 rounded-full shadow-2xl flex items-center gap-3 transition-all duration-300 ease-in-out ${toast.visible ? 'translate-y-0 opacity-100' : '-translate-y-12 opacity-0 pointer-events-none'}`}><div className="w-2 h-2 rounded-full bg-emerald-400 shadow-[0_0_10px_rgba(52,211,153,0.5)]"></div><span className="text-[11px] font-black uppercase tracking-widest">{toast.message}</span></div>

            <header className="h-16 border-b border-zinc-100 px-6 flex items-center justify-between bg-white shrink-0">
                <div className="flex items-center gap-2">
                     <Link to="/dashboard" className="p-2 rounded-lg hover:bg-zinc-100 text-zinc-500 transition-colors" title="Back to Dashboard"><ArrowLeft size={18} /></Link>
                     <div className="w-px h-6 bg-zinc-200 mx-2"></div>
                     {isEditingTitle ? (
                         <form onSubmit={handleTitleRename}><input ref={titleInputRef} type="text" value={headerTitle} onChange={(e) => setHeaderTitle(e.target.value)} onBlur={handleTitleRename} className="font-black tracking-tighter text-lg uppercase bg-zinc-100 p-1 rounded-md outline-none" /></form>
                     ) : (
                         <div className="flex items-center gap-2 group" onClick={() => setIsEditingTitle(true)}><h1 className="font-black tracking-tighter text-lg uppercase truncate max-w-xs cursor-pointer">{headerTitle}</h1><Edit size={14} className="text-zinc-400 opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer" /></div>
                     )}
                </div>
                <div className="flex items-center gap-4">
                     <div className={`text-xs font-bold ${isOverLimit ? 'text-red-500' : 'text-zinc-500'}`}>
                        {wordCount} / {wordLimit.toLocaleString()} words
                     </div>
                    <button onClick={() => setGoalModalOpen(true)} className="flex items-center gap-2 px-4 py-2 bg-white border border-zinc-200 text-zinc-600 rounded-lg text-xs font-bold uppercase tracking-wider hover:bg-zinc-50 transition-colors"><Goal size={14} /> Goal</button>
                    <button onClick={handleExport} className="relative group flex items-center gap-2 px-4 py-2 bg-zinc-800 text-white rounded-lg text-xs font-bold uppercase tracking-wider hover:bg-black transition-colors">
                        {!hasFeatureAccess(userPlan.id, 'canExport') && <Sparkles size={14} className="text-yellow-400" />}
                        <Download size={14} /> Export
                    </button>
                </div>
            </header>

            <div className="flex flex-1 overflow-hidden">
                <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
                    <Toolbar editorInstance={editorInstance} onUpdate={() => handleEditorChange(editorInstance?.getContent() || '')} onNewDocument={() => {}} onShowHistory={() => {}} onSaveVersion={() => {}} viewMode="focused" currentBlockType={currentBlockType} isLinkActive={isLinkActive} />
                    <main className="flex-1 flex justify-center relative bg-zinc-50/50">
                        <div className="w-full max-w-[900px] h-full bg-white relative">
                            {isOverLimit && <div className="absolute bottom-0 left-0 right-0 h-2 bg-red-500/20 pointer-events-none z-10"></div>}
                            <Editor 
                                key={activeDocument.id} 
                                initialContent={activeDocument.content} 
                                onUpdate={handleEditorChange} 
                                onInit={setEditorInstance} 
                                onAIAssist={onRewrite} 
                                onSelectionChange={handleSelectionChange}
                                wordLimit={userPlan.limits.wordLimit}
                                onLimitExceeded={(pasted, allowed) => {
                                    showToast(`Word limit! Pasted ${allowed} of ${pasted} words.`);
                                }}
                            />
                        </div>
                    </main>
                </div>

                <Sidebar
                    userPlan={userPlan}
                    activeTab={activeTab} setActiveTab={setActiveTab}
                    stats={stats} readability={readability} health={health} intent={intent} keywords={keywords}
                    seoTab={seoTab} setSeoTab={setSeoTab} isExpanded={isExpanded} setIsExpanded={setIsExpanded}
                    onRewrite={onRewrite}
                    isAIProcessing={isAIProcessing} targets={activeDocument.targets} setTargets={(t) => handlePropUpdate({ targets: t })}
                    metaTitle={activeDocument.metaTitle} setMetaTitle={(s) => handlePropUpdate({ metaTitle: s })}
                    metaDescription={activeDocument.metaDescription} setMetaDescription={(s) => handlePropUpdate({ metaDescription: s })}
                    faqs={activeDocument.faqs} setFaqs={(f) => handlePropUpdate({ faqs: f })}
                    onGenerateMetadata={onGenerateMetadata}
                    onDetectAI={async () => {
                        await runAIAction('rewrite', async () => {
                            const res = await detectAIContent(activeDocument.content);
                            alert(`AI Detection Score: ${res.score}%`);
                        });
                    }}
                    onGenerateFAQs={onGenerateFAQs}
                    onExportSchema={() => {
                        navigator.clipboard.writeText(JSON.stringify({ "@context": "https://schema.org", "@type": "Article", "headline": activeDocument.metaTitle, "description": activeDocument.metaDescription }, null, 2));
                        showToast('Schema Copied to Clipboard');
                    }}
                    onNavigateOutline={(text) => editorInstance?.scrollToText(text)}
                    sentenceWarnings={sentenceWarnings}
                    optimizationReport={optimizationReport}
                    onHighlight={(enabled) => editorInstance?.toggleHighlights(activeDocument.targets, enabled)}
                    setBrokenLinks={setBrokenLinks}
                    targetDomain={activeDocument.targetDomain}
                    setTargetDomain={(s) => handlePropUpdate({ targetDomain: s })}
                    onUpgradeRequest={() => setIsUpgradeModalOpen(true)}
                />
            </div>
             {isGoalModalOpen && <GoalModal isOpen={isGoalModalOpen} onClose={() => setGoalModalOpen(false)} document={activeDocument} onSave={handleSaveGoals} />}
             {isUpgradeModalOpen && <UpgradeModal isOpen={isUpgradeModalOpen} onClose={() => setIsUpgradeModalOpen(false)} />}
        </div>
    );
}

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { onAuthStateChanged, User as FirebaseUser } from 'firebase/auth';
import { auth } from '../lib/firebase';
import { getUserProfile, createUserProfile, UserProfile } from '../services/firestore';

interface AuthContextType {
  currentUser: FirebaseUser | null;
  userProfile: UserProfile | null;
  loading: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider = ({ children }: { children?: ReactNode }) => {
  const [currentUser, setCurrentUser] = useState<FirebaseUser | null>(null);
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // FIX: Corrected a potential typo from 'Auth' to the imported 'auth' instance.
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      setLoading(true);
      if (user) {
        await user.reload(); // Get the latest user data from Firebase
        setCurrentUser(user);

        if (user.emailVerified) {
          try {
            let profile = await getUserProfile(user.uid);
            // If the user is verified but has no profile, it's their first verified login. Create the profile.
            if (!profile) {
              await createUserProfile(user);
              profile = await getUserProfile(user.uid); // Re-fetch the newly created profile
            }
            setUserProfile(profile);
          } catch (error) {
            console.error("Error fetching or creating user profile:", error);
            setUserProfile(null);
          }
        } else {
          // User is logged in but not verified
          setUserProfile(null);
        }
      } else {
        setCurrentUser(null);
        setUserProfile(null);
      }
      setLoading(false);
    });
    return unsubscribe;
  }, []);

  const value = {
    currentUser,
    userProfile,
    loading,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

