const DocumentCard: React.FC<{ doc: LocalDocument }> = ({ doc }) => {
    const wordCount = useMemo(() => getStats(doc.content).words, [doc.content]);

    // Mock score logic for UI demonstration based on word count/stats
    const score = useMemo(() => {
        const base = Math.min(100, Math.round((wordCount / 1200) * 100));
        return Math.max(65, Math.min(95, base + (doc.title.length % 10)));
    }, [wordCount, doc.title]);

    const isHigh = score >= 80;
    const barColor = isHigh ? 'bg-emerald-500' : 'bg-orange-500';
    const textColor = isHigh ? 'text-emerald-500' : 'text-orange-500';

    const timeAgo = useMemo(() => {
        if (!doc.updatedAt) return 'Just now';
        const seconds = Math.floor((Date.now() - doc.updatedAt) / 1000);
        if (seconds < 60) return 'Just now';
        if (seconds < 3600) return `${Math.floor(seconds/60)}m ago`;
        if (seconds < 86400) return `${Math.floor(seconds/3600)}h ago`;
        return `${Math.floor(seconds/86400)}d ago`;
    }, [doc.updatedAt]);

    return (
        <Link to={`/editor/${doc.id}`} className="bg-white border border-zinc-200 rounded-[24px] p-8 flex flex-col group hover:shadow-xl hover:-translate-y-1 transition-all duration-300">
            <div className="flex justify-between items-start mb-6">
                <h3 className="text-xl font-black text-zinc-900 line-clamp-1 group-hover:text-blue-600 transition-colors flex-1 pr-4">
                    {doc.title}
                </h3>
                <div className={`w-12 h-12 rounded-full border-2 flex items-center justify-center shrink-0 ${isHigh ? 'border-emerald-100 text-emerald-500' : 'border-orange-100 text-orange-500'}`}>
                    <span className="text-sm font-black">{score}</span>
                </div>
            </div>

            <div className="flex items-center gap-6 mb-6">
                <div className="flex items-center gap-2 text-zinc-400">
                    <Clock size={16} />
                    <span className="text-xs font-bold">{timeAgo}</span>
                </div>
                <div className="flex items-center gap-2 text-zinc-400">
                    <FileText size={16} />
                    <span className="text-xs font-bold">{wordCount.toLocaleString()} words</span>
                </div>
            </div>

            <div className="w-full h-1.5 bg-zinc-100 rounded-full overflow-hidden mb-3">
                <div 
                    className={`h-full ${barColor} transition-all duration-1000 ease-out`} 
                    style={{ width: `${score}%` }} 
                />
            </div>

            <div className={`text-[10px] font-black uppercase tracking-widest ${textColor}`}>
                SEO Score {isHigh ? 'High' : 'Moderate'}
            </div>
        </Link>
    );
};

export default function FilesPage() {
    const navigate = useNavigate();
    const { currentUser, userProfile } = useAuth();
    const [documents, setDocuments] = useState<LocalDocument[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');
    const [activeTab, setActiveTab] = useState<'all' | 'trash'>('all');

    const userPlan = useMemo(() => getPlanById(userProfile?.plan), [userProfile]);
    const canCreate = useMemo(() => documents.length < userPlan.limits.maxDocs, [documents, userPlan]);

    useEffect(() => {
        if (!currentUser) return;
        setLoading(true);
        const unsubscribe = firestoreService.getDocuments(currentUser.uid, (docs) => {
            setDocuments(docs);
            setLoading(false);
        });
        return () => unsubscribe();
    }, [currentUser]);

    const handleCreate = async () => {
        if (!currentUser || !canCreate) return;
        const newDocId = await firestoreService.createDocument(currentUser.uid, 'Untitled Document');
        navigate(`/editor/${newDocId}`);
    };

    const filteredDocs = useMemo(() => {
        return documents
            .filter(doc => {
                const matchesSearch = doc.title.toLowerCase().includes(searchTerm.toLowerCase());
                const matchesTab = activeTab === 'all' ? !doc.isTrashed : doc.isTrashed;
                return matchesSearch && matchesTab;
            })
            .sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0));
    }, [documents, searchTerm, activeTab]);

    if (loading) {
        return <div className="flex items-center justify-center h-full"><Loader className="animate-spin text-blue-500" /></div>;
    }

    return (
        <div className="w-full h-full flex flex-col bg-white">
            {/* Top Search Bar Header */}
            <header className="h-20 border-b border-zinc-100 px-10 flex items-center justify-between sticky top-0 bg-white z-20">
                <div className="flex-1 max-w-2xl relative">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-400" size={18} />
                    <input 
                        type="text" 
                        placeholder="Search your SEO documents..." 
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="w-full bg-[#F8FAFC] border-none rounded-2xl py-3.5 pl-12 pr-6 text-sm font-medium focus:ring-2 focus:ring-blue-100 outline-none transition-all placeholder:text-zinc-400"
                    />
                </div>
                <div className="flex items-center gap-6">
                    <div className="bg-blue-50 text-blue-600 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest">
                        {userProfile?.plan || 'Pro'} Plan
                    </div>
                    <div className="w-10 h-10 rounded-full bg-zinc-200 border-2 border-white shadow-sm overflow-hidden flex items-center justify-center">
                        {userProfile?.name?.charAt(0) || 'U'}
                    </div>
                </div>
            </header>

            <div className="flex-1 px-10 py-10 overflow-y-auto custom-scrollbar">
                <div className="max-w-7xl mx-auto">
                    {/* Page Title & New Doc Button */}
                    <div className="flex items-end justify-between mb-12">
                        <div>
                            <h1 className="text-4xl font-black text-zinc-900 tracking-tight mb-2">My Documents</h1>
                            <p className="text-zinc-500 font-medium">Manage and optimize your SEO content pipeline.</p>
                        </div>
                        <button 
                            onClick={handleCreate} 
                            disabled={!canCreate}
                            className="flex items-center gap-2 px-6 py-3.5 bg-blue-600 text-white rounded-xl text-sm font-bold shadow-lg shadow-blue-500/20 hover:bg-blue-700 transition-all disabled:bg-zinc-300 active:scale-95"
                        >
                            <Plus size={18} /> New Document
                        </button>
                    </div>

                    {/* Tabs */}
                    <div className="flex gap-8 border-b border-zinc-100 mb-10">
                        <button 
                            onClick={() => setActiveTab('all')}
                            className={`pb-4 text-sm font-black uppercase tracking-widest transition-all relative ${activeTab === 'all' ? 'text-blue-600' : 'text-zinc-400 hover:text-zinc-600'}`}
                        >
                            All Files
                            {activeTab === 'all' && <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-blue-600 rounded-full" />}
                        </button>
                        <button 
                            onClick={() => setActiveTab('trash')}
                            className={`pb-4 text-sm font-black uppercase tracking-widest transition-all relative ${activeTab === 'trash' ? 'text-blue-600' : 'text-zinc-400 hover:text-zinc-600'}`}
                        >
                            Trash
                            {activeTab === 'trash' && <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-blue-600 rounded-full" />}
                        </button>
                    </div>

                    {/* Grid */}
                    {filteredDocs.length > 0 ? (
                        <>
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 mb-16">
                                {filteredDocs.map(doc => (
                                    <DocumentCard key={doc.id} doc={doc} />
                                ))}
                            </div>
                            <div className="flex justify-center">
                                <button className="px-8 py-3.5 border border-zinc-200 rounded-xl text-sm font-bold text-zinc-600 hover:bg-zinc-50 transition-colors">
                                    Load 12 more documents
                                </button>
                            </div>
                        </>
                    ) : (
                        <div className="text-center py-32 bg-[#F8FAFC] rounded-[40px] border-2 border-dashed border-zinc-200">
                            <h3 className="text-xl font-black text-zinc-900 mb-2">No documents found</h3>
                            <p className="text-zinc-500 font-medium mb-8">Start your next ranking masterpiece today.</p>
                            <button onClick={handleCreate} className="flex items-center gap-2 mx-auto px-8 py-4 bg-blue-600 text-white rounded-2xl text-sm font-bold shadow-xl shadow-blue-500/20 hover:bg-blue-700">
                                <Plus size={20} /> Create New Document
                            </button>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

