        {activeTab === 'optimize' && hasFeatureAccess(userPlan.id, 'hasOptimizeTab') && <OptimizeTab report={props.optimizationReport} sentenceWarnings={props.sentenceWarnings} onNavigateOutline={props.onNavigateOutline} />}
