                <ToolbarButton title="Subscript" icon={<Subscript size={16} />} onClick={() => handleFormat('subscript')} />
                <ToolbarButton title="Superscript" icon={<Superscript size={16} />} onClick={() => handleFormat('superscript')} />
            </Group>

            {/* Group 4: Inserts */}
            <Group>
                <ToolbarButton title="Insert List" icon={<List size={16} />} onClick={() => handleFormat('insertUnorderedList')} />
                <ToolbarButton title="Insert Image" icon={<ImageIcon size={16} />} onClick={() => {
                    const url = prompt("Enter image URL:");
                    if(url) handleFormat('insertImage', url);
                }} />
                <ToolbarButton title="Horizontal Rule" icon={<Minus size={16} />} onClick={() => handleFormat('insertHorizontalRule')} />
                <ToolbarButton title="Link" icon={<LinkIcon size={16} />} active={isLinkActive} onClick={() => {
                    const url = prompt("Enter link URL:");
                    if(url) handleFormat('createLink', url);
                }} />
            </Group>
        </div>

        <div className="flex items-center gap-5 pr-2">
            <div className="flex flex-col items-end">
                <span className="text-[10px] font-bold text-zinc-400 uppercase tracking-widest">{stats.words} Words</span>
            </div>
            <div className="flex flex-col items-end border-l border-zinc-100 pl-5">
                <span className="text-[10px] font-bold text-zinc-400 uppercase tracking-widest">{stats.readingTime} Min Read</span>
            </div>
        </div>
    </div>
  );
};

