    <Routes>
      {/* 1. PUBLIC MARKETING ROUTES */}
      <Route element={<PublicLayout />}>
        <Route path="/" element={<HomePage />} />
        <Route path="/about" element={<AboutPage />} />
        <Route path="/pricing" element={<PricingPage />} />
        <Route path="/contact" element={<ContactPage />} />
        <Route path="/legal" element={<LegalPage />} />
        <Route path="/privacy" element={<PrivacyPage />} />
        <Route path="/terms" element={<TermsPage />} />
        <Route path="/refund" element={<RefundPage />} />
      </Route>

      {/* 2. AUTH & VERIFICATION (No Layout) */}
      <Route path="/auth" element={<AuthPage />} />
      <Route path="/verify-email" element={<VerifyEmailPage />} />

      {/* 3. DYNAMIC SUPPORT & CHANGELOG */}
      <Route path="/support" element={<SupportRoute />} />

      {/* 4. PROTECTED USER ROUTES */}
      <Route element={<RequireAuth />}>
        <Route element={<DashboardLayout />}>
          <Route path="/dashboard" element={<FilesPage />} />
          <Route path="/dashboard/trash" element={<TrashPage />} />
          <Route path="/dashboard/usage" element={<UsagePage />} />
          <Route path="/settings" element={<SettingsPage />} />
          <Route path="/changelog" element={<ChangelogPage />} />
          <Route path="/upgrade" element={<Navigate to="/pricing" replace />} />
        </Route>

        {/* Full-screen Editor */}
        <Route path="/content/:id" element={<EditorPage />} />
      </Route>

      {/* 5. ADMIN ROUTES */}
      <Route element={<AdminRoute />}>
        <Route element={<AdminLayout />}>
          <Route path="/admin" element={<OverviewTab />} />
          <Route path="/admin/users" element={<UsersTab />} />
          <Route path="/admin/apis" element={<AIProvidersTab />} />
          <Route path="/admin/analytics" element={<RevenueTab />} />
        </Route>
      </Route>

      {/* 6. FALLBACK */}
      <Route path="*" element={<NotFound />} />
    </Routes>
  );
};

export default function App() {
  return (
    <AuthProvider>
      <div className="w-screen h-screen bg-zinc-100 overflow-hidden">
        <MainRoutes />
      </div>
    </AuthProvider>
  );
}

